&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;पढ़ने का समय : 22 minutes&lt;/div&gt;
&lt;p&gt;मुझे अक्सर पूछा जाता है कि मेरा AI उपयोग कितना खर्चा है। मैं जवाब देता हूं &quot;20 यूरो per माह&quot; और लोग मुझे आश्चर्य से देखते हैं। तो आज, मैं आपको ब्लैक बॉक्स खोलता हूँ। यह लेख मेरे 73 दिनों के वाइब कोडिंग का पूर्ण ऑडिट है: ओपनकोड की SQLite डेटाबेस से डेटा निकालने की पद्धति, टेबल्स को interroger करने के लिए SQL कोड, और बाज़ार के &lt;strong&gt;सभी&lt;/strong&gt; आपूर्तिकर्ताओं — पश्चिमी और चीनी — के साथ व्यापक तुलना। परिणाम इतना असमान है कि मुझे अपनी गणनाओं की तीन बार जाँच करनी पड़ी।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;टोक&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्टैक_को_समझें_कौन_क्या_करता_है&quot;&gt;स्टैक को समझें: कौन क्या करता है ?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आंकड़ों में गोता लगाने से पहले, आर्किटेक्चर स्पष्ट करते हैं। मेरे सेटअप में तीन अलग‑अलग अभिनेता हैं, और यह महत्वपूर्ण है कि उन्हें गलत न समझें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title मेरी LLM स्टैक के तीन अभिनेता
left to right direction

actor &quot;मैं (डेवलपर)&quot; as Dev

package &quot;OpenCode
(github.com/anomalyco/opencode)&quot; as OC {
  rectangle &quot;CLI वाइब कोडिंग
ओपन सोर्स, मुफ्त&quot; as CLI
  note right of CLI
    C&#39;est l&#39;outil que j&#39;utilise
    pour coder avec des agents IA.
    Il ne fournit AUCUN modèle.
    C&#39;est un terminal + un orchestrateur.
  end note
}

package &quot;Ollama (स्थानीय स्थापना)&quot; as OL {
  rectangle &quot;इन्फरेंस क्लाइंट
मेरी मशीन पर स्थापित&quot; as Client
  note right of Client
    C&#39;est le logiciel qui fait tourner
    les modèles. Il peut les exécuter
    en local OU les déléguer au cloud
    selon le tag (:cloud).
    Il s&#39;authentifie via clé SSH.
  end note
}

package &quot;Ollama Cloud
(ollama.com)&quot; as OCloud {
  rectangle &quot;क्लाउड इन्फ़ेरेंस सेवा
प्रो सब्सक्रिप्शन : 20 यूरो/महीना&quot; as Cloud
  note right of Cloud
    C&#39;est le fournisseur d&#39;inférence.
    Mes modèles avec le tag :cloud
    sont exécutés sur LEURS serveurs.
    L&#39;abonnement Pro donne accès
    à des quotas supérieurs.
  end note
}

Dev --&amp;gt; CLI : &quot;मैं प्रॉम्प्ट्स टाइप कर रहा हूँ&quot;
CLI --&amp;gt; Client : &quot;इस मॉडल को बुलाओ&quot;
Client --&amp;gt; Cloud : &quot;SSH कुंजी + अनुरोध\n(मॉडल :cloud)&quot;
Client --&amp;gt; Client : &quot;स्थानीय निष्पादन
(मॉडल बिना :cloud)&quot;

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;OpenCode एक मॉडल प्रदाता नहीं है।&lt;/strong&gt;यह एक ओपन सोर्स CLI है (&lt;a href=&quot;https://github.com/anomalyco/opencode&quot;&gt;github.com/anomalyco/opencode&lt;/a&gt;) जो IA एजेंट्स को ऑर्केस्ट्रेट करता है। यह सदस्यता नहीं बेचता, यह अनुमान नहीं देता। यह समतुल्य है`git`संस्करण नियंत्रण के लिए : एक उपकरण, सेवा नहीं &lt;strong&gt;Ollama Cloud इन्फरेंस प्रदाता है।&lt;/strong&gt;मेरी स्थानीय Ollama स्थापना &lt;strong&gt;client&lt;/strong&gt; के रूप में कार्य करती है — इसे Device Key के माध्यम से एक अद्वितीय SSH कुंजी के माध्यम से Ollama सर्वरों के साथ प्रमाणित किया जाता है और वह टैग वाले मॉडलों के निष्पादन को उन पर प्रतिनिधिमित करती है`:cloud`. पेशेवर सब्सक्रिप्शन (20€/माह) उच्च कोटे अनलॉक करता है और एक ही मशीन पर कई खातों को Docker के माध्यम से संचय करने की अनुमति देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय_क्यों_एक_ऑडिट&quot;&gt;परिचय: क्यों एक ऑडिट?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;दो महीने पहले, मैं अपने स्थानीय ओला इंस्टॉलेशन पर मॉडल्स मुफ्त में उपयोग कर रहा था। फिर मैंने ओला क्लाउड प्रो का पहला सब्सक्रिप्शन लिया, जो 20€/महीने की लागत से है, जो मुझे क्लाउड मॉडल्स (जिनके टैग`:cloud`) के माध्यम से प्रदाता`ollama-cloud`. दूसरा सब्सक्रिप्शन एक महीने बाद अनुसरण किया, एक अलग Docker इंस्टेंस पर, जिसमें उसका अपना खाता और अपनी स्वयं की SSH कुंजी थी — संचय विधि जो &lt;a href=&quot;0120_cumuler_deux_abonnements_ollama_pro_docker_post.html&quot;&gt;मेरे सब्सक्रिप्शनों के संचय पर लेख&lt;/a&gt; में वर्णित है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;वह प्रश्न जो मुझे परेशान कर रहा था : &lt;strong&gt;क्या ये 20€ प्रति माह न्यायसंगत हैं ?&lt;/strong&gt; केवल अनुमान से नहीं। संख्याओं के साथ।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जवाब देने के लिए, मुझे सटीक डेटा की आवश्यकता थी। अनुमान नहीं। औसत नहीं। मेरी वास्तविक &lt;strong&gt;उपभोग&lt;/strong&gt;, टोकन दर टोकन, मॉडल दर मॉडल, सेशन दर सेशन।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और OpenCode — CLI — इसे SQLite डेटाबेस में संग्रहीत करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ओपेनकोड_डेटाबेस_एक_सोने_की_खान&quot;&gt;ओपेनकोड डेटाबेस : एक सोने की खान&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;OpenCode अपने सत्रों के इतिहास का पूरा रिकॉर्ड एक स्थित SQLite फ़ाइल में संग्रहीत रखता है`~/.local/share/opencode/opencode.db`. La mienne pèse 660 Mo pour 73 jours d&amp;#8217;utilisation — une base de données de production tout à fait respectable.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ls -lh ~/.local/share/opencode/opencode.db
-rw-r--r-- 1 cheroliv cheroliv 660M mai 18 12:25 opencode.db&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्कीमा&quot;&gt;स्कीमा&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;डेटाबेस में लगभग बीस टेबल हैं, लेकिन इनमें से तीन हमारे ऑडिट के लिए महत्वपूर्ण हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title स्कीमा सरलीकृत — OpenCode SQLite
entity &quot;सत्र&quot; as S {
  * id : TEXT
  --
  * model : TEXT (JSON)
  * cost : REAL
  * tokens_input : INTEGER
  * tokens_output : INTEGER
  * tokens_reasoning : INTEGER
  * tokens_cache_read : INTEGER
  * tokens_cache_write : INTEGER
  * time_created : INTEGER
  * project_id : TEXT
}

entity &quot;संदेश&quot; as M {
  * id : TEXT
  --
  * session_id : TEXT &amp;lt;&amp;lt;FK&amp;gt;&amp;gt;
  * data : TEXT (JSON)
  * time_created : INTEGER
}

entity &quot;प्रोजेक्ट&quot; as P {
  * id : TEXT
  --
  * worktree : TEXT
  * name : TEXT
}

S ||--o{ M : &quot;सेशन_आइडी&quot;
S }o--|| P : &quot;परियोजना_आईडी&quot;

note right of S
  La table session agrège
  tokens + coût + modèle.
  C&#39;est notre point d&#39;entrée
  principal.
end note

note right of M
  Les messages individuels.
  Le champ data contient
  le modèle utilisé (format JSON)
  même si la session change
  de modèle en cours de route.
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;टेबल`session`यह एक वैश्विक ऑडिट के लिए आदर्श है : प्रत्येक सत्र का एग्रीगेटेड टोकन count, उपयोग किया गया मॉडल, और लागत होती है। क्षेत्र`model`रॉ JSON है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;id&quot;: &quot;deepseek-v4-pro:cloud&quot;,
  &quot;providerID&quot;: &quot;ollama-cloud&quot;,
  &quot;variant&quot;: &quot;default&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्षेत्र`cost`ओपनकोड डेटाबेस में केवल &lt;strong&gt;बाह्य API शुल्क&lt;/strong&gt; दिखाए जाते हैं, जो API कुंजी (Google Gemini, OpenAI, आदि) के माध्यम से उपयोग के आधार पर भुगतान किए जाते हैं। ओल्लामा के माध्यम से किए गए कॉल — चाहे वे स्थानीय हों या ओल्लामा क्लाउड प्रो के माध्यम से — चिह्नित किए जाते हैं।`cost=0`क्योंकि लागत सदस्यता के कारण निश्चित शुल्क है, per-token के बजाय। इन कॉल्स का वास्तविक लागत मासिक सदस्यता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निष्कर्षण_कोड&quot;&gt;निष्कर्षण कोड&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;किसी भी चीज़ को स्थापित करने की आवश्यकता नहीं है। Node.js 22+ में एक प्रायोगिक SQLite मॉड्यूल एम्बेडेड है (&lt;code&gt;node:sqlite&lt;/code&gt;) यह पूरी तरह से काम करता है। यह स्क्रिप्ट है जिसने मुझे सब कुछ दिया :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const { DatabaseSync } = require(&#39;node:sqlite&#39;);
const db = new DatabaseSync(
  `${process.env.HOME}/.local/share/opencode/opencode.db`,
  { readonly: true }
);

// 1. Statistiques globales
const global = db.prepare(`
  SELECT
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(tokens_reasoning) as total_reasoning,
    SUM(tokens_cache_read) as total_cache_read,
    SUM(cost) as total_cost
  FROM session
`).get();

// 2. Ventilation par modèle et fournisseur
const byModel = db.prepare(`
  SELECT
    json_extract(model, &#39;$.id&#39;) as model_id,
    json_extract(model, &#39;$.providerID&#39;) as provider,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE model IS NOT NULL
  GROUP BY model_id, provider
  ORDER BY SUM(tokens_input) DESC
`).all();

// 3. Par mois
const monthly = db.prepare(`
  SELECT
    strftime(&#39;%Y-%m&#39;, datetime(time_created/1000, &#39;unixepoch&#39;)) as month,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE time_created IS NOT NULL
  GROUP BY month
  ORDER BY month
`).all();

// 4. Messages par modèle (détection des changements intra-session)
const msgByModel = db.prepare(`
  SELECT
    json_extract(m.data, &#39;$.model.providerID&#39;) as provider,
    json_extract(m.data, &#39;$.model.modelID&#39;) as model_id,
    COUNT(*) as messages
  FROM message m
  WHERE json_extract(m.data, &#39;$.model&#39;) IS NOT NULL
  GROUP BY provider, model_id
  ORDER BY COUNT(*) DESC
`).all();

console.log({ global, byModel, monthly, msgByModel });
db.close();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;ℹ️&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;झंडा`--experimental-sqlite`Node.js 22.x पर आवश्यक है। Node.js 24+ पर, मॉड्यूल स्थिर है और अब फ़्लैग की आवश्यकता नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिणाम_73_दिनों_की_खपत&quot;&gt;परिणाम: 73 दिनों की खपत&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वैश्विक_दृश्य&quot;&gt;वैश्विक दृश्य&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;मेट्रिक&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;मूल्य&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;संदर्भ&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;सत्रों OpenCode&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1 022&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;औसत रूप से लगभग 14 सेशन प्रति दिन&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;टोकन इनपुट&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2,62 अरब&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जिसमें 94,5M कैश हिट&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Tokens Output&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;21 मिलियन&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Veuillez fournir le texte français à traduire.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Tokens Reasoning&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;141 000&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नगण्य — लगभग कोई सोच नहीं&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;बाह्य API लागत&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;\$0,22&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सदस्यता के बाहर शुल्क (Gemini + free tiers)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह आंकड़ा \$0,22 महत्वपूर्ण है: यह वही है जो मैंने अपने Ollama Cloud Pro सब्सक्रिप्शन के &lt;strong&gt;अतिरिक्त&lt;/strong&gt; भुगतान किया है। यानी लगभग कुछ नहीं। सब्सक्रिप्शन आवश्यक चीजों को कवर करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title मासिक विकास — टोकन इनपुट
rectangle &quot;मार्च 2026
9 सत्र
37,7M टोकन&quot; as MARS #FFE082
rectangle &quot;अप्रैल 2026
486 सत्र
1,33 मिलियन टोकन&quot; as AVR #81C784
rectangle &quot;मई 2026
527 सत्र
1,25 मिलियन टोकन&quot; as MAI #64B5F6

MARS -right-&amp;gt; AVR : ×35
AVR -right-&amp;gt; MAI : stable (période en cours)

note bottom of MAI
  Mai comptabilisé jusqu&#39;au 18.
  Projection mois complet : ~2,1 Md tokens
  si la tendance se maintient.
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मार्च और अप्रैल के बीच का उछाल उल्लेखनीय है: एक महीने में ×35। यह &#39;टेस्ट&#39; उपयोग से &#39;उत्पादन&#39; उपयोग में संक्रमण है — जब मैंने अपने Gradle प्लगइन के लिए लगातार OpenCode एजेंट चलाना शुरू किया।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वेंटिलेशन_द्वारा_मॉडल_और_आपूर्तिकर्ता&quot;&gt;वेंटिलेशन द्वारा मॉडल और आपूर्तिकर्ता&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्षेत्र`model`टेबल की`session`JSON होना,`json_extract()`स्वच्छ तरीके से वेंटिलेट करने की अनुमति देता है:&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 27.2727%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1819%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;मॉडल × प्रदाता&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;सत्रें&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;इनपुट&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;(Empty)&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;लागत&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-pro @ ollama-cloud&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;63&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;220 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1,94 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;\$0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-pro @ ollama-b&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;124&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;463 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;4,15 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;\$0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-pro @ ollama&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;100&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;252 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2,25 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;\$0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-flash-free @ opencode&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;16&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1,3 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;279 K&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;\$0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;qwen3.6-plus-free @ opencode&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;369 K&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;25 K&lt;/p&gt;&lt;/td&gt;
