&lt;li&gt;&lt;a href=&quot;#_अपवादों_को_कॉन्फ़िगर_करें&quot;&gt;अपवादों को कॉन्फ़िगर करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_knowledge_graph_निकालें&quot;&gt;Knowledge Graph निकालें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_2_ग्रैडल_प्लगिन_नॉलेज_ग्राफ_को_plantuml_में_बदलता_है&quot;&gt;चरण 2 : ग्रैडल प्लगिन नॉलेज ग्राफ को PlantUML में बदलता है&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_पाइपलाइन_वास्तुकला&quot;&gt;पाइपलाइन वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_आंतरिक_घटक&quot;&gt;आंतरिक घटक&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_रेंडरिंग_के_नियम&quot;&gt;रेंडरिंग के नियम&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_3_दैनिक_उपयोग&quot;&gt;चरण 3 : दैनिक उपयोग&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_पूर्ण_आलेख&quot;&gt;पूर्ण आलेख&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समुदाय_द्वारा_फ़िल्टर&quot;&gt;समुदाय द्वारा फ़िल्टर&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_किनारा_प्रकार_द्वारा_फ़िल्टर_करें&quot;&gt;किनारा प्रकार द्वारा फ़िल्टर करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_नोड_के_प्रकार_और_विश्वास_द्वारा_फ़िल्टर_करें&quot;&gt;नोड के प्रकार और विश्वास द्वारा फ़िल्टर करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कस्टम_आउटपुट_डायरेक्टरी&quot;&gt;कस्टम आउटपुट डायरेक्टरी&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_गुणों_का_पूर्ण_संदर्भ&quot;&gt;गुणों का पूर्ण संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पूर्ण_पाइपलाइन_एक_gradle_वर्कफ़्लो_में&quot;&gt;पूर्ण पाइपलाइन एक Gradle वर्कफ़्लो में&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_वर्कफ़्लो_प्रकार&quot;&gt;वर्कफ़्लो प्रकार&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_विकास_चक्र_में_एकीकरण&quot;&gt;विकास चक्र में एकीकरण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_वृद्धिशील_अद्ययन&quot;&gt;वृद्धिशील अद्ययन&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_डॉगफ़ूडिंग_प्लगइन_स्वयं_का_दस्तावेज़_बनाता_है&quot;&gt;डॉगफ़ूडिंग: प्लगइन स्वयं का दस्तावेज़ बनाता है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_यह_निर्धारित_क्यों_है_और_यह_क्यों_मायने_रखता_है&quot;&gt;यह निर्धारित क्यों है (और यह क्यों मायने रखता है)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पाइपलाइन_के_स्वयं_के_आरेख&quot;&gt;पाइपलाइन के स्वयं के आरेख&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_परियोजना_शासन_में_एकीकरण&quot;&gt;परियोजना शासन में एकीकरण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_स्थापना_5_मिनट_की_चेकलिस्ट&quot;&gt;स्थापना : 5 मिनट की चेकलिस्ट&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जाल_और_निवारण_उपाय&quot;&gt;जाल और निवारण उपाय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अंत_में_हमें_क्या_प्राप्त_होता_है&quot;&gt;अंत में हमें क्या प्राप्त होता है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लिंक&quot;&gt;लिंक&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;पढ़ने का समय : 12 minutes&lt;/div&gt;
&lt;p&gt;आपका कोडबेस बढ़ रहा है। मॉड्यूल के बीच निर्भरताएँ बढ़ रही हैं। आर्किटेक्चर दस्तावेज़ लिखे जाने से पहले ही अप्रचलित हो जाता है। और यदि आपका Gradle बिल्ड &lt;em&gt;automatiquement&lt;/em&gt; कोड की वास्तविक संरचना से अद्यतन आरेख उत्पन्न कर सके ? यह ठीक वही है जो Graphify + PlantUML Gradle Plugin पाइपलाइन करता है :`graphify . --no-viz`Knowledge Graph को निकालता है,`./gradlew generateKnowledgeGraphDiagram`इसे PlantUML आरेखों में बदल देता है। शून्य LLM, शून्य मैनुअल, 100% निर्धारित।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;टॉक&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_डायग्राम_हमेशा_कोड_के_पीछे_हैं&quot;&gt;समस्या: डायग्राम हमेशा कोड के पीछे हैं&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कुछ हजार लाइनों से अधिक लंबा कोई भी प्रोजेक्ट इस सिंड्रोम से परिचित होता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;हम प्रोजेक्ट की शुरुआत में एक आर्किटेक्चर डायग्राम बनाते हैं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कोड विकसित हो रहा है, निर्भरताएँ बदल रही हैं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;दियाग्राम सजावटी झूठ बन जाता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कोई इसे अपडेट नहीं करता क्योंकि यह थकाऊ है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;नए आए लोग इस पर निर्भर करते हैं और गलतियाँ करते हैं&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam ActivityBackgroundColor #FDEDEC
skinparam ActivityDiamondBackgroundColor #FFF3CD

start

:Diagramme d&#39;architecture créé\n(manuellement, à la main);

:Le code évolue\n(nouvelles classes, nouvelles dépendances);

:Diagramme obsolète\n(ne reflète plus le code);

if (Qui met à jour ?) then (Personne)
    :Documentation mensongère;
    note right: Les nouveaux développeurs\nse basent dessus... et font des erreurs
else (Quelqu&#39;un)
    :Mise à jour manuelle\n(2-3 heures de travail);
    note right: Déjà obsolète\nà la prochaine PR
endif

stop

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रश्न यह नहीं है कि &lt;em&gt;faut-il des diagrammes ?&lt;/em&gt; — हर कोई जानता है कि हाँ. प्रश्न यह है :&lt;strong&gt;कौन उन्हें अपडेट रखता है ?&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जवाब: कोई नहीं. जब तक यह स्वचालित नहीं है.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समाधान_एक_निर्धारित_पाइपलाइन_knowledge_graph_plantuml&quot;&gt;समाधान : एक निर्धारित पाइपलाइन Knowledge Graph → PlantUML&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सिद्धांत सरल है : हाथ से आरेख बनाने के बजाय, हम उन्हें&lt;strong&gt;कोड की वास्तविक संरचना से उत्पन्न&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Développeur
component &quot;Graphify\n(pip install graphifyy)&quot; as Graphify
collections &quot;graphify-out/graph.json
(ज्ञान ग्राफ)&quot; as KGJSON
component &quot;PlantUML Gradle प्लगइन
(generateKnowledgeGraphDiagram)&quot; as Plugin
component &quot;KnowledgeGraphParser&quot; as Parser
component &quot;KnowledgeGraphRenderer&quot; as Renderer
component &quot;PlantumlService
(सत्यापन + PNG रेंडर)&quot; as PS
collections &quot;diagrams/knowledge-graph/\n(.puml + .png)&quot; as Output

Développeur --&amp;gt; Graphify : graphify . --no-viz
Graphify --&amp;gt; KGJSON : extrait la structure\ndu code source
Développeur --&amp;gt; Plugin : ./gradlew generateKnowledgeGraphDiagram
Plugin --&amp;gt; Parser : parse(graph.json)
Parser --&amp;gt; Plugin : KnowledgeGraph\n(noeuds + arêtes + communautés)
Plugin --&amp;gt; Renderer : render(graph, filters)
Renderer --&amp;gt; Plugin : code PlantUML\ndéterministe
Plugin --&amp;gt; PS : validateSyntax + generateImage
PS --&amp;gt; Output : .puml + .png

note bottom of Plugin
  Pipeline DÉTERMINISTE
  Aucun appel LLM
  Résultat reproductible
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;दो कमांड। बस यही।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Étape 1 : extraire le Knowledge Graph
graphify . --no-viz

# Étape 2 : générer les diagrammes PlantUML
./gradlew generateKnowledgeGraphDiagram&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम? फ़ाइलें`.puml` et &lt;code&gt;.png`में`diagrams/knowledge-graph/&lt;/code&gt;, Git में वर्ज़न किए गए, कोड के साथ हमेशा अद्यतन.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्टेप_1_graphify_स्थापित_करें_और_knowledge_graph_निकालें&quot;&gt;स्टेप 1: Graphify स्थापित करें और Knowledge Graph निकालें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्थापना&quot;&gt;स्थापना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Graphify एक पायथन टूल है जो आपका कोडबेस विश्लेषण करता है और एक संरचित ज्ञान ग्राफ़ बनाता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Méthode recommandée
uv tool install graphifyy &amp;amp;&amp;amp; graphify install --platform opencode

# Alternative avec pip
pip install graphifyy &amp;amp;&amp;amp; graphify install --platform opencode&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अपवादों_को_कॉन्फ़िगर_करें&quot;&gt;अपवादों को कॉन्फ़िगर करें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ाइल बनाएँ`.graphifyignore`परियोजना की जड़ पर व्यापारिक तर्क का हिस्सा न होने वाली फ़ाइलों को बाहर करने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-gitignore hljs&quot; data-lang=&quot;gitignore&quot;&gt;# Secrets — JAMAIS dans le graphe
*-context.yml
*.env

# Fichiers générés
build/
.gradle/

# Tests fonctionnels
src/functionalTest/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_knowledge_graph_निकालें&quot;&gt;Knowledge Graph निकालें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;graphify . --no-viz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;झंडा`--no-viz`यह HTML जनरेशन को छोड़ देता है (Gradle पाइपलाइन में अनुपयोगी)। परिणाम एक फ़ाइल है।`graphify-out/graph.json`شامل :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गाँठें&lt;/strong&gt;: क्लासेस, फ़ंक्शन, फ़ाइलें — उनके प्रकार और समुदाय के साथ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;किनारे&lt;/strong&gt;: नोड्स के बीच संबंध (EXTRACTED कोड से, INFERRED LLM द्वारा)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समुदाय&lt;/strong&gt;: जुड़े नोड्स के स्वचालित समूह&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;संरचना का उदाहरण`graph.json`&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;nodes&quot;: [
    {&quot;id&quot;: &quot;0&quot;, &quot;label&quot;: &quot;LlmService&quot;, &quot;file_type&quot;: &quot;code&quot;, &quot;community&quot;: 0},
    {&quot;id&quot;: &quot;1&quot;, &quot;label&quot;: &quot;ApiKeyPool&quot;, &quot;file_type&quot;: &quot;code&quot;, &quot;community&quot;: 0},
    {&quot;id&quot;: &quot;2&quot;, &quot;label&quot;: &quot;PlantumlService&quot;, &quot;file_type&quot;: &quot;code&quot;, &quot;community&quot;: 1}
  ],
  &quot;links&quot;: [
    {&quot;source&quot;: &quot;1&quot;, &quot;target&quot;: &quot;0&quot;, &quot;relation&quot;: &quot;uses&quot;, &quot;confidence&quot;: &quot;EXTRACTED&quot;, &quot;weight&quot;: 0.9},
    {&quot;source&quot;: &quot;0&quot;, &quot;target&quot;: &quot;2&quot;, &quot;relation&quot;: &quot;calls&quot;, &quot;confidence&quot;: &quot;INFERRED&quot;, &quot;weight&quot;: 0.7}
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;स्रोत कोड (&lt;code&gt;.kt&lt;/code&gt;, &lt;code&gt;.java&lt;/code&gt;) को tree-sitter द्वारा स्थानीय रूप से विश्लेषित किया जाता है,&lt;strong&gt;अपील रहित LLM&lt;/strong&gt;. केवल दस्तावेज़ फ़ाइलें (&lt;code&gt;.adoc&lt;/code&gt;, &lt;code&gt;.md`LLM को एक कॉल करने की आवश्यकता होती है समान्त्रिक निकासी के लिए। इसलिए&lt;/code&gt;--update`Kotlin कोड चलाना लगभग तात्कालिक है।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_2_ग्रैडल_प्लगिन_नॉलेज_ग्राफ_को_plantuml_में_बदलता_है&quot;&gt;चरण 2 : ग्रैडल प्लगिन नॉलेज ग्राफ को PlantUML में बदलता है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_पाइपलाइन_वास्तुकला&quot;&gt;पाइपलाइन वास्तुकला&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्लगइन`com.cheroliv.plantuml`एक कार्य को एकीकृत करता है`generateKnowledgeGraphDiagram`जो बदलता है`graph.json`PlantUML डायग्रामों के तरीके से&lt;strong&gt;पूरी तरह से निर्धारित&lt;/strong&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Gradle&quot; as G
participant &quot;ज्ञान ग्राफ़ आरेख कार्य उत्पन्न करें&quot; as Task
participant &quot;KnowledgeGraphParser&quot; as Parser
participant &quot;KnowledgeGraphRenderer&quot; as Renderer
participant &quot;PlantumlService&quot; as PS

collections &quot;graphify-out/graph.json&quot; as JSON

G -&amp;gt; Task : execute
Task -&amp;gt; JSON : read
Task -&amp;gt; Parser : parse(graph.json)
Parser --&amp;gt; Task : KnowledgeGraph\n(noeuds + arêtes + communautés)
Task -&amp;gt; Renderer : render(graph, filters)
Renderer --&amp;gt; Task : code PlantUML\n(déterministe)
Task -&amp;gt; PS : validateSyntax(plantumlCode)
alt syntaxe valide
    Task -&amp;gt; PS : generateImage → .png
else syntaxe invalide
    Task -&amp;gt; Task : save .puml avec warning
end

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_आंतरिक_घटक&quot;&gt;आंतरिक घटक&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;घटक&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;भूमिका&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;KnowledgeGraphParser&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;पार्स`graph.json`— 3 प्रारूपों का समर्थन करता है : graphify स्वदेशी (&lt;code&gt;nodes&lt;/code&gt;+&lt;code&gt;links&lt;/code&gt;), विरासत (&lt;code&gt;communities&lt;/code&gt;), समतल. संख्यात्मक IDs को लेबल में हल करता है।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;KnowledgeGraphRenderer&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक निर्धारित रूप से बदलता है`KnowledgeGraph`PlantUML कोड में। प्रकार के अनुसार समूह, पैकेज में समुदाय, स्वचालित लीजेंड।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;GenerateKnowledgeGraphDiagramTask&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Gradle टास्क जो आर्केस्ट्रेट करता है: parse → render → validate → PNG। Gradle गुणों के माध्यम से कॉन्फ़िगर किया जा सकता है।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kgmodels.kt&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डेटा मॉडल:`KnowledgeGraph`, &lt;code&gt;KnowledgeGraphNode&lt;/code&gt;, &lt;code&gt;KnowledgeGraphEdge&lt;/code&gt;, &lt;code&gt;KnowledgeGraphCommunity&lt;/code&gt;, &lt;code&gt;EdgeType&lt;/code&gt;.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;PlantumlService&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सिंटैक्स सत्यापन + PNG रेंडरिंग (प्लगिन के सभी कार्यों द्वारा पुन: उपयोग किया जाता है).&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रेंडरिंग_के_नियम&quot;&gt;रेंडरिंग के नियम&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;रेनडरर निर्धारित दृश्यात्मक सम्मेलन लागू करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;किनारे का प्रकार&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;नोटेशन PlantUML&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;अर्थ&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;निकाला&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;-&amp;#8594;&lt;/code&gt;(ठोस रेखा, काला)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;स्रोत कोड से निकाला गया संबंध (निश्चितता)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;निष्कर्षित&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;..&amp;gt;&lt;/code&gt;(बिंदु रेखा)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;LLM द्वारा अनुमानित संबंध (विश्वास स्कोर)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अस्पष्ट&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;--x&lt;/code&gt;(लाल बिंदीदार रेखा)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अस्पष्ट संबंध (जाँचने के लिए)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समुदायों को PlantUML पैकेज के रूप में प्रस्तुत किया जाता है, जिसमें स्वचालित रंग पैलेट होता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_3_दैनिक_उपयोग&quot;&gt;चरण 3 : दैनिक उपयोग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_पूर्ण_आलेख&quot;&gt;पूर्ण आलेख&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Générer le diagramme du Knowledge Graph complet
./gradlew generateKnowledgeGraphDiagram&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sortie : &lt;code&gt;diagrams/knowledge-graph/knowledge-graph-full.puml&lt;/code&gt;+&lt;code&gt;.png&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समुदाय_द्वारा_फ़िल्टर&quot;&gt;समुदाय द्वारा फ़िल्टर&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Une seule communauté
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.community=community_0

# Limiter le nombre de noeuds (lisibilité)
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.community=community_0 \
  -Pplantuml.kg.maxNodes=15&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_किनारा_प्रकार_द्वारा_फ़िल्टर_करें&quot;&gt;किनारा प्रकार द्वारा फ़िल्टर करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Uniquement les relations certaines (EXTRACTED)
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.edgeTypes=EXTRACTED

# Relations certaines + inférées
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.edgeTypes=EXTRACTED,INFERRED&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_नोड_के_प्रकार_और_विश्वास_द्वारा_फ़िल्टर_करें&quot;&gt;नोड के प्रकार और विश्वास द्वारा फ़िल्टर करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Uniquement les classes de code
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.nodeTypes=code

# Seuil de confiance minimum (pour les INFERRED)
./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.minConfidence=0.7&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_कस्टम_आउटपुट_डायरेक्टरी&quot;&gt;कस्टम आउटपुट डायरेक्टरी&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew generateKnowledgeGraphDiagram \
  -Pplantuml.kg.outputDir=docs/architecture&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_गुणों_का_पूर्ण_संदर्भ&quot;&gt;गुणों का पूर्ण संदर्भ&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;संपत्ति&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;दोष&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.community&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;em&gt;(सभी)&lt;/em&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नाम से समुदाय फ़िल्टर करें (उप-स्ट्रिंग मिलान)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.edgeTypes&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;(सभी)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;विराम चिह्न से अलग किए गए किनारों के प्रकार :`EXTRACTED`, &lt;code&gt;INFERRED&lt;/code&gt;, &lt;code&gt;AMBIGUOUS&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.minConfidence&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;0.0&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;किनारों के लिए न्यूनतम विश्वास सीमा&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.maxNodes&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;em&gt;(असीमित)&lt;/em&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नोड्स को दिखाने के लिए अधिकतम संख्या&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.nodeTypes&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;em&gt;(सभी)&lt;/em&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;विराम चिह्नों द्वारा अलग किए गए नोड्स के प्रकार (उदाहरण`class`, &lt;code&gt;code&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;plantuml.kg.outputDir&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;diagrams/knowledge-graph&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;फ़ाइलों के लिए आउटपुट निर्देशिका`.puml` et &lt;code&gt;.png&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पूर्ण_पाइपलाइन_एक_gradle_वर्कफ़्लो_में&quot;&gt;पूर्ण पाइपलाइन एक Gradle वर्कफ़्लो में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वर्कफ़्लो_प्रकार&quot;&gt;वर्कफ़्लो प्रकार&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam ActivityBackgroundColor #E8F4FD
skinparam ActivityDiamondBackgroundColor #FFF3CD
skinparam ActivityBorderColor #2C3E50

start

partition &quot;निष्कर्षण&quot; {
    :graphify . --no-viz;
    note right: Analyse le code source\ntree-sitter (local, pas de LLM)

    :graphify-out/graph.json;
    note right: Noeuds + arêtes\n+ communautés
}

partition &quot;पीढ़ी&quot; {
    :./gradlew generateKnowledgeGraphDiagram;
    note right: Pipeline déterministe\nparse → render → validate → PNG

    if (Filtres actifs ?) then (Oui)
        :Appliquer filtres\n(community, edgeTypes,\nmaxNodes, nodeTypes);
    else (Non)
        :Diagramme complet;
    endif

    :diagrams/knowledge-graph/\nknowledge-graph-full.puml\nknowledge-graph-full.png;
}

partition &quot;एकिकरण&quot; {
    :git add diagrams/knowledge-graph/;
    :git commit;
    note right: Diagrammes versionnés\ntoujours à jour avec le code
}

stop

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_विकास_चक्र_में_एकीकरण&quot;&gt;विकास चक्र में एकीकरण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पाइपलाइन विकास के मुख्य चरणों में स्वाभाविक रूप से एकीकृत होती है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

state &quot;विकास&quot; as dev
state &quot;निष्कर्षण
graphify . --no-viz&quot; as extract
state &quot;जेनरेशन
./gradlew generateKnowledgeGraphDiagram&quot; as generate
state &quot;Commit
संस्करणित आरेख&quot; as commit

[*] --&amp;gt; dev
dev --&amp;gt; extract : Code modifié
extract --&amp;gt; generate : graph.json à jour
generate --&amp;gt; commit : .puml + .png générés
commit --&amp;gt; dev : Diagrammes dans le repo

note right of extract
  Quasi instantané sur du code Kotlin
  (tree-sitter, pas de LLM)
end note

note right of generate
  Déterministe
  Pas de LLM
  Résultat reproductible
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वृद्धिशील_अद्ययन&quot;&gt;वृद्धिशील अद्ययन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब कोड बदलता है, हम पूरे ग्राफ़ को शून्य से फिर से नहीं बनाते :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Mise à jour incrémentale (fichiers modifiés uniquement)
graphify . --update

# Puis régénérer les diagrammes
./gradlew generateKnowledgeGraphDiagram&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;--update`पुनः केवल संशोधित फ़ाइलों को निकालता है (SHA256 द्वारा पता लगाए गए`graphify-out/cache/&lt;/code&gt;). कोटलिन कोड पर, यह लगभग तत्काल होता है क्योंकि ट्री-सिटर स्थानीय रूप से काम करता है बिना किसी LLM कॉल के।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_डॉगफ़ूडिंग_प्लगइन_स्वयं_का_दस्तावेज़_बनाता_है&quot;&gt;डॉगफ़ूडिंग: प्लगइन स्वयं का दस्तावेज़ बनाता है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;PlantUML प्लगिन प्रॉम्प्ट को आरेख में बदलने के लिए मौजूद है। वह अपने &lt;em&gt;propre&lt;/em&gt; कोडबेस का ज्ञान ग्राफ भी दस्तावेज़ीकरण आरेखों में बदल सकता है। यह &lt;em&gt;dogfooding&lt;/em&gt; है: प्लगिन अपनी स्वयं की सेवा का उपभोग करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;सामान्य पाइपलाइन\n(उपयोगकर्ता → आरेख)&quot; as normal {
    [Fichier .prompt] as prompt
    [LlmService\n+ ApiKeyPool] as llm1
    [ProcessPlantumlPromptsTask] as task1
    [Diagramme PNG] as out1

    prompt --&amp;gt; task1
    task1 --&amp;gt; llm1
    llm1 --&amp;gt; out1
}

package &quot;पाइपलाइन नॉलेज ग्राफ
(निर्धारित, कोई LLM नहीं)&quot; as kg {
    [graphify-out/graph.json] as kgjson
    [KnowledgeGraphParser] as parser
    [KnowledgeGraphRenderer] as renderer
    [PlantumlService] as ps
    [Diagramme PNG\n(documentation du plugin)] as out2

    kgjson --&amp;gt; parser
    parser --&amp;gt; renderer
    renderer --&amp;gt; ps
    ps --&amp;gt; out2
}

package &quot;Pipeline Dogfooding
(LLM → प्लगइन की दस्तावेज़ीकरण)&quot; as dogfood {
    [GraphifyPromptAdapter] as gpa
    [Fichiers .prompt\nauto-générés] as auto_prompt
    [LlmService\n+ ApiKeyPool] as llm2
    [ProcessPlantumlPromptsTask] as task2
    [Diagramme PNG\n(documentation LLM)] as out3

    kgjson --&amp;gt; gpa
    gpa --&amp;gt; auto_prompt
    auto_prompt --&amp;gt; task2
    task2 --&amp;gt; llm2
    llm2 --&amp;gt; out3
}

note &quot;एक ही LlmService, एक ही ApiKeyPool,
एक ही PlantumlService
— शून्य डुप्लीकेशन&quot; as N

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle से संबंधित कार्य :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;कार्य&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;LLM ?&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;generateKnowledgeGraphDiagram&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नहीं&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;parivartit kar`graph.json`में PlantUML (निर्धारित)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;generateDiagramDocs&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;हाँ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जनरेट करो`.prompt`ग्राफ़ से, उन्हें LLM के माध्यम से (dogfooding) से संसाधित किया जाता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Documentation déterministe (rapide, pas de LLM)
./gradlew generateKnowledgeGraphDiagram

# Documentation LLM (plus riche, consomme des tokens)
./gradlew generateDiagramDocs&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_यह_निर्धारित_क्यों_है_और_यह_क्यों_मायने_रखता_है&quot;&gt;यह निर्धारित क्यों है (और यह क्यों मायने रखता है)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पाइपलाइन का मुख्य बिंदु`generateKnowledgeGraphDiagram`:&lt;strong&gt;वह कोई LLM नहीं बुलाता&lt;/strong&gt;. परिवर्तन`graph.json`→ PlantUML एक शुद्ध फ़ंक्शन है.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

rectangle &quot;निर्धारित पाइपलाइन
(generateKnowledgeGraphDiagram)&quot; as det {
    [graph.json] as json
    [KnowledgeGraphParser] as parser
    [KnowledgeGraphRenderer] as renderer
    [PlantUML code] as puml

    json --&amp;gt; parser : parse
    parser --&amp;gt; renderer : KnowledgeGraph
    renderer --&amp;gt; puml : render (fonction pure)
}

rectangle &quot;पाइपलाइन LLM
(processPlantumlPrompts)&quot; as llm {
    [.prompt] as prompt
    [LlmService] as llmSvc
    [ChatModel] as model
    [PlantUML code] as puml2

    prompt --&amp;gt; llmSvc
    llmSvc --&amp;gt; model : API call
    model --&amp;gt; puml2 : réponse non-déterministe
}

note bottom of det
  Même entrée → même sortie
  Pas de latence réseau
  Pas de coût en tokens
  Reproductible en CI
end note

note bottom of llm
  Même entrée → sortie variable
  Latence réseau (1-5s)
  Coût en tokens
  Nécessite une clave API
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;वास्तविक लाभ :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;फायदा&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;प्रभाव&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;पुनरावृत्ति&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;समान`graph.json`→ समान आरेख। सही है। हर बार।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;शून्य लागत&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कोई LLM कॉल नहीं = कोई टोकन नहीं = कोई API बिल नहीं।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;शून्य विलंब&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Parse + render लगभग 100ms लेता है, 1-5 सेकंड नहीं।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;संगत CI&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;API कुंजी आवश्यक नहीं है. चर LLM प्रतिक्रिया के कारण कोई अस्थिर परीक्षण नहीं.&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;संस्करणयोग्य&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Le &lt;code&gt;.puml`उत्पन्न पाठ है। हम इसे`diff&lt;/code&gt;, PR में रिव्यूअर, Git में संस्करणित करना।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पाइपलाइन_के_स्वयं_के_आरेख&quot;&gt;पाइपलाइन के स्वयं के आरेख&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लूप को बंद करने के लिए, यहाँ प्लगइन द्वारा उत्पन्न किया जाने वाला पाइपलाइन आरेख है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;डेवलपर&quot; as Dev
participant &quot;ग्रैडल&quot; as G
participant &quot;ज्ञान ग्राफ़ आरेख कार्य उत्पन्न करें&quot; as Task
participant &quot;KnowledgeGraphParser&quot; as Parser
participant &quot;KnowledgeGraphRenderer&quot; as Renderer
participant &quot;PlantumlService&quot; as PS
collections &quot;graphify-out/graph.json&quot; as JSON
collections &quot;आरेख/ज्ञान-ग्राफ/&quot; as Out

Dev -&amp;gt; G : ./gradlew generateKnowledgeGraphDiagram
G -&amp;gt; Task : execute
Task -&amp;gt; JSON : read
Task -&amp;gt; Parser : parse(graph.json)
Parser --&amp;gt; Task : KnowledgeGraph

alt filtres actifs
    Task -&amp;gt; Task : appliquer filtres\n(community, edgeTypes, maxNodes…)
end

Task -&amp;gt; Renderer : render(graph, filters)
Renderer --&amp;gt; Task : code PlantUML

Task -&amp;gt; PS : validateSyntax()
alt valide
    Task -&amp;gt; PS : generateImage()
    PS --&amp;gt; Out : .puml + .png
else invalide
    Task -&amp;gt; Out : .puml (avec warning)
end

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परियोजना_शासन_में_एकीकरण&quot;&gt;परियोजना शासन में एकीकरण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारे प्रोजेक्ट में, यह पाइपलाइन AI एजेंट के लिए EAGER/LAZY संदर्भ प्रबंधन रणनीति में एकीकृत है। नॉलेज ग्राफ़ मैनुअल आर्किटेक्चर दस्तावेज़ीकरण को एक संरचित, क्वेरी करने योग्य और स्वचालित रूप से अद्यतन किए जाने वाले ग्राफ से बदल देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;इच्छुक
(हमेशा चार्ज)&quot; as eager {
    [PROMPT_REPRISE.adoc\n(contexte session)] as pr
    [INDEX.adoc\n(vue d&#39;ensemble)] as idx
    [GRAPH_REPORT.adoc\n(~50 lignes)] as gr
}

package &quot;LAZY — रणनीति
(अनुरोध पर)&quot; as lazy_strat {
    [Méthodologies] as meth
    [Archives sessions] as sessions
}

package &quot;LAZY — Graphify\n(लक्षित प्रश्न)&quot; as lazy_graph {
    [graph.json] as gj
    [Queries\n(query/path/explain)] as queries
}

package &quot;Pipeline PlantUML\n(स्वचालित रूप से उत्पन्न)&quot; as puml {
    [generateKnowledgeGraphDiagram] as kgTask
    [generateDiagramDocs] as ddTask
    [Diagrammes PNG] as diagrams
}

Agent --&amp;gt; eager : Lit en début de session
Agent ..&amp;gt; lazy_strat : Charge si type détecté
Agent ..&amp;gt; lazy_graph : Query si besoin structurel
kgTask --&amp;gt; diagrams : Déterministe
ddTask --&amp;gt; diagrams : Via LLM

note right of gr
  Condensé du Knowledge Graph
  God nodes + communautés
  Remplace ECOSYSTEM_OVERVIEW
  (225 lignes → 50 lignes)
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;दो प्रणालियों का संयोजन पूरक है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;रणनीति कब और कैसे को प्रबंधित करती है&lt;/strong&gt;— शासन, वर्कफ़्लो, संग्रहण&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Graphify QUOI और OÙ को प्रबंधित करता है&lt;/strong&gt;— कोड संरचना, संबंध, लक्षित प्रश्न&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ सत्र रणनीति प्रबंधित करती है&lt;strong&gt;जब&lt;/strong&gt; et le &lt;strong&gt;कैसे&lt;/strong&gt;(शासन, वर्कफ़्लो, सीमाएँ), Graphify इसे प्रबंधित करता है&lt;strong&gt;क्या&lt;/strong&gt; et le &lt;strong&gt;कहाँ&lt;/strong&gt;(कोड की संरचना, संबंध, लक्षित क्वेरी). PlantUML पाइपलाइन इसे प्रबंधित करती है&lt;strong&gt;क्या के साथ?&lt;/strong&gt;(निर्धारित आरेख, संस्करणित, हमेशा अद्यतन) &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्थापना_5_मिनट_की_चेकलिस्ट&quot;&gt;स्थापना : 5 मिनट की चेकलिस्ट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;#&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;चरण&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;आदेश&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Graphify इंस्टॉल करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;uv tool install graphifyy&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अपवादों को कॉन्फ़िगर करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बनाना`.graphifyignore`&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;3&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Knowledge Graph निकालें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;graphify . --no-viz&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;4&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डायग्राम्स बनाएँ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;./gradlew generateKnowledgeGraphDiagram&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;5&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;परिणामों को कमिट करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;git add diagrams/knowledge-graph/&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Script complet en 5 commandes
uv tool install graphifyy
cat &amp;gt; .graphifyignore &amp;lt;&amp;lt; &#39;EOF&#39;
*-context.yml
*.env
build/
.gradle/
EOF
graphify . --no-viz
./gradlew generateKnowledgeGraphDiagram
git add graphify-out/GRAPH_REPORT.adoc graphify-out/graph.json diagrams/knowledge-graph/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_जाल_और_निवारण_उपाय&quot;&gt;जाल और निवारण उपाय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;जाल&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;शमन&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बहुत घना ग्राफ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक बड़ा प्रोजेक्ट सैकड़ों अपठनीय नोड्स उत्पन्न करता है&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;उपयोग करना`-Pplantuml.kg.maxNodes=30`और समुदाय द्वारा फ़िल्टर&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बहुत व्यापक अपवाद&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बहुत सारी फ़ाइलों में`.graphifyignore`ग्राफ़ का मूल्य कम करता है&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सिर्फ credentials और build को बाहर रखना शुरू करें&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;तीरों की दिशा&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;किनारों INFERRED की दिशा अस्पष्ट हो सकती है&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;फ़िल्टर द्वारा`-Pplantuml.kg.edgeTypes=EXTRACTED`केवल कुछ संबंधों के लिए&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अप्रचलित ग्राफ़&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कोड बदलता है लेकिन ग्राफ़ को पुनः नहीं बनाया जाता&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;उपयोग करना`graphify . --update`नियमित रूप से या git हुक`graphify hook install`&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;संशोधित लागत&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;इन्क्रीमेंटल अपडेट लगभग निःशुल्क हैं (ट्री‑सिटर स्थानीय)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;केवल दस्तावेज़ (&lt;code&gt;.adoc&lt;/code&gt;) वे LLM टोकन की खपत करते हैं&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अंत_में_हमें_क्या_प्राप्त_होता_है&quot;&gt;अंत में हमें क्या प्राप्त होता है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;पहले&quot; as avant {
    card &quot;हाथ से बने आरेख
हमेशा अप्रचलित
कोई भी उन्हें अपडेट नहीं करता&quot; as av1 #FDEDEC
}

rectangle &quot;बाद&quot; as apres {
    card &quot;स्वचालित रूप से उत्पन्न आरेख
कोड के साथ हमेशा अद्यतित
गिट में संस्करणबद्ध
निर्धारितीय और पुनः उत्पादन योग्य&quot; as ap1 #E8F8E8
}

avant --&amp;gt; apres : graphify . --no-viz\n+ ./gradlew generateKnowledgeGraphDiagram

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;वास्तविक लाभ :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;लाभ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;हमेशा अद्यतन दस्तावेज़&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डायग्राम वर्तमान कोड को दर्शाते हैं, एक मैनुअल स्नैपशॉट नहीं&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;शून्य रखरखाव प्रयास&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डायग्राम प्रत्येक बिल्ड पर पुन: बनते हैं&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;तकनीकी ऋण में कमी&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अब डायग्राम को मैन्युअली बनाए रखने की आवश्यकता नहीं है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नए के लिए दृश्य संदर्भ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक नया डेवलपर आर्किटेक्चर को देखकर समझता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Fine-tuning संभाव्य&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जोड़े (उप-ग्राफ़ → आरेख) एआई प्रशिक्षण के उदाहरण हैं&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;स्वचालित सत्यापन&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`PlantumlService.validateSyntax()`प्रत्येक उत्पन्न आरेख की जाँच करता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;तेज़ ओनबोर्डिंग&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;5 आरेख = वास्तुकला का पूर्ण दृश्य&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ जिसके पास एक _pourquoi&lt;/em&gt; है, वह सभी &lt;em&gt;comment&lt;/em&gt; को सह सकता है। &lt;/em&gt;__&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्यों &lt;em&gt;pourquoi&lt;/em&gt; : हमेशा अप-टू-डेट डायग्राम। कैसे &lt;em&gt;comment&lt;/em&gt; : Gradle पाइपलाइन में दो कमांड।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
