&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जाल_और_सामान्य_त्रुटियाँ&quot;&gt;जाल और सामान्य त्रुटियाँ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ctrlz_और_ctrlc_को_भ्रमित_करना&quot;&gt;Ctrl+Z और Ctrl+C को भ्रमित करना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जॉब्स_शेल_के_लिए_स्थानीय_होते_हैं&quot;&gt;जॉब्स शेल के लिए स्थानीय होते हैं&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जॉब्स_शेल_बंद_होने_पर_जीवित_नहीं_रहते&quot;&gt;जॉब्स शेल बंद होने पर जीवित नहीं रहते।&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_इंटरएक्टिव_प्रक्रियाएँ_और_fg&quot;&gt;इंटरएक्टिव प्रक्रियाएँ और fg&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सारांश_आरेख&quot;&gt;सारांश आरेख&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fg_क्यों_कम_आंका_गया&quot;&gt;fg क्यों कम आंका गया&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_generate_the_site_jbake_b_3&quot;&gt;Bake (generate) the site jbake -b&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_serve_locally_jbake_b_s_3&quot;&gt;Bake and serve locally jbake -b -s&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_watch_for_changes_jbake_b_reset_3&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_specify_source_and_destination_jbake_source_folder_output_folder_3&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_clear_the_output_directory_before_baking_jbake_b_output_reset_है&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt; है :&lt;/a&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_तकनीकी_ज्ञापन_संकेत&quot;&gt;तकनीकी ज्ञापन : संकेत&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ&quot;&gt;संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;पढ़ने का समय : 10 minutes&lt;/div&gt;
&lt;p&gt;आप फेंकते हैं`./gradlew build`, टर्मिनल 3 मिनट के लिए ब्लॉक किया गया है, और आपको कुछ और करने की आवश्यकता है &lt;em&gt;en attendant&lt;/em&gt; ? नए टैब खोलने की आवश्यकता नहीं है.`Ctrl+Z`प्रक्रिया को सस्पेंड करें`fg`इसे बिल्कुल वहीं लाया जाता है जहाँ आपने उसे छोड़ा था। यह डेवलपर के दैनिक जीवन का सबसे कम आंका जाने वाला यूनिक्स टिप है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;सामग्री की तालिका&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_एक_व्यस्त_टर्मिनल&quot;&gt;समस्या : एक व्यस्त टर्मिनल&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हर डेवलपर ने इस स्थिति को अनुभव किया है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build
&amp;gt; Building...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और आपको एक फ़ाइल देखनी है, एक लॉन्च करना है`git status`, या एक व्यस्त पोर्ट की जांच करें।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

actor Développeur as dev
participant &quot;टर्मिनल&quot; as term
participant &quot;Gradle
( प्रक्रिया )&quot; as gradle

dev -&amp;gt; term : ./gradlew build
term -&amp;gt; gradle : Lance le build
gradle -&amp;gt; term : Occupe le terminal\n(pas de prompt)
dev -&amp;gt; term : veut taper une commande
term --&amp;gt; dev : ❌ Terminal bloqué

note right of dev
  Le développeur est
  paralysé pendant
  toute la durée du build
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अधिकांश डेवलपर्स एक नया टर्मिनल खोलते हैं। लेकिन एक अधिक सुंदर, तेज़ और मूल समाधान मौजूद है: जॉब प्रबंधन।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_तीन_अनिवार्य_आदेश&quot;&gt;तीन अनिवार्य आदेश&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ctrlz_रोकें_sigtstp&quot;&gt;Ctrl+Z — रोकें (SIGTSTP)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`Ctrl+Z`सिग्नल भेजो`SIGTSTP`अग्रभूमि प्रक्रिया में. प्रक्रिया है&lt;strong&gt;निलंबित&lt;/strong&gt;— नहीं मारा गया — और टर्मिनल अपना प्रॉम्प्ट फिर से प्राप्त करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build
&amp;gt; Building...
^Z
[1]+  Stoppé    ./gradlew build
$&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कोष्ठकों के बीच की संख्या`[1]` est le &lt;strong&gt;जॉब नंबर&lt;/strong&gt;. Le `+`डिफ़ॉल्ट जॉब को दर्शाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fg_अग्रभूमि_में_लाएँ&quot;&gt;fg — अग्रभूमि में लाएँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fg`यह निलंबित कार्य को अग्रभूमि में लाता है। प्रक्रिया ठीक उसी स्थान से फिर से शुरू हो जाती है जहाँ वह रुकी थी।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ fg
./gradlew build
&amp;gt; Building... (reprend où il en était)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक विशिष्ट जॉब नंबर के साथ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ fg %2&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bg_पृष्ठभूमि_में_जारी_रखना&quot;&gt;bg — पृष्ठभूमि में जारी रखना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`bg`प्रक्रिया को टर्मिनल ब्लॉक किए बिना फिर से शुरू करता है। लंबे बील्ड्स के लिए आदर्श।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ bg
[1]+ ./gradlew build &amp;amp;
$&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le `&amp;amp;`अंत में इसका मतलब है कि प्रक्रिया बैकग्राउंड में चल रही है.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jobs_शेल_के_कार्यों_को_सूचीबद्ध_करना&quot;&gt;jobs — शेल के कार्यों को सूचीबद्ध करना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ jobs
[1]-  Stoppé    vim README.md
[2]+  En cours   ./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

state &quot;अग्रभूमि\n(ब्लॉक्ड टर्मिनल)&quot; as fg #LightCoral
state &quot;निलंबित
(Ctrl+Z)&quot; as stopped #LightYellow
state &quot;पृष्ठभूमि\n(bg)&quot; as bg_ #LightGreen

[*] --&amp;gt; fg : Lance une commande
fg --&amp;gt; stopped : Ctrl+Z\n(SIGTSTP)
stopped --&amp;gt; fg : fg\nreprend en avant-plan
stopped --&amp;gt; bg_ : bg\nreprend en arrière-plan
bg_ --&amp;gt; fg : fg\nramène en avant-plan
fg --&amp;gt; [*] : Commande terminée

note right of stopped
  Le processus est figé
  mais _pas_ tué
end note

note left of bg_
  Le terminal est libre
  le build continue
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिदृश्य_1_लंबा_बिल्ड&quot;&gt;परिदृश्य 1 : लंबा बिल्ड&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह सबसे सामान्य उपयोग का मामला है। आप एक Gradle बिल्ड शुरू करते हैं, टर्मिनल ब्लॉक हो जाता है, और आपको कुछ अन्य करने की आवश्यकता होती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;टर्मिनल&quot; as term
participant &quot;Gradle&quot; as gradle
database &quot;स्थिति
प्रक्रिया&quot; as state

dev -&amp;gt; term : ./gradlew build
term -&amp;gt; gradle : Lance le build
gradle -&amp;gt; state : En cours (FG)
dev -&amp;gt; term : Ctrl+Z
term -&amp;gt; state : Suspendu (job [1])
term --&amp;gt; dev : Prompt libre $

dev -&amp;gt; term : git status
term --&amp;gt; dev : working tree clean

dev -&amp;gt; term : fg
term -&amp;gt; state : Reprend (FG)
gradle --&amp;gt; dev : Build réussi ✓

note right of state
  Le processus Gradle
  n&#39;a jamais été tué
  Il reprend exactement
  où il s&#39;était arrêté
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_दर_चरण&quot;&gt;चरण-दर-चरण&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build
&amp;gt; Building...
^Z
[1]+  Stoppé    ./gradlew build

$ git status
On branch main
nothing to commit, working tree clean

$ fg
./gradlew build
&amp;gt; Building...
BUILD SUCCESSFUL in 2m 34s&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्केनेरियो_2_भुला_हुआ_संपादक&quot;&gt;स्केनेरियो 2: भुला हुआ संपादक&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आप में हैं`vim`, आपको किसी अन्य फ़ाइल को देखना है बिना बाहर निकले`vim`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Dans vim, en mode commande :
:shell
$ cat /path/to/other/file.txt
$ exit
# Retour dans vim&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लेकिन यह भारी है। के साथ`Ctrl+Z`, यह तुरंत है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Dans vim, n&#39;importe quel moment :
Ctrl+Z
[1]+  Stoppé    vim README.md

$ cat /path/to/other/file.txt
# ... lire le fichier ...

$ fg
vim README.md
# Retour exact là où on en était, curseur en place&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;vim&quot; as vim
participant &quot;शेल&quot; as shell

dev -&amp;gt; vim : édition en cours
dev -&amp;gt; vim : Ctrl+Z
vim -&amp;gt; shell : Suspendu (job [1])
dev -&amp;gt; shell : cat autre_fichier.txt
shell --&amp;gt; dev : contenu du fichier
dev -&amp;gt; shell : fg
shell -&amp;gt; vim : Reprend (job [1])
vim --&amp;gt; dev : Curseur exactement\nà la même position

note right of vim
  vim restaure
  intégralement l&#39;état :
  position du curseur,
  buffer, undo stack
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt; (No output)&lt;code&gt;vim`यह अपनी स्थिति को पूरी तरह से बहाल करता है एक`fg&lt;/code&gt;: कर्सर की स्थिति, बफ़र की सामग्री, अनडू इतिहास — सब कुछ संरक्षित है.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिदृश्य_3_opencode_प्रक्रिया_निलंबित&quot;&gt;परिदृश्य 3: opencode प्रक्रिया निलंबित&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह वह परिदृश्य है जिसने इस लेख को प्रेरित किया। आप उपयोग कर रहे हैं`opencode`(CLI टूल आपके कोड पर एक LLM को नियंत्रित करने के लिए), और प्रक्रिया निलंबित है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam componentStyle rectangle

actor Développeur as dev
participant &quot;opencode
(LLM एजेंट)&quot; as agent
participant &quot;शेल&quot; as shell
participant &quot;गिट&quot; as git

dev -&amp;gt; agent : Session active
agent -&amp;gt; agent : Tour de parole\ndu LLM en cours

note over agent
  Ctrl+Z arrive
  en plein milieu
  d&#39;une analyse de code
end note

dev -&amp;gt; agent : Ctrl+Z
agent -&amp;gt; shell : Suspendu (job [1])
dev -&amp;gt; git : git diff
git --&amp;gt; dev : changements visibles
dev -&amp;gt; shell : fg
shell -&amp;gt; agent : Reprend (job [1])
agent --&amp;gt; dev : Reprend exactement\nl&#39;analyse en cours

note right of agent
  Aucune perte de contexte
  Le LLM reprend sa réponse
  exactement où il en était
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ opencode
# ... session en cours, LLM analyse le code ...
^Z
[1]+  Stoppé    opencode

$ git diff HEAD~1
# vérifier les changements récents

$ fg
opencode
# Le LLM reprend là où il s&#39;était arrêté&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ायदा दोगुना है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;कोई संदर्भ हानि नहीं&lt;/strong&gt;LLM सत्र, वार्तालाप का इतिहास, खुले फ़ाइलें — सब कुछ संरक्षित है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;रीबूट नहीं&lt;/strong&gt;: opencode को पुनः प्रारंभ करने की आवश्यकता नहीं है, संदर्भ को पुनः लोड करने की आवश्यकता नहीं है, LLM को समस्या की पुनः व्याख्या करने की आवश्यकता नहीं है&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिदृश्य_4_कई_जॉब्स_को_एक_साथ_प्रबंधित_करें&quot;&gt;परिदृश्य 4: कई जॉब्स को एक साथ प्रबंधित करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;fg&lt;/code&gt; et `bg`वे एक जॉब नंबर स्वीकार करते हैं एक विशेष प्रक्रिया को लक्ष्य करने के लिए जब कई निलंबित हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ vim config.yml
^Z
[1]+  Stoppé    vim config.yml

$ ./gradlew test
^Z
[2]+  Stoppé    ./gradlew test

$ htop
^Z
[3]+  Stoppé    htop

$ jobs
[1]   Stoppé    vim config.yml
[2]-  Stoppé    ./gradlew test
[3]+  Stoppé    htop

$ fg %2
./gradlew test
# Le build reprend en avant-plan

$ bg %3
[3] htop &amp;amp;
# htop reprend en arrière-plan&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;बाधित नौकरियाँ&quot; as jobs #LightYellow {
  card &quot;[1] vim config.yml&quot; as j1
  card &quot;[2] ./gradlew test&quot; as j2
  card &quot;[3] htop&quot; as j3
}

rectangle &quot;क्रियाएँ&quot; as actions #LightGreen {
  card &quot;fg %2\n→ अग्रभूमि&quot; as a1
  card &quot;bg %3\n→ पृष्ठभूमि&quot; as a2
  card &quot;fg %1\n→ अग्रभूमि&quot; as a3
}

jobs --&amp;gt; actions : fg/bg + numéro de job
actions --&amp;gt; j2 : Reprend
actions --&amp;gt; j3 : En arrière-plan

note bottom of jobs
  Chaque job conserve
  son état exact
  entre les suspend/resume
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_कार्यों_के_आदेशों_का_सारांश&quot;&gt;कार्यों के आदेशों का सारांश&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;आदेश&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;प्रभाव&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;उदाहरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+Z&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;प्रक्रिया को अग्रभूमि में निलंबित करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;भेजने का`SIGTSTP`&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;fg&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डिफ़ॉल्ट जॉब को फ़ोरग्राउंड में फिर से शुरू करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;fg&lt;/code&gt; ou &lt;code&gt;fg %1&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;fg %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जॉब अग्रभूमि में फिर से शुरू करता है&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;fg %2&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;bg&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;डिफ़ॉल्ट जॉब को पृष्ठभूमि में फिर से शुरू करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;bg&lt;/code&gt; ou &lt;code&gt;bg %1&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;bg %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;न के जॉब को पृष्ठभूमि में फिर से शुरू करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;bg %2&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;jobs&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;वर्तमान शेल के कार्यों की सूची बनाएँ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;jobs -l&lt;/code&gt;(PID के साथ)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kill %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;job completo करो n&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kill %2&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fg_bg_ctrlz_ctrlc_और_के_अंतर&quot;&gt;fg, bg, Ctrl+Z, Ctrl+C और &amp;amp; के अंतर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बहुत से डेवलपर्स इन तंत्रों को भ्रमित करते हैं। यहाँ एक निर्णायक स्पष्टीकरण दिया गया है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;**Ctrl+Z**\nSIGTSTP&quot; as ctrlz #LightYellow {
  card &quot;प्रक्रिया को निलंबित करें
(यह अभी भी मेमोरी में है)
fg/bg के साथ उपयोग करने योग्य&quot; as c1
}

rectangle &quot;**Ctrl+C**\nSIGINT&quot; as ctrlc #LightCoral {
  card &quot;प्रक्रिया को मारें
(वापसी संभव नहीं)
सभी स्थिति की हानि&quot; as c2
}

rectangle &quot;**&amp;amp; **\n(पृष्ठभूमि)&quot; as ampersand #LightGreen {
  card &quot;सीधे लॉन्च करें
पृष्ठभूमि में
तुरंत मुक्त टर्मिनल&quot; as c3
}

rectangle &quot;**fg**\n(अग्रभूमि)&quot; as fg_ #SkyBlue {
  card &quot;एक जॉब लाओ
फॉरग्राउंड में सस्पेंडेड
टर्मिनल व्यस्त&quot; as c4
}

rectangle &quot;**bg**\n(पृष्ठभूमि)&quot; as bg_ #Lavender {
  card &quot;एक काम फिर से शुरू
पृष्ठभूमि में निलंबित
मुक्त टर्मिनल&quot; as c5
}

ctrlz -right-&amp;gt; fg_ : fg pour reprendre
ctrlz -right-&amp;gt; bg_ : bg pour continuer\nen arrière-plan
ctrlc -right-&amp;gt; c2 : Pas de retour\nprocessus tué

note bottom of ctrlz
  Le processus est **figé**
  mais **pas tué**
end note

note bottom of ampersand
  Alternative : lancer
  ./gradlew build &amp;amp;
  directement en arrière-plan
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 16.6666%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 16.6666%;&quot;&gt;
&lt;col style=&quot;width: 33.3335%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;शॉर्टकट/कमांड&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;सिग्नल&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;प्रभाव&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;वापस लौटना?&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+Z&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGTSTP&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;प्रक्रिया को निलंबित करें (जमा, मेमोरी में)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;हाँ :`fg` ou &lt;code&gt;bg&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+C&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGINT&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;प्रक्रिया को मारें (समाप्त)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नहीं: नष्ट प्रक्रिया&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+\&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGQUIT&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;प्रक्रिया मारो + core dump&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नहीं : नष्ट प्रक्रिया&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;commande &amp;amp;&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;(No output)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बैकग्राउंड में सीधे लॉन्च करें&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`fg`इसे सामने लाने के लिए&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;admonitionblock tip&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-tip&quot; title=&quot;Tip&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;code&gt;Ctrl+Z`JBake संदर्भ (यह सामग्री JBake टेम्प्लेट और कन्वेंशन का उपयोग करती है): &lt;mark&gt;#&lt;/mark&gt; JBake CLI कमांड ``&lt;/code&gt; # Initialize a new JBake project jbake -i
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h1 id=&quot;_bake_generate_the_site_jbake_b&quot; class=&quot;sect0&quot;&gt;Bake (generate) the site jbake -b&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_serve_locally_jbake_b_s&quot; class=&quot;sect0&quot;&gt;Bake and serve locally jbake -b -s&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_watch_for_changes_jbake_b_reset&quot; class=&quot;sect0&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/h1&gt;

&lt;h1 id=&quot;_specify_source_and_destination_jbake_source_folder_output_folder&quot; class=&quot;sect0&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/h1&gt;

&lt;h1 id=&quot;_clear_the_output_directory_before_baking_jbake_b_output_resetगैर_विध्वंसक_jbake_cli_commands_initialize_a_new_jbake_project_jbake_i&quot; class=&quot;sect0&quot;&gt;Clear the output directory before baking jbake -b . output --reset&lt;strong&gt;गैर-विध्वंसक&lt;/strong&gt;&lt;mark&gt;#&lt;/mark&gt; JBake CLI Commands &lt;code&gt;`&lt;/code&gt; # Initialize a new JBake project jbake -i&lt;/h1&gt;

&lt;h1 id=&quot;_bake_generate_the_site_jbake_b_2&quot; class=&quot;sect0&quot;&gt;Bake (generate) the site jbake -b&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_serve_locally_jbake_b_s_2&quot; class=&quot;sect0&quot;&gt;Bake and serve locally jbake -b -s&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_watch_for_changes_jbake_b_reset_2&quot; class=&quot;sect0&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/h1&gt;

&lt;h1 id=&quot;_specify_source_and_destination_jbake_source_folder_output_folder_2&quot; class=&quot;sect0&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/h1&gt;

&lt;h1 id=&quot;_clear_the_output_directory_before_baking_jbake_b_output_reset&quot; class=&quot;sect0&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt;&lt;/h1&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;fr से hi में अनुवाद करें सभी बैकटिक कोड स्पैन (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) को बिल्कुल वैसा ही रखें — बैकटिक की सामग्री, स्पेसिंग, या स्थिति कभी न बदलें। यह पाठ बड़े वाक्य का एक अंश हो सकता है — अंश का अनुवाद अधिक संदर्भ मांगे बिना करें। केवल अनुवादित पाठ आउटपुट करें — कोई स्पष्टीकरण, कोई टिप्पणी, कोई परिचय, कोई विकल्प, कोई विकल्प नहीं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;प्रक्रिया स्मृति में वैसे ही स्थिर है। आप तुरंत इसे जारी रख सकते हैं`fg`. यह एक &lt;em&gt;pause&lt;/em&gt; है, एक &lt;em&gt;stop&lt;/em&gt; नहीं.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक_जॉब_का_पूरा_जीवन_चक्र&quot;&gt;एक जॉब का पूरा जीवन चक्र&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

title शेल जॉब का पूर्ण जीवन चक्र
state &quot;अस्तित्वहीन&quot; as none
state &quot;अग्रभूमि
(टर्मिनल को घेरता है)&quot; as foreground #LightCoral
state &quot;निलंबित\n(Ctrl+Z / SIGTSTP)&quot; as suspended #LightYellow
state &quot;पृष्ठभूमि\n(bgまたは &amp;amp;)&quot; as background #LightGreen
state &quot;समाप्त
(exit code 0)&quot; as done #LightGray

[*] --&amp;gt; none
none --&amp;gt; foreground : tape une commande
foreground --&amp;gt; suspended : Ctrl+Z
foreground --&amp;gt; done : fin normale

suspended --&amp;gt; foreground : fg
suspended --&amp;gt; background : bg
suspended --&amp;gt; done : kill %n

background --&amp;gt; foreground : fg
background --&amp;gt; done : fin normale\n(en arrière-plan)
background --&amp;gt; suspended : Ctrl+Z\n(si fg puis Ctrl+Z)

done --&amp;gt; [*]

note right of suspended
  L&#39;état suspendu est
  le pivot de tout le
  système de jobs
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_उन्नत_टिप्स&quot;&gt;उन्नत टिप्स&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fg_नौकरी_के_साथ_सबसे_नया_और_अल्टरनेन्स&quot;&gt;fg नौकरी के साथ सबसे नया और अल्टरनेन्स&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;fg`कोई तर्क नहीं होने पर चिह्नित काम लौटाता है&lt;/code&gt;+&lt;code&gt;(सबसे हालिया). लेकिन आप भी इसका उपयोग कर सकते हैं&lt;/code&gt;%-`पिछले जॉब को लक्ष्य करने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ vim file1.txt
^Z
[1]+  Stoppé    vim file1.txt

$ vim file2.txt
^Z
[2]+  Stoppé    vim file2.txt

$ fg      # ramène job [2] (le plus récent)
$ fg %-   # ramène job [1] (le précédent)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_काम_को_सही_तरीके_से_पूरा_करना&quot;&gt;काम को सही तरीके से पूरा करना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ jobs
[1]-  Stoppé    vim config.yml
[2]+  Stoppé    ./gradlew test

$ kill %2       # envoie SIGTERM au job 2
$ kill -9 %1    # envoie SIGKILL au job 1 (force)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_désown_शेल_से_अलग_करें&quot;&gt;désown : शेल से अलग करें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;disown`शेल की जॉब टेबल से एक जॉब हटाएँ। प्रक्रिया चलती रहती है लेकिन अब इसे वापस नहीं लाया जा सकता`fg&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ./gradlew build &amp;amp;
[1] 12345

$ disown %1
# Le processus continue mais n&#39;est plus lié au shell
# Ça survives à la fermeture du terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_nohup_के_साथ_मिलाएँ_लंबी_प्रक्रियाओं_के_लिए&quot;&gt;nohup के साथ मिलाएँ लंबी प्रक्रियाओं के लिए&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक प्रक्रिया टर्मिनल बंद होने के बाद भी जीवित रहने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Le build continue même si vous fermez le terminal&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg&quot; as fg_ #SkyBlue {
  card &quot;जॉब लाओ
सबसे हाल का (+)&quot; as f1
  card &quot;एक नौकरी को लक्ष्य बनाएँ
विशिष्ट : fg %n&quot; as f2
  card &quot;बदलें : fg %-&quot; as f3
}

rectangle &quot;मारो %n&quot; as kill_ #LightCoral {
  card &quot;SIGTERM (स्वच्छ)&quot; as k1
  card &quot;SIGKILL -9 (बल)&quot; as k2
}

rectangle &quot;इन्कार करना&quot; as disown #Lavender {
  card &quot;शेल से अलग करें\n(डिस्कनेक्शन के दौरान जीवित रहता है)&quot; as d1
}

rectangle &quot;nohup + &amp;amp;&quot; as nohup_ #LightGreen {
  card &quot;इम्यूनाइज़्ड प्रक्रिया
SIGHUP के खिलाफ
(टर्मिनल के बंद होने पर जीवित रहता है)&quot; as n1
}

fg_ -right-&amp;gt; kill_ : si faut\nterminer
kill_ -right-&amp;gt; disown_ : ou détacher
nohup_ -left-&amp;gt; fg_ : fg ramène en\navant-plan

note bottom of disown_
  Après disown, fg ne peut
  plus ramener le job
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_जाल_और_सामान्य_त्रुटियाँ&quot;&gt;जाल और सामान्य त्रुटियाँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ctrlz_और_ctrlc_को_भ्रमित_करना&quot;&gt;Ctrl+Z और Ctrl+C को भ्रमित करना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह सबसे सामान्य त्रुटि है।`Ctrl+C`प्रक्रिया को मारता है।`Ctrl+Z`वह निलंबित कर देता है। यदि आप दबाते हैं`Ctrl+C`reflex से, पूरी स्थिति खो जाती है — खुले फ़ाइलें, LLM सत्र, चल रहे बिल्ड।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Ctrl+Z (SIGTSTP)&quot; as z #LightGreen {
  card &quot;स्मृति में जमी हुई प्रक्रिया&quot; as z1
  card &quot;fg इसे सलामत लाता&quot; as z2
  card &quot;कोई नुकसान नहीं&quot; as z3
}

rectangle &quot;Ctrl+C (SIGINT)&quot; as c #LightCoral {
  card &quot;प्रक्रिया पूरी हुई&quot; as c1
  card &quot;स्थायी रूप से खोयी हुई स्थिति&quot; as c2
  card &quot;वापसी संभव नहीं&quot; as c3
}

note bottom of z
  Pause → Reprendre
end note

note bottom of c
  Kill → Perdu
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_जॉब्स_शेल_के_लिए_स्थानीय_होते_हैं&quot;&gt;जॉब्स शेल के लिए स्थानीय होते हैं&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;jobs&lt;/code&gt;, &lt;code&gt;fg&lt;/code&gt; et `bg`वे केवल उसी शेल में काम करते हैं जिसने प्रक्रियाओं को लॉन्च किया। यदि आप एक नया टर्मिनल खोलते हैं, तो आप दूसरे के जॉब्स नहीं देख पाएंगे।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Terminal 1
$ vim file.txt
^Z
[1]+  Stoppé    vim file.txt

# Terminal 2 (nouveau)
$ jobs
# (rien — les jobs sont locaux au shell)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सिस्टम-वाइड प्रक्रियाएँ देखने के लिए, उपयोग करें`ps` ou &lt;code&gt;htop&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;ps aux | grep vim&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_जॉब्स_शेल_बंद_होने_पर_जीवित_नहीं_रहते&quot;&gt;जॉब्स शेल बंद होने पर जीवित नहीं रहते।&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यदि आप टर्मिनल बंद कर देते हैं, तो सभी निलंबित या बैकग्राउंड जॉब्स नष्ट हो जाते हैं। एक प्रक्रिया को जीवित रखने के लिए, उपयोग करें`nohup`+&lt;code&gt;disown&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ nohup ./gradlew build &amp;amp;
[1] 12345
$ disown %1
# Fermer le terminal → le build continue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_इंटरएक्टिव_प्रक्रियाएँ_और_fg&quot;&gt;इंटरएक्टिव प्रक्रियाएँ और fg&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कुछ इंटरएक्टिव प्रोग्राम एक के बाद अच्छा प्रदर्शन नहीं करते`Ctrl+Z`+&lt;code&gt;fg&lt;/code&gt;. यह दुर्लभ है लेकिन ऐसा होता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;कुछ प्रोग्राम जो संकेतों का उपयोग करते हैं (vim, htop, less) अच्छी तरह से काम करते हैं`Ctrl+Z`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;लंबे नेटवर्क प्रोग्राम (ssh, opencode) सामान्यतः सही ढंग से पुनर्प्राप्त होते हैं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;टर्मिनल (ncurses) को संशोधित करने वाले कार्यक्रम कभी‑कभी टर्मिनल को अपेक्षित नहीं स्थिति में छोड़ सकते हैं।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;भ्रष्ट टर्मिनल के बाद एक`fg`, टाइप करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;reset&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सारांश_आरेख&quot;&gt;सारांश आरेख&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

title &quot;fg — टिप्स जो सब कुछ बदल देते हैं&quot;

rectangle &quot;**समस्या**&quot; as problem #LightCoral {
  card &quot;टर्मिनल अवरुद्ध
एक प्रक्रिया द्वारा&quot; as p1
  card &quot;नया\nटर्मिनल खोलना = भारी समाधान&quot; as p2
}

rectangle &quot;समाधान&quot; as solution #LightGreen {
  card &quot;Ctrl+Z → निलंबित&quot; as s1
  card &quot;fg → फिर से शुरू करता है&quot; as s2
  card &quot;bg → पृष्ठभूमि में&quot; as s3
  card &quot;jobs → voir les suspendus&quot; as s4
}

rectangle &quot;**लाभ**&quot; as advantages #SkyBlue {
  card &quot;संदर्भ की हानि नहीं&quot; as a1
  card &quot;रीस्टार्ट नहीं&quot; as a2
  card &quot;एक टर्मिनल पर्याप्त है&quot; as a3
}

problem -right-&amp;gt; solution : &quot;Unix का स्वाभाविक समाधान 40 वर्षों से&quot;
solution -right-&amp;gt; advantages : &quot;परिणाम&quot;

note bottom of advantages
  fg n&#39;est pas un tips obscur
  C&#39;est un mécanisme fondamental
  du shell Unix
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_fg_क्यों_कम_आंका_गया&quot;&gt;fg क्यों कम आंका गया&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अधिकांश आधुनिक डेवलपर्स खोजते हैं`fg`देर से, या कभी नहीं। कुछ कारण :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;IDE टर्मिनल छुपाते हैं&lt;/strong&gt;: VS Code एक इंटीग्रेटेड टर्मिनल प्रदान करता है, लेकिन कई टैब बनाते हैं`fg`दिखने में कम आवश्यक&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ग्राफ़िकल टूल्स CLI को प्रतिस्थापित करते हैं&lt;/strong&gt;: फ़ाइल प्रबंधक, सिस्टम मॉनिटर, ग्राफ़िकल Git क्लाइंट&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;tmux और स्क्रीन&lt;/strong&gt;: ये मल्टीप्लेक्सर्स एक ही समस्या को अलग तरीके से हल करते हैं, लेकिन`fg`यह अधिक सरल और हमेशा उपलब्ध है&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फिर भी,&lt;code&gt;fg&lt;/code&gt;&lt;mark&gt;#&lt;/mark&gt; JBake CLI Commands &lt;code&gt;`&lt;/code&gt; # Initialize a new JBake project jbake -i&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h1 id=&quot;_bake_generate_the_site_jbake_b_3&quot; class=&quot;sect0&quot;&gt;Bake (generate) the site jbake -b&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_serve_locally_jbake_b_s_3&quot; class=&quot;sect0&quot;&gt;Bake and serve locally jbake -b -s&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_watch_for_changes_jbake_b_reset_3&quot; class=&quot;sect0&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/h1&gt;

&lt;h1 id=&quot;_specify_source_and_destination_jbake_source_folder_output_folder_3&quot; class=&quot;sect0&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/h1&gt;

&lt;h1 id=&quot;_clear_the_output_directory_before_baking_jbake_b_output_reset_है&quot; class=&quot;sect0&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt; है :&lt;/h1&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;सार्वभौमिक&lt;/strong&gt;सभी POSIX शेल्स में मौजूद (bash, zsh, fish&amp;#8230;&amp;#8203;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;निर्भरता के बिना&lt;/strong&gt;: tmux या स्क्रीन इंस्टॉल करने की ज़रूरत नहीं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;तत्क्षणिक&lt;/strong&gt;: दो हमले (&lt;code&gt;Ctrl+Z`फिर`fg&lt;/code&gt;) रोकने और फिर से शुरू करने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;संदर्भ संरक्षक&lt;/strong&gt; : l&amp;#8217;état du processus est intact&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

rectangle &quot;fg है
कम आंका गया ?&quot; as why #LightCoral {
  card &quot;IDE के साथ टर्मिनल\nबहु-टैब&quot; as w1
  card &quot;ग्राफ़िकल उपकरण
जो CLI को बदलते हैं&quot; as w2
  card &quot;tmux/screen समस्या को अन्य तरीके से हल करते हैं&quot; as w3
}

rectangle &quot;क्यों fg है
बेहतर ?&quot; as superior #LightGreen {
  card &quot;सार्वत्रिक : bash,
zsh, fish, sh...&quot; as s1
  card &quot;निर्भरता रहित:\nइंस्टॉलेशन नहीं&quot; as s2
  card &quot;दो हमले:\nCtrl+Z फिर fg&quot; as s3
  card &quot;संरक्षित संदर्भ:
शून्य राज्य हानि&quot; as s4
}

why -right-&amp;gt; superior : &quot;सादगी
हमेशा जीतती है&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_तकनीकी_ज्ञापन_संकेत&quot;&gt;तकनीकी ज्ञापन : संकेत&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जिज्ञासु लोगों के लिए, यहाँ संलग्न संकेत हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 14.2857%;&quot;&gt;
&lt;col style=&quot;width: 28.5714%;&quot;&gt;
&lt;col style=&quot;width: 28.5714%;&quot;&gt;
&lt;col style=&quot;width: 28.5715%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;सिग्नल&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;नाम&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;भेजा गया&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;प्रभाव&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGINT&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+C&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बाधा — प्रक्रिया समाप्त कर देती है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;3&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGQUIT&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+\&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कोर डंप के साथ बाहर निकलता&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;18&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGTSTP&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;Ctrl+Z&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;इंटरैक्टिव स्टॉप — प्रक्रिया को निलंबित करता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;19&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGCONT&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;fg&lt;/code&gt;/&lt;code&gt;bg&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जारी रखें — एक निलंबित प्रक्रिया को फिर से शुरू करता है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;15&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGTERM&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kill %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;स्वच्छ समापन&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;9&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;SIGKILL&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;kill -9 %n&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;जबरदस्त समाप्ति (इसे अवरोधित नहीं किया जा सकता)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पूर्ण प्रवाह:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif

participant &quot;उपयोगकर्ता&quot; as user
participant &quot;शेल&quot; as shell
participant &quot;प्रक्रिया&quot; as proc

user -&amp;gt; shell : Ctrl+Z
shell -&amp;gt; proc : SIGTSTP (signal 18)
note right of proc : Processus figé\nen mémoire

user -&amp;gt; shell : fg
shell -&amp;gt; proc : SIGCONT (signal 19)
note right of proc : Processus reprend\nen avant-plan

user -&amp;gt; shell : bg
shell -&amp;gt; proc : SIGCONT (signal 19)
note right of proc : Processus reprend\nen arrière-plan

user -&amp;gt; shell : Ctrl+C
shell -&amp;gt; proc : SIGINT (signal 2)
note right of proc : Processus terminé\nétat perdu
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fg`यह एक अस्पष्ट सुझाव नहीं है — यह यूनिक्स शेल का एक मौलिक तंत्र है, जो 1970 के दशक से उपलब्ध है। अधिकांश डेवलपर्स द्वारा इसे अनदेखा करना हमारे युग का एक लक्षण है: IDE और मल्टीप्लेक्सर्स ने हमें मूल बातों से दूर कर दिया है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लेकिन जब आप एक SSH सर्वर पर हैं, एक न्यूनतम टर्मिनल में हैं, या बस उपयोग कर रहे हैं`opencode`और LLM पूरी तरह से काम कर रहा है —&lt;code&gt;Ctrl+Z&lt;/code&gt;, &lt;code&gt;fg&lt;/code&gt;, &lt;code&gt;bg&lt;/code&gt;, `jobs`हैं आपके सबसे अच्छे दोस्तों.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(No output) Ctrl+Z रोकता है, fg फिर से शुरू करता है। यह टर्मिनल की पॉज़‑प्ले है। (No output)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ&quot;&gt;संदर्भ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;man bash&lt;/code&gt;— खंड JOB CONTROL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;man signal&lt;/code&gt;— POSIX संकेतों की सूची&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://www.gnu.org/software/bash/manual/bash.html#Job-Control&quot;&gt;Bash रेफ़रेंस मैनुअल — जॉब कंट्रोल&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://man7.org/linux/man-pages/man7/signal.7.html&quot;&gt;man 7 signal — लिनक्स सिग्नल&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://tldp.org/LDP/abs/html/x312743.htm&quot;&gt;उन्नत बैश-स्क्रिप्टिंग गाइड — कार्य नियंत्रण&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_पथ_का_अवलोकन&quot;&gt;पथ का अवलोकन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_क्यों_vs_code_घर_में&quot;&gt;क्यों : VS Code घर में&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_सिस्टम_इंस्टॉलेशन_के_साथ_समस्या&quot;&gt;सिस्टम इंस्टॉलेशन के साथ समस्या&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_एक_स्थानीय_स्थापना&quot;&gt;समाधान : एक स्थानीय स्थापना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_वास्तविक_लाभ&quot;&gt;वास्तविक लाभ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_मुख्य_मेनू_के_फ़ॉन्ट_को_अनुकूलित_करें&quot;&gt;मुख्य मेनू के फ़ॉन्ट को अनुकूलित करें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_निरीक्षण&quot;&gt;निरीक्षण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_तकनीक_सीधा_सीएसएस_पैच&quot;&gt;तकनीक : सीधा सीएसएस पैच&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सत्यनिष्ठा_चेतावनी_हटाएँ&quot;&gt;सत्यनिष्ठा चेतावनी हटाएँ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक्सप्लोरर_पैनल_का_फ़ॉन्ट_कस्टमाइज़_करें_लड़ाई&quot;&gt;एक्सप्लोरर पैनल का फ़ॉन्ट कस्टमाइज़ करें — लड़ाई&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_टेंटेटिव1_ऐसा_पैरामीटर_जो_नहीं_मौजूद_है&quot;&gt;टेंटेटिव 1: ऐसा पैरामीटर जो नहीं मौजूद है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रयास_2_एक्सटेंशन_custom_css_and_js_loader&quot;&gt;प्रयास 2 : एक्सटेंशन Custom CSS and JS Loader&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जाल_हर_बार_एक्सटेंशन_को_सक्रिय_करना_होगा&quot;&gt;जाल: हर बार एक्सटेंशन को सक्रिय करना होगा&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रयास_3_रेखाएँ_ओवरलैप_होती_हैं&quot;&gt;प्रयास 3: रेखाएँ ओवरलैप होती हैं&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_zoom_मातृ_कंटेनर_पर&quot;&gt;समाधान : &lt;code&gt;zoom&lt;/code&gt; मातृ कंटेनर पर&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सेलेक्टर्स_का_सारांश_और_क्या_काम_करता_है&quot;&gt;सेलेक्टर्स का सारांश और क्या काम करता है&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ऑटोमैटिक_अपडेट_स्क्रिप्ट&quot;&gt;ऑटोमैटिक अपडेट स्क्रिप्ट&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या&quot;&gt;समस्या&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_स्क्रिप्ट_vscode_update_sh&quot;&gt;स्क्रिप्ट `vscode-update.sh&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संबंधित_फाइलें_अवलोकन&quot;&gt;संबंधित फाइलें — अवलोकन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सीखे_हुए_सबक&quot;&gt;सीखे हुए सबक&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_होम_में_इंस्टॉल_करने_से_सब_कुछ_मुक्त_हो_जाता_है&quot;&gt;होम में इंस्टॉल करने से सब कुछ मुक्त हो जाता है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zoom_font_size_सूची_घटकों_के_लिए&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; सूची घटकों के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_custom_css_एक्सटेंशन_को_स्पष्ट_रूप_से_सक्रिय_करने_की_आवश्यकता_है&quot;&gt;Custom CSS एक्सटेंशन को स्पष्ट रूप से सक्रिय करने की आवश्यकता है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_अपडेट_स्क्रिप्ट_आवश्यक_है&quot;&gt;एक अपडेट स्क्रिप्ट आवश्यक है&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_त्वरित_संदर्भ&quot;&gt;त्वरित संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;पढ़ने का समय : 8 minutes&lt;/div&gt;
&lt;p&gt;VS Code को क्यों स्थापित करें में`/opt`या द्वारा`apt`quand हम इसे अपने घर में रख सकते हैं और अपने IDE को कभी टाइप किए बिना एक प्लेग्राउंड में बदल सकते हैं`sudo`यहाँ एक स्थानीय स्थापना की कहानी है, उसके बाद मेनू और फ़ाइल एक्सप्लोरर के फ़ॉन्ट को बढ़ाने के लिए एक कड़ा संघर्ष।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;विषय सूची&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पथ_का_अवलोकन&quot;&gt;पथ का अवलोकन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Développeur as dev
actor &quot;opencode\n+ LLM&quot; as agent

package &quot;होम उपयोगकर्ता (~)&quot; #LightGreen {
    package &quot;~/apps/&quot; {
        component &quot;VS Code
(टैरबॉल)&quot; as vscode #SkyBlue
        component &quot;vscode-update.sh&quot; as script #LightYellow
    }
    package &quot;~/.config/Code/&quot; {
        component &quot;settings.json&quot; as settings #Lavender
    }
    package &quot;~/.vscode-custom-css/&quot; {
        component &quot;custom.css
(ज़ूम: 1.25)&quot; as customcss #Lavender
    }
}

cloud &quot;code.visualstudio.com&quot; as download

dev --&amp;gt; vscode : Télécharge &amp;amp; installe
dev --&amp;gt; script : Lance mise à jour
script --&amp;gt; download : wget dernière version
script --&amp;gt; vscode : Remplace + re-patch CSS
agent --&amp;gt; settings : Écrit config
agent --&amp;gt; customcss : Écrit zoom CSS
agent --&amp;gt; vscode : Patch workbench CSS

note right of vscode
  Installation dans le home
  = contrôle total sans sudo
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_क्यों_vs_code_घर_में&quot;&gt;क्यों : VS Code घर में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सिस्टम_इंस्टॉलेशन_के_साथ_समस्या&quot;&gt;सिस्टम इंस्टॉलेशन के साथ समस्या&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code को इंस्टॉल किया गया के माध्यम से`apt`, &lt;code&gt;dnf`या में&lt;/code&gt;/opt`ऐप्लिकेशन के फ़ाइलों को रूट अधिकारों के पीछे लॉक करता है। नेटिव CSS का कोई भी संशोधन, de`product.json`या इंस्टॉलेशन फ़ोल्डर की आवश्यकता है`sudo`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब, जब कोई उपयोग करता है&lt;strong&gt;ओपेन्कोड&lt;/strong&gt;(टूल CLI अपने कोड पर एक LLM को नियंत्रित करने के लिए), एजेंट को सक्षम होने की आवश्यकता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;कॉन्फ़िगरेशन फ़ाइलों में लिखना (&lt;code&gt;~/.config/Code/User/settings.json&lt;/code&gt;) — यह पहले से ही होमपेज में है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;IDE के एसेट्स को संशोधित करें (वर्कबेंच CSS,&lt;code&gt;product.json&lt;/code&gt;) उन्नत कस्टमाइज़ेशन के लिए — यह sudo के बिना ब्लॉक है&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_एक_स्थानीय_स्थापना&quot;&gt;समाधान : एक स्थानीय स्थापना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम आधिकारिक टैरबॉल आर्काइव डाउनलोड करते हैं और उसे सीधे therein में निकालते हैं`~/apps/`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/apps
cd ~/apps
wget &quot;https://code.visualstudio.com/sha/download?build=stable&amp;amp;os=linux-x64&quot; -O vscode.tar.gz
tar -xzf vscode.tar.gz
rm vscode.tar.gz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बाइनरी तब है`~/apps/VSCode-linux-x64/bin/code`. कोई नहीं`sudo`किसी भी फ़ाइल को पढ़ने, संपादित करने या बदलने के लिए आवश्यक नहीं है`~/apps/VSCode-linux-x64/`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वास्तविक_लाभ&quot;&gt;वास्तविक लाभ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;इंस्टॉलेशन सिस्टम
(/opt, apt, dnf)&quot; #LightCoral {
    card &quot;VS Code रूट की संपत्ति&quot; {
        [CSS du workbench : sudo requis]
        [product.json : sudo requis]
        [Dossier d&#39;install : non modifiable]
    }
}

rectangle &quot;स्थापना होम\n(~/apps)&quot; #LightGreen {
    card &quot;VS Code यूज़र की संपत्ति&quot; {
        [CSS du workbench : libre]
        [product.json : libre]
        [Dossier d&#39;install : libre]
        [Script update maison]
    }
}

&quot;इंस्टॉलेशन सिस्टम
(/opt, apt, dnf)&quot; -right-&amp;gt; &quot;स्थापना होम\n(~/apps)&quot; : **Non, merci**\nJe prends le home

note bottom of &quot;स्थापना होम\n(~/apps)&quot;
  L&#39;agent opencode+LLM peut
  modifier les fichiers de l&#39;IDE
  sans aucune élévation de privilèges
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;लाभ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;विवरण&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;sudo नहीं&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;IDE के सभी फ़ाइल उपयोगकर्ता के हैं।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;CSS का सीधा संशोधन&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;पैच किया जा सकता है`workbench.desktop.main.css`विशेषाधिकार वृद्धि के बिना&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;घरेलू अपडेट स्क्रिप्ट&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक साधारण शेल स्क्रिप्ट स्वचालित रूप से डाउनलोड, प्रतिस्थापित और पुनः पैच करती है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;अलगाव&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सिस्टम इंस्टॉलेशन प्रदूषित नहीं है ; rollback = फ़ोल्डर हटाएँ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_मुख्य_मेनू_के_फ़ॉन्ट_को_अनुकूलित_करें&quot;&gt;मुख्य मेनू के फ़ॉन्ट को अनुकूलित करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निरीक्षण&quot;&gt;निरीक्षण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मुख्य मेनू (फ़ाइल, संपादन, दृश्य &amp;#8230;&amp;#8203;) और ड्रॉप‑डाउन का डिफ़ॉल्ट फ़ॉन्ट बहुत छोटा है। VS Code में इसे बदलने के लिए कोई सेटिंग नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_तकनीक_सीधा_सीएसएस_पैच&quot;&gt;तकनीक : सीधा सीएसएस पैच&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ाइल के अंत में CSS जोड़ें`workbench.desktop.main.css`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;workbench.desktop
.main.css&quot; as css
participant &quot;product.json&quot; as product
participant &quot;VS कोड&quot; as vscode

== Patch CSS ==
dev -&amp;gt; css : Ajouter règles font-size\n(.menubar-menu-title, etc.)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode -&amp;gt; vscode : Charge le CSS patché
vscode --&amp;gt; dev : Menus et dropdowns en 23px/22px ✓

== Suppression warning ==
vscode --&amp;gt; dev : ⚠️ &quot;आपकी स्थापना दूषित है&quot;
dev -&amp;gt; product : Supprimer clé &quot;चेकसम&quot;\n(python3 -c ...)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode --&amp;gt; dev : Plus de warning ✓

note over css, product
  Deux fichiers dans ~/apps/
  = modifiables sans sudo
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;CSS_FILE=&quot;$HOME/apps/VSCode-linux-x64/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;

cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; &#39;EOF&#39;
.menubar-menu-title{font-size:23px!important}
.menubar&amp;gt;.menubar-menu-button{font-size:23px!important}
.monaco-menu-option{font-size:22px!important;line-height:34px!important}
.monaco-menu .action-label:not(.codicon){font-size:22px!important}
.menubar-menu-items-holder .monaco-menu .action-item .action-label{font-size:22px!important}
EOF&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सत्यनिष्ठा_चेतावनी_हटाएँ&quot;&gt;सत्यनिष्ठा चेतावनी हटाएँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code अपने फ़ाइलों में हुए परिवर्तनों का पता लगाता है और एक बैनर प्रदर्शित करता है &quot;Your installation is corrupt&quot;। इससे बचने के लिए, हम चेकसम हटा देते हैं`product.json`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-python hljs&quot; data-lang=&quot;python&quot;&gt;import json
product_json = &quot;$HOME/apps/VSCode-linux-x64/resources/app/product.json&quot;
with open(product_json, &#39;r&#39;) as f:
    data = json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(product_json, &#39;w&#39;) as f:
    json.dump(data, f, indent=2)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;रीस्टार्ट के बाद, कोई चेतावनी नहीं रहती और मेनू अंततः पढ़ने योग्य हो जाते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक्सप्लोरर_पैनल_का_फ़ॉन्ट_कस्टमाइज़_करें_लड़ाई&quot;&gt;एक्सप्लोरर पैनल का फ़ॉन्ट कस्टमाइज़ करें — लड़ाई&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_टेंटेटिव1_ऐसा_पैरामीटर_जो_नहीं_मौजूद_है&quot;&gt;टेंटेटिव 1: ऐसा पैरामीटर जो नहीं मौजूद है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहले हम स्वाभाविक पैरामीटर का प्रयास करते हैं`workbench.tree.fontSize`में`settings.json`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;workbench.tree.fontSize&quot;: 20
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;कोई प्रभाव नहीं&lt;/strong&gt;. यह सेटिंग VS Code में मौजूद नहीं है। इसका सबूत यह है कि अनमान्य सेटिंग्स चुपचाप अनदेखी कर दिए जाते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रयास_2_एक्सटेंशन_custom_css_and_js_loader&quot;&gt;प्रयास 2 : एक्सटेंशन Custom CSS and JS Loader&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक्सटेंशन इंस्टॉल करते हैं`be5invis.vscode-custom-css`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;~/apps/VSCode-linux-x64/bin/code --install-extension be5invis.vscode-custom-css&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक CSS फ़ाइल बनाते हैं`~/.vscode-custom-css/custom.css`एक्सप्लोरर के तत्वों को लक्षित करने वाले चयनकर्ताओं के साथ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-tree-rows .monaco-tree-row,
.sidebar .monaco-list-row,
.explorer-viewlet .monaco-list-row,
.monaco-list-row .monaco-icon-label {
    font-size: 22px !important;
    line-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और हम इस फ़ाइल को सेटिंग्स में संदर्भित करते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;vscode_custom_css.imports&quot;: [
        &quot;file:///home/user/.vscode-custom-css/custom.css&quot;
    ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;परिवर्तन लागू नहीं होते.&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_जाल_हर_बार_एक्सटेंशन_को_सक्रिय_करना_होगा&quot;&gt;जाल: हर बार एक्सटेंशन को सक्रिय करना होगा&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक्सटेंशन की दस्तावेज़ीकरण इस महत्वपूर्ण बिंदु पर चुप है: प्रत्येक कस्टम CSS संशोधन के बाद, आपको यह करना होगा&lt;strong&gt;अनिवार्य रूप से&lt;/strong&gt;कमांड चलाएँ पैलेट से :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;→ टाइप करना&lt;strong&gt;कस्टम CSS और JS सक्षम करें&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;VS Code को रीस्टार्ट की आवश्यकता है → स्वीकार करें&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस चरण के बिना, सीएसएस कभी भी IDE में इंजेक्ट नहीं किया जाता।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रयास_3_रेखाएँ_ओवरलैप_होती_हैं&quot;&gt;प्रयास 3: रेखाएँ ओवरलैप होती हैं&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;के साथ भी`font-size: 22px` et &lt;code&gt;line-height: 36px&lt;/code&gt;, जैमबेज वाले अक्षर (g, p, f, b) पड़ोस वाली लाइनों पर फैल जाते हैं. हम जोड़ने की कोशिश कर रहे हैं`height` et &lt;code&gt;min-height&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-list-row {
    height: 36px !important;
    min-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;कोई बदलाव नहीं&lt;/strong&gt;. VS Code JavaScript में लाइनों की ऊँचाइयाँ गणना करता है और CSS मानों को ओवरराइड करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_zoom_मातृ_कंटेनर_पर&quot;&gt;समाधान : &lt;code&gt;zoom&lt;/code&gt; मातृ कंटेनर पर&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;प्रयास 1
पैरामीटर मौजूद नहीं है&quot; #LightCoral {
    card &quot;workbench.tree.fontSize&quot; as t1 {
        [VS Code ignore le paramètre]
    }
}

rectangle &quot;प्रयास 2
कस्टम CSS + फ़ॉन्ट-आकार&quot; #LightYellow {
    card &quot;.monaco-list-row { font-size: 22px }&quot; as t2 {
        [Texte plus grand\nmais lignes superposées]
    }
}

rectangle &quot;अस्थायी 3
font-size + line-height + height&quot; #LightYellow {
    card &quot;height: 36px !important&quot; as t3 {
        [VS Code override\npar JavaScript]
        [Aucun effet]
    }
}

rectangle &quot;समाधान
पैरेंट कंटेनर पर ज़ूम&quot; #LightGreen {
    card &quot;.monaco-list-rows { zoom: 1.25 }&quot; as t4 {
        [Texte + espacement\nproportionnels]
        [Layout JS respecté]
        [✓ Résultat conforme]
    }
}

t1 -down-&amp;gt; t2 : Pas de paramètre ?\nOn essaie le CSS
t2 -down-&amp;gt; t3 : Lignes superposées ?\nOn force la hauteur
t3 -down-&amp;gt; t4 : Override JS ?\nOn utilise zoom

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JavaScript लेआउट के खिलाफ लड़ने के बजाय, हम प्रॉपर्टी का उपयोग करते हैं`zoom`लाइनों के कंटेनर पर :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.explorer-viewlet .monaco-list-rows,
.sidebar .monaco-list-rows {
    zoom: 1.25;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`zoom`समान रूप से कंटेनर का रेंडर बढ़ाता है — टेक्स्ट और स्पेसिंग — VS Code के JavaScript इंजन द्वारा गणना किए गए लेआउट को तोड़े बिना। 1.25 का कारक लगभग 13px से 16px के परिवर्तन के अनुरूप है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परिणाम :&lt;strong&gt;फ़ाइल के नाम अंततः पढ़ने योग्य हैं, लाइनें सही अंतराल वाली हैं&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सेलेक्टर्स_का_सारांश_और_क्या_काम_करता_है&quot;&gt;सेलेक्टर्स का सारांश और क्या काम करता है&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;पहुँच&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;CSS&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;परिणाम&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size`पर&lt;/code&gt;.monaco-list-row`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size: 22px !important&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बड़ा पाठ लेकिन रेखाएँ अ overlap&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;line-height&lt;/code&gt;+&lt;code&gt;height`पर&lt;/code&gt;.monaco-list-row`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;line-height: 36px; height: 36px&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कोई प्रभाव नहीं (override JS)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;zoom`पर&lt;/code&gt;.monaco-list-rows`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;zoom: 1.25&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सफल — पाठ + अनुपातिक अंतराल&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ऑटोमैटिक_अपडेट_स्क्रिप्ट&quot;&gt;ऑटोमैटिक अपडेट स्क्रिप्ट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;डेवलपर
या cron&quot; as dev
participant &quot;vscode-update.sh&quot; as script
participant &quot;VSCode टैरबॉल\n(code.visualstudio.com)&quot; as remote
participant &quot;~/apps/\nVSCode-linux-x64&quot; as local
participant &quot;~/apps/
vscode-backup&quot; as backup
participant &quot;कार्य बेंच
.desktop.main.css&quot; as css
participant &quot;product.json&quot; as product

dev -&amp;gt; script : ./vscode-update.sh
script -&amp;gt; local : Lire version courante
script -&amp;gt; remote : wget dernière version
script -&amp;gt; script : Comparer versions

alt Version identique
    script --&amp;gt; dev : &quot;पहले से ही अपडेट!&quot;
else Nouvelle version
    script -&amp;gt; backup : Sauvegarder installation courante\n(horodatée)
    script -&amp;gt; local : rm -rf ancienne installation
    script -&amp;gt; local : mv nouvelle installation
    script -&amp;gt; css : Ajouter patch CSS\n(menubar 23px, dropdown 22px)
    script -&amp;gt; product : Supprimer checksums\n(python3)
    script --&amp;gt; dev : &quot;अपडेट पूरा\n1.xx.yy → 1.zz.ww&quot;
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समस्या&quot;&gt;समस्या&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब VS Code अपडेट होता है, तो यह इंस्टॉलेशन फ़ोल्डर को बदल देता है और&lt;strong&gt;सभी CSS पैच हटाएँ&lt;/strong&gt;&amp;gt;. इसे हर बार हाथ से फिर से लागू करना आवश्यक है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्क्रिप्ट_vscode_update_sh&quot;&gt;स्क्रिप्ट `vscode-update.sh&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम बनाते हैं`~/apps/vscode-update.sh`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;#!/bin/bash
set -e

VSCODE_DIR=&quot;$HOME/apps/VSCode-linux-x64&quot;
BACKUP_DIR=&quot;$HOME/apps/vscode-backup&quot;
TEMP_DIR=&quot;/tmp/vscode-update&quot;

MENUBAR_FONT_SIZE=&quot;23px&quot;
DROPDOWN_FONT_SIZE=&quot;22px&quot;

echo &quot;=== VS Code Local Updater ===&quot;

CURRENT_VERSION=$(&quot;$VSCODE_DIR/bin/code&quot; --version 2&amp;gt;/dev/null | head -1)
echo &quot;Current version: $CURRENT_VERSION&quot;

echo &quot;Downloading latest VS Code...&quot;
mkdir -p &quot;$TEMP_DIR&quot;
wget -q &quot;https://code.visualstudio.com/sha/download?build=stable&amp;amp;os=linux-x64&quot; \
    -O &quot;$TEMP_DIR/vscode.tar.gz&quot;

echo &quot;Extracting...&quot;
mkdir -p &quot;$TEMP_DIR/extracted&quot;
tar -xzf &quot;$TEMP_DIR/vscode.tar.gz&quot; -C &quot;$TEMP_DIR/extracted&quot;

NEW_VERSION=$(&quot;$TEMP_DIR/extracted/VSCode-linux-x64/bin/code&quot; \
    --version 2&amp;gt;/dev/null | head -1)
echo &quot;New version: $NEW_VERSION&quot;

if [ &quot;$CURRENT_VERSION&quot; = &quot;$NEW_VERSION&quot; ]; then
    echo &quot;Already up to date!&quot;
    rm -rf &quot;$TEMP_DIR&quot;
    exit 0
fi

echo &quot;Backing up current installation...&quot;
mkdir -p &quot;$BACKUP_DIR&quot;
cp -r &quot;$VSCODE_DIR&quot; &quot;$BACKUP_DIR/VSCode-linux-x64-$(date +%Y%m%d-%H%M%S)&quot;

echo &quot;Updating...&quot;
rm -rf &quot;$VSCODE_DIR&quot;
mv &quot;$TEMP_DIR/extracted/VSCode-linux-x64&quot; &quot;$VSCODE_DIR&quot;
rm -rf &quot;$TEMP_DIR&quot;

CSS_FILE=&quot;$VSCODE_DIR/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;
echo &quot;Re-applying custom CSS patch \
    (menubar=${MENUBAR_FONT_SIZE}, dropdown=${DROPDOWN_FONT_SIZE})...&quot;
cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; CSSEOF
.menubar-menu-title{font-size:${MENUBAR_FONT_SIZE}!important}\
.menubar&amp;gt;.menubar-menu-button{font-size:${MENUBAR_FONT_SIZE}!important}\
.monaco-menu-option{font-size:${DROPDOWN_FONT_SIZE}!important;\
line-height:34px!important}\
.monaco-menu .action-label:not(.codicon)\
{font-size:${DROPDOWN_FONT_SIZE}!important}\
.menubar-menu-items-holder .monaco-menu .action-item .action-label\
{font-size:${DROPDOWN_FONT_SIZE}!important}
CSSEOF

PRODUCT_JSON=&quot;$VSCODE_DIR/resources/app/product.json&quot;
if [ -f &quot;$PRODUCT_JSON&quot; ]; then
    echo &quot;Removing checksums to prevent integrity warning...&quot;
    python3 -c &quot;
import json
with open(&#39;$PRODUCT_JSON&#39;,&#39;r&#39;) as f: data=json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(&#39;$PRODUCT_JSON&#39;,&#39;w&#39;) as f: json.dump(data,f,indent=2)
print(&#39;Done.&#39;)
&quot;
fi

echo &quot;=== Update complete: $CURRENT_VERSION -&amp;gt; $NEW_VERSION ===&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;स्क्रिप्ट :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;लेटेस्ट स्थिर संस्करण डाउनलोड करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;जाँच करें कि क्या संस्करण वर्तमान से अलग है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वर्तमान स्थापना (समयांकित) में सहेजें`~/apps/vscode-backup/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इंस्टॉलेशन फ़ोल्डर बदलें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फिर से लागू करें&lt;/strong&gt;मुख्य मेनू का CSS पैच&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Supprime les checksums&lt;/strong&gt; de `product.json`अखंडता चेतावनी से बचने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
कस्टमाइज़ेशन एक्सप्लोरर पैन का Custom CSS एक्सटेंशन के माध्यम से और फ़ाइल`~/.vscode-custom-css/custom.css`वे अपडेट के कारण बच जाते हैं क्योंकि वे इंस्टॉलेशन फ़ोल्डर के बाहर रहते हैं।
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संबंधित_फाइलें_अवलोकन&quot;&gt;संबंधित फाइलें — अवलोकन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

rectangle &quot;VS Code की स्थापना
(~/apps/VSCode-linux-x64/)&quot; #LightCoral {
    component &quot;workbench.desktop\n.main.css&quot; as css #LightCoral
    component &quot;product.json&quot; as product #LightCoral
    component &quot;बाइनरी
bin/code&quot; as binary #LightCoral
}

rectangle &quot;उपयोगकर्ता कॉन्फ़िगरेशन
(~/.config/Code/)&quot; #LightGreen {
    component &quot;settings.json&quot; as settings #LightGreen
    component &quot;एक्सटेंशन/&quot; as extensions #LightGreen
}

rectangle &quot;स्थायी अनुकूलन
(~/.vscode-custom-css/)&quot; #SkyBlue {
    component &quot;custom.css\n(zoom: 1.25)&quot; as customcss #SkyBlue
}

rectangle &quot;स्वचालन
(~/apps/)&quot; #LightYellow {
    component &quot;vscode-update.sh&quot; as script #LightYellow
    component &quot;vscode-backup/&quot; as backup #LightYellow
}

script ..&amp;gt; css : Re-patch après MAJ
script ..&amp;gt; product : Supprime checksums\naprès MAJ
settings --&amp;gt; customcss : Référence via\nvscode_custom_css.imports
extensions ..&amp;gt; css : Custom CSS Loader\ninjecte custom.css

note bottom of css
  **Ne survit pas** aux mises à jour
  Re-patché par le script
end note

note bottom of customcss
  **Survit** aux mises à jour
  Vit hors du dossier d&#39;installation
end note

note bottom of settings
  **Survit** aux mises à jour
  Vit dans ~/.config/
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
