&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सीखे_हुए_सबक&quot;&gt;सीखे हुए सबक&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

rectangle &quot;**स्थानीय स्थापना**\n घर में&quot; as install #LightGreen {
    card &quot;सुडो नहीं
 CSS/config को संशोधित करने के लिए&quot; as i1
    card &quot;opencode+LLM सब कुछ संशोधित कर सकता है&quot; as i2
    card &quot;Rollback = पुनर्स्थापित
 टाइमस्टैम्प्ड बैकअप&quot; as i3
}

rectangle &quot;**CSS का कस्टमाइज़ेशन**
 ज़ूम बनाम फ़ॉन्ट-आकार&quot; as css #LightYellow {
    card &quot;ज़ूम &amp;gt; फ़ॉन्ट-आकार\n घटकों की सूची के लिए&quot; as c1
    card &quot;ले आउट JS ओवरराइड
ऊँचाई/लाइन-ऊँचाई&quot; as c2
    card &quot;Extension Custom CSS
 आवश्यक सक्रियण
 हस्तचालित (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;**स्वचालन**\n अपडेट स्क्रिप्ट&quot; as auto #LightCoral {
    card &quot;CSS को री-पैच करने के बाद
 प्रत्येक अपडेट&quot; as a1
    card &quot;चेकसम हटाएँ
 product.json&quot; as a2
    card &quot;समय-चिह्नित बैकअप
 प्रतिस्थापन से पहले&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

note top of auto
  Sans script, chaque MAJ
  efface les patches CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_होम_में_इंस्टॉल_करने_से_सब_कुछ_मुक्त_हो_जाता_है&quot;&gt;होम में इंस्टॉल करने से सब कुछ मुक्त हो जाता है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;स्थानीय स्थापना में`~/apps`VS Code पर पूर्ण नियंत्रण देता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;नहीं`sudo`CSS को संशोधित करने या कॉन्फ़िगरेशन को बदलने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;opencode+LLM एजेंट IDE के कॉन्फ़िगरेशन फ़ाइलों और एसेट्स में लिख सकता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;साधारण रोलबैक : टाइमस्टैम्प्ड बैकअप पुनर्स्थापित करें&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zoom_font_size_सूची_घटकों_के_लिए&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; सूची घटकों के लिए&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code JavaScript के माध्यम से लाइन की ऊँचाई को नियंत्रित करता है। संशोधित करें`font-size`ले�ेआउट इंजन द्वारा आवंटित ऊँचाई को छू पाने में असमर्थ होने से पाठ ओवरफ़्लो हो जाते हैं। गुण`zoom`माता कंटेनर को बड़ा करने से सब कुछ समानुपातिक रूप से बड़ा हो जाता है और इस समस्या को टाल दिया जाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_custom_css_एक्सटेंशन_को_स्पष्ट_रूप_से_सक्रिय_करने_की_आवश्यकता_है&quot;&gt;Custom CSS एक्सटेंशन को स्पष्ट रूप से सक्रिय करने की आवश्यकता है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह &lt;code&gt;set and forget&lt;/code&gt; पैरामीटर नहीं है। प्रत्येक कस्टम CSS फ़ाइल में बदलाव करने के लिए &lt;code&gt;Enable Custom CSS and JS&lt;/code&gt; को कमांड पैलेट से फिर से चलाना आवश्यक है। (&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_एक_अपडेट_स्क्रिप्ट_आवश्यक_है&quot;&gt;एक अपडेट स्क्रिप्ट आवश्यक है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;स्क्रिप्ट के बिना, VS Code के प्रत्येक अपडेट वर्कबेंच के CSS पैच को मिटा देता है। स्क्रिप्ट`vscode-update.sh`डाउनलोड, प्रतिस्थापन, री-पैच और चेकसम्स की सफ़ाई को स्वचालित करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_त्वरित_संदर्भ&quot;&gt;त्वरित संदर्भ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;VS Code डाउनलोड : &lt;a href=&quot;https://code.visualstudio.com/Download&quot; class=&quot;bare&quot;&gt;https://code.visualstudio.com/Download&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एक्सटेंशन कस्टम CSS और JS लोडर :`be5invis.vscode-custom-css`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;VS Code के द्वारा एक्सप्लोरर फ़ॉन्ट के लिए एक नेटिव सेटिंग मांगे जाने का मुद्दा:https://github.com/microsoft/vscode/issues/149[github.com/microsoft/vscode#149]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ_और_उद्देश्य&quot;&gt;संदर्भ और उद्देश्य&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_शुरुआती_बिंदु&quot;&gt;शुरुआती बिंदु&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लक्ष्य&quot;&gt;लक्ष्य&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पहली_बाधा_ruby_gems&quot;&gt;पहली बाधा : `ruby { gems() }&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ग्रोवी_शुगर_सिंटैक्स_क्या_छिपाता_है&quot;&gt;ग्रोवी शुगर सिंटैक्स क्या छिपाता है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_मैकेनिज़म_का_विघटन&quot;&gt;मैकेनिज़म का विघटन&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_तीन_भागों_का_समाधान&quot;&gt;तीन भागों का समाधान&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_भाग_1_ivy_रेपॉ_rubygems_के_लिए&quot;&gt;भाग 1 : Ivy रेपॉ rubygems के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jbake_cli_commands_initialize_a_new_jbake_project_jbake_i&quot;&gt;JBake CLI Commands &lt;code&gt;`&lt;/code&gt; # Initialize a new JBake project jbake -i&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_generate_the_site_jbake_b&quot;&gt;Bake (generate) the site jbake -b&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_serve_locally_jbake_b_s&quot;&gt;Bake and serve locally jbake -b -s&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_watch_for_changes_jbake_b_reset&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_specify_source_and_destination_jbake_source_folder_output_folder&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_clear_the_output_directory_before_baking_jbake_b_output_reset&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ_और_उद्देश्य&quot;&gt;संदर्भ और उद्देश्य&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_शुरुआती_बिंदु&quot;&gt;शुरुआती बिंदु&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परियोजना`slider-gradle`Gradle प्लग़िन के माध्यम से AsciiDoc फ़ाइलों से Reveal.js प्रजेंटेशन बनाता है`org.asciidoctor.jvm.revealjs`. मुख्य कार्य की कॉन्फ़िगरेशन`asciidoctorRevealJs`वह रूट buildscript में सीधे रहता था`build.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;plugins { id(&quot;org.asciidoctor.jvm.revealjs&quot;) }

apply&amp;lt;slides.SlidesPlugin&amp;gt;()

project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
    repositories { ruby { gems() } }
    revealjs {
        version = &quot;3.1.0&quot;
        templateGitHub {
            setOrganisation(&quot;hakimel&quot;)
            setRepository(&quot;reveal.js&quot;)
            setTag(&quot;3.9.1&quot;)
        }
    }
    revealjsOptions {
        // ... configuration complète
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लक्ष्य&quot;&gt;लक्ष्य&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस पूरी कॉन्फ़िगरेशन को`buildSrc/src/main/kotlin/slides/SlidesPlugin.kt`कि बिल्डस्क्रिप्ट उपभोक्ता कम हो जाए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;apply&amp;lt;slides.SlidesPlugin&amp;gt;()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्लगिन को पूरी तरह से स्वायत्त होना चाहिए: यह अपने प्लगिन निर्भरताओं को स्वयं लागू करता है, अपने रिपॉज़िटरीज़ को कॉन्फ़िगर करता है, और अपने रूबी जेम्स को प्रबंधित करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पहली_बाधा_ruby_gems&quot;&gt;पहली बाधा : `ruby { gems() }&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ग्रोवी_शुगर_सिंटैक्स_क्या_छिपाता_है&quot;&gt;ग्रोवी शुगर सिंटैक्स क्या छिपाता है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लाइन`repositories { ruby { gems() } }`यह एक Groovy DSL एक्सटेंशन है जो केवल buildscript के निष्पादन संदर्भ में उपलब्ध है। यह buildSrc से 접근 가능한 स्थिर Kotlin API के रूप में मौजूद नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इसको फ़ोन करने की कोशिश करते हुए`SlidesPlugin.kt`, संकलन तुरंत असफल हो जाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_मैकेनिज़म_का_विघटन&quot;&gt;मैकेनिज़म का विघटन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ग्रेडल कैश का विश्लेषण करने के बाद (&lt;code&gt;~/.gradle/caches/modules-2/files-2.1/rubygems/&lt;/code&gt;), फ़ाइल में हमें पता चलता है`ivy-3.1.0.xml`: (Note: The output should be exactly &quot; : &quot; with a leading space, colon, and trailing space, as per the instruction to translate the fragment and preserve formatting.)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;artifact type=&#39;gem&#39; url=&#39;https://rubygems.org/gems/asciidoctor-revealjs-3.1.0.gem&#39; /&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`ruby { gems() }`वास्तव में कर रहा था&lt;strong&gt;तीन भिन्न संचालन&lt;/strong&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Enregistrer un repo Ivy pointant vers &lt;code&gt;&lt;a href=&quot;https://rubygems.org/gems/&quot; class=&quot;bare&quot;&gt;https://rubygems.org/gems/&lt;/a&gt;&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;समूह को बाहर रखें`rubygems`Maven रिपॉजिटरी टकराव से बचने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;जेम को कॉन्फ़िगरेशन में सहेजें`asciidoctorGems`जिससे JRuby इसे रनटाइम पर लोड करे&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इन तीन जिम्मेदारियों को कोटलिन में अलग‑अलग रूप से पुन: उत्पन्न किया जाना चाहिए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_तीन_भागों_का_समाधान&quot;&gt;तीन भागों का समाधान&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_भाग_1_ivy_रेपॉ_rubygems_के_लिए&quot;&gt;भाग 1 : Ivy रेपॉ rubygems के लिए&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.repositories.mavenCentral() {
    content { excludeGroup(&quot;rubygems&quot;) }
}
project.repositories.ivy {
    url = project.uri(&quot;https://rubygems.org/gems/&quot;)
    patternLayout { artifact(&quot;[module]-[revision].gem&quot;) } &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;
    metadataSources { artifact() }
    content { includeGroup(&quot;rubygems&quot;) }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;colist arabic&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td&gt;&lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;1&lt;/b&gt;&lt;/td&gt;
&lt;td&gt;एक्सटेंशन`.gem`इसे हार्डकोड किया जाना चाहिए।&lt;code&gt;[ext]`डिफ़ॉल्ट रूप से में हल करता है&lt;/code&gt;.jar`, जिससे एक त्रुटि होती है`Resource missing`.&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbake_cli_commands_initialize_a_new_jbake_project_jbake_i&quot;&gt;JBake CLI Commands &lt;code&gt;`&lt;/code&gt; # Initialize a new JBake project jbake -i&lt;/h3&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h1 id=&quot;_bake_generate_the_site_jbake_b&quot; class=&quot;sect0&quot;&gt;Bake (generate) the site jbake -b&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_serve_locally_jbake_b_s&quot; class=&quot;sect0&quot;&gt;Bake and serve locally jbake -b -s&lt;/h1&gt;

&lt;h1 id=&quot;_bake_and_watch_for_changes_jbake_b_reset&quot; class=&quot;sect0&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/h1&gt;

&lt;h1 id=&quot;_specify_source_and_destination_jbake_source_folder_output_folder&quot; class=&quot;sect0&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/h1&gt;

&lt;h1 id=&quot;_clear_the_output_directory_before_baking_jbake_b_output_reset&quot; class=&quot;sect0&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt;&lt;/h1&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;नोट: आइवी रेपो सीधे घोषित किया गया है पर`project.repositories`और नहीं एक ब्लॉक में`repositories { }`क्योंकि इस ब्लॉक का रिसीवर नहीं है`RepositoryHandler`Gradle का मानक लेकिन एक grolifant API एक्सटेंशन के साथ अनुकूल नहीं`ivy`&lt;mark&gt;#&lt;/mark&gt; Gradle Integration JBake को Gradle बिल्ड में JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}

=== भाग 2: निर्भरता asciidoctorGems

प्लगइन`org.asciidoctor.jvm.gems`इसे पहले लागू किया जाना चाहिए — यह कॉन्फ़िगरेशन बनाता है`asciidoctorGems`और कार्य`asciidoctorGemsPrepare`:

[source,kotlin]
----
project.plugins.apply(&quot;org.asciidoctor.jvm.gems&quot;)
project.plugins.apply(&quot;org.asciidoctor.jvm.revealjs&quot;) &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;

project.dependencies {
    add(&quot;asciidoctorGems&quot;, &quot;rubygems:asciidoctor-revealjs:3.1.0@gem&quot;) &lt;i class=&quot;conum&quot; data-value=&quot;2&quot;&gt;&lt;/i&gt;&lt;b&gt;(2)&lt;/b&gt;
}
----

&amp;lt;1&amp;gt; लागू करने का क्रम महत्वपूर्ण है :
### JBake CLI कमांड
----

# एक नया JBake प्रोजेक्ट प्रारंभ करें jbake -i

# बेक (जेनरेट) साइट jbake -b

# बेक और स्थानीय रूप से परोसें jbake -b -s

# बेक और बदलावों की निगरानी करें jbake -b --reset

# स्रोत और गंतव्य निर्दिष्ट करें jbake source_folder output_folder

# बेकिंग से पहले आउटपुट निर्देशिका साफ़ करें jbake -b . output --reset`gems`पहले`revealjs`. &amp;lt;2&amp;gt; योग्यकर्ता`@gem`निर्भरता पर सही एक्सटेंशन बल दें।

=== भाग 3 : settings.gradle.kts

`dependencyResolutionManagement`में`settings.gradle.kts`इसे परियोजनाओं को अपने स्वयं के रिपॉज़िटरी की घोषणा करने की अनुमति देनी चाहिए :

[source,kotlin]
----
@Suppress(&quot;UnstableApiUsage&quot;)
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.PREFER_PROJECT)
}
----

इसी पंक्ति के बिना, Gradle प्लगइन में घोषित रिपॉज़िटरी को अनदेखा करता है और gems का समाधान विफल हो जाता है।

== बाइटकोड्स द्वारा API का आत्मनिरीक्षण

=== क्यों `javap` ?

प्लगइन`asciidoctor-gradle-jvm-slides` est en version `4.0.0-alpha.1`. उसका दस्तावेज़ अस्तित्वहीन या अपूर्ण है। एकमात्र विश्वसनीय स्रोत संकलित क्लासेस की प्रत्यक्ष जाँच है।

=== कार्य का पदानुक्रम

[source,bash]
----
javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.slides.AsciidoctorJRevealJSTask
----

परिणाम :

[source]
----
public class AsciidoctorJRevealJSTask
  extends org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask
  implements org.asciidoctor.gradle.base.slides.SlidesToExportAware
----

=== की खोज `forkOptions

निरीक्षण करते हुए.

&amp;lt;/think&amp;gt;

निरीक्षण करते हुए`AbstractAsciidoctorTask`:

[source,bash]
----
javap -p -classpath asciidoctor-gradle-jvm-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask | grep -i &quot;fork\|exec\|jvm&quot;
----

पाया जाता है:

[source]
----
final org.ysb33r.grolifant.api.v4.JavaForkOptions javaForkOptions;
public void forkOptions(org.gradle.api.Action&amp;lt;org.ysb33r.grolifant.api.v4.JavaForkOptions&amp;gt;);
public static final org.asciidoctor.gradle.base.process.ProcessMode JAVA_EXEC;
----

=== JavaForkOptions की एपीआई (grolifant)

`javaLauncher`इस कार्य पर मौजूद नहीं है। वास्तविक API का`org.ysb33r.grolifant.api.v4.JavaForkOptions`दिखाता है :

[source]
----
public void executable(java.lang.Object);  &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;
public void setExecutable(java.lang.Object);
----

&amp;lt;1&amp;gt; पद्धति`executable(Object)`असाइनमेंट को बदलता है`executable = ...`जो कंपाइल नहीं होता (`val`पुन: आवंटित नहीं किया जा सकता).

=== RevealJSExtension

`revealjs { }`कार्य की एक विधि नहीं है, लेकिन एक**परियोजना विस्तार**:

[source,bash]
----
javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.slides.RevealJSExtension
----

इस तक पहुँचा जाता है:

[source,kotlin]
----
project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;().apply {
    version = &quot;3.1.0&quot;
    templateGitHub {
        setOrganisation(&quot;hakimel&quot;)
        setRepository(&quot;reveal.js&quot;)
        setTag(&quot;3.9.1&quot;)
    }
}
----

== जावा टूलचेन कॉन्फ़िगरेशन

=== JavaToolchainService की समस्या

`JavaToolchainService`यह प्रोजेक्ट एक्सटेंशन नहीं है। निम्नलिखित कॉल विफल होता है :

[source,kotlin]
----
// ERREUR : Extension of type &#39;JavaToolchainService&#39; does not exist
project.extensions.getByType&amp;lt;JavaToolchainService&amp;gt;()
----

अच्छी API है`serviceOf`:

[source,kotlin]
----
import org.gradle.kotlin.dsl.support.serviceOf

project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
    setInProcess(&quot;JAVA_EXEC&quot;)
    forkOptions {
        executable(
            project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()
                .launcherFor {
                    languageVersion.set(JavaLanguageVersion.of(17))
                    vendor.set(JvmVendorSpec.ADOPTIUM)
                }
                .get()
                .executablePath
                .asFile
                .absolutePath
        )
    }
}
----

== स्वचालित डॉकर का पता लगाना

=== संदर्भ

Asciidoctor/JRuby प्लगिन को Java 17 की आवश्यकता है। Kotlin 2.0.x बिल्डSrc में Java 25 का समर्थन नहीं करता (वर्ज़न पार्सर क्रैश हो जाता है पर`&quot;25.0.2&quot;`Gradle डेमन को इसलिए Java 17 पर चलना चाहिए या Docker का उपयोग किया जाना चाहिए।

=== रणनीति

1. Docker उपलब्ध → कंटेनर के माध्यम से निष्पादन`eclipse-temurin:17`(डिफ़ॉल्ट व्यवहार)
2. Docker अनुपस्थित + Java 17 → स्थानीय निष्पादन
3. Docker अनुपस्थित + Java &amp;gt; 17 → स्पष्ट त्रुटि

[source,kotlin]
----
val isDockerAvailable = try {
    Runtime.getRuntime().exec(arrayOf(&quot;docker&quot;, &quot;info&quot;)).waitFor() == 0
} catch (e: Exception) {
    false
}

val javaVersion = JavaVersion.current().majorVersion.toInt()

when {
    isDockerAvailable -&amp;gt; project.tasks.register&amp;lt;Exec&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
        group = GROUP_TASK_SLIDER
        description = &quot;Slider settings and generation (via Docker)&quot;
        dependsOn(TASK_CLEAN_SLIDES_BUILD)
        finalizedBy(TASK_DASHBOARD_SLIDES_BUILD)
        commandLine(
            &quot;docker&quot;, &quot;run&quot;, &quot;--rm&quot;,
            &quot;-v&quot;, &quot;${project.rootDir.absolutePath}:/workspace&quot;,
            &quot;-v&quot;, &quot;${System.getProperty(&quot;user.home&quot;)}/.gradle:/root/.gradle&quot;,
            &quot;-w&quot;, &quot;/workspace&quot;,
            &quot;eclipse-temurin:17&quot;,
            &quot;./gradlew&quot;, TASK_ASCIIDOCTOR_REVEALJS
        )
        workingDir = project.rootDir
    }
    javaVersion == 17 -&amp;gt; {
        project.repositories.mavenCentral() {
            content { excludeGroup(&quot;rubygems&quot;) }
        }
        project.repositories.ivy {
            url = project.uri(&quot;https://rubygems.org/gems/&quot;)
            patternLayout { artifact(&quot;[module]-[revision].gem&quot;) }
            metadataSources { artifact() }
            content { includeGroup(&quot;rubygems&quot;) }
        }
        project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;().apply {
            version = &quot;3.1.0&quot;
            templateGitHub {
                setOrganisation(&quot;hakimel&quot;)
                setRepository(&quot;reveal.js&quot;)
                setTag(&quot;3.9.1&quot;)
            }
        }
        project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
            setInProcess(&quot;JAVA_EXEC&quot;)
            forkOptions {
                executable(
                    project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()
                        .launcherFor {
                            languageVersion.set(JavaLanguageVersion.of(17))
                            vendor.set(JvmVendorSpec.ADOPTIUM)
                        }
                        .get()
                        .executablePath
                        .asFile
                        .absolutePath
                )
            }
            // ... reste de la configuration
        }
    }
    else -&amp;gt; error(
        &quot;Docker est requis pour exécuter $TASK_ASCIIDOCTOR_REVEALJS &quot; +
        &quot;avec Java $javaVersion. Installez Docker ou utilisez Java 17.&quot;
    )
}
----

== अंतिम परिणाम

=== भोक्ता बिल्डस्क्रिप्ट

[source,kotlin]
----
apply&amp;lt;slides.SlidesPlugin&amp;gt;()
----

इतना ही। प्लगिन पूरी जिम्मेदारी लेता है।

=== settings.gradle.kts

[source,kotlin]
----
pluginManagement {
    repositories {
        mavenLocal()
        gradlePluginPortal()
    }
}

plugins {
    id(&quot;org.gradle.toolchains.foojay-resolver-convention&quot;) version &quot;0.8.0&quot;
}

@Suppress(&quot;UnstableApiUsage&quot;)
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.PREFER_PROJECT)
}

rootProject.name = &quot;slider-gradle&quot;
----

== जाल और समाधानों का सारांश

[cols=&quot;2,3,3&quot;]
|===
|समस्या |कारण |समाधान

|`ruby { gems() }`Kotlin में उपलब्ध नहीं |केवल Groovy DSL एक्सटेंशन |तीन अलग‑अलग तंत्र : Ivy रेपो + Maven बहिष्करण +`asciidoctorGems` |Gradle एक की खोज कर रहा है`.jar`एक के बजाय`.gem` |`[ext]`हल करता है से`jar`डिफ़फ़ॉल्ट रूप से |Hardcoder`.gem`इवी पैटर्न में + योग्यता`@gem` |`ivy { }`में कंपाइल नहीं होता`repositories { }` |रिसीवर grolifant Kotlin DSL के साथ असंगत |सीधी कॉल`project.repositories.ivy { }` |`javaLauncher`अनसुलझा |अस्तित्वहीन गुणधर्म पर`AsciidoctorJRevealJSTask` |`setInProcess(&quot;JAVA_EXEC&quot;)`+`forkOptions { executable(...) }` |`executable = ...`कंपाइल नहीं होता |संपत्ति`val`में`JavaForkOptions`grolifant |पद्धति`executable(Object)`के स्थान पर |`JavaToolchainService`के माध्यम से नहीं मिला`extensions` |यह Gradle का एक सेवा है, एक एक्सटेंशन नहीं |`project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()` |`revealjs { }`कार्य में हल नहीं |परियोजना विस्तार, कार्य की विधि नहीं |`project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;()` |बिल्ड Java 25 के साथ क्रैश होती है |Kotlin 2.0.x दो अंकों वाले Java संस्करणों को पार्स नहीं करता |स्वचालित Docker पहचान + Java 17 का फॉलबैक
|===

== जाँच की विधि : अज्ञात API को javap के साथ पढ़ना

=== सिद्धांत

जब दस्तावेज़ अनुपलब्ध या अधूरा हो, तब बाइटकोड सत्य का स्रोत होता है। `javap`यह JDK का मानक टूल है जो फ़ाइलों को डीकंपाइल करता है`.class` en signatures Java lisibles, स्रोत कोड की आवश्यकता नहीं

=== चरण 1: Gradle कैश में jar को खोजें

Gradle सभी अपनी निर्भरताओं को डाउनलोड करता है में`~/.gradle/caches/modules-2/files-2.1/`. पहला कदम वह jar खोजना है जिसमें जाँचने के लिए क्लास मौजूद है:

[source,bash]
----
find ~/.gradle/caches -name &quot;asciidoctor-gradle-jvm-slides*.jar&quot; 2&amp;gt;/dev/null
----

.परिणाम :

[source]
----
/home/user/.gradle/caches/modules-2/files-2.1/org.asciidoctor/
asciidoctor-gradle-jvm-slides/4.0.0-alpha.1/.../
asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar
----

=== चरण 2 : jar की कक्षाओं की सूची बनाएं

क्लास का निरीक्षण करने से पहले, हम जाँचते हैं कि यह jar में वास्तव में मौजूद है:

[source,bash]
----
jar tf asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar | grep -i &quot;RevealJS\|revealjs&quot;
----

.यह सभी उपलब्ध वर्गों को प्रकट करता है : `AsciidoctorJRevealJSTask`, `RevealJSExtension`, `RevealJSOptions`, etc.

=== चरण 3 : एक कक्षा का निरीक्षण करें

[source,bash]
----
javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.slides.AsciidoctorJRevealJSTask
----

विकल्प`-p`सभी सदस्यों को प्रदर्शित करता है, निजी सदस्यों सहित। परिणाम तुरंत मुख्य पंक्ति दिखाता है :

[source]
----
public class AsciidoctorJRevealJSTask
extends org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask
----

=== चरण 4 : पदानुक्रम में ऊपर उठना

कार्य विस्तृत होता है`AbstractAsciidoctorTask`. इसे उसकी बारी पर निरीक्षण किया जाता है पहले उसके जार को खोजते हुए :

[source,bash]
----
find ~/.gradle/caches -name &quot;asciidoctor-gradle-jvm-[0-9]*.jar&quot; 2&amp;gt;/dev/null

javap -p -classpath asciidoctor-gradle-jvm-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask | grep -i &quot;fork\|exec\|jvm\|java&quot;
----

वही पता चलता है।`forkOptions`, `JAVA_EXEC`, et `javaForkOptions` de type `org.ysb33r.grolifant.api.v4.JavaForkOptions`.

=== चरण 5: अज्ञात प्रकारों का पालन करें

`JavaForkOptions`एक अज्ञात गrolifant कक्षा है। हम इसके jar को खोजते हैं :

[source,bash]
----
find ~/.gradle/caches -name &quot;grolifant*.jar&quot; 2&amp;gt;/dev/null
----

फिर हम इसकी जाँच करते हैं:

[source,bash]
----
javap -p -classpath grolifant40-legacy-api-2.0.0-alpha.6.jar \
org.ysb33r.grolifant.api.v4.JavaForkOptions
----

वहाँ इसे पाया जाता है`executable(java.lang.Object)`— बुलाने की सही विधि, के विपरीत`executable = ...`जो संकलित नहीं होता क्योंकि यह एक संपत्ति है`val`.

=== चरण 6: परियोजना एक्सटेंशन की जाँच करें

के लिए`revealjs { }`, प्रश्न यह था: क्या यह कार्य की एक विधि है या प्रोजेक्ट का एक विस्तार? निरीक्षण का`AsciidoctorJRevealJSTask` कोई भी तरीका नहीं दिखाता`revealjs`. फिर निरीक्षण किया जाता है`RevealJSExtension`:

[source,bash]
----
javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.slides.RevealJSExtension | head -5
----

[source]
----
public class RevealJSExtension implements groovy.lang.GroovyObject {
public static final java.lang.String NAME;
----

की मौजूदगी`NAME`यह पुष्टि करता है कि यह एक पंजीकृत एक्सटेंशन परियोजना पर है, के माध्यम से सुलभ`project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;()`.

=== विधि का सारांश

[cols=&quot;1,3&quot;]
|===
|चरण |क्रिया

|1 |`find ~/.gradle/caches -name &quot;*.jar&quot;`— जार को खोजें |2 |`jar tf jar.jar \| grep NomClasse`— जाँचना कि कक्षा मौजूद है |3 |`javap -p -classpath jar.jar NomCompletClasse`— कक्षा का निरीक्षण करें |4 |पहचानकर्ता`extends`और हिरार्की में चढ़ना |5 |अज्ञात प्रकारों को अपने जारों में ट्रैक करें |6 |खोजें`NAME`एक प्रोजेक्ट एक्सटेंशन की पहचान करने के लिए
|===

यह विधि किसी भी Gradle प्लगइन पर लागू होती है जिसका API दस्तावेज़ीकृत नहीं है या जिसका अल्फा संस्करण अब मौजूदा दस्तावेज़ से मेल नहीं खाता।

== अगला कदम

यह buildSrc प्लगिन को Gradle Plugin Portal या Maven Local पर प्रकाशित किए गए एक स्वतंत्र प्रोजेक्ट में निकाला जाएगा। उपयोग करने वाला buildscript तब : बन जाएगा।

[source,kotlin]
----
plugins { id(&quot;slides&quot;) version &quot;1.0.0&quot; }
----

Et `settings.gradle.kts`इसे उसके न्यूनतम स्तर तक घटा दिया जाएगा बिना किसी संदर्भ के`foojay-resolver-convention`, JDK का प्रावधान प्लगिन द्वारा स्वयं प्रबंधित किया जाता है या यह एक आवश्यक शर्त के रूप में दस्तावेज़ीकृत किया जाता है।&lt;/code&gt;&lt;/pre&gt;
