&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ऑपरेशनल_जिम्मेदारियाँ&quot;&gt;�ऑपरेशनल जिम्मेदारियाँ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;कौन क्या संभालता है ?&quot; {

  rectangle &quot;Supabase द्वारा प्रबंधित (0 प्रयास)&quot; #LightGreen {
