&lt;li&gt;&lt;a href=&quot;#_त्रुटि_मामलों_का_प्रबंधन&quot;&gt;त्रुटि मामलों का प्रबंधन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अधिक_उन्नत_निरंतरता_रणनीतियाँ&quot;&gt;अधिक उन्नत निरंतरता रणनीतियाँ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_2_प्री_लोडिंग_स्क्रिप्ट_में_head&quot;&gt;चरण 2 : प्री-लोडिंग स्क्रिप्ट में `&amp;lt;head&amp;gt;&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_का_दिल&quot;&gt;समाधान का दिल&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_स्क्रिप्ट_की_अनाटॉमी_हर_पंक्ति_मायने_रखती_है&quot;&gt;स्क्रिप्ट की अनाटॉमी : हर पंक्ति मायने रखती है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सिस्टम_प्राथमिकता_का_पता_लगाना_बोनस&quot;&gt;सिस्टम प्राथमिकता का पता लगाना (बोनस)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रदर्शन_यह_स्क्रिप्ट_तेज़_क्यों_है&quot;&gt;प्रदर्शन : यह स्क्रिप्ट तेज़ क्यों है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_head_में_इष्टतम_स्थान&quot;&gt;&amp;lt;head&amp;gt;` में इष्टतम स्थान&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_3_css_एट्रिब्यूट_सेलेक्टर्स_की_शक्ति&quot;&gt;चरण 3 : CSS एट्रिब्यूट सेलेक्टर्स की शक्ति&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_बूटस्ट्रैप_5_थीम_सिस्टम&quot;&gt;बूटस्ट्रैप 5 थीम सिस्टम&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_css_संरचना_एक_थीम_सिस्टम_के_लिए&quot;&gt;CSS संरचना एक थीम सिस्टम के लिए&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_रिज़्यूमे&quot;&gt;रिज़्यूमे&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस गहन तकनीकी लेख में, हम देखते हैं कि कैसे पेज लोड होने पर होने वाले कष्टप्रद चमकते प्रभाव के बिना एक थीम (लाइट/डार्क) सेलेक्टर को लागू किया जाए। हम ब्राउज़र रेंडरिंग चक्र का विस्तृत विश्लेषण करते हैं, FOUC (फ़्लैश ऑफ़ 언स्टाइल्ड कंटेंट) के मूल कारणों की पहचान करते हैं, और सिंक्रोनस प्री-लोडिंग पर आधारित एक मज़बूत समाधान प्रस्तुत करते हैं।&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;। यह तकनीक एक सुचारू और पेशेवर उपयोगकर्ता अनुभव सुनिश्चित करती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_इस_अभिशप्त_थीम_का_झिलमिलाना&quot;&gt;समस्या: इस अभिशप्त थीम का झिलमिलाना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_उपयोगकर्ता_अनुभव_के_लिए_एक_दुःस्वप्न&quot;&gt;उपयोगकर्ता अनुभव के लिए एक दुःस्वप्न&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कल्पना कीजिए कि आपने अपने वेब एप्लिकेशन के लिए एक सुंदर डार्क थीम बनाने में घंटों बिता दिए हैं। रंग पूरी तरह संतुलित हैं, विपरीतता अनुकूल है, और आपके उपयोगकर्ता इस विकल्प से प्यार करते हैं। लेकिन एक शर्मिंदगी भरी समस्या है: हर बार पेज रीलोड होने पर, एक क्षण के लिए डिफ़ॉल्ट लाइट थीम दिखाई देती है, इससे पहले कि डार्क थीम सक्रिय हो।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह &quot;फ़्लैश&quot; दृश्य, यद्यपि संक्षिप्त (कभी‑कभी 100ms से कम), मानव आंख द्वारा तुरंत अनुभव किया जाता है और एक असहज अनुभव उत्पन्न करता है। उन उपयोगकर्ताओं के लिए जो दृष्टि सुविधा या पहुँच के कारण डार्क थीम चुनते हैं, यह झिलमिलाहट दर्दनाक भी हो सकती है, विशेष रूप से कम रोशनी वाले वातावरण में।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_फ़ouc_एक_पुराना_वेब_समस्या&quot;&gt;फ़OUC : एक पुराना वेब समस्या&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह घटना वह चीज की एक विविधता है जिसको &#39;फ़्लैश ऑफ़ अनस्टाइल्ड कंटेंट&#39; (FOUC) कहा जाता है, जो वेब विकास की एक क्लासिक समस्या है जो सीएसएस के प्रारंभिक दिनों तक वापस जाती है। FOUC तब होता है जब ब्राउज़र अस्थायी रूप से CSS शैलियों के बिना HTML सामग्री प्रदर्शित करता है, जिससे अनस्टाइल्ड सामग्री का फ़्लैश बनता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारे विशिष्ट मामले में, हम पूरी तरह से अनस्टाइल्ड सामग्री के बारे में बात नहीं कर रहे हैं, बल्कि एक के बारे में हैं&lt;strong&gt;गलत थीम का फ्लैश&lt;/strong&gt;(FOWT) - सामग्री स्टाइल की गई है, लेकिन गलत थीम के साथ। यह विशेष रूप से निराशाजनक है क्योंकि यह दर्शाता है कि हमारा एप्लिकेशन &quot;भूल&quot; जाती है कि उपयोगकर्ता की प्राथमिकता प्रत्येक पृष्ठ लोड पर।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_गुणवत्ता_की_धारणा_पर_प्रभाव&quot;&gt;गुणवत्ता की धारणा पर प्रभाव&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह समस्या, हालांकि तकनीकी है, आपके अनुप्रयोग की गुणवत्ता की धारणा पर महत्वपूर्ण प्रभाव डालती है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;पॉलिश की कमी&lt;/strong&gt;: झिलमिलाहट से ऐसा प्रतीत होता है कि एप्लिकेशन अपूर्ण है या अनुकूलित नहीं की गई है। उपयोगकर्ता अक्सर इन छोटे दृश्य दोषों को समग्र रूप से पेशेवरता की कमी से जोड़ते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;संगतता का भंग&lt;/strong&gt;: एप्लिकेशन प्रतीत होता है कि वह उपयोगकर्ता की प्राथमिकताओं को &quot;भूल&quot; रही है, जिससे इंटरफ़ेस और अपेक्षाओं के बीच असंतुलन की भावना उत्पन्न होती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;आँखों की थकान&lt;/strong&gt;: रोशनी के प्रति संवेदनशील उपयोगकर्ताओं या माइग्रेन से पीड़ित लोगों के लिए, यह रोशनी भरी फ़्लैश सिर्फ़ एक साधारण सौंदर्य संबंधित असुविधा से अधिक हो सकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;अनुभूत प्रदर्शन&lt;/strong&gt;: विडंबना यह है कि, भले ही आपकी साइट तेज़ी से लोड हो, इस ब्लिंकिंग से ऐसा प्रतीत हो सकता है कि एप्लिकेशन धीमी या अप्रतिक्रियाशील है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समस्या_का_तकनीकी_विश्लेषण&quot;&gt;समस्या का तकनीकी विश्लेषण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्या को हल करने के तरीके को समझने के लिए, सबसे पहले यह समझना होगा कि यह क्यों होता है। झिलमिलाहट एक वेब पृष्ठ के जीवन चक्र में तीन महत्वपूर्ण घटनाओं के बीच समय में अंतराल के कारण होती है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML का प्रारम्भिक पर्सिंग&lt;/strong&gt;ब्राउज़र आपके पेज की संरचना को पढ़ता और विश्लेषण करता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;सीएसएस शैलियों का अनुप्रयोग&lt;/strong&gt;ब्राउज़र CSS नियम लागू करता है और दृश्य प्रस्तुति की गणना करता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;जावास्क्रिप्ट का निष्पादन&lt;/strong&gt;: आपका कोड जो थीम बदलता है चल रहा है&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्या तब होती है जब घटना क्रमांक 3 (JavaScript का निष्पादन) ब्राउज़र द्वारा पहले से ही शुरू किए गए या समाप्त किए गए घटना क्रमांक 2 (स्टाइलिंग लागू करने की प्रक्रिया) के बाद होती है। उस समय, ब्राउज़र पहले से ही यह निर्णय ले चुका होता है कि कौन सी थीम दिखाएँ, और आपका कोड पहले रेंडर से पहले इसे प्रभावित करने के लिए बहुत देर से आता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_क्लासिक_स्क्रिप्ट_क्यों_पर्याप्त_नहीं_है&quot;&gt;क्लासिक स्क्रिप्ट क्यों पर्याप्त नहीं है?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अनुभवी_लेकिन_अप्रभावी_दृष्टिकोण&quot;&gt;अनुभवी लेकिन अप्रभावी दृष्टिकोण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक डेवलपर के लिए सबसे प्राकृतिक दृष्टिकोण यह होगा कि हम हमारे के अंत में एक स्क्रिप्ट रखें`&amp;lt;body&amp;gt;`जो उपयोगकर्ता के पसंदीदा विषय की जाँच करता है और उसे लागू करता है। यह दृष्टिकोण वेब की पारंपरिक सर्वोत्तम प्रथाओं का पालन करता है, जो पेज के अंत में स्क्रिप्ट लोड करने की सिफारिश करते हैं ताकि रेंडरिंग को ब्लॉक न किया जाए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// À la fin de &amp;lt;body&amp;gt; - L&#39;APPROCHE INSUFFISANTE
document.addEventListener(&#39;DOMContentLoaded&#39;, () =&amp;gt; {
  const theme = localStorage.getItem(&#39;preferred-theme&#39;);
  if (theme === &#39;dark&#39;) {
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
  }
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण पहली नज़र में तर्कसंगत लगता है। हम DOM के तैयार होने का इंतज़ार करते हैं, फिर हम थीम लागू करते हैं। सरल, नहीं? दुर्भाग्य से, इस सरलता में ब्राउज़र के रेंडरिंग चक्र के टाइमिंग से संबंधित एक मौलिक दोष छिपा हुआ है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_domcontentloaded_इवेंट_को_समझें&quot;&gt;DOMContentLoaded इवेंट को समझें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;घटना`DOMContentLoaded`यह तब ट्रिगर होता है जब प्रारंभिक HTML दस्तावेज़ पूरी तरह से लोड हो गया हो और ब्राउज़र द्वारा पार्स किया गया हो,&lt;strong&gt;इंतज़ार किए बिना&lt;/strong&gt;स्टाइल शीट्स, इमेज और सब-फ़्रेम्स के लोडिंग का अंत। यह समझने के लिए एक महत्वपूर्ण बिंदु है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ घटनाओं का सामान्य अनुक्रम है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ब्राउज़र HTML डाउनलोड करना शुरू करता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;यह HTML का विश्लेषण करता है जैसे ही इसे प्राप्त होता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वह टैग खोजता है`&amp;lt;link&amp;gt;`CSS के लिए और उन्हें डाउनलोड करना शुरू करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वह टैग खोजता है`&amp;lt;script&amp;gt;`और उन्हें निष्पादित करता है (उनके प्रकार और विशेषताओं के अनुसार)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वह DOM (Document Object Model) बनाता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;घटना &lt;code&gt;DOMContentLoaded&lt;/code&gt; ट्रिगर होती है&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;वह शैलियों को लागू करना जारी रखता है और लेआउट बनाता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;पहला पेंट (प्रदर्शन) होता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;घटना`load`जब सभी संसाधन लोड हो जाते हैं, तब यह ट्रिगर होता है&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्या ? के बीच चरण 6 (DOMContentLoaded) और चरण 8 (premier paint), ब्राउज़र ने पहले ही निर्णय ले लिए हैं कि पेज को कैसे दिखाना है। यदि आपके थीम बदलने वाला स्क्रिप्ट चरण 6 पर चलता है, यह पहले ही बहुत देर हो चुकी है डिफ़ॉल्ट स्टाइल के साथ पहले प्रदर्शन से बचने के लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रेंडर_ब्लॉकिंग_की_समस्या&quot;&gt;रेंडर ब्लॉकिंग की समस्या&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;वास्तव में, टाइमिंग और भी जटिल है। आधुनिक ब्राउज़र अनुभव की गई प्रदर्शन को बेहतर बनाने के लिए परिष्कृत अनुकूलन तकनीकों का उपयोग करते हैं। वे उपयोगकर्ता को स्क्रीन पर कुछ दिखाने के लिए पहले पेंट (First Contentful Paint) को जितना संभव हो सके जल्दी करने की कोशिश करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CSS डिफ़ॉल्ट रूप से &quot;render-blocking&quot; होते हैं, जिसका अर्थ है कि ब्राउज़र पहला पेंट करने से पहले स्टाइलशीट डाउनलोड और पार्स करने की प्रतीक्षा करता है। यह तर्कसंगत है: हम असामयिक सामग्री प्रदर्शित नहीं करना चाहते।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लेकिन यहाँ जाल है : जब ब्राउज़र इन CSS स्टाइल को पहली बार लागू करता है, तो वह वर्तमान DOM स्थिति के आधार पर ऐसा करता है। यदि विशेषता`data-bs-theme`अभी तक टैग पर परिभाषित नहीं है`&amp;lt;html&amp;gt;`, ब्राउज़र डिफ़ॉल्ट स्टाइल लागू करेगा (सामान्यतः हल्का थीम).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फिर, जब आपका स्क्रिप्ट चलता है और इस विशेषता को बदलता है, ब्राउज़र को करना चाहिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;इस बदलाव से प्रभावित सभी शैलियों की गणना फिर से करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;यदि आवश्यक हो तो लेआउट फिर से तैयार करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;प्रभावित तत्वों को फिर से रंगें&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पुनःगणना और फिर से चित्रण की प्रक्रिया है जो दृश्यमान चमक का कारण बनती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समस्या_का_दृश्यीकरण&quot;&gt;समस्या का दृश्यीकरण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस समस्याग्रस्त अनुक्रम को बेहतर ढंग से समझने के लिए, एक विस्तृत अनुक्रम आरेख की जाँच करते हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-flux-incorrect&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Utilisateur
participant Navigateur
participant &quot;Parser HTML&quot; as Parser
participant &quot;CSSOM&quot; as CSS
participant &quot;Script.js (शरीर का अंत)&quot; as Script
participant &quot;Render Engine&quot; as Render

Utilisateur -&amp;gt; Navigateur: Demande la page
activate Navigateur

Navigateur -&amp;gt; Parser: Parse le HTML
activate Parser
Parser -&amp;gt; CSS: Découvre et charge les CSS
activate CSS
Parser -&amp;gt; Parser: Construit le DOM
Parser -&amp;gt; Navigateur: DOM Ready (DOMContentLoaded)
deactivate Parser

CSS -&amp;gt; CSS: Parse les feuilles de style
CSS -&amp;gt; Render: CSSOM Ready
deactivate CSS

activate Render
Render -&amp;gt; Render: Calcule les styles avec data-bs-theme=&quot;&quot;note right: डिफ़ॉल्ट थीम (light)
Render -&amp;gt; Navigateur: प्रथम पेंट (हल्का थीम)
note right: उपयोगकर्ता हल्का थीम देखता है
deactivate Render

Navigateur -&amp;gt; Script: स्क्रिप्ट चलाता है
activate Script
Script -&amp;gt; Script: localStorage पढ़ता है
Script -&amp;gt; Navigateur: setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;)
deactivate Script

activate Render
Render -&amp;gt; Render: data-bs-theme= के साथ शैलियों की गणना फिर से करता है&quot;dark&quot;
note right: Thème sombre
Render -&amp;gt; Navigateur: Repaint (Thème Sombre)
note right: Clignotement visible
deactivate Render

deactivate Navigateur
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह आरेख स्पष्ट रूप से समस्या को दर्शाता है: पहला paint तब होता है जब हमारा स्क्रिप्ट सही विषय सेट करने का अवसर प्राप्त नहीं कर पाता। अनुक्रमिक repaint दृश्यमान झिलमिलाहट उत्पन्न करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_असफल_समाधान_प्रयास&quot;&gt;असफल समाधान प्रयास&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कई दृष्टिकोण इस समस्या को हल करने के प्रयास में अपनाए गए थे, लेकिन अधिकांश में अपने स्वयं के नुकसान हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;पद्धति 1 : लोड होने तक सामग्री को छिपाएँ&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;body {
  opacity: 0;
  transition: opacity 0.3s;
}

body.loaded {
  opacity: 1;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण तब तक सभी सामग्री को कैश करता है जब तक JavaScript सही विषय सेट नहीं कर देता। समस्या? यह कृत्रिम रूप से सामग्री के प्रदर्शन को देरी देता है, जिससे साइट धीमी लगती है। इसके अलावा, यदि JavaScript अक्षम है, तो उपयोगकर्ता कुछ भी नहीं देखता!&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;दृष्टिकोण 2 : एक लोडर/स्पिनर का उपयोग करें&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रवेश 1 के समान, लेकिन एक लोडिंग स्पिनर के साथ। यह समस्या को छिपाता है लेकिन वास्तविक प्रदर्शन में सुधार नहीं करता और अनावश्यक अनुभवित देरी जोड़ता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;पद्धति 3: डिफ़ॉल्ट रूप से डार्क थीम&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कुछ डेवलपर्स CSS में डार्क थीम को डिफ़ॉल्ट के रूप में सेट करते हैं। यह डार्क थीम उपयोगकर्ताओं के लिए फ्लिकरिंग को रोकता है, लेकिन हल्की थीम उपयोगकर्ताओं के लिए विपरीत समस्या पैदा करता है !&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इनमें से कोई भी दृष्टिकोण संतोषजनक नहीं है, क्योंकि वे समस्या के लक्षण का इलाज करते हैं, जड़ कारण का नहीं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वास्तविक_समाधान_जल्दी_कार्य_करें&quot;&gt;वास्तविक समाधान : जल्दी कार्य करें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस समस्या को हल करने की कुंजी यह समझना है कि हमें उस एट्रिब्यूट को परिभाषित करना होगा।&lt;code&gt;data-bs-theme&lt;/code&gt; &lt;strong&gt;पहले&lt;/strong&gt;कि ब्राउज़र CSS स्टाइल लगाना शुरू नहीं करता। इसका अर्थ है कि हमारा स्क्रिप्ट पृष्ठ के जीवन चक्र में पहले चलना चाहिए, और यही वह बात है जिसका हम अगले खंड में अन्वेषण करेंगे।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समाधान_पूर्व_लोडिंग_early_loading&quot;&gt;समाधान : पूर्व लोडिंग (Early Loading)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_मूल_सिद्धांत&quot;&gt;मूल सिद्धांत&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारी झिलमिलाहट समस्या का सुंदर समाधान एक सरल लेकिन शक्तिशाली सिद्धांत पर आधारित है:&lt;strong&gt;ब्राउज़र रेंडरिंग प्रक्रिया के साथ एप्लिकेशन की स्थिति को सिंक्रोनाइज़ करना&lt;/strong&gt;. पेज लोड होने का इंतज़ार करने के बजाय, हमें थीम सेट कर देना चाहिए&lt;strong&gt;के दौरान&lt;/strong&gt;लोड हो रहा है, इससे पहले भी कि CSS शैलियाँ लागू हो जाएँ।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण &quot;Early Loading&quot; या &quot;Synchronous Preloading&quot; वेब विकास के शब्दजाल में कहा जाता है। इस विचार का उद्देश्य हमारे थीम डिटेक्शन लॉजिक को पृष्ठ के जीवन चक्र में हो सकने वाले सबसे पहले चरण में निष्पादित करना है, आदर्श रूप से टैग में।&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;, भले ही ब्राउज़र CSS फ़ाइलों को डाउनलोड करना शुरू न करे.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_क्यों_head_आदर्श_स्थान_है&quot;&gt;क्यों &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; आदर्श स्थान है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le `&amp;lt;head&amp;gt;`एक HTML दस्तावेज़ को ब्राउज़र द्वारा क्रमिक रूप से ऊपर से नीचे तक प्रसंस्कृत किया जाता है। प्रत्येक तत्व उस क्रम में प्रसंस्कृत किया जाता है जिसमें वह दिखाई देता है। यह विशेषता हमारे समाधान के लिए अत्यंत महत्वपूर्ण है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब ब्राउज़र एक टैग से मिलता है`&amp;lt;script&amp;gt;`में`&amp;lt;head&amp;gt;` sans les attributs &lt;code&gt;async&lt;/code&gt; ou &lt;code&gt;defer&lt;/code&gt;, il :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML का पर्सिंग रोकें&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्क्रिप्ट डाउनलोड करें&lt;/strong&gt;(यदि बाह्य) या बिस्तर (यदि इनलाइन)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्क्रिप्ट को तुरंत निष्पादित करें&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML का पार्सिंग फिर से शुरू करें&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह व्यवहार, अक्सर प्रदर्शन समस्या माना जाता है (जिस कारण से सामान्य सिफ़ारिश पेज के अंत में स्क्रिप्ट रखने की होती है), इस विशेष स्थिति में हमारा सहयोगी बन जाता है। अपना थीम डिटेक्शन स्क्रिप्ट पृष्ठ के शुरू में रखकर`&amp;lt;head&amp;gt;`, हम गारंटी देते हैं कि यह ब्राउज़र टैग्स से मिलने से पहले चलता है`&amp;lt;link&amp;gt;`हमारे स्टाइल शीट्स के.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_की_तीन_स्तरीय_आर्किटेक्चर&quot;&gt;समाधान की तीन-स्तरीय आर्किटेक्चर&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा पूर्ण समाधान तीन परस्पर निर्भर परतों से बना है, प्रत्येक एक विशिष्ट भूमिका निभाती है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;परत 1 : स्थायित्व (localStorage)&lt;/strong&gt; यह परत उपयोगकर्ता के चयन को सत्रों के बीच संग्रहीत और पुनः प्राप्त करने के लिए जिम्मेदार है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;लेयर 2: प्रारंभिक सिंक्रोनाइज़ेशन (इनलाइन स्क्रिप्ट &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; में)&lt;/strong&gt; यह लेयर प्रारंभिक रेंडरिंग से पहले एप्लिकेशन की स्थिति को DOM के साथ सिंक्रनाइज़ करती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;लेयर 3: रिएक्टिव स्टाइल (CSS एट्रिब्यूट चयनकर्ता के साथ)&lt;/strong&gt; यह लेयर लेयर 2 द्वारा परिभाषित स्थिति के आधार पर दृश्य शैलियों को परिभाषित करती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब हम प्रत्येक परत का विस्तृत अन्वेषण करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_1_उपयोगकर्ता_की_पसंद_को_सेव_करना&quot;&gt;चरण 1 : उपयोगकर्ता की पसंद को सेव करना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_localstorage_आपकी_स्थायी_स्मृति&quot;&gt;localStorage : आपकी स्थायी स्मृति&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le &lt;code&gt;localStorage`यह एक Web Storage API है जो ब्राउज़र में लगातार आधार पर कुंजी‑मूल्य युग्मों को संग्रहीत करने की अनुमति देती है। कुकीज़ के विपरीत, डेटा`localStorage&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;इन्हें कभी भी सर्वर पर स्वचालित रूप से नहीं भेजा जाता&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;उनके पास अधिक स्टोरेज क्षमता होती है (आमतौर पर 5-10 एमबी)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;उनकी समाप्ति तिथि नहीं होती (स्पष्ट रूप से हटाने तक निरंतर)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इनका सीमित प्रोटोकॉल और डोमेन (Same-Origin Policy) तक सीमित है&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारे उपयोग केस के लिए`localStorage`यह सही है क्योंकि :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;हमें इस जानकारी को सर्वर के साथ साझा करने की आवश्यकता नहीं है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;हम चाहते हैं कि प्राथमिकता अनिश्चितकाल तक बनी रहे&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;आवश्यक भंडारण आकार न्यूनतम है (कुछ बाइट्स)&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_थीम_बैकअप_का_कार्यान्वयन&quot;&gt;थीम बैकअप का कार्यान्वयन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ बताया गया है कि हम उपयोगकर्ता के विकल्प को कैसे सहेजते हैं जब वह थीम बदलता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// Fonction complète pour changer le thème
function setTheme(newTheme) {
  // Validation de l&#39;entrée
  if (![&#39;light&#39;, &#39;dark&#39;, &#39;auto&#39;].includes(newTheme)) {
    console.error(&#39;Thème invalide:&#39;, newTheme);
    return;
  }

  try {
    // Sauvegarde dans localStorage
    localStorage.setItem(&#39;preferred-theme&#39;, newTheme);

    // Application immédiate dans le DOM
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

    // Dispatch d&#39;un événement personnalisé pour notifier d&#39;autres composants
    window.dispatchEvent(new CustomEvent(&#39;theme-changed&#39;, {
      detail: { theme: newTheme }
    }));

    console.log(&#39;Thème changé:&#39;, newTheme);
  } catch (error) {
    console.error(&#39;Erreur lors de la sauvegarde du thème:&#39;, error);
    // Fallback : on applique quand même le thème visuellement
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);
  }
}

// Exemple d&#39;utilisation avec un bouton
document.getElementById(&#39;theme-toggle&#39;).addEventListener(&#39;click&#39;, () =&amp;gt; {
  const currentTheme = document.documentElement.getAttribute(&#39;data-bs-theme&#39;) || &#39;light&#39;;
  const newTheme = currentTheme === &#39;light&#39; ? &#39;dark&#39; : &#39;light&#39;;
  setTheme(newTheme);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_त्रुटि_मामलों_का_प्रबंधन&quot;&gt;त्रुटि मामलों का प्रबंधन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह महत्वपूर्ण है कि मामलों को प्रबंधित किया जाए जहाँ वह`localStorage`उपलब्ध या सुलभ नहीं है। कई परिदृश्य एक्सेस को रोक सकते हैं`localStorage`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;सख्त निजी नेविगेशन&lt;/strong&gt;सफ़ारी निजी ब्राउज़िंग मोड में एक अपवाद फेंकता है`QuotaExceededError`लिखने के प्रयासों के दौरान में`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;गोपनीयता सेटिंग्स&lt;/strong&gt;: कुछ ब्राउज़र या गोपनीयता एक्सटेंशन एक्सेस को ब्लॉक कर सकते हैं`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;डोमेन की सीमाएँ&lt;/strong&gt; : Le `localStorage`यह प्रोटोकॉल पर सुलभ नहीं है`file://`कुछ ब्राउज़र में।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;भंडारण स्थान भर गया&lt;/strong&gt;हालांकि दुर्लभ, भंडारण स्थान पूरी तरह से भर सकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इसलिए हमारा कोड एक ब्लॉक का उपयोग करता है`try&amp;#8230;&amp;#8203;catch`इन स्थितियों को शालीनता से संभालने के लिए, भले ही स्थायित्व उपलब्ध न हो, थीम बदलने की सुविधा प्रदान करना जारी रखें।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अधिक_उन्नत_निरंतरता_रणनीतियाँ&quot;&gt;अधिक उन्नत निरंतरता रणनीतियाँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अधिक जटिल अनुप्रयोगों के लिए, आप अतिरिक्त रणनीतियों पर विचार कर सकते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;सर्वर सिंक्रोनाइज़ेशन (वैकल्पिक)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;async function setTheme(newTheme) {
  // Sauvegarde locale immédiate
  localStorage.setItem(&#39;preferred-theme&#39;, newTheme);
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

  // Synchronisation serveur en arrière-plan (si l&#39;utilisateur est connecté)
  if (userIsAuthenticated()) {
    try {
      await fetch(&#39;/api/user/preferences&#39;, {
        method: &#39;POST&#39;,
        headers: { &#39;Content-Type&#39;: &#39;application/json&#39; },
        body: JSON.stringify({ theme: newTheme })
      });
    } catch (error) {
      console.warn(&#39;Échec de la synchronisation serveur:&#39;, error);
      // L&#39;échec n&#39;est pas critique car la préférence est déjà sauvegardée localement
    }
  }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण लॉग इन उपयोगकर्ताओं के लिए उपकरणों के बीच प्राथमिकताओं को सिंक्रनाइज़ करने की अनुमति देता है, जबकि तत्काल स्थानीय प्रतिक्रिया बनाए रखता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_2_प्री_लोडिंग_स्क्रिप्ट_में_head&quot;&gt;चरण 2 : प्री-लोडिंग स्क्रिप्ट में `&amp;lt;head&amp;gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_का_दिल&quot;&gt;समाधान का दिल&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ वास्तव में जादू होता है। हम एक छोटा स्क्रिप्ट लगाएँगे।&lt;strong&gt;इनलाइन&lt;/strong&gt;हमारे में सीधे`&amp;lt;head&amp;gt;`, सभी हमारे टैग से पहले`&amp;lt;link&amp;gt;`शैली शीट्स की. यह स्क्रिप्ट जानबूझकर न्यूनतम, स्वतंत्र, और सबसे तेज़ तरीके से चलाने के लिए डिज़ाइन किया गया है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html lang=&quot;fr&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;
    &amp;lt;title&amp;gt;Mon Site Incroyable&amp;lt;/title&amp;gt;

    &amp;lt;!-- ==========================================
         NOTRE SCRIPT MAGIQUE DE PRÉ-CHARGEMENT
         Ce script DOIT être le premier élément
         dans le &amp;lt;head&amp;gt; après les meta tags
         ========================================== --&amp;gt;
    &amp;lt;script&amp;gt;
      // IIFE pour ne pas polluer le scope global
      (function() {
        &#39;use strict&#39;;

        try {
          // Lecture de la préférence sauvegardée
          const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);

          // Si une préférence existe, on l&#39;applique immédiatement
          if (savedTheme) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
          }
          // Optionnel : Détecter la préférence système si aucune sauvegarde
          else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
          }
          // Sinon, le thème par défaut du CSS sera utilisé (généralement &#39;light&#39;)

        } catch (error) {
          // En cas d&#39;erreur (localStorage bloqué, etc.), on log discrètement
          // et on laisse le thème par défaut s&#39;appliquer
          console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
        }
      })();
    &amp;lt;/script&amp;gt;
    &amp;lt;!-- FIN DU SCRIPT MAGIQUE --&amp;gt;

    &amp;lt;!-- Les feuilles de style sont chargées APRÈS le script --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/bootstrap.min.css&quot;&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/styles.css&quot;&amp;gt;

    &amp;lt;!-- Autres ressources du head --&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;!-- Contenu de la page --&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्क्रिप्ट_की_अनाटॉमी_हर_पंक्ति_मायने_रखती_है&quot;&gt;स्क्रिप्ट की अनाटॉमी : हर पंक्ति मायने रखती है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस स्क्रिप्ट को प्रत्येक पंक्ति में तोड़कर समझते हैं कि प्रत्येक डिज़ाइन निर्णय क्यों लिया गया :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;IIFE (तुरंत बुलाया गया फ़ंक्शन अभिव्यक्ति)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;(function() {
  // ...
})();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह संरचना एक फ़ंक्शन बनाती है जो तुरंत निष्पादित होती है। क्यों? ताकि हम अपने चर को एक स्थानीय स्कोप में अलग कर सकें और वैश्विक स्कोप को प्रदूषित होने से बचा सकें। भले ही हम केवल उपयोग करें`const`(जिसका ब्लॉक स्कोप होता है), IIFE एक अच्छी प्रथा है जो हमारे इरादों को स्पष्ट करती है और संभावित नाम संघर्षों से बचाती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;कड़ा मोड&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;&#39;use strict&#39;;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह निर्देश जावास्क्रिप्ट के कड़ाई मोड को सक्रिय करता है, जो : - अघोषित चर के उपयोग को प्रतिबंधित करता है - Génère des erreurs pour les opérations dangereuses कुछ जावास्क्रिप्ट इंजनों में प्रदर्शन में सुधार लाता है&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस तरह के गंभीर स्क्रिप्ट के लिए, हम अधिकतम सुरक्षा चाहते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ब्लॉक try&amp;#8230;&amp;#8203;catch&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;try {
  // Code principal
} catch (error) {
  console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह ब्लॉक अत्यंत महत्वपूर्ण है। यह सुनिश्चित करता है कि यदि कुछ गलत हो जाता है (localStorage ब्लॉक, असंभाव्य सिंटैक्स त्रुटि, आदि.), तो हमारा स्क्रिप्ट पूरी पृष्ठ लोड को अवरुद्ध नहीं करेगा। का उपयोग`console.warn`इसके बजाय`console.error`इंगित करता है कि यह एक गंभीर समस्या नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;localStorage की पढ़ाई&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पंक्ति कुछ संदर्भों में (सफारी की सख्त निज़ी नेविगेशन) में एक अपवाद उठा सकती है। इसलिए यह एक try&amp;#8230;&amp;#8203;catch ब्लॉक में है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;शर्ती आवेदन&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;if (savedTheme) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम केवल तभी थीम लागू करते हैं जब हमें एक संग्रहीत थीम मिली हो। अन्यथा, हम CSS को अपने डिफ़ॉल्ट थीम का उपयोग करने देते हैं। यह दृष्टिकोण जावास्क्रिप्ट में हार्ड-कोडेड डिफ़ॉल्ट मान की तुलना में अधिक मजबूत है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सिस्टम_प्राथमिकता_का_पता_लगाना_बोनस&quot;&gt;सिस्टम प्राथमिकता का पता लगाना (बोनस)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक वैकल्पिक लेकिन शालीन सुधार यह है कि यदि उपयोगकर्ता आपके एप्लिकेशन में अभी तक स्पष्ट विकल्प नहीं चुना है, तो ऑपरेटिंग सिस्टम की थीम प्राथमिकता का पता लगाया जाता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह सुविधा मीडिया क्वेरी का उपयोग करती है`prefers-color-scheme`सिस्टम को पूछने के लिए। macOS, Windows 10+, iOS, और आधुनिक Android पर, यह प्रश्न उपयोगकर्ता की सिस्टम प्राथमिकता लौटाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;फ़ायदे :&lt;/strong&gt; - व्यक्तिगत अनुभव पहली यात्रा से - संगतता के साथ उपयोगकर्ता का प्रणाली पर्यावरण - पहली यात्रा के लिए कोई भंडारण आवश्यक नहीं&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;विचार :&lt;/strong&gt; सभी ब्राउज़र इस सुविधा का समर्थन नहीं करते हैं (लेकिन 2020 से समर्थन उत्कृष्ट रहा है) - सत्यापन`window.matchMedia`संगतता सुनिश्चित करता है - उपयोगकर्ता हमेशा इस विकल्प को ओवरराइड कर सकता है&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रदर्शन_यह_स्क्रिप्ट_तेज़_क्यों_है&quot;&gt;प्रदर्शन : यह स्क्रिप्ट तेज़ क्यों है&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा प्री-लोड स्क्रिप्ट बेहद तेज़ होने के लिए डिज़ाइन किया गया है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;न्यूनतम आकार&lt;/strong&gt;लगभग 300 बाइट्स अनमिनिफ़ाइड, 200 बाइट्स मिनिफ़ाइड। यह किसी भी इमेज या जावास्क्रिप्ट लाइब्रेरी की तुलना में नगण्य है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;इनलाइन&lt;/strong&gt;को अतिरिक्त HTTP अनुरोध नहीं है। स्क्रिप्ट HTML में है, इसलिए यह तुरंत उपलब्ध है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;सादे समकालिक संचालन&lt;/strong&gt;localStorage में एक कुंजी पढ़ना (अत्यंत तेज़ संचालन) और DOM विशेषता संशोधन (ब्राउज़र का मूल संचालन).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;कोई निर्भरता नहीं&lt;/strong&gt;: कोई फ्रेमवर्क नहीं, कोई लाइब्रेरी नहीं, केवल वैनिला JavaScript। कोई स्टार्टअप समय नहीं, कोई डिपेंडेंसी पार्सिंग नहीं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;एकल निष्पादन&lt;/strong&gt;यह स्क्रिप्ट लोड होने पर केवल एक बार चलती है। कोई इवेंट लिस्नर नहीं, कोई लूप नहीं, कोई जटिल गणना नहीं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;व्यावहारिक रूप से, आधुनिक हार्डवेयर पर, यह स्क्रिप्ट 1 मिलीसेकंड से कम समय में चलती है – एक अवलगनीय समय जो पृष्ठ लोड होने के प्रदर्शन पर कोई प्रभाव नहीं डालता।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_head_में_इष्टतम_स्थान&quot;&gt;&amp;lt;head&amp;gt;` में इष्टतम स्थान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;तत्वों का क्रम में`&amp;lt;head&amp;gt;`est important. Voici l&amp;#8217;ordre recommandé :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;head&amp;gt;
    &amp;lt;!-- 1. Métadonnées critiques --&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;

    &amp;lt;!-- 2. Notre script de pré-chargement (IMMÉDIATEMENT après les meta) --&amp;gt;
    &amp;lt;script&amp;gt;
      (function() { /* notre code */ })();
    &amp;lt;/script&amp;gt;

    &amp;lt;!-- 3. Titre de la page --&amp;gt;
    &amp;lt;title&amp;gt;Mon Site&amp;lt;/title&amp;gt;

    &amp;lt;!-- 4. Feuilles de style --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;styles.css&quot;&amp;gt;

    &amp;lt;!-- 5. Autres ressources (fonts, favicons, etc.) --&amp;gt;
    &amp;lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.googleapis.com&quot;&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;

    &amp;lt;!-- 6. Autres scripts avec defer ou async --&amp;gt;
    &amp;lt;script src=&quot;app.js&quot; defer&amp;gt;&amp;lt;/script&amp;gt;
&amp;lt;/head&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह आदेश सुनिश्चित करता है कि :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;चारसेट किसी भी पाठ प्रसंस्करण से पहले परिभाषित किया जाता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;हमारा स्क्रिप्ट CSS लोड होने से पहले चलता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CSS को बाद में लोड किया जाता है और फिर सही विषय को सीधे लागू किया जाता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;अन्य गैर‑महत्वपूर्ण संसाधन अंत में लोड किए जाते हैं&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_3_css_एट्रिब्यूट_सेलेक्टर्स_की_शक्ति&quot;&gt;चरण 3 : CSS एट्रिब्यूट सेलेक्टर्स की शक्ति&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_बूटस्ट्रैप_5_थीम_सिस्टम&quot;&gt;बूटस्ट्रैप 5 थीम सिस्टम&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bootstrap 5 ने CSS कस्टम प्रॉपर्टीज़ (CSS चर) और एट्रिब्यूट सेलेक्टर्स पर आधारित थीम प्रबंधन की एक शानदार प्रणाली पेश की। यह प्रणाली एट्रिब्यूट का उपयोग करती है`data-bs-theme`तत्व पर`&amp;lt;html&amp;gt;`निर्धारित करने के लिए कि कौन सा रंग चरों का सेट लागू करना है&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस प्रणाली की सुंदरता इसकी सरलता में निहित है: अलग‑अलग स्टाइलशीट लोड करने या हजारों तत्वों पर क्लासेज को टॉगल करने के बजाय, हम केवल एक तत्व पर एक विशेषता बदलते हैं, और CSS कैस्केड के माध्यम से बाक़ी काम कर देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_css_संरचना_एक_थीम_सिस्टम_के_लिए&quot;&gt;CSS संरचना एक थीम सिस्टम के लिए&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ एक पूर्ण CSS संरचना है एक मजबूत थीम प्रणाली लागू करने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;/**
 * SYSTÈME DE THÈME COMPLET
 * Utilise les Custom Properties CSS pour une maintenance facile
 */

/* ============================================
   THÈME PAR DÉFAUT (LIGHT)
   Défini sur :root pour être le fallback
   ============================================ */
:root {
  /* Couleurs de base */
  --color-primary: #0d6efd;
  --color-secondary: #6c757d;
  --color-success: #198754;
  --color-danger: #dc3545;
  --color-warning: #ffc107;
  --color-info: #0dcaf0;

  /* Couleurs de fond */
  --bg-primary: #ffffff;
  --bg-secondary: #f8f9fa;
  --bg-tertiary: #e9ecef;

  /* Couleurs de texte */
  --text-primary: #212529;
  --text-secondary: #6c757d;
  --text-tertiary: #adb5bd;

  /* Couleurs de bordure */
  --border-color: #dee2e6;
  --border-color-subtle: #e9ecef;

  /* Couleurs d&#39;ombre */
  --shadow-sm: rgba(0, 0, 0, 0.075);
  --shadow-md: rgba(0, 0, 0, 0.15);
  --shadow-lg: rgba(0, 0, 0, 0.25&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_gradlerunner_पर_निर्भरता&quot;&gt;समस्या : GradleRunner पर निर्भरता&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_प्लगिन_विकास_का_संदर्भ&quot;&gt;प्लगिन विकास का संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लॉगिंग_की_दुविधा&quot;&gt;लॉगिंग की दुविधा&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_les_fausses_bonnes_idées&quot;&gt;Les Fausses Bonnes Idées&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_स्वतंत्र_लॉगर&quot;&gt;समाधान : स्वतंत्र लॉगर&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_अनुशंसित_वास्तुकला&quot;&gt;अनुशंसित वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्पादन_प्रवाह&quot;&gt;निष्पादन प्रवाह&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
