&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक स्थिर साइट का अंतर्राष्ट्रीयकरण (i18n) पहली नज़र में जटिल लग सकता है, लेकिन JBake के साथ Thymeleaf को मिलाकर बहुभाषी साइट बनाने के लिए सुंदर समाधान प्रदान करता है। इस लेख में, मैं आपको दिखाऊँगा कि मैंने अपने ब्लॉग पर i18n कैसे लागू किया, जिसमें टेम्पलेटिंग और कई भाषाओं में लेख प्रबंधन दोनों शामिल हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_उपयोग_केस_आरेख_use_case&quot;&gt;उपयोग केस आरेख (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;लेखक&quot; as author
actor &quot;फ़्रेंच पाठक&quot; as reader_fr
actor &quot;पाठक EN&quot; as reader_en

rectangle &quot;मल्टीभाषी JBake साइट&quot; {
  usecase &quot;लेख लिखें FR&quot; as UC1
  usecase &quot;लेख लिखें EN&quot; as UC2
  usecase &quot;i18n संदेश कॉन्फ़िगर करें&quot; as UC3
  usecase &quot;साइट उत्पन्न करें&quot; as UC4
  usecase &quot;लेख पढ़ें FR&quot; as UC5
  usecase &quot;लेख EN पढ़ें&quot; as UC6
  usecase &quot;भाषा बदलें&quot; as UC7
  usecase &quot;देखें उपलब्ध अनुवाद&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अंतर्राष्ट्रीयीकरण_की_वास्तुकला&quot;&gt;अंतर्राष्ट्रीयीकरण की वास्तुकला&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा दृष्टिकोण दो स्तम्भों पर आधारित है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;टेम्पलेटिंग का i18n&lt;/strong&gt;: Thymeleaf संदेश फाइलों का उपयोग इंटरफ़ेस तत्वों के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;सामग्री का अंतर्राष्ट्रीयीकरण&lt;/strong&gt;: भाषा के अनुसार आलेखों का संगठन एक समर्पित फ़ोल्डर संरचना में&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_संरचना_आरेख_फ़ाइल_संगठन&quot;&gt;संरचना आरेख (फ़ाइल संगठन)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_इस_दृष्टिकोण_क्यों&quot;&gt;इस दृष्टिकोण क्यों?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पृथक्करण करने की अनुमति देता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;भाषा चाहे जैसी भी हो, इंटरफ़ेस में स्थिरता बनाए रखें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;सामग्री और लेख अनुवाद को स्वतंत्र रूप से प्रबंधित करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;बड़े रिफैक्टरिंग किए बिना नयी भाषाएँ जोड़ने को सुगम बनाना&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;केवल कुछ भाषाओं में उपलब्ध लेखों की अनुमति दें&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_घटक_आरेख&quot;&gt;घटक आरेख&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;स्रोत&quot; {
  folder &quot;content/blog/2025/&quot; {
    folder &quot;(no output)&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;en/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;टेम्प्लेट्स/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;संदेश/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake इंजन&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;जेनरेटेड साइट&quot; {
  folder &quot;(no output)&quot; {
    folder &quot;ब्लॉग/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;en/&quot; {
    folder &quot;ब्लॉग/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i18n_thymeleaf_के_साथ_टेम्प्लेटिंग&quot;&gt;I18n Thymeleaf के साथ टेम्प्लेटिंग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_structure_des_fichiers_de_messages&quot;&gt;Structure des fichiers de messages&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहला चरण समर्थित प्रत्येक भाषा के लिए गुण फ़ाइलें बनाने से शुरू होता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_संदेश_फ़ाइलों_की_सामग्री&quot;&gt;संदेश फ़ाइलों की सामग्री&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ एक फ़ाइल का उदाहरण है`messages_fr.properties`(No output - empty string)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और उसका अंग्रेजी समकक्ष`messages_en.properties`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_टेम्पलेट्स_में_उपयोग&quot;&gt;टेम्पलेट्स में उपयोग&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने Thymeleaf टेम्पलेट्स में, सिंटैक्स का उपयोग करें`#{}`संदेशों तक पहुँचने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अनुक्रम_आरेख_i18n_समाधान&quot;&gt;अनुक्रम आरेख - i18n समाधान&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc
पार्सर&quot; as parser
participant &quot;Thymeleaf
इंजन&quot; as thymeleaf
participant &quot;I18n\nसमाधानकर्ता&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;स्वागत&quot;
i18n --&amp;gt; thymeleaf: &quot;स्वागत&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;होम&quot;
i18n --&amp;gt; thymeleaf: &quot;होम&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbake_में_लोकेल_कॉन्फ़िगरेशन&quot;&gt;JBake में लोकेल कॉन्फ़िगरेशन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आपकी फ़ाइल में`jbake.properties`, डिफ़ॉल्ट locale सेट करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_लेखों_का_i18n_फ़ोल्डर_द्वारा_संगठन&quot;&gt;लेखों का I18n: फ़ोल्डर द्वारा संगठन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_फ़्लो_flow_का_प्रवाह_आरेख_निर्माण&quot;&gt;फ़्लो (Flow) का प्रवाह आरेख - निर्माण&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;हर AsciiDoc फ़ाइल के लिए&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;हर टेम्प्लेट के लिए&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;सामग्री फ़िल्टरिंग&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_फ़ोल्डर_संरचना&quot;&gt;फ़ोल्डर संरचना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ाइल नामों में सफ़िक्स का उपयोग करने के बजाय, मैंने स्पष्टता और रखरखाव में सुधार लाने वाले फ़ोल्डर आधारित संगठन को चुना है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_इस_दृष्टिकोण_के_फ़ायदे&quot;&gt;इस दृष्टिकोण के फ़ायदे&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस संरचना के कई फायदे हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्पष्ट पृथक्करण&lt;/strong&gt;: प्रत्येक भाषा का अपना स्थान है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लचीला नामकरण&lt;/strong&gt;: फ़ाइलें भाषा के अनुसार विभिन्न नाम रख सकती हैं&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्केलेबिलिटी&lt;/strong&gt;: एक नई भाषा जोड़ना आसान है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;प्राकृतिक संगठन&lt;/strong&gt;: JBake के समयबद्ध तर्क का पालन करता है&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लेखों_के_मेटाडेटा&quot;&gt;लेखों के मेटाडेटा&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हर लेख में अनुवादों के बीच संबंध स्थापित करने के लिए मेटाडेटा शामिल होना चाहिए। यहाँ एक उदाहरण दिया गया है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;फ़्रेंच संस्करण&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;अंग्रेज़ी संस्करण&lt;/strong&gt;(&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
एट्रिब्यूट`:jbake-article-id:`यह महत्वपूर्ण है: यह एक ही लेख के विभिन्न अनुवादों को जोड़ने की अनुमति देता है।
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_यूआरएल_कॉन्फ़िगरेशन&quot;&gt;यूआरएल कॉन्फ़िगरेशन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;में`jbake.properties`, URL पैटर्न को भाषा शामिल करने के लिए कॉन्फ़िगर करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इससे इस प्रकार के URL उत्पन्न होंगे :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_बहुभाषी_प्रदर्शन_के_लिए_टेम्प्लेट&quot;&gt;बहुभाषी प्रदर्शन के लिए टेम्प्लेट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_भाषा_चयनकर्ता_के_साथ_लेख_टेम्पलेट&quot;&gt;भाषा चयनकर्ता के साथ लेख टेम्पलेट&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक टेम्प्लेट बनाएँ`post.html`disponible अनुवाद दिखाता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_भाषा_द्वारा_फ़िल्टर_किया_गया_सूचकांक&quot;&gt;भाषा द्वारा फ़िल्टर किया गया सूचकांक&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रत्येक भाषा के लिए इंडेक्स टेम्प्लेट बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(फ़्रेंच सूचक) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(अंग्रेज़ी अनुक्रमणिका) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_भाषाओं_के_बीच_नेविगेशन&quot;&gt;भाषाओं के बीच नेविगेशन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_वैश्विक_भाषा_चयनकर्ता&quot;&gt;वैश्विक भाषा चयनकर्ता&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_फ़्लो_चार्ट_उपयोगकर्ता_पढ़ना&quot;&gt;फ़्लो चार्ट - उपयोगकर्ता पढ़ना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने मुख्य टेम्पलेट में एक भाषा चयनकर्ता जोड़ें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सेलेक्टर_के_लिए_css_शैली&quot;&gt;सेलेक्टर के लिए CSS शैली&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_भाषा_अनुसार_rss_फ़ीड&quot;&gt;भाषा अनुसार RSS फ़ीड&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अलग-अलग भाषाओं के लिए अलग-अलग RSS फ़ीड प्राप्त करने के लिए, अलग टेम्प्लेट बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(फ़्रेंच फ़्लक्स) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अच्छी_प्रथाएँ_और_टिप्स&quot;&gt;अच्छी प्रथाएँ और टिप्स&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_cohérence_des_identifiants_darticle&quot;&gt;1. Cohérence des identifiants d&amp;#8217;article&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह सुनिश्चित करें कि`:jbake-article-id:`सभी लेखों के अनुवादों के लिए समान है। एक सुसंगत प्रारूप का उपयोग करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Préférez les identifiants en anglais pour universalité&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Utilisez des tirets pour séparer les mots&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;विशेष अक्षरों से बचें&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_संगत_तारीखें&quot;&gt;2. संगत तारीखें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक लेख के सभी अनुवादों की प्रकाशन तिथि समान होनी चाहिए`:jbake-date:`)। यह सॉर्टिंग और कालानुक्रमिक प्रदर्शन को आसान बनाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_बहुभाषी_टैग&quot;&gt;3. बहुभाषी टैग&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;टैग्स के लिए, आपके पास दो विकल्प हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;विकल्प 1: अंग्रेजी में सार्वभौमिक टैग&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Option 2 : Tags traduits avec mapping&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_अनुवाद_न_किए_गए_लेखों_का_प्रबंधन&quot;&gt;4. अनुवाद न किए गए लेखों का प्रबंधन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सभी लेखों को अनुवाद करना अनिवार्य नहीं है। यदि कोई लेख केवल एक भाषा में उपलब्ध है, तो वह अन्य भाषा की सूची में बस नहीं दिखेगा।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_बहुभाषी_साइटमैप&quot;&gt;5. बहुभाषी साइटमैप&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सभी भाषाओं को शामिल करने वाला साइटमैप बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake साइट का Thymeleaf के साथ अंतर्राष्ट्रीयकरण एक मजबूत और बनाए रखने योग्य दृष्टिकोण है। टेम्पलेटिंग से i18n (संदेश फ़ाइलों के माध्यम से) और सामग्री से i18n (फ़ोल्डर संगठन के माध्यम से) को अलग करके, आप एक लचीली प्रणाली प्राप्त करते हैं जो आसानी से विकसित हो सकती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मुख्य बिंदु जिन्हें याद रखना चाहिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Thymeleaf संदेश फाइलें&lt;/strong&gt;उपयोगकर्ता इंटरफ़ेस के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ़ोल्डर द्वारा संगठन&lt;/strong&gt;(वर्ष/भाषा) लेखों के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;आर्टिकल पहचानकर्ता&lt;/strong&gt;अनुवाद लिंक करने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समर्पित टेम्प्लेट्स&lt;/strong&gt;प्रत्येक भाषा के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्पष्ट URLs&lt;/strong&gt;भाषा कोड सहित&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_डिप्लॉयमेंट_आरेख&quot;&gt;डिप्लॉयमेंट आरेख&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;विकास मशीन&quot; {
  artifact &quot;स्रोत&quot; {
    folder &quot;सामग्री/&quot;
    folder &quot;templates/&quot;
    folder &quot;एसेट्स/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;बिल्ड सर्वर
(CI/CD)&quot; {
  component &quot;GitHub Actions
या GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / होस्टिंग&quot; {
  node &quot;स्थिर वेब सर्वर&quot; {
    artifact &quot;जेनेरेटेड साइट&quot; {
      folder &quot;/fr/ब्लॉग/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;जेनेरेटेड साइट&quot; : déploiement

actor &quot;पाठक&quot; as users

users --&amp;gt; &quot;स्थिर वेब सर्वर&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह आर्किटेक्चर आपको केवल दो भाषाओं के साथ आसानी से शुरू करने और बिना बड़े रीफ़ैक्टरिंग के अन्य भाषाएँ जोड़ने की अनुमति देता है। सब कुछ पूरी तरह स्थैतिक और उच्च प्रदर्शन वाला बना रहता है, JBake के दर्शन के अनुरूप।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बहुभाषी विकास की शुभकामनाएँ! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_टॉर_और_इसके_हस्ताक्षर_का_डाउनलोड&quot;&gt;टॉर और इसके हस्ताक्षर का डाउनलोड&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_हस्ताक्षर_का_क्रिप्टोग्राफिक_सत्यापन&quot;&gt;हस्ताक्षर का क्रिप्टोग्राफिक सत्यापन&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_टोर_प्रोजेक्ट_की_सार्वजनिक_कुंजी_आयात_करें&quot;&gt;1. टोर प्रोजेक्ट की सार्वजनिक कुंजी आयात करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_हस्ताक्षर_की_जाँच_करें&quot;&gt;2. हस्ताक्षर की जाँच करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_व्यावहारिक_मामला_वैध_हस्ताक्षर_लेकिन_प्रमाणित_नहीं_की_गई_कुंजी&quot;&gt;व्यावहारिक मामला: वैध हस्ताक्षर लेकिन प्रमाणित नहीं की गई कुंजी&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_साइन_क्यों_सत्यापित_करें&quot;&gt;साइन क्यों सत्यापित करें ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_टॉर_ब्राउज़र_की_एक्सट्रैक्शन_और_लॉन्च&quot;&gt;टॉर ब्राउज़र की एक्सट्रैक्शन और लॉन्च&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_उबुन्टू_डेस्कटॉप_एकीकरण&quot;&gt;उबुन्टू डेस्कटॉप एकीकरण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_के_साथ_शैक्षिक_संसाधनों_का_अन्वेषण_करें&quot;&gt;Tor के साथ शैक्षिक संसाधनों का अन्वेषण करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_browser_का_अपडेट&quot;&gt;Tor Browser का अपडेट&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ&quot;&gt;संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक ऐसी दुनिया में जहाँ डिजिटल गोपनीयता दिन-ब-दिन खतरे में पड़ रही है, &lt;strong&gt;Tor Browser&lt;/strong&gt; एक आवश्यक उपकरण बना रहता है जो अपने अनामिकता और जानकारी की स्वतंत्रता को संरक्षित रखने में मदद करता है। हालाँकि, यह महत्वपूर्ण है कि कभी भी डाउनलोड किया गया सॉफ़्टवेयर न चलाएँ बिना&lt;strong&gt;उसकी प्रामाणिकता सत्यापित की गई&lt;/strong&gt;. यह लेख एक पूरी विधि प्रस्तुत करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;डाउनलोड &lt;strong&gt;Tor Browser&lt;/strong&gt; और उसका हस्ताक्षर`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;डाउनलोड की गई फ़ाइल की वैधता की जाँच करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntu पर &lt;strong&gt;Tor Browser&lt;/strong&gt; इंस्टॉल करें और लॉन्च करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इसे डेस्कटॉप मेनús में दैनिक उपयोग के लिए जोड़ें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;टोर के माध्यम से शैक्षिक संसाधनों और नैतिक OSINT का अन्वेषण करें&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_टॉर_और_इसके_हस्ताक्षर_का_डाउनलोड&quot;&gt;टॉर और इसके हस्ताक्षर का डाउनलोड&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;टोर ब्राउज़र के लिए एक समर्पित फ़ोल्डर बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फिर टॉर ब्राउज़र का आर्काइव और उसकी हस्ताक्षर डाउनलोड करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_हस्ताक्षर_का_क्रिप्टोग्राफिक_सत्यापन&quot;&gt;हस्ताक्षर का क्रिप्टोग्राफिक सत्यापन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह चरण है&lt;strong&gt;आवश्यक&lt;/strong&gt;यह सुनिश्चित करने के लिए कि डाउनलोड किया गया फ़ाइल वास्तव में &lt;strong&gt;Tor Project&lt;/strong&gt; से आता है और इसे संशोधित नहीं किया गया है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_टोर_प्रोजेक्ट_की_सार्वजनिक_कुंजी_आयात_करें&quot;&gt;1. टोर प्रोजेक्ट की सार्वजनिक कुंजी आयात करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सुनिश्चित करें कि कुंजी सही तरह से आयात की गई है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_हस्ताक्षर_की_जाँच_करें&quot;&gt;2. हस्ताक्षर की जाँच करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यदि सब कुछ सही है, तो निम्नलिखित संदेश प्रदर्शित होगा :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अप्रमाणित कुंजी चेतावनी के मामले में, इसका मतलब सिर्फ यह है कि आपने अभी तक टोर प्रोजेक्ट की विश्वसनीय कुंजी पर हस्ताक्षर नहीं किए हैं, लेकिन हस्ताक्षर अभी भी वैध है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_व्यावहारिक_मामला_वैध_हस्ताक्षर_लेकिन_प्रमाणित_नहीं_की_गई_कुंजी&quot;&gt;व्यावहारिक मामला: वैध हस्ताक्षर लेकिन प्रमाणित नहीं की गई कुंजी&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पुष्टि के दौरान इस तरह का संदेश देखना सामान्य है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह संदेश इंगित करता है कि हस्ताक्षर तकनीकी रूप से &quot;सही&quot; है (फ़ाइल को बदल नहीं गया है), लेकिन आपका GPG सिस्टम स्वयं कुंजी पर &lt;strong&gt;विश्वास को प्रमाणित&lt;/strong&gt; नहीं कर सकता। इस संदेह को दूर करने के लिए, प्राथमिक कुंजी के फिंगरप्रिंट की तुलना करना आवश्यक है (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) उस आधिकारिक टोर प्रोजेक्ट साइट पर प्रकाशित के साथ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आधिकारिक साइट के अनुसार, अपेक्षित पदचिह्न है :`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्योंकि प्रदर्शित छाप द्वारा`gpg`यह आधिकारिक साइट की उस जैसी &lt;strong&gt;पूरी तरह&lt;/strong&gt; मेल खाता है, आप सुनिश्चित हो सकते हैं कि कुंजी वैध है और फ़ाइल सुरक्षित है। &quot;अस증माणित कुंजी&quot; की चेतावनी तब आपकी स्थानीय GPG कॉन्फ़िगरेशन के बारे में जानकारी होती है, और हस्ताक्षर की वैधता या फ़ाइल की प्रामाणिकता के बारे में नहीं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_साइन_क्यों_सत्यापित_करें&quot;&gt;साइन क्यों सत्यापित करें ?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GPG हस्ताक्षरों की जांच डिजिटल सुरक्षा का एक मूलभूत कार्य है। यह करने की अनुमति देती है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;गारंटी देना&lt;strong&gt;प्रामाणिकता&lt;/strong&gt;डाउनलोड किया गया सॉफ़्टवेयर का&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एक दुर्भावनापूर्ण अभिनेता द्वारा समझौता किए गए फ़ाइल की स्थापना को रोकें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;भाग लेना&lt;strong&gt;डिजिटल संप्रभुता&lt;/strong&gt;व्यक्तिगत&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एक जिम्मेदार और नैतिक डिजिटल संस्कृति को बढ़ावा दें&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;उपयोगकर्ता&quot; as U
actor &quot;सर्वर TorProject&quot; as S

usecase &quot;टोर और उसके हस्ताक्षर डाउनलोड करें&quot; as D
usecase &quot;सार्वजनिक कुंजी आयात करें&quot; as K
usecase &quot;जीपीजी हस्ताक्षर की जाँच करें&quot; as V
usecase &quot;इंस्टॉल और Tor लॉन्च करें&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_टॉर_ब्राउज़र_की_एक्सट्रैक्शन_और_लॉन्च&quot;&gt;टॉर ब्राउज़र की एक्सट्रैक्शन और लॉन्च&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;डाउनलोड की गई आर्काइव को निकालें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फिर ब्राउज़र लॉन्च करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहले लॉन्च के दौरान, एक कॉन्फ़िगरेशन विंडो खुल जाएगी ताकि टोर नेटवर्क से कनेक्शन स्थापित किया जा सके।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_उबुन्टू_डेस्कटॉप_एकीकरण&quot;&gt;उबुन्टू डेस्कटॉप एकीकरण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एप्लिकेशन मेन्यू में &lt;strong&gt;Tor Browser&lt;/strong&gt; जोड़ने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आप फिर से कर सकते हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;एप्लिकेशन मेनू से &lt;strong&gt;Tor Browser&lt;/strong&gt; लॉन्च करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इसे डॉक के पसंदीदा में जोड़ें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;यदि आप चाहें तो कीबोर्ड शॉर्टकट बनाएँ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_के_साथ_शैक्षिक_संसाधनों_का_अन्वेषण_करें&quot;&gt;Tor के साथ शैक्षिक संसाधनों का अन्वेषण करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor केवल एक अनामिकता उपकरण नहीं है। यह शैक्षिक और अनुसंधान संसाधनों तक पहुँच का एक प्रवेश द्वार है, विशेष रूप से निम्नलिखित क्षेत्रों में :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ओसिंट (सार्वजनिक स्रोत खुफिया)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;शैक्षिक साझाकरण और ओपन सोर्स&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(Tor के माध्यम से पहुँच के लिए अधिक गोपनीयता)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(Tor के माध्यम से सुलभ)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(मुक्त वैज्ञानिक साहित्य तक पहुँच)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ज्ञान का संप्रेषण और मानव की समझ डिजिटल समाज में&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;डिजिटल संस्कृति, अभिव्यक्ति की स्वतंत्रता और ज्ञान तक पहुँच के संसाधन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;तकनीकों की साइबर सुरक्षा और नैतिकता पर मुक्त दस्तावेज़&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_browser_का_अपडेट&quot;&gt;Tor Browser का अपडेट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अधतम सुरक्षा सुनिश्चित करने के लिए, &lt;strong&gt;Tor Browser&lt;/strong&gt; को अद्यतित रखना अत्यंत महत्वपूर्ण है। ब्राउज़र में एक स्वचालित अपडेट तंत्र बनाया गया है जिसे कमांड लाइन से ट्रिगर किया जा सकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor Browser स्थापना निर्देशिका से, बस स्टार्टअप स्क्रिप्ट को पुनः आरंभ करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लॉन्च पर, &lt;strong&gt;Tor Browser&lt;/strong&gt; स्वचालित रूप से जांचेगा कि क्या एक नया संस्करण उपलब्ध है। यदि ऐसा है, तो यह इसे डाउनलोड और स्थापित करेगा आपके लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह साधारण विधि सुनिश्चित करती है कि आपके पास हमेशा नवीनतम सुरक्षा पैच और सबसे हालिया सुधार हों, जो सुरक्षित ब्राउज़िंग के लिए आवश्यक है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने डाउनलोड की जाँच करना एक आवश्यक आदत है, जो सुरक्षित डिजिटल वातावरण में प्रगति करने वाले हर व्यक्ति के लिए महत्वपूर्ण है। टॉर को सत्यापित तरीके से स्थापित करना, यह&lt;strong&gt;अपनी डिजिटल अखंडता की रक्षा करें&lt;/strong&gt;, &lt;strong&gt;मुक्त सॉफ़्टवेयर में विश्वास बनाए रखें&lt;/strong&gt;, et &lt;strong&gt;अपनी सूचना स्वायत्तता को मज़बूत करना&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;डिजिटल सुरक्षा एक जागरूकता का कार्य है, न कि पागलपन का।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title टॉर के उपयोग का संक्षिप्त अवलोकन
actor Utilisateur
rectangle &quot;Tor ब्राउज़र&quot; {
rectangle &quot;अनामिकता&quot; as A
rectangle &quot;OSINT खोज&quot; as O
rectangle &quot;शैक्षिक साझा करना&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ&quot;&gt;संदर्भ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;टोर प्रोजेक्ट की आधिकारिक साइट :https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;हस्ताक्षर सत्यापन दस्तावेज़ :https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntu दस्तावेज़ :https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;शैक्षिक संग्रह :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह लेख &lt;strong&gt;सुरक्षा और डिजिटल जागरूकता&lt;/strong&gt; श्रृंखला का हिस्सा है। जिम्मेदार और शैक्षिक प्रथाओं को बढ़ावा देने हेतु स्वतंत्र टूल्स के चारों ओर.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;लक्षित दर्शक : Gradle डेवलपर्स जो मल्टी-बिल्ड प्रोजेक्ट्स में निर्भरता प्रबंधन का सामना कर रहे हैं।&lt;/div&gt;
&lt;p&gt;हमारे प्लग़िन बनाने की खोज में`site-baker`हमने एक स्वच्छ और केंद्रीकृत कोडベース को बनाए रखने का प्रयास किया है। आधुनिक ग्रैडल इकोसिस्टम में एक सर्वोत्तम प्रथा इसका उपयोग करना है।&lt;strong&gt;संस्करणों की सूची&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) निर्भरताओं को प्रबंधित करने के लिए। लेकिन जब आपका प्रोजेक्ट अधिक जटिल हो जाता है, जैसे एक**&lt;mark&gt;#&lt;/mark&gt; ग्रेडल इंटीग्रेशन JBake को JBake ग्रेडल प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर ग्रेडल बिल्ड में एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}**कहाँ एक स्वतंत्र बिल्ड (हमारा प्लगिन) को दूसरे में शामिल किया जाना चाहिए ?

यह वही जगह थी जहाँ हमारी यात्रा ने अप्रत्याशित मोड़ ले लिया। हम चाहते थे कि हमारा प्लगइन`site-baker`, जो स्वयं एक Gradle प्रोजेक्ट है, हमारे मुख्य प्रोजेक्ट के समान संस्करण कैटलॉग का उपयोग करता है। यह लेख, हमारी श्रृंखला का पाँचवाँ, बताता है कि हमने इस चुनौती को कैसे हल किया।

== 1. वर्ज़न कैटलॉग (`libs.versions.toml`) : एक अनुस्मरण

फ़ाइल`gradle/libs.versions.toml`यह Gradle की एक सुविधा है जो आपके परियोजना के निर्भरताओं के संस्करण और निर्देशांक को केंद्रीकृत करने की अनुमति देती है। इसकी सामान्य रूप से चार खंडों में संरचना होती है:

*   `[versions]`: परिभाषित करता है संस्करण संख्याओं के लिए एलियास (उदाहरण:`kotlin = &quot;1.9.20&quot;`).
*   `[libraries]`: परिभाषित करता है अलियास पूर्ण निर्भरताओं के लिए, ऊपर परिभाषित संस्करणों का उपयोग करके (ex:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`).
*   `[bundles]`कई लाइब्रेरीज़ को एक ही एलियास के तहत समूहित करता (उदाहरण:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]`)
*   `[plugins]`: ग्रैडल प्लगिन के लिए एलियास परिभाषित करता है।

एक बार परिभाषित करने पर, Gradle स्वचालित रूप से टाइप किए हुए एक्सेसर उत्पन्न करता है, जिससे आपका`build.gradle.kts` beaucoup plus lisible :

[source,kotlin]
----
dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}
----

.संस्करण कैटलॉग का डेटा प्रवाह

[plantuml, toml-flow, svg]
----
@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;ग्रैडल&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;द्वारा पढ़ा जाता है&quot;
G --&amp;gt; BuildScript : &quot;एक्सेसर `libs` जेनरेट करें&quot;
BuildScript -&amp;gt; G : &quot;libs` का उपयोग करके निर्भरताओं की घोषणा करें&quot;
@enduml
----

== 2. समस्या: एक संयुक्त बिल्ड और दो अलग‑अलग दुनियाएँ

हमारी परियोजना संरचना एक**JBake को Gradle बिल्ड में JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे कॉल करके एकीकृत किया जा सकता है:

----

tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) { mainClass.set(&quot;org.jbake.launcher.Main&quot;) classpath = configurations[&quot;jbake&quot;] args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;) }**. मुख्य परियोजना (`thymeleaf.cheroliv.com`) inclut le projet du plugin (`site-baker`) के माध्यम से आदेश`includeBuild(&quot;site-baker&quot;)`फ़ाइल में`settings.gradle.kts`.

.build composite की संरचना

[plantuml, composite-build, svg]
----
@startuml
!theme plain
package &quot;मुख्य परियोजना&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;gradle&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;### ग्रैडल एकीकरण
JBake को JBake ग्रैडल प्लगइन का उपयोग करके या JBake CLI को सीधे कॉल करके ग्रैडल बिल्ड में एकीकृत किया जा सकता है:

```kotlin
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;स्थान-बेकर&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml
----

समस्या यह है कि, डिफ़ॉल्ट रूप से, एक शामिल बिल्ड एक है**अलग दुनिया**. इसकी अपनी कॉन्फ़िगरेशन, इसका अपना जीवन चक्र, और यह फ़ाइल को नहीं देखता`libs.versions.toml`मुख्य बिल्ड का. हमारा`plugin/build.gradle.kts`उपयोग करने की कोशिश कर रहा था`libs.plugins.kotlin.jvm`, लेकिन वस्तु`libs`सही TOML फ़ाइल से उत्पन्न नहीं किया गया था, जिससे बिल्ड त्रुटियाँ हुईं।

== 3. समाधान : निर्भरता समाधान साझा करना

कई शोधों के बाद, यह समाधान Gradle की एक ऐसी विशेषता निकली जो इस मामले के लिए विशेष रूप से डिज़ाइन की गई थी :`dependencyResolutionManagement`.

फ़ाइल में`settings.gradle.kts` du **समावेशी निर्माण**import sys

def main(): data = sys.stdin.read() sys.stdout.write(data)

if __name__ == &#39;__main__&#39;: main()`site-baker/settings.gradle.kts`), हम Gradle को बता सकते हैं कि संस्करण कैटलॉग कहाँ से उपयोग करने के लिए प्राप्त किया जा सकता है।

यहाँ वह कॉन्फ़िगरेशन है जिसे हमने जोड़ा है`site-baker/settings.gradle.kts`:

[source,kotlin]
----
// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)
----

महत्वपूर्ण भाग का विश्लेषण करें:

[source,kotlin]
----
versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}
----

*   `create(&quot;libs&quot;)`: हम संस्करणों का एक कैटलॉग घोषित करते हैं जिसे लियास के माध्यम से पहुँचा जा सकेगा`libs`.
*   `from(files(&quot;../gradle/libs.versions.toml&quot;))`: यह जादू है। हम Gradle को बताते हैं कि इस कैटलॉग का स्रोत TOML फ़ाइल निर्देशिका में स्थित है।`gradle` du **मातृ परियोजना**(No output)`../`)

इस कॉन्फ़िगरेशन के साथ, बिल्ड`site-baker`अब उसे पता है कि उसे मुख्य प्रोजेक्ट के संस्करण कैटलॉग का उपयोग करना होगा। वस्तु`libs`सही ढंग से उत्पन्न किया गया है, और निर्भरताएँ अपेक्षित रूप से समाधान कर ली गई हैं।

== 4. निष्कर्ष : अच्छी तरह से प्रबंधित संयुक्त निर्माणों की शक्ति

यह अनुभव सीखों से भरपूर रहा। संस्करण कैटलॉग रखरखाव के लिए एक शानदार उपकरण है, लेकिन कंपोज़िट बिल्ड परिदृश्यों में उसका व्यवहार हमेशा सहज नहीं होता।

की याद रखनी है कि एक समावेशी बिल्ड एक स्वतंत्र बिल्ड ही रहता है। संस्करण कैटलॉग जैसी कॉन्फ़िगरेशन साझा करने के लिए, Gradle द्वारा प्रदान किए गए स्पष्ट तंत्र का उपयोग करना आवश्यक है, जैसे ब्लॉक।`dependencyResolutionManagement`में`settings.gradle.kts`.

इस समस्या को हल करके, हमने न केवल अपने build को साफ़ किया, बल्कि हमने अपने प्रोजेक्ट की स्थिरता को भी मजबूत किया है, यह सुनिश्चित करके कि प्लगइन और मुख्य प्रोजेक्ट एक ही स्रोत की सच्चाई साझा करते हैं अपने dependencies के लिए।

अगले आर्टिकल में, हम अब अधिक जटिल कार्य जोड़कर अपने प्लगइन को समृद्ध करना जारी रखेंगे, क्योंकि अब हमारी निर्भरता प्रबंधन मजबूत और केंद्रीकृत है।&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लक्षण_भूतिया_बिल्ड्स&quot;&gt;लक्षण : भूतिया बिल्ड्स&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_जांच_कॉन्फ़िगरेशन_कैश_क्या_है&quot;&gt;जांच: कॉन्फ़िगरेशन कैश क्या है?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_का_कारण_एक_अनुपालन_न_करने_वाला_प्लगइन&quot;&gt;समस्या का कारण: एक अनुपालन न करने वाला प्लगइन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अस्थायी_समाधान_कैश_को_निष्क्रिय_करें&quot;&gt;अस्थायी समाधान : कैश को निष्क्रिय करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_वास्तविक_समाधान_प्लगिन_को_संगत_बनाना&quot;&gt;वास्तविक समाधान: प्लगिन को संगत बनाना&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;lक्ष्यित दर्शक : वे Gradle डेवलपर्स जो पहले से ही &#39;जादुई&#39; या अप्रत्याशित बिल्ड व्यवहार का सामना कर चुके हैं।&lt;/div&gt;
&lt;p&gt;हमारे प्लगइन बनाने की यात्रा में`site-baker`, हमने एक कड़े TDD दृष्टिकोण का पालन किया। हर सुविधा का परीक्षण किया गया, सत्यापित किया गया, और हम विश्वास के साथ आगे बढ़ रहे थे। और फिर, एक दिन, अप्रत्याशित घटना हुई। बिल्ड्स अनियमित रूप से व्यवहार करने लगे। प्लगइन के लॉजिक या कॉन्फ़िगरेशन फ़ाइलों में किए गए संशोधनों को नजरअंदाज किया जा रहा प्रतीत होता था, और हमारे कार्यात्मक परीक्षण, जो पहले विश्वसनीय थे, स्पष्ट कारण बिना विफल हो रहे थे।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस तरह की समस्या अविश्वसनीय रूप से निराशाजनक हो सकती है। यह उपकरण की विश्वसनीयता और हमारे कोड की वैधता पर सवाल उठाता है। गहन डिबगिंग सत्र के बाद, दोषी पहचान लिया गया है: वह&lt;strong&gt;Gradle की कॉन्फ़िगरेशन कैश&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_लक्षण_भूतिया_बिल्ड्स&quot;&gt;लक्षण : भूतिया बिल्ड्स&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्या कई तरीकों से प्रकट हो रही थी :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;मैं एक कार्य में एक अक्षर श्रृंखला संशोधित कर रहा था`println`, लेकिन पुरानी स्ट्रिंग चलने के दौरान प्रदर्शित होती रही।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;मैं अपनी फाइल में एक मान बदल रहा था`managed-jbake-context.yml`, लेकिन प्लगिन ऐसा व्यवहार कर रहा था जैसे फ़ाइल में कोई संशोधन नहीं किया गया था।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कार्यात्मक परीक्षण, जो तत्काल परीक्षण परियोजनाएँ बनाते हैं, विफल हो रहे थे क्योंकि प्लगइन प्रतीत होता था कि ताज़ा बनाई गई कॉन्फ़िगरेशन फ़ाइलों का पता नहीं लगा पा रहा है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सब कुछ ऐसा लग रहा था जैसे Gradle हमारे बिल्ड की एक &quot;फ़ेंटम संस्करण&quot; को चला रहा हो, हमारे सबसे हालिया बदलावों को अनदेखा करते हुए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_जांच_कॉन्फ़िगरेशन_कैश_क्या_है&quot;&gt;जांच: कॉन्फ़िगरेशन कैश क्या है?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कन्फ़िगरेशन कैश Gradle की एक आधुनिक और बहुत शक्तिशाली विशेषता है, जो नए संस्करणों में डिफ़ॉल्ट रूप से सक्रिय है। इसका उद्देश्य बिल्ड को तेज़ करना है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;सिद्धांत सरल है :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;पहली बार चलाने पर, Gradle चरण को निष्पादित करता है&lt;strong&gt;Configuration&lt;/strong&gt; (lecture des &lt;code&gt;build.gradle.kts&lt;/code&gt;, कार्यों की रचना, निर्भरताओं का समाधान) और एक कार्य ग्राफ़ बनाता है.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इस चरण के अंत में, Gradle&lt;strong&gt;इस टास्क ग्राफ को सिरीयलाइज़ करें&lt;/strong&gt;और वह इसे कैश में रखता/रखती है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;अनुसरण करने वाले निष्पादनों में, यदि कुछ भी नहीं बदलता (बिल्ड स्क्रिप्ट्स,&lt;code&gt;gradle.properties&lt;/code&gt;, etc.), Gradle&lt;strong&gt;यह पूरी तरह से कॉन्फ़िगरेशन चरण को छोड़ देता है&lt;/strong&gt;और कैश किए गए कार्य ग्राफ़ को पुनः उपयोग करता है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बड़े प्रोजेक्ट्स पर समय की बचत अद्भुत है। हालाँकि, इस प्रदर्शन की एक कीमत है: यह प्लगइन्स के लिखे जाने के तरीके पर सख्त नियम लागू करती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;कॉन्फ़िगरेशन कैश का जीवन चक्र&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_का_कारण_एक_अनुपालन_न_करने_वाला_प्लगइन&quot;&gt;समस्या का कारण: एक अनुपालन न करने वाला प्लगइन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा प्लगइन`site-baker`वह अनजाने में कॉन्फ़िगरेशन कैश के कई नियमों का उल्लंघन कर रहा था। एक टास्क ग्राफ़ को सीरियलाइज़ करने योग्य बनाने के लिए, टास्क में कॉम्प्लेक्स ऑब्जेक्ट्स जैसे ऑब्जेक्ट के संदर्भ नहीं होने चाहिए।`Project`या फ़ाइलों को निष्पादन चरण के दौरान मनमाने ढंग से पढ़ें।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारी मुख्य त्रुटि यह थी कि हमने YAML फ़ाइल की सामग्री को कार्य के निष्पादन तर्क के भीतर सीधे पढ़ा, अपने एक्सटेंशन में संग्रहीत पथ संदर्भ का उपयोग करके। यह दृष्टिकोण कैश के साथ असंगत है क्योंकि Gradle नहीं जान सकता कि फ़ाइल की सामग्री बदल गई है यदि इस पढ़ाई को मॉडल नहीं बनाया गया है एक के रूप में.&lt;strong&gt;कार्य प्रविष्टि&lt;/strong&gt;(Task Input).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अस्थायी_समाधान_कैश_को_निष्क्रिय_करें&quot;&gt;अस्थायी समाधान : कैश को निष्क्रिय करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमें अनब्लॉक करने और पूर्वानुमेय बिल्ड व्यवहार को फिर से प्राप्त करने के लिए, सबसे तेज़ समाधान कॉन्फ़िगरेशन कैश को अक्षम करना रहा। बस फ़ाइल में निम्नलिखित लाइन जोड़ें।&lt;code&gt;gradle.properties`प्लगिन का उपयोग करने वाला प्रोजेक्ट (या हमारे मामले में, परीक्षण प्रोजेक्ट)`site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;तुरंत, बिल्ड्स ने अपना सामान्य व्यवहार फिर से हासिल कर लिया। प्रत्येक निष्पादन ने कॉन्फ़िगरेशन चरण को फिर से शुरू किया और हमारे परिवर्तन ध्यान में रखे गए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हालाँकि, यह एक टर्नअराउंड समाधान है, एक स्थायी समाधान नहीं। यह प्रदर्शन को त्याग देती है और हमारे प्लगइन की मूल समस्या को हल नहीं करती।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_वास्तविक_समाधान_प्लगिन_को_संगत_बनाना&quot;&gt;वास्तविक समाधान: प्लगिन को संगत बनाना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक प्लगइन आधुनिक Gradle इकोसिस्टम का एक अच्छा नागरिक बनने के लिए, इसे कॉन्फ़िगरेशन कैश के साथ संगत होना चाहिए। इसका मतलब है कि हमें अपने कार्यों की ओर डेटा प्रवाह के तरीके को पुनर्विचार करने की आवश्यकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कुंजी का उपयोग करने की&lt;strong&gt;प्रोवाइडर एपीआई&lt;/strong&gt;Gradle के लिए. सीधे मान पास करने के बजाय (जैसे एक`String` ou un &lt;code&gt;File&lt;/code&gt;) हमारे कार्यों के लिए, हमें बिताना चाहिए के`Property&amp;lt;T&amp;gt;`या कुछ`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;।यहाँ रिफैक्टरिंग योजना :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;कार्य प्रविष्टियों की घोषणा करें:&lt;/strong&gt;YAML फ़ाइल को पार्स करने वाला कार्य इसे इनपुट के रूप में घोषित करना चाहिए। इसके लिए हम एनोटेशन का उपयोग करते हैं।&lt;code&gt;@InputFile&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- @get:InputFile अमूर्त मान configFile: RegularFileProperty ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_संदर्भ_हमारा_प्लग़िन_site_baker&quot;&gt;1. संदर्भ : हमारा प्लग़िन `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_कॉन्फ़िगरेशन_मॉडलिंग_कोटलिन_में&quot;&gt;2. कॉन्फ़िगरेशन मॉडलिंग कोटलिन में&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_jackson_का_build_gradle_kts_में_एकीकरण&quot;&gt;3. Jackson का &lt;code&gt;build.gradle.kts&lt;/code&gt; में एकीकरण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tdd_पद्धति_yaml_पार्सिंग_का_परीक्षण&quot;&gt;4. TDD पद्धति: YAML पार्सिंग का परीक्षण&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_test_unitaire_mapper_le_yaml_en_objet_kotlin&quot;&gt;4.1. Test Unitaire : Mapper le YAML en Objet Kotlin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_कार्यात्मक_परीक्षण_कॉन्फ़िगरेशन_फ़ाइल_की_पढ़ी_को_मान्य_करें&quot;&gt;4.2. कार्यात्मक परीक्षण : कॉन्फ़िगरेशन फ़ाइल की पढ़ी को मान्य करें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_पार्सिंग_फ़्लो_का_दृश्यीकरण&quot;&gt;5. पार्सिंग फ़्लो का दृश्यीकरण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;लक्ष्य दर्शक: मध्यवर्ती Gradle डेवलपर जो जटिल कॉन्फ़िगरेशन प्रबंधित करना चाहते हैं।&lt;/div&gt;
&lt;p&gt;Gradle प्लगिन डेवलपमेंट में, जटिल कॉन्फ़िगरेशन का प्रबंधन एक सामान्य कार्य है। DSL को हज़ारों प्रॉपर्टीज़ से ओवरलोड करने के बजाय, अक्सर साफ और मेंटेनेबल रखने के लिए कॉन्फ़िगरेशन को YAML जैसे बाहरी फ़ाइल में परिभाषित करना बेहतर होता है। यह लेख आपको Jackson की शक्तिशाली लाइब्रेरी को इंटीग्रेट करने के माध्यम से मार्गदर्शन करता है, जिससे YAML फ़ाइलों को Kotlin ऑब्जेक्ट्स में पार्स किया जा सके, एक कड़ी TDD पद्धति अपनाकर हमारे प्लगिन की रोबस्टनेस सुनिश्चित की जा सके।&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_संदर्भ_हमारा_प्लग़िन_site_baker&quot;&gt;1. संदर्भ : हमारा प्लग़िन `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा प्लगइन`site-baker`इसे एक स्थिर साइट की पीढ़ी और तैनाती को स्वचालित करने के लिए डिज़ाइन किया गया है। इसे YAML कॉन्फ़िगरेशन फ़ाइल पढ़ने की आवश्यकता है (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) स्रोतों के पथ, तैनाती के गंतव्य, और Git पहचानकर्ता जैसी जानकारी प्राप्त करने के लिए&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम जो YAML कॉन्फ़िगरेशन पार्स करना चाहते हैं, वह इस तरह दिखता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_कॉन्फ़िगरेशन_मॉडलिंग_कोटलिन_में&quot;&gt;2. कॉन्फ़िगरेशन मॉडलिंग कोटलिन में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पार्स करने से पहले, हमें कोटलिन में अपने डेटा की संरचना परिभाषित करनी होगी। जैक्सन इन क्लासेस का उपयोग करके YAML सामग्री को स्वचालित रूप से मैप करेगा।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ंक्शन`parseSiteConfiguration`यह हमारे डीज़ीसीरियलाइज़ेशन के लिए प्रवेश बिंदु है। यह उपयोग करती है`ObjectMapper`Jackson का, कॉन्फ़िगर किया गया`YAMLFactory`YAML प्रारूप के लिए और`registerKotlinModule()`कोटलिन की विशिष्टताओं के समर्थन के लिए (जैसे प्रॉपर्टी के डिफ़ॉल्ट मान).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_jackson_का_build_gradle_kts_में_एकीकरण&quot;&gt;3. Jackson का &lt;code&gt;build.gradle.kts&lt;/code&gt; में एकीकरण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जैकसन का उपयोग करने के लिए, हमें आवश्यक निर्भरताएँ जोड़नी हैं में`build.gradle.kts`हमारे मॉड्यूल का`plugin`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम उपयोग करते हैं`jackson-module-kotlin`कोटलिन समर्थन के लिए और`jackson-dataformat-yaml`YAML प्रारूप के प्रबंधन के लिए&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tdd_पद्धति_yaml_पार्सिंग_का_परीक्षण&quot;&gt;4. TDD पद्धति: YAML पार्सिंग का परीक्षण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब, हम अपने पार्सिंग लॉजिक को सत्यापित करने के लिए TDD लागू करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_test_unitaire_mapper_le_yaml_en_objet_kotlin&quot;&gt;4.1. Test Unitaire : Mapper le YAML en Objet Kotlin&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक यूनिट टेस्ट से शुरू करते हैं`SiteBakerPluginTest.kt`फ़ंक्शन की जाँच करने के लिए`parseSiteConfiguration`यह YAML स्ट्रिंग को सही ढंग से ऑब्जेक्ट में बदल सकता है`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परीक्षण फ़ाइल की सामग्री पढ़ता है`managed-jbake-context.yml`(जो परीक्षण वैध होने के लिए मौजूद होना चाहिए) और वस्तु पर दावे करता है`SiteConfiguration`परिणामी. यह सत्यापित करता है कि YAML की मुख्य मान सही ढंग से मैप की गई हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_कार्यात्मक_परीक्षण_कॉन्फ़िगरेशन_फ़ाइल_की_पढ़ी_को_मान्य_करें&quot;&gt;4.2. कार्यात्मक परीक्षण : कॉन्फ़िगरेशन फ़ाइल की पढ़ी को मान्य करें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह सुनिश्चित करने के लिए कि प्लगइन अपने DSL के माध्यम से कॉन्फ़िगरेशन फ़ाइल पढ़ सके और पार्सिंग एक वास्तविक Gradle वातावरण में काम करे, हम एक फ़ंक्शनल टेस्ट जोड़ते हैं`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परीक्षण महत्वपूर्ण है क्योंकि यह वास्तविक प्रोजेक्ट में प्लगिन के निष्पादन का अनुकरण करता है। इसे होना चाहिए&lt;strong&gt;हवा-रोधी&lt;/strong&gt;, यानी उसे स्वयं फ़ाइल बनानी चाहिए`managed-jbake-context.yml`नियंत्रित सामग्री के साथ, परीक्षण की पुनरुत्पादन क्षमता और अलगाव सुनिश्चित करने के लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह कार्यात्मक परीक्षण सत्यापित करता है कि परीक्षण के अस्थायी निर्देशिका में कॉपी किया गया कॉन्फ़िगरेशन फ़ाइल अपेक्षित डेटा रखता है। यद्यपि यह परीक्षण सीधे YAML को Kotlin ऑब्जेक्ट में नहीं पार्स करता, यह फ़ाइल की उपस्थिति और उसकी सामग्री को मान्य करता है, जो प्लगइन द्वारा पार्सिंग के लिए एक आवश्यक प्रारंभिक चरण है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_पार्सिंग_फ़्लो_का_दृश्यीकरण&quot;&gt;5. पार्सिंग फ़्लो का दृश्यीकरण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आरेख निम्नलिखित YAML कॉन्फ़िगरेशन के पार्सिंग के दौरान डेटा प्रवाह और इंटरैक्शन को दर्शाता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Utilisateur Gradle&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;साइट एक्सटेंशन&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;parseSiteConfiguration()&quot; as Parser
participant &quot;SiteConfiguration (Kotlin वस्तु)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD दृष्टिकोण का पालन करते हुए, हमने Gradle प्लगिन के भीतर Kotlin ऑब्जेक्ट्स में YAML कॉन्फ़िगरेशन फ़ाइलों को पार्स करने के लिए जैक्सन लाइब्रेरी को सफलतापूर्वक इंटीग्रेट किया। इस विधि ने हमें करने की अनुमति दी :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्पष्ट रूप से मॉडलिंग&lt;/strong&gt;हमारी कॉन्फ़िगरेशन Kotlin डेटा क्लासेस के साथ।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पार्सिंग लॉजिक को सत्यापित करें&lt;/strong&gt;लक्षित यूनिट परीक्षणों के साथ।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समेकन सुनिश्चित करें&lt;/strong&gt;वास्तविक Gradle वातावरण में हर्मेटिक कार्यात्मक परीक्षणों के माध्यम से।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह ठोस आधार हमें हमारे प्लगइन को ऐसी सुविधाओं के साथ विस्तार करने के लिए भरोसा दिलाता है जो इस कॉन्फ़िगरेशन पर आधारित हैं, साथ ही कोड की बनाए रखने योग्यता और मजबूती को सुनिश्चित करते हुए। अब YAML पार्सिंग हमारे प्लगइन की एक विश्वसनीय और परीक्षण की गई सुविधा है।&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परियोजना_प्रारम्भ&quot;&gt;परियोजना प्रारम्भ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_हमारा_पहला_tdd_चक्र_एक_कार्य_रिकॉर्ड_करें&quot;&gt;2. हमारा पहला TDD चक्र : एक कार्य रिकॉर्ड करें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_पहला_परीक्षण_जो_परीक्षण_असफल_होता_है&quot;&gt;2.1. पहला परीक्षण (जो परीक्षण असफल होता है)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_अगला_कोड_परीक्षा_पास_करना&quot;&gt;2.2. अगला कोड (परीक्षा पास करना)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_दूसरा_चक्र_tdd_एक_डीएसएल_एक्सटेंशन_जोड़ें&quot;&gt;3. दूसरा चक्र TDD: एक डीएसएल एक्सटेंशन जोड़ें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_पहला_परीक्षण&quot;&gt;3.1. पहला परीक्षण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_कोड_फिर&quot;&gt;3.2. कोड फिर&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_कार्यात्मक_परीक्षण_एकीकरण_को_सत्यापित_करें&quot;&gt;4. कार्यात्मक परीक्षण: एकीकरण को सत्यापित करें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_एकीकरण_परीक्षण_एक_नियंत्रित_वातावरण_बनाएँ&quot;&gt;4.1. एकीकरण परीक्षण: एक नियंत्रित वातावरण बनाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_लॉजिक_को_अंतिम_रूप_दें&quot;&gt;4.2. लॉजिक को अंतिम रूप दें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस लेख में, हम जानेंगे कि Gradle प्लगिन के लिए एक मजबूत विकास आधार कैसे स्थापित करें, परीक्षण-निर्देशित विकास (TDD - Test-Driven Development) दृष्टिकोण का उपयोग करके। यह विधि सुनिश्चित करती है कि हमारा कोड मजबूत, रखरखाव योग्य और आवश्यकताओं को सटीक रूप से शुरू से ही पूरा करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परियोजना_प्रारम्भ&quot;&gt;परियोजना प्रारम्भ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle बहुत सहजता से एक नए प्लगइन के निर्माण को सुविधाजनक बनाता है, कमांड के माध्यम से।&lt;code&gt;gradle init&lt;/code&gt;. कोटलिन के साथ एक &#39;Gradle Plugin&#39; बनाने का चयन करके, हमें एक उपयोग के लिए तैयार प्रोजेक्ट संरचना मिलती है, जिसमें दो महत्वपूर्ण प्रकार के परीक्षण शामिल हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;इकाई परीक्षण :&lt;/strong&gt; Situés dans &lt;code&gt;src/test&lt;/code&gt;, वे हमारे प्लगिन के अलग‑अलग घटकों को सत्यापित करने की अनुमति देते हैं, जैसे किसी कार्य की आंतरिक तर्क या किसी एक्सटेंशन की कॉन्फ़िगरेशन। वे तेज़ हैं और इन्हें ग्रैडल की पूर्ण निष्पादन की आवश्यकता नहीं है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;कार्यात्मक परीक्षण :&lt;/strong&gt;में स्थित`src/functionalTest`, वे उपयोग करते हैं`GradleRunner`पूरी Gradle बिल्ड चलाने के लिए एक अस्थायी परीक्षण प्रोजेक्ट में। यह हमें नियंत्रित वातावरण में प्लगिन के वास्तविक व्यवहार को सत्यापित करने की अनुमति देता है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_हमारा_पहला_tdd_चक्र_एक_कार्य_रिकॉर्ड_करें&quot;&gt;2. हमारा पहला TDD चक्र : एक कार्य रिकॉर्ड करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारी पहली आवश्यकता सरल है: प्लगइन को एक नामित कार्य पंजीकृत करना होगा`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_पहला_परीक्षण_जो_परीक्षण_असफल_होता_है&quot;&gt;2.1. पहला परीक्षण (जो परीक्षण असफल होता है)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD के अनुसार, हम पहले एक परीक्षण लिखते हैं जो इस कार्य की मौजूदगी की जाँच करता है। में`SiteBakerPluginTest.kt`(हमारा यूनिट परीक्षण फ़ाइल), हम जोड़ते हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परीक्षण विफल होता है, क्योंकि हमने अभी तक अपने प्लगइन में कोई कोड नहीं लिखा है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_अगला_कोड_परीक्षा_पास_करना&quot;&gt;2.2. अगला कोड (परीक्षा पास करना)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब हम आवश्यक न्यूनतम कोड लिख रहे हैं में`SiteBakerPlugin.kt`ताकि परीक्षा पास हो:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम परीक्षणों को फिर से चला रहे हैं, और वे पास हो रहे हैं. हमारी पहली सुविधा मान्य है.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_दूसरा_चक्र_tdd_एक_डीएसएल_एक्सटेंशन_जोड़ें&quot;&gt;3. दूसरा चक्र TDD: एक डीएसएल एक्सटेंशन जोड़ें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अगली आवश्यकता उपयोगकर्ताओं को उनके DSL ब्लॉक के माध्यम से हमारे प्लग़िन को कॉन्फ़िगर करने की अनुमति देना है`build.gradle.kts`. हम एक ब्लॉक चाहते हैं`site { &amp;#8230;&amp;#8203; }`जहाँ आप एक कॉन्फ़िगरेशन पथ निर्दिष्ट कर सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_पहला_परीक्षण&quot;&gt;3.1. पहला परीक्षण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम एक परीक्षण जोड़ रहे हैं ताकि यह सत्यापित किया जा सके कि एक्सटेंशन`site`यह ठीक से दर्ज की गई है और हम इसे मान दे सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह टेस्ट फेल हो जाता है क्योंकि न तो क्लास`SiteExtension`एक्सटेंशन का पंजीकरण भी मौजूद नहीं है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_कोड_फिर&quot;&gt;3.2. कोड फिर&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम क्लास बनाते हैं`SiteBakerExtension.kt`और हम अपडेट करते हैं`SiteBakerPlugin.kt`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;परीक्षण फिर से पास हो रहे हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_कार्यात्मक_परीक्षण_एकीकरण_को_सत्यापित_करें&quot;&gt;4. कार्यात्मक परीक्षण: एकीकरण को सत्यापित करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब जब इकाइयाँ परीक्षण की गई हैं, हमें यह सुनिश्चित करने की आवश्यकता है कि सब कुछ एक वास्तविक बिल्ड में एक साथ काम करे। यह फ़ंक्शनल परीक्षण की भूमिका है`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_एकीकरण_परीक्षण_एक_नियंत्रित_वातावरण_बनाएँ&quot;&gt;4.1. एकीकरण परीक्षण: एक नियंत्रित वातावरण बनाएँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परीक्षण हमारा प्लगइन का उपयोग करके एक वास्तविक प्रोजेक्ट का अनुकरण करेगा। इसे विश्वसनीय होने के लिए, इसे&lt;strong&gt;वायुरोधी&lt;/strong&gt;, यानी इसे मौजूदा फ़ाइलों पर निर्भर नहीं रहना चाहिए। इसे स्वयं सभी आवश्यक शर्तें बनानी चाहिए जो इसके निष्पादन के लिए आवश्यक हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;टेस्ट इसलिए:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;एक बनाना`build.gradle.kts`हमारा प्लगिन और इसका DSL का उपयोग करने वाला परीक्षण.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;कॉन्फ़िगरेशन फ़ाइल बनाएँ&lt;/strong&gt;(&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(Note: The output preserves the exact characters, including spaces and the parenthesis, as there is no translatable text.)&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) जो प्लगिन को पढ़ना चाहिए। यह परीक्षण की मजबूती के लिए एक महत्वपूर्ण चरण है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;कार्य को निष्पादित करें`printSiteConfig`के माध्यम से`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;निर्माण आउटपुट सही है, यह सुनिश्चित करें।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रत्येक निष्पादन में इस कॉन्फ़िगरेशन फ़ाइल को कॉपी करके या बनाकर, हम सुनिश्चित करते हैं कि परीक्षण है।&lt;strong&gt;पुनरावृत्ति योग्य&lt;/strong&gt;और यह बाहरी स्थिति पर निर्भर नहीं करता है। यह हमारे परीक्षणों को फ़ाइल पढ़ने से संबंधित रिग्रेशन से सुरक्षित रखता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परीक्षा तब तक असफल रहेगी जब तक कि कार्य`printSiteConfig`यह एक्सटेंशन का मान वास्तव में उपयोग नहीं करेगा।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_लॉजिक_को_अंतिम_रूप_दें&quot;&gt;4.2. लॉजिक को अंतिम रूप दें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हम टास्क को अद्यतन कर रहे हैं में`SiteBakerPlugin.kt`इसे कॉन्फ़िगर किया गया मान प्रदर्शित करने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सभी परीक्षण, इकाई और कार्यात्मक, अब पास हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD दृष्टिकोण का पालन करते हुए, हमने एक प्लगइन को चरणबद्ध और सुरक्षित तरीके से बनाया। प्रत्येक छोटी सुविधा को तुरंत एक परीक्षण द्वारा मान्य किया जाता है, तेज़ इकाई परीक्षणों से लेकर पूरी एकीकरण को मान्य करने वाले कार्यात्मक परीक्षणों तक।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने परीक्षणों को कार्यात्मक बनाने में सावधानी बरतते हुए&lt;strong&gt;हर्मेटिक&lt;/strong&gt;— विशेषकर प्रोग्रामेटिक रूप से आवश्यक कॉन्फ़िगरेशन फ़ाइलों को बनाकर — हम एक अत्यंत मज़बूत सुरक्षा जाल बुन रहे हैं। यह सख़्ती हमें प्रभावी रूप से रिग्रेशन से बचाती है और हमें भविष्य में अधिक जटिल सुविधाएँ जोड़ने का भरोसा देता है, जैसे YAML कॉन्फ़िगरेशन फ़ाइल का पार्सिंग।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह मजबूत परीक्षण आधार प्लगइन के रखरखाव और भविष्य के विकास के लिए सबसे मूल्यवान संपत्ति है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_1_परियोजना_सहायक_शुरू_करें&quot;&gt;चरण 1: परियोजना सहायक शुरू करें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;लक्षित दर्शक : शुरुआती से मध्यम स्तर के डेवलपर Gradle के साथ&lt;/div&gt;
&lt;p&gt;एक नया Gradle प्लगइन प्रोजेक्ट शुरू करने की प्रक्रिया डरावनी लग सकती है। सौभाग्य से, Gradle एक शक्तिशाली इंटरैक्टिव सहायक प्रदान करता है, कार्य`init`, जो एक पूर्ण, स्वच्छ और उपयोग के लिए तैयार प्रोजेक्ट संरचना उत्पन्न करता है। यह गाइड आपको दिखाएगा कि इस टूल का उपयोग करके एक स्वस्थ प्लगइन आधार कैसे बनाया जाए, इसकी संरचना समझाएगा और आपको दिखाएगा कि पहले बिल्ड कार्य कैसे चलाएँ जाएँ।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_1_परियोजना_सहायक_शुरू_करें&quot;&gt;चरण 1: परियोजना सहायक शुरू करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कमांड`gradle init`यह प्रारम्भ बिंदु है। यह एक कमांड-लाइन असिस्टेंट शुरू करता है जो आपको परियोजना को कॉन्फ़िगर करने के लिए प्रश्नों की एक श्रृंखला पूछता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;खाली फ़ोल्डर में अपना टर्मिनल खोलें और चलाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सहायक आपको मार्गदर्शन करेगा। यहाँ एक कोटलिन में लिखे गए Gradle प्लगिन के लिए किए जाने वाले विकल्प हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;जनरेट करने के लिए परियोजना के प्रकार का चयन करें:&lt;/strong&gt;चुनें`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;कार्यान्वयन भाषा चुनें:&lt;/strong&gt;चुनें`Kotlin`।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;बिल्ड स्क्रिप्ट DSL चुनें:&lt;/strong&gt;चुनिए`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;परियोजना का नाम:&lt;/strong&gt;अपने प्रोजेक्ट के लिए एक नाम दर्ज करें (उदाहरण:`site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;**&lt;mark&gt;#&lt;/mark&gt; ग्रैडल एकीकरण&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे कॉल करके Gradle बिल्ड में एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}**### ग्रेडल इंटीग्रेशन
JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड में इंटीग्रेट किया जा सकता है:

----

tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) { mainClass.set(&quot;org.jbake.launcher.Main&quot;) classpath = configurations[&quot;jbake&quot;] args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;) } ```

अपने प्लगिन के लिए एक विशिष्ट पहचानकर्ता दें (उदाहरण के लिए:`com.cheroliv.site-baker`).

1.  **### gradle एकीकरण

JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड में एकीकृत किया जा सकता है:

```kotlin
----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}
----

प्लगिन वर्ग:**कार्यान्वयन कक्षा का नाम निर्दिष्ट करें (उदाहरण:`com.cheroliv.SiteBakerPlugin`).

एक बार पूरा हो जाने के बाद, Gradle एक पूर्ण फ़ाइल पदानुक्रम उत्पन्न करता है।

.प्रारंभीकरण प्रक्रिया का आरेख

[plantuml, init-gradle, svg]
----
@startuml
start
:Lancer `gradle init`;
:Choisir &quot;Gradle plugin&quot;;
:Choisir &quot;### Gradle इंटीग्रेशन
JBake को Gradle बिल्ड्स में JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर एकीकृत किया जा सकता है:

```kotlin
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}&quot; (langage);
