&lt;li&gt;&lt;a href=&quot;#_पाइपलाइन_मेट्रिक्स&quot;&gt;पाइपलाइन मेट्रिक्स&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सूचनाएँ&quot;&gt;सूचनाएँ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
