&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_विस्तृत_उपयोगकर्ता_कहानियाँ&quot;&gt;विस्तृत उपयोगकर्ता कहानियाँ&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_us1_1_बॉट_की_इनिशियलाइज़ेशन&quot;&gt;US1.1 : बॉट की इनिशियलाइज़ेशन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_us2_1_spotify_की_स्मार्ट_खोज&quot;&gt;US2.1 : Spotify की स्मार्ट खोज&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_us3_1_निष्कर्षण_यूट्यूब_लचीली&quot;&gt;US3.1 : निष्कर्षण यूट्यूब लचीली&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_approche_log_driven_development&quot;&gt;Approche Log Driven Development&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_लॉगिंग_रणनीति&quot;&gt;लॉगिंग रणनीति&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लॉग्स_की_संरचना&quot;&gt;लॉग्स की संरचना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_exemple_de_log_design&quot;&gt;Exemple de Log Design&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pydantic_के_साथ_सत्यापन_आर्किटेक्चर&quot;&gt;Pydantic के साथ सत्यापन आर्किटेक्चर&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_डेटा_मॉडल&quot;&gt;डेटा मॉडल&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कार्यात्मक_त्रुटि_प्रबंधन&quot;&gt;कार्यात्मक त्रुटि प्रबंधन&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_monades_और_error_handling&quot;&gt;Monades और Error Handling&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रतिबंधों_से_बचने_की_रणनीति&quot;&gt;प्रतिबंधों से बचने की रणनीति&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_बहु_स्रोत_दृष्टिकोण&quot;&gt;बहु-स्रोत दृष्टिकोण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_आवर्ती_विकास_योजना&quot;&gt;आवर्ती विकास योजना&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_स्प्रिंट_योजना&quot;&gt;स्प्रिंट योजना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_गुणवत्ता_मेट्रिक्स&quot;&gt;गुणवत्ता मेट्रिक्स&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_तैनाती_और_मॉनिटरिंग&quot;&gt;तैनाती और मॉनिटरिंग&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_उत्पादन_वास्तुकला&quot;&gt;उत्पादन वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रोएक्टिव_मॉनिटरिंग&quot;&gt;प्रोएक्टिव मॉनिटरिंग&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष_और_संभावनाएँ&quot;&gt;निष्कर्ष और संभावनाएँ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_अगले_चरण&quot;&gt;अगले चरण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_परिचय&quot;&gt;&lt;/a&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Discord बॉट विकसित करने की प्रक्रिया जिसमें Spotify और YouTube APIS का एकीकरण होता है, एक आधुनिक तकनीकी चुनौती पेश करता है, विशेषकर हालिया प्रतिबंधों और प्लेटफ़ॉर्म के विकास के प्रकाश में। यह लेख एक पद्धति-आधारित दृष्टिकोण प्रस्तुत करता है जो के आधार पर&lt;strong&gt;लॉग-आधारित विकास&lt;/strong&gt;(LDD), टेस्ट-चालित विकास का एक विस्तार, फ़ंक्शनल प्रोग्रामिंग पैराडाइम में Python के साथ लागू।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा लक्ष्य: एक मजबूत, बनाए रखने योग्य और विस्तारशील बॉट बनाना जो वर्तमान संगीत APIs की सीमाओं को नेविगेट कर सके और Discord पर एक सुचारू उपयोगकर्ता अनुभव प्रदान कर सके।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ_और_वर्तमान_चुनौतियाँ&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_संदर्भ_और_वर्तमान_चुनौतियाँ&quot;&gt;&lt;/a&gt;संदर्भ और वर्तमान चुनौतियाँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_संगीत_apis_का_विकास&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_संगीत_apis_का_विकास&quot;&gt;&lt;/a&gt;संगीत APIs का विकास&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;संगीत प्लेटफ़ॉर्म ने अपनी एक्सेस नीतियों को काफी कड़ा कर दिया है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Spotify&lt;/strong&gt;: मेटाडेटा तक पहुँच पर प्रतिबंध, कोटा सीमा&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;YouTube&lt;/strong&gt;: एंटी-बॉट नीति मजबूत, प्रमाणीकरण की जटिलता&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;विवाद&lt;/strong&gt;: नई सुरक्षा और प्रदर्शन आवश्यकताएँ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लॉग_चालित_विकास_की_पद्धति&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_लॉग_चालित_विकास_की_पद्धति&quot;&gt;&lt;/a&gt;लॉग-चालित विकास की पद्धति&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;LDD टडी को बढ़ाती है, लॉग्स को विकास के केंद्र में रखकर :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लॉग्स की परिभाषा&lt;/strong&gt;कार्यान्वयन से पहले&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;अवलोकन द्वारा सत्यापन&lt;/strong&gt;अपेक्षित व्यवहार&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पूर्ण ट्रेसेबिलिटी&lt;/strong&gt;कुछ डेटा प्रवाह&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;प्रोएक्टिव डिबगिंग&lt;/strong&gt;त्रुटियों की आशा में&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सैद्धांतिक_वास्तुकला&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_सैद्धांतिक_वास्तुकला&quot;&gt;&lt;/a&gt;सैद्धांतिक वास्तुकला&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme aws-orange

package &quot;डिस्कॉर्ड बॉट कोर&quot; {
  [Command Handler] as CH
  [Event Listener] as EL
  [Log Manager] as LM
}

package &quot;सगीत एकीकरण परत&quot; {
  [Spotify Client] as SC
  [YouTube Client] as YC
  [Audio Processor] as AP
}

package &quot;कार्यात्मक कोर&quot; {
  [Data Validation] as DV
  [Business Logic] as BL
  [Error Handling] as EH
}

package &quot;बाह्य APIs&quot; {
  [Spotify API] as SAPI
  [YouTube API] as YAPI
  [Discord API] as DAPI
}

CH --&amp;gt; BL
EL --&amp;gt; BL
BL --&amp;gt; DV
BL --&amp;gt; EH
BL --&amp;gt; LM

SC --&amp;gt; SAPI
YC --&amp;gt; YAPI
CH --&amp;gt; DAPI

DV ..&amp;gt; SC : validates
DV ..&amp;gt; YC : validates
AP --&amp;gt; SC
AP --&amp;gt; YC

LM --&amp;gt; EH : logs errors
LM --&amp;gt; BL : logs operations

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_स्टैक_तकनीक_और_फ़ंक्शनल_पैराडाइम&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_स्टैक_तकनीक_और_फ़ंक्शनल_पैराडाइम&quot;&gt;&lt;/a&gt;स्टैक तकनीक और फ़ंक्शनल पैराडाइम&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_तकनीकी_विकल्प&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_तकनीकी_विकल्प&quot;&gt;&lt;/a&gt;तकनीकी विकल्प&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा स्टैक फंक्शनल प्रोग्रामिंग के इर्द-गिर्द घूमता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;PyMonade&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;साइड इफ़ेक्ट्स का प्रबंधन और फ़ंक्शनों का संयोजन&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;Pydantic&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;टाइप-सेप डेटा मान्यता और सीरियलाइज़ेशन&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;Asyncio&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;असिंक्रोनस प्रोग्रामिंग APIs के लिए&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;Structlog&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;संरचित लॉगिंग LDD के लिए&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लागू_कार्यात्मक_सिद्धांत&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_लागू_कार्यात्मक_सिद्धांत&quot;&gt;&lt;/a&gt;लागू कार्यात्मक सिद्धांत&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain

title कार्यात्मक डेटा प्रवाह
participant &quot;डिस्कोर्ड कमांड&quot; as DC
participant &quot;सत्यापक&quot; as V
participant &quot;व्यवसाय तर्क&quot; as BL
participant &quot;API क्लाइंट&quot; as AC
participant &quot;लॉगर&quot; as L

DC -&amp;gt; V: Raw Input
activate V
V -&amp;gt; V: Pydantic Validation
V -&amp;gt; L: Log Validation
V --&amp;gt; DC: Maybe[ValidData]
deactivate V

DC -&amp;gt; BL: ValidData
activate BL
BL -&amp;gt; BL: Pure Computation
BL -&amp;gt; L: Log Business Logic
BL -&amp;gt; AC: API Request
activate AC
AC -&amp;gt; AC: IO Operation
AC -&amp;gt; L: Log API Call
AC --&amp;gt; BL: Maybe[Result]
deactivate AC
BL --&amp;gt; DC: Either[Error, Success]
deactivate BL

DC -&amp;gt; L: Log Final Result

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_agile_पद्धति_और_बैकलॉग&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_agile_पद्धति_और_बैकलॉग&quot;&gt;&lt;/a&gt;Agile पद्धति और बैकलॉग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_एपिक_मुख्य&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_एपिक_मुख्य&quot;&gt;&lt;/a&gt;एपिक मुख्य&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा विकास 4 प्रमुख एपिक्स के इर्द-गिर्द आयोजित है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_epic_1_आधारभूत_संरचना_बॉट_discord&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_epic_1_आधारभूत_संरचना_बॉट_discord&quot;&gt;&lt;/a&gt;Epic 1: आधारभूत संरचना बॉट Discord&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;व्यवसाय मूल्य&lt;/strong&gt; : आधार मजबूत और विस्तारयोग्य&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;स्वीकृति मानदंड&lt;/strong&gt; : - स्थिर Discord कनेक्शन, पुनः कनेक्शन प्रबंधन के साथ - मॉड्यूलर कमांड सिस्टम - एकीकृत संरचित लॉगिंग - केंद्रीकृत त्रुटि प्रबंधन&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_epic_2_स्पोटिफ़ाई_का_एकीकरण&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_epic_2_स्पोटिफ़ाई_का_एकीकरण&quot;&gt;&lt;/a&gt;Epic 2 : स्पोटिफ़ाई का एकीकरण&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;व्यवसायिक मूल्य&lt;/strong&gt;: संगीत मेटाडेटा तक पहुंच&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;स्वीकृति मानदंड&lt;/strong&gt; : - सुरक्षित OAuth2 प्रमाणीकरण स्मार्ट कैश के साथ ट्रैक्स की खोज - API कोटा प्रबंधन नेटवर्क त्रुटियों पर फ़ॉलबैक&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_epic_3_youtube_का_एकीकरण&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_epic_3_youtube_का_एकीकरण&quot;&gt;&lt;/a&gt;Epic 3 : YouTube का एकीकरण&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;व्यवसायिक मूल्य&lt;/strong&gt; : ऑडियो सामग्री तक पहुंच&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;स्वीकृति मानक&lt;/strong&gt; : - प्रतिबंधों का क़ानूनी परिहार - अनुकूलित ऑडियो एक्सट्रैक्शन निजी/हटाए गए वीडियो का प्रबंधन - Respect des ToS YouTube&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_epic_4_संगीत_विशेषताएँ&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_epic_4_संगीत_विशेषताएँ&quot;&gt;&lt;/a&gt;Epic 4 : संगीत विशेषताएँ&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;व्यवसाय मूल्य&lt;/strong&gt; : पूर्ण उपयोगकर्ता अनुभव&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;स्वीकृति मानदंड : - उच्च गुणवत्ता ऑडियो लेक्चर - बुद्धिमान पढ़ने की क़्यू - Discord वॉयस कमांड - क्रॉस‑प्लेटफ़ॉर्म सिंक्रोनाइज़ेशन&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_विस्तृत_उपयोगकर्ता_कहानियाँ&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_विस्तृत_उपयोगकर्ता_कहानियाँ&quot;&gt;&lt;/a&gt;विस्तृत उपयोगकर्ता कहानियाँ&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_us1_1_बॉट_की_इनिशियलाइज़ेशन&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_us1_1_बॉट_की_इनिशियलाइज़ेशन&quot;&gt;&lt;/a&gt;US1.1 : बॉट की इनिशियलाइज़ेशन&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;जैसे एक&lt;/strong&gt; डेवलपर &lt;strong&gt;मैं चाहता हूँ&lt;/strong&gt; एक डिस्कॉर्ड बॉट जो विश्वसनीय तरीके से जुड़ता है &lt;strong&gt;इसके लिए&lt;/strong&gt; सेवा की उपलब्धता सुनिश्चित करना&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;DoD (पूरा होने की परिभाषा)&lt;/strong&gt; : - [ ] बॉट स्टार्टअप पर स्वचालित रूप से कनेक्ट होता है - [ ] स्ट्रक्चर्ड लॉग प्रत्येक चरण का दस्तावेज़ीकरण करते हैं विच्छेद होने पर स्वचालित पुनर्संयोजन - [ ] एकीकरण परीक्षण पास होते हैं&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_us2_1_spotify_की_स्मार्ट_खोज&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_us2_1_spotify_की_स्मार्ट_खोज&quot;&gt;&lt;/a&gt;US2.1 : Spotify की स्मार्ट खोज&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;के रूप में&lt;/strong&gt; Discord उपयोगकर्ता &lt;strong&gt;मैं&lt;/strong&gt; Spotify के माध्यम से ट्रैक्स खोजना &lt;strong&gt;के लिए&lt;/strong&gt; संगीत खोजने और साझा करने&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;DoD&lt;/strong&gt; : - [ ] आदेश`/search`कार्यात्मक - [ ] प्रासंगिक परिणाम मेटाडेटा के साथ - [ ] अनुरोधों को अनुकूलित करने के लिए स्थानीय कैश - [ ] API त्रुटियों का शालीन प्रबंधन&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_us3_1_निष्कर्षण_यूट्यूब_लचीली&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_us3_1_निष्कर्षण_यूट्यूब_लचीली&quot;&gt;&lt;/a&gt;US3.1 : निष्कर्षण यूट्यूब लचीली&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;के रूप में&lt;/strong&gt; प्रणाली &lt;strong&gt;मैं चाहता हूँ&lt;/strong&gt; यूट्यूब ऑडियो को विश्वसनीय तरीके से निकालना &lt;strong&gt;के लिए&lt;/strong&gt; सेवा की निरंतरता बनाए रखना&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;DoD&lt;/strong&gt; : - [ ] Extraction sans violation des ToS - [ ] इष्टतम ऑडियो गुणवत्ता - [ ] भौगोलिक प्रतिबंधों का प्रबंधन - [ ] ऑपरेशनों के विस्तृत लॉग&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_approche_log_driven_development&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_approche_log_driven_development&quot;&gt;&lt;/a&gt;Approche Log Driven Development&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लॉगिंग_रणनीति&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_लॉगिंग_रणनीति&quot;&gt;&lt;/a&gt;लॉगिंग रणनीति&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme spacelab

title Log Driven Development Flow

start

:Define Expected Behavior;
note right: Spécification des logs attendus

:Write Log Assertions;
note right: Tests basés sur les logs

:Implement Minimal Code;
note right: Code juste suffisant

:Run &amp;amp; Observe Logs;
note right: Validation comportementale

if (Logs Match Expectations?) then (yes)
  :Refactor &amp;amp; Optimize;
  note right: Amélioration continue
else (no)
  :Debug via Logs;
  note right: Analyse des écarts
  :Fix Implementation;
endif

:Integration Tests;
note right: Validation end-to-end

stop

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लॉग्स_की_संरचना&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_लॉग्स_की_संरचना&quot;&gt;&lt;/a&gt;लॉग्स की संरचना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा LDD दृष्टिकोण संरचित लॉग्स का उपयोग करता है जिसमें समान्यात्मक स्तर होते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;ट्रेस&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;विस्तृत डेटा प्रवाह&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;डिबग&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;फ़ंक्शन के आंतरिक स्थितियाँ&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;सूचना&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;सफल व्यवसाय संचालन&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;चेतावनी&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;खराब स्थितियाँ लेकिन नियंत्रित&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;त्रुटि&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;हस्तक्षेप की आवश्यकता वाली त्रुटियाँ&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;(no output)&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;सिस्टम विफलताएँ&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_exemple_de_log_design&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_exemple_de_log_design&quot;&gt;&lt;/a&gt;Exemple de Log Design&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spotify की खोज सुविधा को लागू करने से पहले, हम इसके लॉग्स को परिभाषित करते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;INFO: spotify.search.start query=&quot;bohemian rhapsody&quot; user_id=123456
DEBUG: spotify.search.validation query_length=16 safe_chars=true
DEBUG: spotify.search.api_call endpoint=&quot;/search&quot; params={...}
INFO: spotify.search.success results_count=15 duration_ms=340&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pydantic_के_साथ_सत्यापन_आर्किटेक्चर&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_pydantic_के_साथ_सत्यापन_आर्किटेक्चर&quot;&gt;&lt;/a&gt;Pydantic के साथ सत्यापन आर्किटेक्चर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_डेटा_मॉडल&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_डेटा_मॉडल&quot;&gt;&lt;/a&gt;डेटा मॉडल&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारी कार्यात्मक दृष्टिकोण प्रारंभिक सत्यापन को प्राथमिकता देता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme cerulean-outline

class SpotifyTrack {
  +id: str
  +name: str
  +artists: List[str]
  +duration_ms: int
  +external_urls: Dict[str, str]
  --
  +validate_duration() : bool
  +to_discord_embed() : Embed
}

class YouTubeVideo {
  +id: str
  +title: str
  +duration: timedelta
  +available: bool
  --
  +validate_availability() : bool
  +extract_audio_url() : Optional[str]
}

class DiscordCommand {
  +command: str
  +args: List[str]
  +user: User
  +channel: Channel
  --
  +validate_permissions() : bool
  +log_execution() : None
}

SpotifyTrack --|&amp;gt; BaseModel
YouTubeVideo --|&amp;gt; BaseModel
DiscordCommand --|&amp;gt; BaseModel

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कार्यात्मक_त्रुटि_प्रबंधन&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_कार्यात्मक_त्रुटि_प्रबंधन&quot;&gt;&lt;/a&gt;कार्यात्मक त्रुटि प्रबंधन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_monades_और_error_handling&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_monades_और_error_handling&quot;&gt;&lt;/a&gt;Monades और Error Handling&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;PyMonad का उपयोग करके त्रुटियों का सुंदर प्रबंधन संभव है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme toy

title त्रुटि प्रबंधन प्रवाह
participant &quot;आदेश&quot; as C
participant &quot;शायद Monad&quot; as M
participant &quot;कोई भी मोनैड&quot; as E
participant &quot;लॉगर&quot; as L

C -&amp;gt; M: search_query
activate M

alt Valid Query
  M -&amp;gt; E: Success(query)
  activate E
  E -&amp;gt; E: api_call()

  alt API Success
    E -&amp;gt; L: log_success()
    E --&amp;gt; C: Right(result)
  else API Error
    E -&amp;gt; L: log_api_error()
    E --&amp;gt; C: Left(api_error)
  end
  deactivate E

else Invalid Query
  M -&amp;gt; L: log_validation_error()
  M --&amp;gt; C: Nothing
end

deactivate M

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्रतिबंधों_से_बचने_की_रणनीति&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_प्रतिबंधों_से_बचने_की_रणनीति&quot;&gt;&lt;/a&gt;प्रतिबंधों से बचने की रणनीति&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_बहु_स्रोत_दृष्टिकोण&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_बहु_स्रोत_दृष्टिकोण&quot;&gt;&lt;/a&gt;बहु-स्रोत दृष्टिकोण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;API प्रतिबंधों के सामने, हम विविधीकरण रणनीति अपनाते हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme mars

title बहु‑स्रोत रणनीति
start

:User Request;

:Primary Source\n(Spotify);

if (Available?) then (yes)
  :Return Spotify Data;
  stop
else (no)
  :Log Fallback;
  :Secondary Source\n(YouTube Music);

  if (Available?) then (yes)
    :Return YouTube Data;
    stop
  else (no)
    :Tertiary Source\n(Local Cache);

    if (Available?) then (yes)
      :Return Cached Data;
      :Log Cache Hit;
      stop
    else (no)
      :Return Error;
      :Log Complete Failure;
      stop
    end
  end
end

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_आवर्ती_विकास_योजना&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_आवर्ती_विकास_योजना&quot;&gt;&lt;/a&gt;आवर्ती विकास योजना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्प्रिंट_योजना&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_स्प्रिंट_योजना&quot;&gt;&lt;/a&gt;स्प्रिंट योजना&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा विकास 2 सप्ताह के स्प्रिंट चक्र का पालन करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;स्प्रिंट 1-2&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;इंफ्रास्ट्रक्चर और डिस्कॉर्ड बॉट कोर&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;स्प्रिंट 3-4&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;Spotify के साथ LDD का एकीकरण&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;स्प्रिंट 5-6&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;यूट्यूब एकीकरण और परिहार&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;स्प्रिंट 7-8&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;उन्नत संगीत सुविधाएँ&lt;/p&gt;
&lt;/dd&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;&lt;strong&gt;स्प्रिंट 9-10&lt;/strong&gt;&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;अनुकूलन और उत्पादन&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_गुणवत्ता_मेट्रिक्स&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_गुणवत्ता_मेट्रिक्स&quot;&gt;&lt;/a&gt;गुणवत्ता मेट्रिक्स&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रत्येक स्प्रिंट का मूल्यांकन :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लॉग कवरेज&lt;/strong&gt;&amp;gt;90% महत्वपूर्ण पथों&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;API की विश्वसनीयता&lt;/strong&gt;: &amp;lt;1% अप्रबंधित त्रुटियाँ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;प्रदर्शन&lt;/strong&gt;: &amp;lt;500ms औसत प्रतिक्रिया समय&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;रखरखाव क्षमता&lt;/strong&gt;: चक्रीय जटिलता &amp;lt;10&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_तैनाती_और_मॉनिटरिंग&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_तैनाती_और_मॉनिटरिंग&quot;&gt;&lt;/a&gt;तैनाती और मॉनिटरिंग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_उत्पादन_वास्तुकला&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_उत्पादन_वास्तुकला&quot;&gt;&lt;/a&gt;उत्पादन वास्तुकला&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme vibrant

cloud &quot;डिस्कॉर्ड सर्वर&quot; {
  [User Commands]
}

node &quot;उत्पादन पर्यावरण&quot; {
  [Discord Bot]
  [Log Aggregator]
  [Metrics Collector]
  [Health Monitor]
}

database &quot;लॉग भंडारण&quot; {
  [Structured Logs]
  [Error Traces]
  [Performance Metrics]
}

cloud &quot;बाह्य API&quot; {
  [Spotify API]
  [YouTube API]
}

[User Commands] --&amp;gt; [Discord Bot]
[Discord Bot] --&amp;gt; [Log Aggregator]
[Discord Bot] --&amp;gt; [Spotify API]
[Discord Bot] --&amp;gt; [YouTube API]
[Log Aggregator] --&amp;gt; [Structured Logs]
[Metrics Collector] --&amp;gt; [Performance Metrics]
[Health Monitor] --&amp;gt; [Error Traces]

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रोएक्टिव_मॉनिटरिंग&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_प्रोएक्टिव_मॉनिटरिंग&quot;&gt;&lt;/a&gt;प्रोएक्टिव मॉनिटरिंग&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;LDD इंटेलिजेंट मॉनिटरिंग को सुगम बनाता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लॉग पैटर्न पर आधारित अलर्ट&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;व्यवहारिक असामान्यताओं का पता लगाना&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;वास्तविक समय के व्यावसायिक मेट्रिक्स&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लॉग सहसंबंध द्वारा सहायता प्राप्त डिबगिंग&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष_और_संभावनाएँ&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_निष्कर्ष_और_संभावनाएँ&quot;&gt;&lt;/a&gt;निष्कर्ष और संभावनाएँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पद्धतिगत दृष्टिकोण कार्यात्मक प्रतिमान के लाभों को Log Driven Development की मजबूती के साथ जोड़ता है। यह हमें करने देता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समस्याओं की भविष्यवाणी&lt;/strong&gt;अग्रिम रूप से डिज़ाइन किए गए लॉग्स के कारण&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गुणवत्ता बनाए रखें&lt;/strong&gt;लगातार मान्यता के माध्यम से&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;जल्दी से अनुकूलित करना&lt;/strong&gt;एपीआई परिवर्तनों के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ट्रेसेबिलिटी सुनिश्चित करें&lt;/strong&gt;संचालन का समापन&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इटरेटिव विकास और मॉड्यूलर वास्तुकला बदलते संगीत प्लेटफ़ॉर्म की बाधाओं के प्रति स्केलेबिलिटी सुनिश्चित करती हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अगले_चरण&quot;&gt;&lt;a class=&quot;anchor&quot; href=&quot;#_अगले_चरण&quot;&gt;&lt;/a&gt;अगले चरण&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ़ेज़ 1&lt;/strong&gt;PyMonade के साथ कोर का कार्यान्वयन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ़ेज़ 2&lt;/strong&gt;: Spotify के साथ स्मार्ट कैश का एकीकरण&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ़ेज़ 3&lt;/strong&gt;: समाधान YouTube लचीली&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;चरण ४&lt;/strong&gt;: उन्नत सुविधाएँ और अनुकूलन&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह मजबूत अवधारणात्मक आधार हमें तकनीकी चुनौतियों से निपटने और एक असाधारण उपयोगकर्ता अनुभव प्रदान करने में सक्षम बनाएगा।&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;इस लेख के बाद एक तकनीकी श्रृंखला आएगी जिसमें प्रत्येक घटक के कार्यान्वयन का विस्तृत विवरण दिया जाएगा, कोड उदाहरणों और कार्यात्मक पैटर्न के साथ।&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_इस_गाइड_का_उद्देश्य&quot;&gt;इस गाइड का उद्देश्य&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पूर्वापेक्षा&quot;&gt;पूर्वापेक्षा&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_इंस्टॉल_और_कॉन्फ़िगर_करें_उपकरण&quot;&gt;इंस्टॉल और कॉन्फ़िगर करें उपकरण&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_lm_sensors_सेंसरों_का_पता_लगाने_के_लिए&quot;&gt;lm-sensors सेंसरों का पता लगाने के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tlp_स्मार्ट_ऊर्जा_प्रबंधक&quot;&gt;tlp` : स्मार्ट ऊर्जा प्रबंधक&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cpufrequtils_सीपीयू_की_आवृत्तियों_को_सीमित_करना&quot;&gt;cpufrequtils` : सीपीयू की आवृत्तियों को सीमित करना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_auto_cpufreq_सरलीकृत_गतिशील_प्रबंधन&quot;&gt;auto-cpufreq` : सरलीकृत गतिशील प्रबंधन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_thermald_स्वचालित_तापीय_संरक्षण&quot;&gt;thermald` : स्वचालित तापीय संरक्षण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_वास्तविक_समय_में_निगरानी&quot;&gt;वास्तविक समय में निगरानी&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sensors_कमांड_लाइन_में&quot;&gt;sensors` कमांड लाइन में&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_विकल्प_gui_psensor&quot;&gt;विकल्प GUI : `psensor&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अतिरिक्त_सुझाव&quot;&gt;अतिरिक्त सुझाव&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सिस्टम_को_साफ़_करके_अतिभार_को_सीमित_करना&quot;&gt;सिस्टम को साफ़ करके अतिभार को सीमित करना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ज्यादा_आगे_जाने_के_लिए&quot;&gt;ज्यादा आगे जाने के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;�📚 निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्या आप महसूस करते हैं कि आपका लैपटॉप Ubuntu पर असामान्य रूप से गर्म हो रहा है ? यह लेख आपको एक विधि प्रस्तुत करता है&lt;strong&gt;सॉफ़्टवेयर&lt;/strong&gt;पूरा के लिए&lt;strong&gt;ठंडा करना&lt;/strong&gt;, &lt;strong&gt;निरीक्षण करना&lt;/strong&gt; et &lt;strong&gt;तापमान को नियंत्रित करना&lt;/strong&gt;आपकी मशीन का।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_इस_गाइड_का_उद्देश्य&quot;&gt;इस गाइड का उद्देश्य&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;कंप्यूटर की वैश्विक तापमान को कम करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ऊर्जा प्रबंधन को अनुकूलित करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;आलोचनात्मक घटकों (CPU, GPU, आदि) की निगरानी करें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;धीमी गति से बचें&lt;strong&gt;तापीय थ्रॉटलिंग&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Installer les outils;
:Analyser les capteurs;
:Appliquer des réglages;
note right: cpufreq, tlp, auto-cpufreq
:Surveiller en temps réel;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पूर्वापेक्षा&quot;&gt;पूर्वापेक्षा&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;एक Ubuntu मशीन (20.04 या उससे ऊपर अनुशंसित)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इंटरनेट कनेक्शन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कमांड लाइन दक्षता (प्रारंभिक से मध्यम स्तर)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_इंस्टॉल_और_कॉन्फ़िगर_करें_उपकरण&quot;&gt;इंस्टॉल और कॉन्फ़िगर करें उपकरण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_lm_sensors_सेंसरों_का_पता_लगाने_के_लिए&quot;&gt;lm-sensors सेंसरों का पता लगाने के लिए&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install lm-sensors
sudo sensors-detect
sensors&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जवाब दें`YES`सभी प्रश्नों के लिए`sensors-detect`मॉड्यूल की पहचान करने के लिए&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tlp_स्मार्ट_ऊर्जा_प्रबंधक&quot;&gt;tlp` : स्मार्ट ऊर्जा प्रबंधक&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install tlp tlp-rdw
sudo systemctl enable tlp
sudo systemctl start tlp&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
(*) --&amp;gt; &quot;TLP सक्रिय है ?&quot;
if &quot;हाँ&quot; then
  --&amp;gt; [yes] &quot;उपभोग में कमी&quot;
  --&amp;gt; &quot;सीपीयू आवृत्ति सीमा&quot;
else
  --&amp;gt; [no] &quot;स्टार्ट TLP&quot;
  --&amp;gt; &quot;स्वचालित सक्रियण&quot;
endif
--&amp;gt;(*)
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_cpufrequtils_सीपीयू_की_आवृत्तियों_को_सीमित_करना&quot;&gt;cpufrequtils` : सीपीयू की आवृत्तियों को सीमित करना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install cpufrequtils
cpufreq-info
sudo cpufreq-set -g powersave&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;powersave&lt;/code&gt;: आवृत्ति शिखरों को सीमित करता है&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;performance&lt;/code&gt;: शक्ति को प्राथमिकता देता है, तापमान के नुकसान पर&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_auto_cpufreq_सरलीकृत_गतिशील_प्रबंधन&quot;&gt;auto-cpufreq` : सरलीकृत गतिशील प्रबंधन&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;git clone https://github.com/AdnanHodzic/auto-cpufreq.git
cd auto-cpufreq
sudo ./auto-cpufreq-installer
sudo auto-cpufreq --install&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Analyse charge système;
:Réglage fréquence CPU;
:Vérification température;
:Adaptation dynamique;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_thermald_स्वचालित_तापीय_संरक्षण&quot;&gt;thermald` : स्वचालित तापीय संरक्षण&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install thermald
sudo systemctl enable thermald
sudo systemctl start thermald&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_वास्तविक_समय_में_निगरानी&quot;&gt;वास्तविक समय में निगरानी&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sensors_कमांड_लाइन_में&quot;&gt;sensors` कमांड लाइन में&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;watch -n 2 sensors&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_विकल्प_gui_psensor&quot;&gt;विकल्प GUI : `psensor&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install psensor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सरल ग्राफ़िकल इंटरफ़ेस CPU, GPU, पंखों के लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अतिरिक्त_सुझाव&quot;&gt;अतिरिक्त सुझाव&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;भारी टैब्स और अनुप्रयोग बंद करें (उदा: ब्राउज़र)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;बैटरी पर तीव्र उपयोग से बचें&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;प्रक्रियाओं की निगरानी करना माध्यम से`htop`(No output)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install htop
htop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सिस्टम_को_साफ़_करके_अतिभार_को_सीमित_करना&quot;&gt;सिस्टम को साफ़ करके अतिभार को सीमित करना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt autoremove
sudo apt autoclean
sudo journalctl --vacuum-time=3d&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ज्यादा_आगे_जाने_के_लिए&quot;&gt;ज्यादा आगे जाने के लिए&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आप एक सेवा बना सकते हैं`systemd`स्टार्टअप पर स्वचालित रूप से कुछ सेटिंग्स लागू करने के लिए कस्टम. क्या आप अगले लेख में एक उदाहरण चाहते हैं? मुझे बताइए !&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;�📚 निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इन साधारण उपकरणों को संयोजित करके, आप हासिल करेंगे :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;नियंत्रित CPU तापमान&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कम वेंटिलेशन शोर&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एक बेहतर स्वायत्तता&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने तापमान को नियमित रूप से निगरानी करना न भूलें, जिससे कोई अतितापन न हो।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;(No output) अपने CPU को पिघलने से रोकना बेहतर है। (No output)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_युद्ध_का_मैदान_एक_मॉकअप_तीन_ब्राउज़र_बहुतेरे_रेंडर&quot;&gt;युद्ध का मैदान : एक मॉकअप, तीन ब्राउज़र, बहुतेरे रेंडर&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_1_सेक्शन_hero_की_उड़ती_हुई_कार्ड&quot;&gt;समस्या 1: सेक्शन &quot;Hero&quot; की उड़ती हुई कार्ड&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_2_कैनिबल_नेविगेशन_बार&quot;&gt;समस्या 2 : कैनिबल नेविगेशन बार&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_3_अराजक_टाइपोग्राफी&quot;&gt;समस्या 3: अराजक टाइपोग्राफी&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_4_नेविगेशन_बार_जो_बाहर_निकलती_है&quot;&gt;समस्या 4 : नेविगेशन बार जो बाहर निकलती है&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_5_अदृश्य_हैम्बर्गर_मेनू&quot;&gt;समस्या 5: अदृश्य हैम्बर्गर मेनू&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष_अथक_डिबगिंग_के_सबक&quot;&gt;निष्कर्ष: अथक डिबगिंग के सबक&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;पढ़ने का समय :&lt;/strong&gt; लगभग 7 मिनट &lt;strong&gt;स्तर :&lt;/strong&gt; मध्यवर्ती&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस विस्तृत केस स्टडी में, हम ब्राउज़र संगतता की सबसे सामान्य और कभी‑कभी सबसे निराशाजनक समस्याओं का विश्लेषण करेंगे जो Bootstrap 5.2 के साथ UI मॉकअप बनाने के दौरान सामना किए जाते हैं। फ्लेक्सबॉक्स प्रबंधन से लेकर फ़ॉन्ट रेंडरिंग की सूक्ष्मता तक, हमारा डिबगिंग यात्रा देखें कि फायरफ़ॉक्स के तहत एक विकृत डिज़ाइन को कैसे सभी ब्राउज़रों पर पिक्सेल‑परफेक्ट अनुभव में बदलें।&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_युद्ध_का_मैदान_एक_मॉकअप_तीन_ब्राउज़र_बहुतेरे_रेंडर&quot;&gt;युद्ध का मैदान : एक मॉकअप, तीन ब्राउज़र, बहुतेरे रेंडर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हर फ्रंट‑एंड डेवलपर को यह भावना होती है. घंटों की मेहनत के बाद मॉकअप आखिरकार परफेक्ट हो जाती है. संरेखण सटीक होते हैं, टाइपोग्राफी सुंदर होती है, एनिमेशन चिकनी होती हैं. हम संतोष की सांस लेते हैं, अपने काम को क्रोम (या ब्रेव, या एज) पर देखते हैं, फिर सावधानी बरतते हुए प्रोजेक्ट को फ़ायरफ़ॉक्स पर खोलते हैं. और उसी moment पर, आपदा आ जाती है. त element बाहर निकल जाते हैं, संरेखण टूट जाते हैं, फॉन्ट के आकार अव्यवस्थित हो जाते हैं&amp;#8230;&amp;#8203; सुंदर सामंजस्य उड़ जाता है.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह बिल्कुल वही परिदृश्य है जिसका सामना हमने एक नई पोर्टफ़ोलियो इंटरफेस विकसित करते समय किया। ज़रूरतें सरल थीं: एक आधुनिक, उत्तरदायी होम पेज, जिसमें थीम सेलेक्टर (हल्का, गहरा, और उच्च विपरीत), &lt;strong&gt;vanilla JavaScript&lt;/strong&gt; का उपयोग करके और &lt;strong&gt;Bootstrap 5.2&lt;/strong&gt; के नवीनतम संस्करण के साथ।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह लेख चमत्कारिक समाधानों की सूची नहीं है। यह हमारे डिबगिंग सत्र का लॉगबुक है, ब्लिंक (Chromium, Brave) और गेको (Firefox) इंजनों के रेंडरिंग अंतर के &quot;क्यों&quot; में एक गहरा गोता, और यह प्रदर्शित करता है कि मजबूत और आधुनिक समाधान हमेशा जल्दबाजी में लगाए गए पैचों से बेहतर होते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;उपयोग केस आरेख: डिबगिंग प्रक्रिया&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;फ़्रंट-एंड डेवलपर&quot; as Dev

rectangle &quot;बूटस्ट्रैप 5 UI मॉकअप&quot; {
  usecase &quot;फ़्लेक्सबॉक्स संरेखण को ठीक करें&quot; as UC1
  usecase &quot;पैडिंग को डायनामिक रूप से समायोजित करें (JS)&quot; as UC2
  usecase &quot;टाइपोग्राफी नियंत्रित करना (clamp())&quot; as UC3
  usecase &quot;मेन्यू ओवरफ़्लो को हल करें&quot; as UC4
  usecase &quot;मेनू आइकन को दिखाएँ&quot; as UC5
}

actor &quot;फ़ायरफ़ॉक्स ब्राउज़र&quot; as Firefox

Dev -- (UC1)
Dev -- (UC2)
Dev -- (UC3)
Dev -- (UC4)
Dev -- (UC5)

(UC1) ..&amp;gt; Firefox : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
(UC2) ..&amp;gt; Firefox : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
(UC3) ..&amp;gt; Firefox : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
(UC4) ..&amp;gt; Firefox : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
(UC5) ..&amp;gt; Firefox : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;

note right of Firefox : Révèle les problèmes de compatibilité
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;घटक आरेख: फ्रंट-एंड समाधान की वास्तुकला&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain

package &quot;फ़्रंट-एंड समाधान&quot; {
  component &quot;HTML (टेम्प्लेट FTL)&quot; as HTML
  component &quot;script.js&quot; as JS
  component &quot;styles.css&quot; as CSS

  interface &quot;DOM का नियंत्रण&quot; as iDOM
  interface &quot;Corrections CSS&quot; as iCSS
}

package &quot;फ़्रेमवर्क&quot; {
  component &quot;बूटस्ट्रैप 5.2&quot; as BS
  interface &quot;Variables CSS&quot; as iVars
  interface &quot;उपयोगी कक्षाएँ&quot; as iUtils
}

HTML ..&amp;gt; iDOM : nécessite
JS ..&amp;gt; iDOM : réalise

HTML ..&amp;gt; iCSS : nécessite
CSS ..&amp;gt; iCSS : réalise

CSS ..&amp;gt; iVars : nécessite
BS ..&amp;gt; iVars : fournit

HTML ..&amp;gt; iUtils : utilise
BS ..&amp;gt; iUtils : fournit

note right of JS
  - Mesure la hauteur de la navbar
  - Applique le padding dynamiquement
end note

note right of CSS
  - Utilise clamp() pour la typographie
  - Réduit les marges du menu
  - Surcharge l&#39;icône du menu via les variables
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_1_सेक्शन_hero_की_उड़ती_हुई_कार्ड&quot;&gt;समस्या 1: सेक्शन &quot;Hero&quot; की उड़ती हुई कार्ड&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहला बग भी सबसे स्पष्ट था. स्वागत अनुभाग (&quot;hero&quot;) दो कॉलम से मिलकर बना है: बायाँ ओर मुख्य शीर्षक; दायाँ ओर एक परिचय कार्ड।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लक्षण:&lt;/strong&gt;Chrome और Brave पर, दोनों कॉलम लंबवत रूप से पूरी तरह से केंद्रित थे। फ़ायरफ़ॉक्स पर, दायाँ कार्ड अनियमित रूप से बाएँ पाठ के नीचे गिर रहा था।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;जाँच :&lt;/strong&gt;HTML कोड फिर भी सरल और सही लग रहा था, Bootstrap के मानक क्लासेस का उपयोग करके।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;section id=&quot;home&quot; class=&quot;hero-section&quot;&amp;gt;
    &amp;lt;div class=&quot;container&quot;&amp;gt;
        &amp;lt;!-- Cette ligne est la clé du problème --&amp;gt;
        &amp;lt;div class=&quot;row align-items-center min-vh-100&quot;&amp;gt;
            &amp;lt;div class=&quot;col-lg-6&quot;&amp;gt;
                &amp;lt;!-- Contenu de gauche --&amp;gt;
            &amp;lt;/div&amp;gt;
            &amp;lt;div class=&quot;col-lg-6&quot;&amp;gt;
                &amp;lt;!-- Carte de droite --&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/div&amp;gt;
&amp;lt;/section&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारा अनुकूलित CSS के लिए`.hero-section`परिभाषित कर रहा था`display: flex` et &lt;code&gt;align-items: center&lt;/code&gt;, और कक्षा`min-vh-100`दिया गया था एक न्यूनतम ऊँचाई पंक्ति को (&lt;code&gt;div.row&lt;/code&gt;). तो फ़ायरफ़ॉक्स ने कॉलम को केंद्रित करने से क्यों इनकार कर दिया ?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गहरा कारण :&lt;/strong&gt;यह एक पाठ्यपुस्तक उदाहरण है कि रेंडर इंजन निहित ऊँचाइयों की व्याख्या कैसे करते हैं। La`&amp;lt;section&amp;gt;`की एक`min-height`, लेकिन नहीं`height`स्पष्ट. लागू करने के लिए`align-items-center`के भीतर`div.row`, Firefox को इस कंटेनर की संदर्भ ऊंचाई जानने की आवश्यकता है। जैसे उसके माता-पिता (&lt;code&gt;div.container&lt;/code&gt; et la `&amp;lt;section&amp;gt;`खुद) की कोई ऊँचाई नहीं थी&lt;strong&gt;सख्त&lt;/strong&gt;, Firefox खो गया था। Blink इंजन, अधिक उदार, की &quot;deviner&quot; करने की क्षमता रखता है और तत्वों को केंद्रित करने में सक्षम है। Gecko, विनिर्देश के प्रति अधिक पालन करने वाला, ऐसा नहीं करता।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;हल :&lt;/strong&gt;�ऊँचाई स्पष्ट करें। हमने मजबूर किया वह`.container` et le `.row`अपने संबंधित पैरेंट की 100% ऊँचाई लेने के लिए यूटिलिटी क्लास का उपयोग करना`h-100`Bootstrap का&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;section id=&quot;home&quot; class=&quot;hero-section&quot;&amp;gt;
    &amp;lt;div class=&quot;container h-100&quot;&amp;gt;
        &amp;lt;div class=&quot;row align-items-center min-vh-100 h-100&quot;&amp;gt;
            &amp;lt;!-- ... --&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/div&amp;gt;
&amp;lt;/section&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock tip&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-tip&quot; title=&quot;Tip&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब एक`align-items`Flexbox लंबवत अक्ष पर अपेक्षा के अनुसार काम नहीं करता, हमेशा सुनिश्चित करें कि कंटेनर में एक ऊँचाई है (&lt;code&gt;height&lt;/code&gt; ou &lt;code&gt;min-height&lt;/code&gt;) परिभाषित और, यदि समस्या बनी रहती है (विशेषकर Firefox पर), सुनिश्चित करें कि मध्यवर्ती मातृ कंटेनर इस ऊँचाई को अच्छी तरह से प्रसारित करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_2_कैनिबल_नेविगेशन_बार&quot;&gt;समस्या 2 : कैनिबल नेविगेशन बार&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;हीरो सेक्शन संरेखित होने के बाद, एक और समस्या सामने आई: नेविगेशन बार, जिसमें उसका वर्ग है`fixed-top`, शीर्षक पर आच्छादित हो रहा था. एक`padding-top: 80px`सेक्शन &#39;Hero&#39; पर समाधान के रूप में लागू किया गया था।&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लक्षण :&lt;/strong&gt; Le `padding`यह क्रोम पर पर्याप्त था, लेकिन फायरफ़ॉक्स पर नहीं, जहाँ शीर्षक हमेशा आंशिक रूप से छिपा रहता था।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गहरा कारण:&lt;/strong&gt;एक &quot;जादुई संख्या&quot; का उपयोग (&lt;code&gt;80px&lt;/code&gt;) यह एक बहुत खराब अभ्यास है। एक तत्व की ऊँचाई, जैसे कि नेविगेशन बार, कुछ पिक्सेल तक एक ब्राउज़र से दूसरे ब्राउज़र में बदल सकती है, क्योंकि फ़ॉन्ट रेंडरिंग, स्पेसिंग या उपयोगकर्ता विकल्पों में सूक्ष्म अंतर होते हैं। एक स्थिर मान पर निर्भर रहना एक नाज़ुक डिज़ाइन की रेसिपी है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समाधान:&lt;/strong&gt;JavaScript में एक गतिशील और अनफ़ेलिबल समाधान। हमने एक छोटा स्क्रिप्ट लिखा:&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;पेज के रेंडर होने के बाद नेविगेशन बार की &lt;strong&gt;वास्तविक&lt;/strong&gt; ऊँचाई मापें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इस मापी हुई ऊँचाई को लागू करें`padding-top`Hero&quot; सेक्शन में&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;इस फ़ंक्शन को हर बार विंडो के आकार बदलने पर फिर से चलाएँ ताकि बदलावों के अनुकूल बनाया जा सके (जैसे हैमबर्गर मेन्यू में स्विच करना).&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;document.addEventListener(&#39;DOMContentLoaded&#39;, function() {
    function adjustHeroPadding() {
        const navbar = document.querySelector(&#39;.navbar.fixed-top&#39;);
        const heroSection = document.querySelector(&#39;.hero-section&#39;);

        if (navbar &amp;amp;&amp;amp; heroSection) {
            const navbarHeight = navbar.offsetHeight;
            heroSection.style.paddingTop = navbarHeight + &#39;px&#39;;
        }
    }

    // Ajuster au chargement et au redimensionnement
    adjustHeroPadding();
    window.addEventListener(&#39;resize&#39;, adjustHeroPadding);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;अनुक्रम आरेख: पैडिंग का गतिशील समायोजन&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title कैनिबल नेविगेशन बार की समस्या का समाधान
actor Utilisateur
participant &quot;ब्राउज़र&quot; as Browser
participant &quot;script.js&quot; as JS
participant &quot;DOM&quot; as DOM

Utilisateur -&amp;gt; Browser: Charge la page
activate Browser

Browser -&amp;gt; JS: Déclenche l&#39;événement &#39;DOMContentLoaded&#39;
activate JS

JS -&amp;gt; DOM: querySelector(&#39;.navbar.fixed-top&#39;)
activate DOM
DOM --&amp;gt; JS: Retourne l&#39;élément Navbar
deactivate DOM

JS -&amp;gt; DOM: querySelector(&#39;.hero-section&#39;)
activate DOM
DOM --&amp;gt; JS: Retourne l&#39;élément Hero
deactivate DOM

JS -&amp;gt; DOM: navbar.offsetHeight
activate DOM
DOM --&amp;gt; JS: Retourne la hauteur calculée (ex: 83px)
deactivate DOM

JS -&amp;gt; DOM: heroSection.style.paddingTop = &quot;83px&quot;
activate DOM
deactivate DOM

deactivate JS
deactivate Browser

... Plus tard ...

Utilisateur -&amp;gt; Browser: Redimensionne la fenêtre
activate Browser
Browser -&amp;gt; JS: Déclenche l&#39;événement &#39;resize&#39;
activate JS
JS -&amp;gt; JS: Exécute à nouveau adjustHeroPadding()
note right of JS: Le processus de mesure et\nd&#39;application du padding se répète.
deactivate JS
deactivate Browser

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समांतर में, हमने बेशक नियम हटा दिया`padding-top: 80px;`हमारी फ़ाइल का`styles.css`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_3_अराजक_टाइपोग्राफी&quot;&gt;समस्या 3: अराजक टाइपोग्राफी&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;आगामी चिंता ब्रांड छवि के लिए सबसे अधिक हानिकारक थी: मुख्य शीर्षक का आकार।&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लक्षण :&lt;/strong&gt;फ़ायरफ़ॉक्स पर, &quot;Développeur Formateur&amp;#8230;&amp;#8203;&quot; शीर्षक का फ़ॉन्ट विशाल था, लगभग चौंकाने वाला, जबकि यह अन्य ब्राउज़र पर सामंजस्यपूर्ण थी।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गहरा कारण :&lt;/strong&gt;शीर्षक ने एक क्लास का उपयोग किया`display-4`बूटस्ट्रैप का ये कक्षाएं प्रतिक्रियाशील फॉन्ट आकार का उपयोग करती हैं, जो अक्सर इकाई पर आधारित होती हैं`rem`फिर से, फ़ायरफ़ॉक्स का रेंडरिंग एल्गोरिदम, &quot;Inter&quot; फ़ॉन्ट के साथ संयुक्त, हमारे 1920x1080 रिज़ॉल्यूशन पर आकार की बहुत बड़ी गणना हो रही थी।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समाधान:&lt;/strong&gt;CSS फ़ंक्शन के साथ नियंत्रण पुनः प्राप्त करें`clamp()&lt;code&gt;. यह सुविधा सुचारू टाइपोग्राफी के लिए एक क्रांति है। यह आपको तीन मानों के साथ एक फ़ॉन्ट आकार निर्धारित करने की अनुमति देता है: एक न्यूनतम आकार, एक &quot;préférée&quot; आकार (जो दृश्य की चौड़ाई के अनुसार अनुकूलित होता है,`vw&lt;/code&gt;), और एक अधिकतम आकार।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.hero-content h1 {
    color: var(--text-primary);
    line-height: 1.2;
    /*
       Min: 2rem
       Préférée: s&#39;adapte à la vue
       Max: 2.5rem (40px)
    */
    font-size: clamp(2rem, 1.2rem + 1.5vw, 2.5rem);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;के साथ`clamp()&lt;code&gt;, हम ब्राउज़र से कह सके: &quot;स्क्रीन के साथ फ़ॉन्ट बढ़ाएँ, लेकिन अधिक नहीं&lt;strong&gt;कभी नहीं&lt;/strong&gt;सीमा का`2.5rem&lt;/code&gt;. इसने सभी ब्राउज़रों पर रेंडरिंग को तुरंत समायोजित कर दिया, जिससे हमें अंतिम दिखावट पर पूर्ण नियंत्रण मिल गया।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_4_नेविगेशन_बार_जो_बाहर_निकलती_है&quot;&gt;समस्या 4 : नेविगेशन बार जो बाहर निकलती है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;यह वही समस्या है जिसने हमें सबसे अधिक परेशानी दी और अंततः रेंडरिंग के सूक्ष्म अंतरों की गहरी प्रकृति को प्रकट किया।&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लक्षण:&lt;/strong&gt;1920x1080 स्क्रीन पर, मेनू के अंतिम लिंक (&quot;Blog&quot;, &quot;Contact&quot;) स्क्रीन के दाहिनी ओर धकेल दिए गए थे, लेकिन केवल फ़ायरफ़ॉक्स पर.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गहरा कारण:&lt;/strong&gt;कई असफल प्रयासों के बाद (बूटस्ट्रैप के ब्रेकपॉइंट्स बदलने`lg` à &lt;code&gt;xl`फिर`xxl&lt;/code&gt;) हमने समझा। कारण बूटस्ट्रैप की लॉजिक नहीं थी, बल्कि सरल चौड़ाई की गणना थी। फ़ायरफ़ॉक्स पर, सभी लिंक की चौड़ाइयों का योग, उनके शामिल`padding` et `margin`sub-pixel के स्तर तक, यह &lt;strong&gt;légèrement&lt;/strong&gt; 1920 पिक्सेल से अधिक थी। Chrome पर, यही समान योग &lt;strong&gt;légèrement&lt;/strong&gt; कम थी। हमें कुछ पिक्सेल की कमी थी।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समाधान:&lt;/strong&gt;एक सर्जिकल स्तर के अंतराल में कमी। क्योंकि फ़ायरफ़ॉक्स को विशेष रूप से लक्षित करना पुराने CSS &amp;#8220;hacks&amp;#8221; के साथ बाहर के सवाल में था, एकमात्र समाधान एक सामान्य शैली खोजने का था जो हर जगह काम करती। हमने इसलिए प्रत्येक नेविगेशन लिंक के क्षैतिज मार्जिन और पैडिंग को थोड़ा कम कर दिया।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;/* La version finale, légèrement plus compacte */
.navbar-nav .nav-link {
    font-size: 0.9rem; /* 90% de la taille de base */
    color: var(--text-primary) !important;
    font-weight: 500;
    margin: 0 0.2rem;
    padding: 0.5rem 0.5rem !important;
    border-radius: 0.375rem;
    transition: all 0.3s ease;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह कमी, एकल तत्व पर नग्न आँख से लगभग अदृश्य, हमें सामूहिक रूप से आवश्यक स्थान प्रदान कर दिया जिससे कि सभी लिंक फ़ायरफ़ॉक्स के फ्रेम में आ जाएँ, जबकि अन्य ब्राउज़र पर लगभग समान दिखावट बनी रहे।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_5_अदृश्य_हैम्बर्गर_मेनू&quot;&gt;समस्या 5: अदृश्य हैम्बर्गर मेनू&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अंतिम समस्या, और कम नहीं थी, मोबाइल एक्सेसिबिलिटी से संबंधित थी।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लक्षण :&lt;/strong&gt;रिस्पॉन्सिव मोड (मेनू &quot;hamburger&quot;) में, मेनू का आइकॉन थीम &quot;dark&quot; और &quot;high-contrast&quot; पर अदृश्य था।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गहरा कारण :&lt;/strong&gt;Bootstrap 5 का मेनू आइकन एक`background-image`(एक URL में एन्कोड किया गया SVG)। डिफ़ॉल्ट रूप से, इसकी रेखा का रंग गहरा होता है, हल्के पृष्ठभूमि के लिए अनुकूलित। यह थीम परिवर्तन के अनुसार स्वचालित रूप से अनुकूल नहीं होती।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;समाधान :&lt;/strong&gt;Bootstrap के CSS चर का उपयोग करके आइकन को ओवरराइड करें। हमने एक नया SVG आइकन निर्धारित किया, लेकिन इस बार एक सफेद स्ट्रोक के साथ।&lt;code&gt;#ffffff&lt;/code&gt;), और हमने इसे विशेष रूप से लागू किया जब विषय`dark` ou `high-contrast`वे सक्रिय हैं।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;/* ======================
   Fix pour l&#39;icône du menu Burger (Blanc)
   ====================== */
[data-bs-theme=&quot;dark&quot;] .navbar-toggler-icon,
[data-bs-theme=&quot;high-contrast&quot;] .navbar-toggler-icon {
    --bs-navbar-toggler-icon-bg: url(&quot;data:image/svg+xml,%3csvg xmlns=&#39;http://www.w3.org/2000/svg&#39; viewBox=&#39;0 0 30 30&#39;%3e%3cpath stroke=&#39;%23ffffff&#39; stroke-linecap=&#39;round&#39; stroke-miterlimit=&#39;10&#39; stroke-width=&#39;2&#39; d=&#39;M4 7h22M4 15h22M4 23h22&#39;/%3e%3c/svg%3e&quot;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बूटस्ट्रैप घटकों जैसे इस का अनुकूलन अब CSS चर के ओवरराइड के माध्यम से बढ़ता जा रहा है (&lt;code&gt;--bs-component-property&lt;/code&gt;), qui est la méthode la plus propre et la plus pérenne.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष_अथक_डिबगिंग_के_सबक&quot;&gt;निष्कर्ष: अथक डिबगिंग के सबक&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह यात्रा, हालांकि कभी‑कभी निराशाजनक होती है, सीखों से भरपूर है। हर हल की गई समस्या वेब विकास के एक मौलिक सत्य को मजबूत करती है :&lt;strong&gt;कुछ भी एक कठोर बहु-ब्राउज़र परीक्षण का विकल्प नहीं है&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Mindmap : डीबगिंग का सारांश और सीखे गए सबक&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
+ Débogage Cross-Browser : Bootstrap 5
++ **Conflit :** Chrome (Blink) vs Firefox (Gecko)
++ **Problème 1 : Alignement Hero**
+++ Cause : Hauteur implicite
+++ Solution : Classe `.h-100`
++ **Problème 2 : Navbar Cannibale**
+++ Cause : &quot;जादुई संख्या&quot; (padding fixe)
+++ Solution : JS `offsetHeight`
++ **Problème 3 : Typographie Géante**
+++ Cause : Rendu des `rem`
+++ Solution : CSS `clamp()`
++ **Problème 4 : Menu qui déborde**
+++ Cause : Calcul de largeur sub-pixel
+++ Solution : Réduction des marges/paddings
++ **Problème 5 : Icône Invisible**
+++ Cause : SVG non adaptable au thème
+++ Solution : Surcharge de variable CSS
++ **Leçons Clés**
+++ Firefox force un code robuste
+++ Fuir les &quot;जादुई संख्याएँ&quot;
+++ Maîtriser la typographie fluide
+++ Personnaliser via les variables CSS
@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ये हैं सीख जो हमने रखी हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Firefox एक सहयोगी है :&lt;/strong&gt;इसकी CSS मानकों के प्रति सबसे बड़ी वफ़ादारी हमें अधिक मजबूत और कम अस्पष्ट कोड लिखने के लिए मजबूर करती है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;जादुई संख्याओं से बचें :&lt;/strong&gt;स्थिर मान (जैसे`padding-top: 80px`) समय bombs हैं। हमेशा गतिशील समाधानों को प्राथमिकता दें या सापेक्ष (Flexbox, Grid)।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;अपनी टाइपोग्राफी को मास्टर करें:&lt;/strong&gt;इस्तेमाल करें`clamp()`अनुकूलन योग्य फ़ॉन्ट के आकार पर पूर्ण नियंत्रण रखने के लिए।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;घटक के रूप में सोचें:&lt;/strong&gt;बूटस्ट्रैप को अनुकूलित करने के लिए, उसके CSS चरों को ओवरराइड करें, बजाय फ्रेमवर्क को ओवरराइट करने वाले नियमों को गुणा करने के।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;एक ब्राउज़र मत लक्ष्य कीजिए:&lt;/strong&gt;समाधान लगभग कभी भी किसी विशिष्ट ब्राउज़र के लिए &quot;hack&quot; करने का नहीं होता, बल्कि एक सामान्य शैली खोजने का होती है जो हर जगह काम करती है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अंत में, मॉकअप अब मजबूत, पूर्वानुमान योग्य और टेम्प्लेटिंग सिस्टम में एकीकृत होने के लिए तैयार है। प्रत्येक ठीक किया गया बग असफलता नहीं था, बल्कि बेहतर गुणवत्ता वाले कोड की ओर एक कदम था।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_gradle_प्लगिन_के_यूनिट_टेस्ट्स_को_अलग_करना&quot;&gt;समस्या: Gradle प्लगिन के यूनिट टेस्ट्स को अलग करना&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_की_वास्तुकला&quot;&gt;समस्या की वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_गलत_अच्छे_विचार_की_आकर्षण&quot;&gt;एक गलत अच्छे विचार की आकर्षण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_संपत्ति_का_सिमुलेट_extrapropertiesextension_के_साथ&quot;&gt;समाधान: संपत्ति का सिमुलेट &lt;code&gt;ExtraPropertiesExtension&lt;/code&gt; के साथ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_1_extrapropertiesextension_को_समझें&quot;&gt;चरण 1 : ExtraPropertiesExtension को समझें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_2_परीक्षण_की_व्यवस्था_तैयारी&quot;&gt;चरण 2 : परीक्षण की व्यवस्था - तैयारी&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_3_संपत्ति_का_इंजेक्शन&quot;&gt;चरण 3 : संपत्ति का इंजेक्शन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_4_समाधान_प्रवाह_आरेख&quot;&gt;चरण 4: समाधान प्रवाह आरेख&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_5_पहलेपश्चात_तुलना&quot;&gt;चरण 5: पहले/पश्चात तुलना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_6_कई_टेस्ट_केसों_का_प्रबंधन&quot;&gt;चरण 6: कई टेस्ट केसों का प्रबंधन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_का_अंतिम_वास्तुकला&quot;&gt;समाधान का अंतिम वास्तुकला&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_इस_दृष्टिकोण_के_लाभ&quot;&gt;इस दृष्टिकोण के लाभ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अच्छे_अभ्यास_और_सलाह&quot;&gt;अच्छे अभ्यास और सलाह&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_उपयोगिता_विधि_बनाएँ&quot;&gt;एक उपयोगिता विधि बनाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_गुणों_की_पुष्टि&quot;&gt;गुणों की पुष्टि&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_gradle_प्लगिन_के_यूनिट_टेस्ट्स_को_अलग_करना&quot;&gt;समस्या: Gradle प्लगिन के यूनिट टेस्ट्स को अलग करना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle प्लगिन के लिए यूनिट परीक्षण लिखते समय, एक सामान्य चुनौती प्रोजेक्ट की कॉन्फ़िगरेशन के अनुसार निर्भरताओं को प्रबंधित करने की है, जैसी फ़ाइल में परिभाषित गुण`gradle.properties`. हमारे केस में, प्लगइन`jbake.ghpages`एक संपत्ति पढ़नी थी`site_config_path`सही ढंग से काम करने के लिए. कार्य के लिए यूनिट परीक्षण`initialize`प्लगइन के व्यवहार की जाँचना इस संपत्ति की उपस्थिति में करनी चाहिए थी।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मूल समस्या यह है कि यूनिट टेस्ट, डिज़ाइन द्वारा, &lt;strong&gt;इसोलेटेड&lt;/strong&gt; होने चाहिए। का उपयोग`ProjectBuilder`Gradle का एक उदाहरण बनाता है`Project`मेमोरी में, फ़ाइल सिस्टम पर एक वास्तविक प्रोजेक्ट से पूरी तरह डिस्कनेक्टेड। इसलिए, इस टेस्ट इंस्टेंस द्वारा फ़ाइल को स्वचालित रूप से नहीं पढ़ा जाता।&lt;code&gt;gradle.properties`और इसलिए संपत्ति की जानकारी नहीं है`site_config_path&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समस्या_की_वास्तुकला&quot;&gt;समस्या की वास्तुकला&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;निम्नलिखित आरेख परीक्षण वातावरण और फ़ाइल सिस्टम के बीच के असंपर्क को दर्शाता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!define RECTANGLE class

package &quot;उत्पादन वातावरण&quot; {
  RECTANGLE ProjectReal {
    + build.gradle.kts
    + gradle.properties
    + src/
  }

  RECTANGLE GradleProperties {
    site_config_path=src/jbake/settings/site.yml
  }

  RECTANGLE JbakePlugin {
    - readProperty(name: String)
    + initialize()
  }

  ProjectReal --&amp;gt; GradleProperties : lit au démarrage
  JbakePlugin --&amp;gt; GradleProperties : accède via project.properties
}

package &quot;परीक्षण वातावरण&quot; {
  RECTANGLE ProjectTest {
    + Créé par ProjectBuilder
    + En mémoire uniquement
    + Pas de gradle.properties
  }

  RECTANGLE JbakePluginTest {
    + testInitialize()
  }

  ProjectTest -[#red]x GradleProperties : ❌ Pas d&#39;accès
  JbakePluginTest --&amp;gt; ProjectTest : utilise
}

note right of ProjectTest : Isolation = Pas d&#39;accès\nau système de fichiers
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_एक_गलत_अच्छे_विचार_की_आकर्षण&quot;&gt;एक गलत अच्छे विचार की आकर्षण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक पहला दृष्टिकोण हो सकता है कि एक फ़ाइल बनाई जाए`gradle.properties`फर्जी परीक्षण संसाधनों में।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;// src/test/resources/gradle.properties
site_config_path=src/jbake/settings/site.yml&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हालाँकि, यह विधि विफल होने के लिए नियत है क्योंकि`ProjectBuilder`यह फ़ाइल सिस्टम को कॉन्फ़िगरेशन फ़ाइलों की खोज के लिए स्कैन करने के लिए डिज़ाइन नहीं किया गया है। परीक्षण अलग-थलग रहेगा और इस फ़ाइल को अनदेखा कर देगा।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समाधान_संपत्ति_का_सिमुलेट_extrapropertiesextension_के_साथ&quot;&gt;समाधान: संपत्ति का सिमुलेट &lt;code&gt;ExtraPropertiesExtension&lt;/code&gt; के साथ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस समस्या का शानदार समाधान फ़ाइल को &lt;strong&gt;lire&lt;/strong&gt; करने से नहीं है, बल्कि ऑब्जेक्ट में संपत्ति की उपस्थिति को &lt;strong&gt;simuler&lt;/strong&gt; करने से है`Project`टेस्ट। Gradle इसके लिए एक शक्तिशाली तंत्र प्रदान करता है : &lt;strong&gt;अतिरिक्त गुण&lt;/strong&gt; (Extra Properties).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_1_extrapropertiesextension_को_समझें&quot;&gt;चरण 1 : ExtraPropertiesExtension को समझें&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`ExtraPropertiesExtension`यह Gradle मॉडल के प्रत्येक ऑब्जेक्ट से जुड़ा एक कुंजी-मूल्य कंटेनर है। यह परियोजना, किसी कार्य, या किसी अन्य Gradle एक्सटेंशन में गतिशील रूप से गुण जोड़ने की अनुमति देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!define RECTANGLE class

RECTANGLE Project {
  + name: String
  + version: String
  + extensions: ExtensionContainer
  + properties: Map&amp;lt;String, ?&amp;gt;
}

RECTANGLE ExtensionContainer {
  + getByType(Class&amp;lt;T&amp;gt;): T
  + add(String, Object): void
}

RECTANGLE ExtraPropertiesExtension {
  + set(String, Object): void
  + get(String): Object
  + has(String): boolean
  + getProperties(): Map&amp;lt;String, Object&amp;gt;
}

Project --&amp;gt; ExtensionContainer : contient
ExtensionContainer --&amp;gt; ExtraPropertiesExtension : gère
ExtraPropertiesExtension --&amp;gt; Project : synchronise avec\nproject.properties

note right of ExtraPropertiesExtension : Point d&#39;entrée pour\ninjecter des propriétés
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_2_परीक्षण_की_व्यवस्था_तैयारी&quot;&gt;चरण 2 : परीक्षण की व्यवस्था - तैयारी&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आइए, हम अपने यूनिट टेस्ट की बुनियादी संरचना बनाना शुरू करते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;JbakeGhPagesPluginTest.kt - Structure de base&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class JbakeGhPagesPluginTest {

    @TempDir
    lateinit var testProjectDir: File

    @Test
    fun `check initialize and config yaml file if not existing`() {
        // Étape 1 : Créer un projet de test isolé
        val project = ProjectBuilder.builder()
            .withProjectDir(testProjectDir)
            .build()

        // Suite des étapes...
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_3_संपत्ति_का_इंजेक्शन&quot;&gt;चरण 3 : संपत्ति का इंजेक्शन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह परियोजना में संपत्ति इंजेक्ट करने के लिए विस्तृत प्रक्रिया है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;JbakeGhPagesPluginTest.kt - Injection complète&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `check initialize and config yaml file if not existing`() {
    // Étape 1 : Créer un projet de test isolé en mémoire
    val project = ProjectBuilder.builder()
        .withProjectDir(testProjectDir)
        .build()

    // Étape 2 : Récupérer le gestionnaire de propriétés supplémentaires
    val extra = project.extensions.getByType(ExtraPropertiesExtension::class.java)

    // Étape 3 : Définir la propriété requise pour ce test
    extra.set(&quot;site_config_path&quot;, &quot;src/jbake/settings/site.yml&quot;)

    // Étape 4 : Vérifier que la propriété est bien injectée
    assertTrue(project.hasProperty(&quot;site_config_path&quot;))

    // Étape 5 : Appliquer le plugin qui pourra maintenant accéder à la propriété
    project.plugins.apply(&quot;jbake.ghpages&quot;)

    // Étape 6 : Exécuter la tâche et vérifier son comportement
    val task: Task = project.tasks.findByName(&quot;initialize&quot;)
        .apply(::assertNotNull)!!

    // Étape 7 : Exécuter les actions de la tâche
    task.actions.forEach { it.execute(task) }

    // Étape 8 : Assertions finales
    assertEquals(
        &quot;src/jbake/settings/site.yml&quot;,
        project.properties[&quot;site_config_path&quot;],
        &quot;La propriété devrait être accessible dans le projet&quot;
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_4_समाधान_प्रवाह_आरेख&quot;&gt;चरण 4: समाधान प्रवाह आरेख&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Créer ProjectBuilder;
:Obtenir ExtraPropertiesExtension;
:Injecter la propriété\nvia extra.set();

partition &quot;जाँच&quot; {
  :Vérifier project.hasProperty();
  :Appliquer le plugin;
  :Récupérer la tâche;
}

partition &quot;निष्पादन&quot; {
  :Exécuter les actions\nde la tâche;
  :Le plugin lit\nproject.properties;
}

partition &quot;दावे&quot; {
  :Vérifier la propriété\nest accessible;
  :Valider le comportement\nattendues;
}

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_5_पहलेपश्चात_तुलना&quot;&gt;चरण 5: पहले/पश्चात तुलना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!define RECTANGLE class

package &quot;AVANT - समस्या&quot; {
  RECTANGLE TestProject1 {
    + ProjectBuilder.build()
    + Pas de propriétés
  }

  RECTANGLE Plugin1 {
    + initialize()
    + ❌ project.properties[&quot;साइट_कॉन्फ़िग_पथ&quot;] = null
  }

  TestProject1 --&amp;gt; Plugin1 : échec

  note right of Plugin1 : Test échoue car\nla propriété n&#39;existe pas
}

package &quot;बाद - समाधान&quot; {
  RECTANGLE TestProject2 {
    + ProjectBuilder.build()
    + ExtraPropertiesExtension
  }

  RECTANGLE ExtraProps {
    + set(&quot;साइट_कॉन्फ़िग_पथ&quot;, &quot;...&quot;)
  }

  RECTANGLE Plugin2 {
    + initialize()
    + ✅ project.properties[&quot;साइट_कॉन्फ़िग_पथ&quot;] = &quot;src/jbake/settings/site.yml&quot;
  }

  TestProject2 --&amp;gt; ExtraProps : configure
  ExtraProps --&amp;gt; Plugin2 : propriété disponible

  note right of Plugin2 : Test réussit car\nla propriété est simulée
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_चरण_6_कई_टेस्ट_केसों_का_प्रबंधन&quot;&gt;चरण 6: कई टेस्ट केसों का प्रबंधन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;विभिन्न परिदृश्यों का परीक्षण करने के लिए, विभिन्न कॉन्फ़िगरेशन के साथ कई परीक्षण बनाइए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Tests multiples avec configurations différentes&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class JbakeGhPagesPluginTest {

    @TempDir
    lateinit var testProjectDir: File

    private fun createProjectWithProperty(propertyValue: String?): Project {
        val project = ProjectBuilder.builder()
            .withProjectDir(testProjectDir)
            .build()

        // Injection conditionnelle de la propriété
        propertyValue?.let { value -&amp;gt;
            val extra = project.extensions.getByType(ExtraPropertiesExtension::class.java)
            extra.set(&quot;site_config_path&quot;, value)
        }

        return project
    }

    @Test
    fun `should work with valid property`() {
        val project = createProjectWithProperty(&quot;src/jbake/settings/site.yml&quot;)
        project.plugins.apply(&quot;jbake.ghpages&quot;)

        val task = project.tasks.findByName(&quot;initialize&quot;)!!
        task.actions.forEach { it.execute(task) }

        // Assertions pour le cas normal
        assertEquals(&quot;src/jbake/settings/site.yml&quot;, project.properties[&quot;site_config_path&quot;])
    }

    @Test
    fun `should handle missing property gracefully`() {
        val project = createProjectWithProperty(null) // Pas de propriété
        project.plugins.apply(&quot;jbake.ghpages&quot;)

        val task = project.tasks.findByName(&quot;initialize&quot;)!!

        // Le plugin devrait gérer l&#39;absence de propriété
        assertDoesNotThrow {
            task.actions.forEach { it.execute(task) }
        }
    }

    @Test
    fun `should handle invalid property path`() {
        val project = createProjectWithProperty(&quot;invalid/path/to/config.yml&quot;)
        project.plugins.apply(&quot;jbake.ghpages&quot;)

        val task = project.tasks.findByName(&quot;initialize&quot;)!!

        // Test du comportement avec un chemin invalide
        assertThrows&amp;lt;FileNotFoundException&amp;gt; {
            task.actions.forEach { it.execute(task) }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_का_अंतिम_वास्तुकला&quot;&gt;समाधान का अंतिम वास्तुकला&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!define RECTANGLE class

package &quot;परीक्षण वातावरण&quot; {
  RECTANGLE TestClass {
    + createProjectWithProperty()
    + testValidProperty()
    + testMissingProperty()
    + testInvalidProperty()
  }

  RECTANGLE ProjectBuilder {
    + builder()
    + withProjectDir()
    + build()
  }

  RECTANGLE TestProject {
    + extensions
    + properties
    + plugins
    + tasks
  }

  RECTANGLE ExtraPropertiesExtension {
    + set(key, value)
    + get(key)
    + has(key)
  }

  RECTANGLE JbakePlugin {
    + apply(project)
    + createInitializeTask()
    + readSiteConfigPath()
  }
}

TestClass --&amp;gt; ProjectBuilder : utilise
ProjectBuilder --&amp;gt; TestProject : crée
TestProject --&amp;gt; ExtraPropertiesExtension : contient
TestClass --&amp;gt; ExtraPropertiesExtension : configure
ExtraPropertiesExtension --&amp;gt; TestProject : synchronise properties
TestProject --&amp;gt; JbakePlugin : applique
JbakePlugin --&amp;gt; TestProject : lit properties

note right of ExtraPropertiesExtension : Point de contrôle\npour l&#39;injection
note bottom of TestProject : Environnement\ncontrôlé et isolé
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_इस_दृष्टिकोण_के_लाभ&quot;&gt;इस दृष्टिकोण के लाभ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पूर्ण पृथक्करण&lt;/strong&gt;परीक्षण किसी बाहरी फ़ाइल पर निर्भर नहीं है। यह स्वतंत्र है और किसी भी पर्यावरण (स्थानीय, CI/CD आदि) में विश्वसनीय रूप से चलाया जा सकता है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;स्पष्टता और इरादा&lt;/strong&gt;परीक्षण स्पष्ट रूप से अपने निष्पादन के लिए पूर्व शर्तों की घोषणा करता है। जो कोई भी परीक्षण पढ़ता है, वह तुरंत देखता है कि प्लगिन को संपत्ति की आवश्यकता होती है।`site_config_path`चलने के लिए.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;रखरखावीयता&lt;/strong&gt;: यदि संपत्ति का नाम बदलता है, तो बस परीक्षण में एक स्थान पर इसे अपडेट करना पर्याप्त है, परीक्षण कॉन्फ़िगरेशन फ़ाइलों को संशोधित किए बिना।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लचीलापन&lt;/strong&gt;परीक्षण करना बहुत आसान हो जाता है विभिन्न परिदृश्यों का, क्योंकि प्रत्येक परीक्षण में इंजेक्ट की गई संपत्ति के मान को बस बदल दिया जाता है (वैध मान, अमान्य मान, अनुपस्थित, आदि)।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;प्रदर्शन&lt;/strong&gt;: फ़ाइलों की कोई पढ़ाई नहीं, सब मेमोरी में होता है, जो परीक्षणों को तेज़ बनाता है.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पुनरावृत्ति&lt;/strong&gt;परीक्षण निर्धारित हैं क्योंकि वे फ़ाइल सिस्टम की स्थिति पर निर्भर नहीं करते।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अच्छे_अभ्यास_और_सलाह&quot;&gt;अच्छे अभ्यास और सलाह&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_एक_उपयोगिता_विधि_बनाएँ&quot;&gt;एक उपयोगिता विधि बनाएँ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Méthode utilitaire pour la réutilisation&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class GradleTestUtils {
    companion object {
        fun createProjectWithProperties(
            projectDir: File,
            properties: Map&amp;lt;String, String&amp;gt;
        ): Project {
            val project = ProjectBuilder.builder()
                .withProjectDir(projectDir)
                .build()

            val extra = project.extensions.getByType(ExtraPropertiesExtension::class.java)
            properties.forEach { (key, value) -&amp;gt;
                extra.set(key, value)
            }

            return project
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_गुणों_की_पुष्टि&quot;&gt;गुणों की पुष्टि&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Validation robuste&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `should validate property injection`() {
    val project = createProjectWithProperty(&quot;test-value&quot;)

    // Vérifications multiples
    assertTrue(project.hasProperty(&quot;site_config_path&quot;))
    assertEquals(&quot;test-value&quot;, project.property(&quot;site_config_path&quot;))
    assertNotNull(project.properties[&quot;site_config_path&quot;])

    // Vérification que la propriété est accessible par le plugin
    project.plugins.apply(&quot;jbake.ghpages&quot;)
    // ... reste du test
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यूनिट परीक्षण वातावरण के लिए कॉन्फ़िगरेशन फ़ाइलें पढ़ने के लिए संघर्ष करने के बजाय, सर्वोत्तम अभ्यास आवश्यक स्थिति को अनुकरण करने से बना है। का उपयोग`ExtraPropertiesExtension`ग्रैडल गुणों को प्रोग्रामेटिक रूप से परिभाषित करने की विधि प्रभावी और विश्वसनीय प्लगइन यूनिट परीक्षण करने के लिए सबसे स्वच्छ और सबसे मजबूत तरीका है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह तकनीक एक बाह्य निर्भरता समस्या को एक सरल निर्भरता इंजेक्शन में बदल देती है, जो टेस्ट-ड्रिवन डेवलपमेंट (TDD) के दर्शन के मूल में होती है। यह परीक्षण पर्यावरण पर पूर्ण नियंत्रण प्रदान करती है जबकि उच्च गुणवत्ता वाले यूनिट परीक्षण के लिए आवश्यक अलगाव को बनाए रखती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस लेख में प्रस्तुत आरेख और उदाहरण दिखाते हैं कि इस दृष्टिकोण को कैसे चरणबद्ध और प्रणालीगत तरीके से लागू किया जा सकता है, जिससे आपके Gradle प्लगइन के लिए एक मजबूत और बनाए रखने योग्य टेस्ट सूट बनाया जा सकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_allprojects_और_subprojects_के_साथ_configurations_को_केंद्रीकृत_करें&quot;&gt;allprojects` और &lt;code&gt;subprojects&lt;/code&gt; के साथ Configurations को केंद्रीकृत करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sourceplantuml&quot;&gt;[source,plantuml]&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ग्रैडल_एकीकरण_jbake_को_jbake_gradle_प्लगिन_का_उपयोग_करके_या_jbake_cli_को_सीधे_बुलाकर_gradle_बिल्ड्स_में_एकीकृत_किया_जा_सकता_है&quot;&gt;ग्रैडल एकीकरण JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड्स में एकीकृत किया जा सकता है:&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_initialize_a_new_jbake_project_jbake_i&quot;&gt;Initialize a new JBake project jbake -i&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_generate_the_site_jbake_b&quot;&gt;Bake (generate) the site jbake -b&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_serve_locally_jbake_b_s&quot;&gt;Bake and serve locally jbake -b -s&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bake_and_watch_for_changes_jbake_b_reset&quot;&gt;Bake and watch for changes jbake -b --reset&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_specify_source_and_destination_jbake_source_folder_output_folder&quot;&gt;Specify source and destination jbake source_folder output_folder&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_clear_the_output_directory_before_baking_jbake_b_output_reset&quot;&gt;Clear the output directory before baking jbake -b . output --reset &lt;code&gt;`&lt;/code&gt;&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gradle_एकीकरण_jbake_को_gradle_निर्माण_में_jbake_gradle_प्लगइन_का_उपयोग_करके_या_jbake_cli_को_सीधे_बुलाकर_एकीकृत_किया_जा_सकता_है_kotlin_tasks_registerjavaexecbake_mainclass_setorg_jbake_launcher_main_classpath_configurationsjbake_args_listofprojectdir_absolutepath_builddirjbake&quot;&gt;Gradle एकीकरण JBake को Gradle निर्माण में JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर एकीकृत किया जा सकता है: &lt;code&gt;&lt;code&gt;kotlin tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) { mainClass.set(&quot;org.jbake.launcher.Main&quot;) classpath = configurations[&quot;jbake&quot;] args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;) } &lt;/code&gt;&lt;/code&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_abstract_class_reportfunctionalteststask_opentestreporttask_init_description_फ़ायरफ़ॉक्स_में_फंक्शनल_टेस्ट_रिपोर्ट_खोलता_है_reportpath_buildreportstestsfunctionaltestindex_html&quot;&gt;abstract class ReportFunctionalTestsTask : OpenTestReportTask() { init { description = &quot;फ़ायरफ़ॉक्स में फंक्शनल टेस्ट रिपोर्ट खोलता है।&quot; reportPath = &quot;build/reports/tests/functionalTest/index.html&quot; } }&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sourcekotlin&quot;&gt;[source,kotlin]&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tasks_registercom_yourpackage_reportunitteststaskreporttests_tasks_registercom_yourpackage_reportfunctionalteststaskreportfunctionaltests&quot;&gt;tasks.register\&amp;lt;com.yourpackage.ReportUnitTestsTask\&amp;gt;(&quot;reportTests&quot;) {} tasks.register\&amp;lt;com.yourpackage.ReportFunctionalTestsTask\&amp;gt;(&quot;reportFunctionalTests&quot;) {}&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_रिपोर्ट_कार्यों_का_uml_आरेख_कोड_plantuml&quot;&gt;रिपोर्ट कार्यों का UML आरेख (कोड PlantUML)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sourceplantuml_2&quot;&gt;[source,plantuml]&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_enduml&quot;&gt;@enduml&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सॉफ्टवेयर प्रोजेक्ट के लिए बिल्ड कार्यों का स्वचालन महत्वपूर्ण है, और Gradle, अपने Kotlin DSL के साथ, असाधारण लचीलापन प्रदान करता है। हमारी बातचीत के दौरान, हमने बिल्ड लॉजिक को केंद्रीकृत और पुनः उपयोग करने के तरीकों का पता लगाया, विशेष रूप से टेस्ट रिपोर्ट के लिए, का लाभ उठाते हुए&lt;strong&gt;सभी परियोजनाएँ&lt;/strong&gt;, &lt;strong&gt;बिल्डSrc&lt;/strong&gt;, और Kotlin में कस्टम कार्य&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_allprojects_और_subprojects_के_साथ_configurations_को_केंद्रीकृत_करें&quot;&gt;allprojects` और &lt;code&gt;subprojects&lt;/code&gt; के साथ Configurations को केंद्रीकृत करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ब्लॉक`allprojects` et `subprojects`आपके`build.gradle.kts`जड़ आपके मल्टी-मॉड्यूल प्रोजेक्ट में सामान्य कॉन्फ़िगरेशन लागू करने के लिए बुनियादी है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;*&lt;code&gt;allprojects { &amp;#8230;&amp;#8203; }`कॉन्फ़िगरेशन लागू करें&lt;strong&gt;मूल परियोजना और इसकी सभी उप-परियोजनाओं के लिए&lt;/strong&gt;। परिभाषित करने के लिए आदर्श`group&lt;/code&gt;, एक`version`, या कुछ`repositories`सामान्य (No output)&lt;code&gt;subprojects { &amp;#8230;&amp;#8203; }`कॉन्फ़िगरेशन लागू करें&lt;strong&gt;केवल उप-परियोजनाओं तक&lt;/strong&gt;, मूल परियोजना को छोड़कर. परफेक्ट मॉड्यूल-विशिष्ट प्लगिन लागू करने के लिए (जैसे`java&lt;/code&gt; ou &lt;code&gt;kotlin-jvm&lt;/code&gt;) या आपकी लाइब्रेरी के सामान्य निर्भरताएँ।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ एक उदाहरणात्मक उदाहरण :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// build.gradle.kts (projet racine)
plugins {
    base // Appliqué au projet racine
}

allprojects {
    group = &quot;com.example&quot;
    version = &quot;1.0.0&quot;

    repositories {
        mavenCentral()
    }

    tasks.withType&amp;lt;org.gradle.api.tasks.testing.Test&amp;gt; {
        useJUnitPlatform() // Configuration commune des tests pour tous les projets
    }
}

subprojects {
    apply(plugin = &quot;java&quot;)
    apply(plugin = &quot;org.jetbrains.kotlin.jvm&quot;)

    dependencies {
        implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib-jdk8&quot;)
    }

}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;\==`buildSrc`बिल्ड तर्क का स्विस आर्मी चाकू&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब आपके कार्यों की तर्क जटिल हो जाती है या इसे पुनः उपयोग में लाने की आवश्यकता होती है,&lt;strong&gt;buildSrc&lt;/strong&gt;यह प्राथमिक समाधान है। यह एक विशेष Gradle मॉड्यूल है जो मुख्य बिल्ड स्क्रिप्ट्स से पहले संकलित किया जाता है, जिससे इसकी क्लासेस आपके बिल्ड के पूरे क्लासपाथ पर उपलब्ध हो जाती हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;\=== क्यों उपयोग करें`buildSrc`कार्यों के लिए ?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;पुन: उपयोगिता&lt;/strong&gt;एक परिभाषित कार्य में`buildSrc`इस बिल्ड के किसी भी प्रोजेक्ट में लागू किया जा सकता है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;संगठन&lt;/strong&gt;: बिल्ड कोड को सेंट्रलाइज़ करें, जिससे यह अधिक साफ़ और रखरखाव योग्य हो।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;टाइप सुरक्षा और ऑटो‑कम्प्लीशन&lt;/strong&gt;: कोटलिन कोड में`buildSrc`इसे संकलित किया जाता है, जो आपके IDE में त्रुटि जाँच और स्वत पूर्णता प्रदान करता है, विकास अनुभव को बेहतर बनाता है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;\=== प्रवाह आरेख`buildSrc`(कोड PlantUML)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस आरेख को उत्पन्न करने के लिए, नीचे दिया गया कोड कॉपी करें और PlantUML समर्थन करने वाले टूल में पेस्ट करें।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sourceplantuml&quot;&gt;[source,plantuml]&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;@startuml skinparam handwritten true skinparam monochrome true&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ग्रैडल_एकीकरण_jbake_को_jbake_gradle_प्लगिन_का_उपयोग_करके_या_jbake_cli_को_सीधे_बुलाकर_gradle_बिल्ड्स_में_एकीकृत_किया_जा_सकता_है&quot;&gt;ग्रैडल एकीकरण JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड्स में एकीकृत किया जा सकता है:&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}
----

rectangle &quot;ग्रैडल बिल्ड प्रक्रिया घटक &quot;buildSrc&quot; जैसे BS { फ़ाइल &quot;MyCustomTask.kt&quot; के रूप में T फ़ाइल &quot;MyConventionPlugin.kt&quot; के रूप में P } घटक &quot;Root Project&quot; के रूप में RP घटक &quot;Subproject A&quot; के रूप में SA घटक &quot;Subproject B&quot; को SB के रूप में }

T --\&amp;gt; P : &quot;is defined in&quot; P --&amp;gt; RP : &quot;इस पर लागू किया जाता है P --&amp;gt; SA : &quot;लागू किया जाता है P --\&amp;gt; SB : &quot;लागू किया जाता है

RP --|\&amp;gt; SA : &quot;शामिल RP --|\&amp;gt; SB : &quot;शामिल

RP -up-&amp;gt; BS : \&quot;निर्भर करता है (बिल्ड लॉजिक के लिए)\ SA -up-&amp;gt; BS : &quot;निर्माण तर्क के लिए (निर्भर करता है) SB -up-&amp;gt; BS : &quot;निर्भर करता है (बिल्ड तर्क के लिए)

T के दाएँ ओर नोट कस्टम टास्क वर्ग (उदाहरण: OpenTestReportTask) end note

पी के दाएँ नोट कॉन्वेंशन प्लगइन वे कार्यों को दर्ज करते हैं end note

## @enduml

\== अभिव्यक्त रिपोर्ट कार्यों का निर्माण

टेस्ट रिपोर्ट्स को संभालने के लिए, हमने एक मॉड्यूलर दृष्टिकोण तैयार किया एक अमूर्त कार्य क्लास का उपयोग करके में`buildSrc`. आपकी आवश्यकताओं के अनुसार, यह वर्ग से विरासत में ले सकता है`DefaultTask` ou de `Exec`.

\=== अमूर्त कार्य`OpenTestReportTask`(से विरासत में प्राप्त`DefaultTask`)

यदि आपको फ़ाइल सिस्टम या अन्य Gradle API के साथ बातचीत करने वाली कस्टम Kotlin तर्क चाहिए, और फिर बाहरी कमांड चलाने की आवश्यकता हो, तो इस दृष्टिकोण की सिफारिश की जाती है।

## [source,kotlin]

package com.yourpackage

आयात org.gradle.api.DefaultTask आयात org.gradle.api.tasks.Input import org.gradle.api.tasks.TaskAction import java.io.File

abstract class OpenTestReportTask : DefaultTask() {&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;init {
    group = &quot;verification&quot;
    description = &quot;Opens a test report in Firefox.&quot;
    dependsOn(&quot;check&quot;) // Assure que les rapports sont générés
}&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;@get:Input
abstract var reportPath: String&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;@TaskAction
fun openReport() {
    val separator = File.separator
    val reportFile = project.layout.projectDirectory.asFile.toPath()
        .resolve(reportPath.replace(&quot;/&quot;, separator))
        .toAbsolutePath()
        .toFile()&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;literalblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;if (!reportFile.exists()) {
    logger.warn(&quot;Report file does not exist: $reportFile. Ensure &#39;check&#39; ran.&quot;)
    return
}&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;literalblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;    project.exec {
        commandLine(&quot;firefox&quot;, &quot;--new-tab&quot;, reportFile.absolutePath)
    }
    logger.lifecycle(&quot;Opened test report: ${reportFile.absolutePath}&quot;)
}&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;## }

\=== वास्तविक कार्यान्वयन

ये क्लासेस अमूर्त कार्य से विरासत में लेती हैं और रिपोर्ट के विशिष्ट पथ को परिभाषित करती हैं।

## [source,kotlin]

पैकेज com.yourpackage

अमूर्त वर्ग ReportUnitTestsTask : OpenTestReportTask() { init { description = &quot;फ़ायरफ़ॉक्स में यूनिट परीक्षण रिपोर्ट खोलता है। reportPath = &quot;build/reports/tests/test/index.html } }

package com.yourpackage

