&lt;li&gt;&lt;a href=&quot;#_गिट_व्यवहार_का_परीक्षण&quot;&gt;गिट व्यवहार का परीक्षण&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_आगामी_कदम&quot;&gt;आगामी कदम&lt;/a&gt;&lt;/li&gt;
