&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह पोस्ट Kotlin DSL में लिखे गए Gradle प्लगिन की संपूर्ण डिज़ाइन और परीक्षण (TDD) प्रक्रिया प्रस्तुत करती है। यह प्लगिन &lt;strong&gt;JBake&lt;/strong&gt; और &lt;strong&gt;JGit&lt;/strong&gt; के माध्यम से &lt;strong&gt;Git तैनाती&lt;/strong&gt; के साथ स्थिर साइटों की पीढ़ी को स्वचालित करता है, सब कुछ YAML कॉन्फ़िगरेशन फ़ाइल से।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_उद्देश्य&quot;&gt;उद्देश्य&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक Gradle प्लगइन बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin DSL में कॉन्फ़िगरेबल ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;सक्षम&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JBake से एक स्थिर साइट उत्पन्न करें ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JGit का उपयोग करके दूरस्थ Git रिपॉजिटरी पर तैनात करें;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CI/CD वर्कफ़्लो में एकीकृत करने योग्य ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;TDD दृष्टिकोण के अनुसार परीक्षण किया गया।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_घोषणात्मक_विन्यास&quot;&gt;घोषणात्मक विन्यास&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ YAML कॉन्फ़िगरेशन का एक उदाहरण है जिसे हमारे DSL में मॉडेल किया जाना है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/trainings.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह कॉन्फ़िगरेशन Kotlin DSL में एक घोषणीय Gradle एक्सटेंशन के माध्यम से प्रतिनिधित्व की जाती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्लगइन_की_आर्किटेक्चर&quot;&gt;प्लगइन की आर्किटेक्चर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;इंजन-प्लगइन&quot; {
class WorkspaceEngineExtension
class GenerateSiteTask
interface GitAdapter
class JGitAdapter
WorkspaceEnginePlugin --&amp;gt; WorkspaceEngineExtension
WorkspaceEnginePlugin --&amp;gt; GenerateSiteTask
GenerateSiteTask --&amp;gt; GitAdapter
JGitAdapter ..|&amp;gt; GitAdapter
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dsl_एक्सटेंशन_की_परिभाषा&quot;&gt;DSL एक्सटेंशन की परिभाषा&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;open class WorkspaceEngineExtension {
    var outputDir: String = &quot;build/site&quot;
    var template: String = &quot;freemarker&quot;
    var repoUrl: String = &quot;&quot;
    var branch: String = &quot;main&quot;
    var message: String = &quot;Generated by engine&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कस्टमाइज़्ड_कार्य_की_परिभाषा&quot;&gt;कस्टमाइज़्ड कार्य की परिभाषा&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;abstract class GenerateSiteTask : DefaultTask() {
    lateinit var gitAdapter: GitAdapter

    @get:Input abstract val repoUrl: Property&amp;lt;String&amp;gt;
    @get:InputDirectory abstract val outputDir: DirectoryProperty
    @get:Input abstract val branch: Property&amp;lt;String&amp;gt;
    @get:Input abstract val message: Property&amp;lt;String&amp;gt;

    @TaskAction
    fun run() {
        val repo = gitAdapter.cloneRepository(repoUrl.get(), outputDir.get().asFile)
        gitAdapter.commitAndPush(repo, branch.get(), message.get())
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_इंटरफ़ेस_gitadapter&quot;&gt;इंटरफ़ेस GitAdapter&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;interface GitAdapter {
    fun cloneRepository(uri: String, directory: File): Repository
    fun commitAndPush(repo: Repository, branch: String, message: String)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_jgit_के_साथ_वास्तविक_कार्यान्वयन&quot;&gt;JGit के साथ वास्तविक कार्यान्वयन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class JGitAdapter : GitAdapter {
    override fun cloneRepository(uri: String, directory: File): Repository {
        return Git.cloneRepository()
            .setURI(uri)
            .setDirectory(directory)
            .call()
            .repository
    }

    override fun commitAndPush(repo: Repository, branch: String, message: String) {
        Git(repo).use {
            it.add().addFilepattern(&quot;.&quot;).call()
            it.commit().setMessage(message).call()
            it.push().call()
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कॉन्फ़िगरेशन_dsl_कोटलिन&quot;&gt;कॉन्फ़िगरेशन DSL कोटलिन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;workspaceEngine {
    outputDir = &quot;build/out&quot;
    template = &quot;freemarker&quot;
    repoUrl = &quot;https://github.com/cheroliv/trainings.git&quot;
    branch = &quot;main&quot;
    message = &quot;deploy from plugin&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_मॉकिटो_के_साथ_यूनिट_टेस्ट&quot;&gt;मॉकिटो के साथ यूनिट टेस्ट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निर्भरताएँ&quot;&gt;निर्भरताएँ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;testImplementation(&quot;org.mockito:mockito-core:5.12.0&quot;)
testImplementation(&quot;org.mockito.kotlin:mockito-kotlin:5.2.1&quot;)
testImplementation(&quot;org.junit.jupiter:junit-jupiter:5.10.0&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_गिट_व्यवहार_का_परीक्षण&quot;&gt;गिट व्यवहार का परीक्षण&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class GenerateSiteTaskMockitoTest {

    @TempDir
    lateinit var tempDir: File

    @Test
    fun `task should call clone and commitAndPush`() {
        val project = ProjectBuilder.builder().build()
        val task = project.tasks.create(&quot;generateSite&quot;, GenerateSiteTask::class.java)

        val mockGitAdapter = mock&amp;lt;GitAdapter&amp;gt;()
        val mockRepo = mock&amp;lt;Repository&amp;gt;()

        whenever(mockGitAdapter.cloneRepository(any(), any())).thenReturn(mockRepo)

        task.gitAdapter = mockGitAdapter
        task.repoUrl.set(&quot;https://github.com/cheroliv/test.git&quot;)
        task.outputDir.set(project.layout.projectDirectory.dir(tempDir.name))
        task.branch.set(&quot;main&quot;)
        task.message.set(&quot;test commit&quot;)

        task.run()

        verify(mockGitAdapter).cloneRepository(eq(&quot;https://github.com/cheroliv/test.git&quot;), any())
        verify(mockGitAdapter).commitAndPush(eq(mockRepo), eq(&quot;main&quot;), eq(&quot;test commit&quot;))
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;विकासकर्ता&quot; as Dev
participant &quot;ग्रैडल प्रोजेक्टबिल्डर&quot; as Project
participant &quot;साइट टास्क बनाएँ&quot; as Task
participant &quot;गिटएडैप्टर (मॉक)&quot; as Adapter
participant &quot;JGitAdapter / Mockito&quot; as Impl

Dev -&amp;gt; Project : construit projet Gradle
Dev -&amp;gt; Task : configure les propriétés
Task -&amp;gt; Adapter : cloneRepository()
Adapter -&amp;gt; Impl : simulé par Mockito
Task -&amp;gt; Adapter : commitAndPush()
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ज़िम्मेदारियों का पृथक्करण vía`GitAdapter`यह Gradle प्लगिन विकास में TDD को पूरी तरह से लागू करने की अनुमति देता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Git कॉल अमूर्त और परीक्षण योग्य हैं ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;DSL कॉन्फ़िगरेशन साफ़ और स्पष्ट है ;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;प्लगिन वास्तविक कार्यान्वयन से निरपेक्ष रहता है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण उच्च परीक्षणीयता और विस्तार क्षमता (GitHub API, GitLab, आदि की ओर) सुनिश्चित करता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_आगामी_कदम&quot;&gt;आगामी कदम&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;JBake जनरेशन को एक के रूप में एकीकृत करें`BakeAdapter`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;एकीकृत परीक्षण जोड़ें के साथ`GradleRunner`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;फ़ाइलों की स्वचालित लोडिंग का समर्थन करें`site.yml`के माध्यम से SnakeYAML&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_asciidoc_क्या_है&quot;&gt;AsciiDoc क्या है?&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_asciidoc_क्यों_चुनें&quot;&gt;AsciiDoc क्यों चुनें ?&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_उपयोग_केस_आरेख_use_case&quot;&gt;उपयोग केस आरेख (Use Case)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_diagramme_mind_map&quot;&gt;Diagramme Mind Map&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रवाह_आरेख_प्रवाह&quot;&gt;प्रवाह आरेख (प्रवाह)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_asciidoc_फ़ाइल_की_बुनियादी_संरचना&quot;&gt;एक AsciiDoc फ़ाइल की बुनियादी संरचना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_मूलभूत_सिंटैक्स&quot;&gt;मूलभूत सिंटैक्स&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_शीर्षक_और_अनुभाग&quot;&gt;शीर्षक और अनुभाग&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_बोल्ड_इटैलिक_और_मोनोस्पेस_में_टेक्स्ट&quot;&gt;बोल्ड, इटैलिक और मोनोस्पेस में टेक्स्ट&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सूची_बिंदु_और_क्रमांकित&quot;&gt;सूची बिंदु और क्रमांकित&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_लिंक_और_चित्र&quot;&gt;लिंक और चित्र&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कोड_ब्लॉकों&quot;&gt;कोड ब्लॉकों&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_तालिकाएँ&quot;&gt;तालिकाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_नोट्स_और_चेतावनियाँ&quot;&gt;नोट्स और चेतावनियाँ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अट्रिब्यूट_और_चर_का_उपयोग&quot;&gt;अट्रिब्यूट और चर का उपयोग&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सामान्य_उपयोग_के_मामले&quot;&gt;सामान्य उपयोग के मामले&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अच्छे_अभ्यास&quot;&gt;अच्छे अभ्यास&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_आगे_बढ़ने_के_लिए&quot;&gt;आगे बढ़ने के लिए&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;लक्षित दर्शक :&lt;/em&gt; विकासकर्ता, तकनीकी लेखक, और कोई भी व्यक्ति जो तकनीकी दस्तावेज़ या समृद्ध लेख लिखना चाहता है।&lt;/div&gt;
&lt;p&gt;AsciiDoc एक हल्का मार्कअप भाषा है, जो संरचित तकनीकी दस्तावेज़, लेख, किताब या फिर प्रस्तुतियाँ तैयार करने के लिए डिज़ाइन किया गया है। यह अपनी पठनीयता, सिंटैक्टिक समृद्धि और विभिन्न प्रारूप (HTML, PDF, DocBook आदि) उत्पन्न करने की क्षमता से अलग होता है। इस लेख में, हम एससीआइडॉक का मूलभूत सिंटैक्स़ देखेंगे और तेज़ी से शुरू करने के लिए कुछ सुझाव देंगे।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_asciidoc_क्या_है&quot;&gt;AsciiDoc क्या है?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc दस्तावेज़ विवरण की एक भाषा है, जो Markdown के समान है लेकिन अधिक शक्तिशाली है। यह पाठ, शीर्षक, सूचियों, तालिकाओं, कोड ब्लॉक और कई अन्य चीज़ों को प्रभावी ढंग से संरचित करने की अनुमति देती है। इसकी बहुमुखी प्रतिभा के कारण, यह ओपन‑सोर्स परियोजनाओं के दस्तावेज़ीकरण, किताबों की लेखन और वेब प्रकाशन के लिए एक लोकप्रिय विकल्प है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_asciidoc_क्यों_चुनें&quot;&gt;AsciiDoc क्यों चुनें ?&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;सहज और पठनीय सिंटैक्स।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;जटिल संरचनाओं (तालिकाएँ, नोट्स, चेतावनियाँ, आदि) का प्राकृतिक समर्थन।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;मल्टी-फॉर्मैट उत्पादन (HTML, PDF, ePub, DocBook…)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JBake या Antora जैसे स्थिर साइट जनरेटरों के साथ आसान इंटीग्रेशन।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;उन्नत अनुकूलन विशेषताओं और एक्सटेंशन के साथ&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_उपयोग_केस_आरेख_use_case&quot;&gt;उपयोग केस आरेख (Use Case)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक उपयोग केस डायग्राम उपयोगकर्ताओं और प्रणाली के बीच मुख्य इंटरैक्शन को प्रस्तुत करने की अनुमति देता है। यहाँ एक दस्तावेज़ीकरण प्रणाली के लिए एक सरल उदाहरण है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
:Utilisateur: --&amp;gt; (Rédiger documentation)
:Utilisateur: --&amp;gt; (Générer PDF)
:Utilisateur: --&amp;gt; (Publier sur site web)
(Rédiger documentation) ..&amp;gt; (Générer PDF) : inclut
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_diagramme_mind_map&quot;&gt;Diagramme Mind Map&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;माइंड मैप (मानसिक मानचित्र) AsciiDoc से संबंधित अवधारणाओं और उनके संबंधों का पता लगाने के लिए आदर्श है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
* AsciiDoc
** Syntaxe
*** Titres
*** Listes
*** Blocs de code
*** Tableaux
** Extensions
*** PlantUML
*** MathJax
** Export
*** HTML
*** PDF
*** EPUB
@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्रवाह_आरेख_प्रवाह&quot;&gt;प्रवाह आरेख (प्रवाह)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक फ्लो डायग्राम AsciiDoc दस्तावेज़ की उत्पादन प्रक्रिया का वर्णन करने की अनुमति देता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Écrire fichier .adoc;
:Ajouter images et diagrammes;
if (Valider la syntaxe ?) then (oui)
:Générer HTML/PDF;
:Publier ou partager;
else (non)
:Corriger erreurs;
:back to start;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक_asciidoc_फ़ाइल_की_बुनियादी_संरचना&quot;&gt;एक AsciiDoc फ़ाइल की बुनियादी संरचना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक AsciiDoc फ़ाइल सामान्यतः शीर्षक से शुरू होती है, वैकल्पिक विशेषताओं के बाद, फिर संरचित सामग्री। यहाँ एक न्यूनतम उदाहरण दिया गया है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Titre Principal
Auteur
2024-09-03
:toc:
:icons: font

Votre contenu commence ici...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_मूलभूत_सिंटैक्स&quot;&gt;मूलभूत सिंटैक्स&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_शीर्षक_और_अनुभाग&quot;&gt;शीर्षक और अनुभाग&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc कई स्तरों के शीर्षकों का समर्थन करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Titre de niveau 1
== Titre de niveau 2
=== Titre de niveau 3
==== Titre de niveau 4&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_बोल्ड_इटैलिक_और_मोनोस्पेस_में_टेक्स्ट&quot;&gt;बोल्ड, इटैलिक और मोनोस्पेस में टेक्स्ट&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;*gras* _italique_ `monospace`&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सूची_बिंदु_और_क्रमांकित&quot;&gt;सूची बिंदु और क्रमांकित&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* Élément 1
* Élément 2

. Premier
. Deuxième
. Troisième&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_लिंक_और_चित्र&quot;&gt;लिंक और चित्र&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;Lien standard : https://asciidoc.org[AsciiDoc]
Image : image::images/logo.png[AsciiDoc Logo]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_कोड_ब्लॉकों&quot;&gt;कोड ब्लॉकों&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;[source,python]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;def hello(): print(&quot;नमस्ते AsciiDoc !&quot;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_तालिकाएँ&quot;&gt;तालिकाएँ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;|===
| Colonne 1 | Colonne 2

| Valeur A
| Valeur B

| Valeur C
| Valeur D
|===&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_नोट्स_और_चेतावनियाँ&quot;&gt;नोट्स और चेतावनियाँ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc दृश्य सूचना ब्लॉक प्रस्तुत करता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;NOTE: Ceci est une note importante.
TIP: Conseil utile pour l’utilisateur.
WARNING: Attention à ce point.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अट्रिब्यूट_और_चर_का_उपयोग&quot;&gt;अट्रिब्यूट और चर का उपयोग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कस्टम विशेषताएँ मान पुनः उपयोग करने या व्यवहार को कॉन्फ़िगर करने की अनुमति देती हैं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:project-name: AsciiDoc Explorer

Le projet s’appelle {project-name}.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सामान्य_उपयोग_के_मामले&quot;&gt;सामान्य उपयोग के मामले&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ओपन सोर्स प्रोजेक्ट दस्तावेज़ीकरण (README, तकनीकी मार्गदर्शिका) - पुस्तकें और ईबुक्स लेखन - स्थिर वेबसाइटों का स्वचालित उत्पादन (JBake, Antora) - तकनीकी प्रस्तुतियाँ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अच्छे_अभ्यास&quot;&gt;अच्छे अभ्यास&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;संगत शीर्षकों का उपयोग करें और (:toc:) के साथ एक स्वचालित सारणी। - ध्यान आकर्षित करने के लिए मुख्य बिंदुओं पर अधिसूचनाओं को प्राथमिकता दें। अपनी फाइलों को व्यवस्थित रखें ताकि रखरखाव आसान हो। उदाहरण दिखाने के लिए एनोटेटेड कोड ब्लॉक्स का उपयोग करें।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc एक शक्तिशाली और सुलभ उपकरण है जो तकनीकी दस्तावेज़ या संरचित लेख तैयार करने के लिए उपयोगी है। इसकी समृद्ध व्याकरण, बहु-प्रारूप उत्पादन के संयोजन से, यह विकसित करने वालों और मांग वाले लेखकों के लिए एक उत्कृष्ट साथी बन जाता है। अपने अगले प्रोजेक्ट में AsciiDoc आज़माइए और अंतर देखिए!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_आगे_बढ़ने_के_लिए&quot;&gt;आगे बढ़ने के लिए&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;आधिकारिक दस्तावेज़: &lt;a href=&quot;https://asciidoc.org&quot; class=&quot;bare&quot;&gt;https://asciidoc.org&lt;/a&gt; - Asciidoctor : &lt;a href=&quot;https://asciidoctor.org&quot; class=&quot;bare&quot;&gt;https://asciidoctor.org&lt;/a&gt; - JBake और AsciiDoc : &lt;a href=&quot;https://jbake.org/docs/2.6.4/#asciidoc_support&quot; class=&quot;bare&quot;&gt;https://jbake.org/docs/2.6.4/#asciidoc_support&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने अनुभव और युक्तियाँ टिप्पणी में साझा करें!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_nat_और_निजी_पते&quot;&gt;समस्या: NAT और निजी पते&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_1_अपना_सार्वजनिक_ip_पता_पहचानें&quot;&gt;चरण 1: अपना सार्वजनिक IP पता पहचानें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_2_अपने_उबुन्टू_मशीन_का_स्थानीय_ip_पता_जानें&quot;&gt;चरण 2: अपने उबुन्टू मशीन का स्थानीय IP पता जानें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_3_अपने_बॉक्स_पर_पोर्ट_फॉरवर्डिंग_सेट_अप_करें&quot;&gt;चरण 3: अपने बॉक्स पर पोर्ट फॉरवर्डिंग सेट अप करें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रशासन_इंटरफ़ेस_तक_पहुँच&quot;&gt;प्रशासन इंटरफ़ेस तक पहुँच&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_रीडायरेक्शन_की_कॉन्फ़िगरेशन&quot;&gt;रीडायरेक्शन की कॉन्फ़िगरेशन&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_4_ubuntu_पर_सेवा_की_कॉन्फ़िगरेशन&quot;&gt;चरण 4: Ubuntu पर सेवा की कॉन्फ़िगरेशन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_5_ubuntu_फ़ायरवॉल_कॉन्फ़िगरेशन&quot;&gt;चरण 5: Ubuntu फ़ायरवॉल कॉन्फ़िगरेशन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_चरण_6_परीक्षण_और_सत्यापन&quot;&gt;चरण 6 : परीक्षण और सत्यापन&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_स्थानीय_नेटवर्क_से_परीक्षण&quot;&gt;स्थानीय नेटवर्क से परीक्षण&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_बाहर_से_टेस्ट&quot;&gt;बाहर से टेस्ट&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अच्छी_प्रथाएँ_और_सुरक्षा&quot;&gt;अच्छी प्रथाएँ और सुरक्षा&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_मूल_सुरक्षा&quot;&gt;मूल सुरक्षा&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कनेक्शन_मॉनिटरिंग&quot;&gt;कनेक्शन मॉनिटरिंग&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_रेवर्स_प्रॉक्सी_का_उपयोग&quot;&gt;रेवर्स प्रॉक्सी का उपयोग&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पोर्ट_फॉरवर्डिंग_के_विकल्प&quot;&gt;पोर्ट फॉरवर्डिंग के विकल्प&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_क्लाउड_समाधान&quot;&gt;क्लाउड समाधान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_vps_और_रिवर्स_प्रॉक्सी&quot;&gt;VPS और रिवर्स प्रॉक्सी&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_निवारण&quot;&gt;समस्या निवारण&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_सामान्य_समस्याएँ&quot;&gt;सामान्य समस्याएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_नेटवर्क_डिबग&quot;&gt;नेटवर्क डिबग&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;लक्षित दर्शक : मध्यम&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;अनुमानित पूर्वापेक्षाएँ&lt;/strong&gt; : Ubuntu का बुनियादी ज्ञान, टर्मिनल का बुनियादी ज्ञान, मूल नेटवर्क अवधारणाएँ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;तकनीकी अवधारणाएँ&lt;/strong&gt; : NAT, पोर्ट फ़ॉरवर्डिंग, फ़ायरवॉल, रिवर्स प्रॉक्सी&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;सिस्टम कमांडें&lt;/strong&gt; : टर्मिनल का उपयोग, नेटवर्क कॉन्फ़िगरेशन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;उन्नत अनुभाग&lt;/strong&gt; : निगरानी, सुरक्षा, क्लाउड विकल्प&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_nat_और_निजी_पते&quot;&gt;समस्या: NAT और निजी पते&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;समस्या : क्या आप अपनी Ubuntu मशीन पर एक वेब एप्लिकेशन विकसित कर रहे हैं और अपने घरेलू नेटवर्क के बाहर से इसे सुलभ बनाना चाहते हैं ? आप सही जगह पर हैं ! इस लेख में, हम देखेंगे कि आप अपने बॉक्स इंटरनेट पर पोर्ट फ़ॉरवर्डिंग कॉन्फ़िगर करके एक स्थानीय सेवा (उदाहरण के लिए पोर्ट 8080 पर) को इंटरनेट तक कैसे प्रदर्शित कर सकते हैं।&lt;/div&gt;
&lt;p&gt;डिफ़ॉल्ट रूप से, आपके इंटरनेट बॉक्स का NAT (Network Address Translation) का उपयोग करके आपके घरेलू नेटवर्क के सभी उपकरणों के बीच केवल एक सार्वजनिक IP पता साझा किया जाता है। आपकी स्थानीय मशीनें निजी IP पते (192.168.x.x, 10.x.x.x, आदि) का उपयोग करती हैं, जो इंटरनेट पर रूट करने योग्य नहीं हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जब आप अपनी Ubuntu मशीन पर कोई सेवा शुरू करते हैं (उदाहरण के लिए पोर्ट 8080 पर एक वेब सर्वर), तो वह केवल आपके स्थानीय नेटवर्क से ही सुलभ होता है। इसे इंटरनेट से सुलभ बनाने के लिए, हमें एक पोर्ट फ़ॉरवर्डिंग कॉन्फ़िगर करने की आवश्यकता होती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_1_अपना_सार्वजनिक_ip_पता_पहचानें&quot;&gt;चरण 1: अपना सार्वजनिक IP पता पहचानें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सबसे पहले, अपने इंटरनेट कनेक्शन का सार्वजनिक IP पता प्राप्त करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Plusieurs méthodes au choix
curl ifconfig.me
curl ipecho.net/plain
wget -qO- http://ipecho.net/plain

# Ou encore
curl -s checkip.amazonaws.com&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह IP पता वही है जिसका उपयोग इंटरनेट उपयोगकर्ता आपकी सेवा तक पहुँचने के लिए करेंगे।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_2_अपने_उबुन्टू_मशीन_का_स्थानीय_ip_पता_जानें&quot;&gt;चरण 2: अपने उबुन्टू मशीन का स्थानीय IP पता जानें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आपकी Ubuntu मशीन के पास आपके स्थानीय नेटवर्क पर एक निजी IP पता है। जानने के लिए:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Afficher toutes les interfaces réseau
ip addr show

# Ou plus spécifiquement pour l&#39;interface principale
ip route get 1.1.1.1 | awk &#39;{print $7; exit}&#39;

# Alternative avec hostname
hostname -I | awk &#39;{print $1}&#39;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस पते को नोट करें (उदाहरण के लिए`192.168.1.100`), हमें इसे कॉन्फ़िगरेशन के लिए चाहिए होगा।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_3_अपने_बॉक्स_पर_पोर्ट_फॉरवर्डिंग_सेट_अप_करें&quot;&gt;चरण 3: अपने बॉक्स पर पोर्ट फॉरवर्डिंग सेट अप करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कॉन्फ़िगरेशन आपके बॉक्स के मॉडल के अनुसार भिन्न होता है, लेकिन सिद्धांत समान रहता है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रशासन_इंटरफ़ेस_तक_पहुँच&quot;&gt;प्रशासन इंटरफ़ेस तक पहुँच&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने ब्राउज़र को खोलें और अपने बॉक्स के वेब इंटरफ़ेस पर जाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ्रीबॉक्स&lt;/strong&gt;:`192.168.1.1` ou &lt;code&gt;mafreebox.freebox.fr&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;लाइवबॉक्स ऑरेंज&lt;/strong&gt;&lt;code class=&quot;No output&quot;&gt;192.168.1.1&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SFR बॉक्स&lt;/strong&gt;(No output)&lt;code&gt;192.168.1.1&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Bbox Bouygues&lt;/strong&gt;(No output)&lt;code&gt;192.168.1.254&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रीडायरेक्शन_की_कॉन्फ़िगरेशन&quot;&gt;रीडायरेक्शन की कॉन्फ़िगरेशन&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पोर्ट फॉरवर्डिंग के लिए समर्पित खंड की तलाश करें (नाम भिन्न हो सकते हैं):&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;पोर्ट रीडायरेक्शन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;NAT/PAT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;पोर्ट फॉरवर्डिंग&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;गेम सर्वर&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इन सेटिंग्स के साथ एक नया नियम बनाएँ :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;क्षेत्र&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;मूल्य&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;नाम/विवरण&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ubuntu वेब सेवा&quot; (या कोई अन्य स्पष्ट नाम)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बाहरी पोर्ट (या सार्वजनिक पोर्ट)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;8080&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;आंतरिक IP पता&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;आपकी Ubuntu मशीन का IP (उदाहरण: 192.168.1.100)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;आंतरिक पोर्ट (या निजी पोर्ट)&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;8080&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;प्रोटोकॉल&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;TCP&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;राज्य&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सक्रिय&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_4_ubuntu_पर_सेवा_की_कॉन्फ़िगरेशन&quot;&gt;चरण 4: Ubuntu पर सेवा की कॉन्फ़िगरेशन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सुनिश्चित करें कि आपका सेवा सभी इंटरफेस पर सुनता है, केवल localhost पर नहीं:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# ✅ Correct : écoute sur toutes les interfaces
python3 -m http.server 8080 --bind 0.0.0.0

# ❌ Incorrect : écoute seulement en local
python3 -m http.server 8080 --bind 127.0.0.1&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जाँचने के लिए कि आपका सेवा सही ढंग से सुन रहा है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Vérifier les ports en écoute
sudo netstat -tlnp | grep :8080
# ou avec ss (plus moderne)
sudo ss -tlnp | grep :8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आपको कुछ ऐसा देखना चाहिए`0.0.0.0:8080`और नहीं`127.0.0.1:8080`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_5_ubuntu_फ़ायरवॉल_कॉन्फ़िगरेशन&quot;&gt;चरण 5: Ubuntu फ़ायरवॉल कॉन्फ़िगरेशन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu डिफ़ॉल्ट रूप से UFW (Uncomplicated Firewall) का उपयोग करता है। स्थिति जाँचें और आवश्यकतानुसार पोर्ट की अनुमति दें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Vérifier le statut du pare-feu
sudo ufw status

# Si le pare-feu est actif, autoriser le port 8080
sudo ufw allow 8080/tcp

# Ou plus spécifiquement pour un service web
sudo ufw allow &#39;Apache&#39;  # si vous utilisez Apache
sudo ufw allow &#39;Nginx Full&#39;  # si vous utilisez Nginx&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_चरण_6_परीक्षण_और_सत्यापन&quot;&gt;चरण 6 : परीक्षण और सत्यापन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्थानीय_नेटवर्क_से_परीक्षण&quot;&gt;स्थानीय नेटवर्क से परीक्षण&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहले, अपने स्थानीय नेटवर्क पर किसी अन्य मशीन से पहुँच का परीक्षण करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Remplacez par l&#39;IP locale de votre machine Ubuntu
curl http://192.168.1.100:8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_बाहर_से_टेस्ट&quot;&gt;बाहर से टेस्ट&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अब, अपने सार्वजनिक IP का उपयोग करके इंटरनेट से परीक्षण करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Remplacez par votre IP publique
curl http://VOTRE_IP_PUBLIQUE:8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आप ऑनलाइन उपकरणों का भी उपयोग कर सकते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://www.yougetsignal.com/tools/open-ports/&quot; class=&quot;bare&quot;&gt;https://www.yougetsignal.com/tools/open-ports/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://canyouseeme.org/&quot; class=&quot;bare&quot;&gt;https://canyouseeme.org/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अच्छी_प्रथाएँ_और_सुरक्षा&quot;&gt;अच्छी प्रथाएँ और सुरक्षा&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_मूल_सुरक्षा&quot;&gt;मूल सुरक्षा&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Configurer fail2ban pour protéger contre les attaques par force brute
sudo apt update &amp;amp;&amp;amp; sudo apt install fail2ban

# Limiter l&#39;accès avec UFW (exemple : autoriser seulement certaines IP)
sudo ufw allow from 203.0.113.0/24 to any port 8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_कनेक्शन_मॉनिटरिंग&quot;&gt;कनेक्शन मॉनिटरिंग&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Surveiller les connexions en temps réel
sudo netstat -an | grep :8080

# Logs des connexions (selon votre application)
sudo tail -f /var/log/nginx/access.log  # pour Nginx
sudo journalctl -f -u your-service      # pour un service systemd&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_रेवर्स_प्रॉक्सी_का_उपयोग&quot;&gt;रेवर्स प्रॉक्सी का उपयोग&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बेहतर सुरक्षा और लचीलापन के लिए, नginx जैसे रिवर्स प्रॉक्सी का उपयोग करने पर विचार करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-nginx hljs&quot; data-lang=&quot;nginx&quot;&gt;server {
    listen 80;
    server_name votre-domaine.com;

    location / {
        proxy_pass http://localhost:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पोर्ट_फॉरवर्डिंग_के_विकल्प&quot;&gt;पोर्ट फॉरवर्डिंग के विकल्प&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_क्लाउड_समाधान&quot;&gt;क्लाउड समाधान&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ngrok&lt;/strong&gt;: सुरक्षित अस्थायी सुरंग&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Cloudflare टनल&lt;/strong&gt;नि:शुल्क और सुरक्षित समाधान&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;serveo.net&lt;/strong&gt;: सरल SSH टनल&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Exemple avec ngrok
ngrok http 8080

# Exemple avec serveo
ssh -R 80:localhost:8080 serveo.net&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vps_और_रिवर्स_प्रॉक्सी&quot;&gt;VPS और रिवर्स प्रॉक्सी&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पेशेवर उपयोग के लिए, VPN के माध्यम से आपके स्थानीय बुनियादी ढाँचे की ओर इशारा करते हुए एक रिवर्स प्रॉक्सी के साथ VPS का उपयोग करने पर विचार करें।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_निवारण&quot;&gt;समस्या निवारण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_सामान्य_समस्याएँ&quot;&gt;सामान्य समस्याएँ&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 60%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;समस्या&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;हल&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;बाहर से सेवा असुलभ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;पोर्ट फ़ॉरवर्डिंग कॉन्फ़िगरेशन की जाँच करें और सुनिश्चित करें कि सेवा 0.0.0.0 पर सुन रही है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कनेक्शन अस्वीकारित&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सेवा शुरू नहीं हुई है या यह केवल 127.0.0.1 पर सुन रही है&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;कनेक्शन टाइमआउट&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;फ़ायरवॉल (बॉक्स या Ubuntu) की समस्या या पोर्ट फ़ॉरवर्डिंग का गलत कॉन्फ़िगरेशन&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;सार्वजनिक IP नियमित रूप से बदलता है&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;एक डायनामिक DNS (DynDNS, No-IP, आदि) कॉन्फ़िगर करें।&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_नेटवर्क_डिबग&quot;&gt;नेटवर्क डिबग&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Tester la connectivité locale
telnet localhost 8080

# Tester depuis une autre machine du réseau
telnet 192.168.1.100 8080

# Vérifier les routes réseau
ip route show

# Analyser le trafic réseau
sudo tcpdump -i any port 8080&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इंटरनेट पर एक स्थानीय सेवा को उजागर करने के लिए पोर्ट फॉरवर्डिंग, सुरक्षा और निगरानी की सावधानीपूर्वक कॉन्फ़िगरेशन की आवश्यकता होती है। यद्यपि यह दृष्टिकोण विकास या व्यक्तिगत परियोजनाओं के लिए आदर्श है, उत्पादन उपयोग के लिए अधिक मज़बूत विकल्प (VPS, CDN, क्लाउड सेवाओं) पर विचार करें।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;महत्वपूर्ण है कि आप हमेशा सुरक्षा को ध्यान में रखें: मजबूत पासवर्ड उपयोग करें, अपने सिस्टम को नियमित रूप से अपडेट करें, और अपने उजागर सेवाओं तक पहुँच की निगरानी करें।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने अनुभव और प्रश्न टिप्पणियों में साझा करने में संकोच न करें !&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ_प्लगइन_ग्रेडल_बेकरी&quot;&gt;संदर्भ: प्लगइन ग्रेडल बेकरी&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_1_खराब_मॉक_की_जाँच_करें&quot;&gt;समस्या #1: खराब मॉक की जाँच करें&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_निदान&quot;&gt;निदान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान&quot;&gt;समाधान&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_2_सिलसिलेवार_unfinishedstubbingexception&quot;&gt;समस्या #2 : सिलसिलेवार UnfinishedStubbingException&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_निदान_2&quot;&gt;निदान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_2&quot;&gt;समाधान&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_3_कॉन्फ़िगरेशन_फ़ाइल_मौजूद_नहीं_है&quot;&gt;समस्या #3: कॉन्फ़िगरेशन फ़ाइल मौजूद नहीं है&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_निदान_3&quot;&gt;निदान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_3&quot;&gt;समाधान&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समस्या_4_afterevaluate_और_nullpointerexception&quot;&gt;समस्या #4 : afterEvaluate और NullPointerException&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_निदान_4&quot;&gt;निदान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_समाधान_4&quot;&gt;समाधान&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_पूर्ण_समाधान&quot;&gt;पूर्ण समाधान&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_सीखे_गए_सबक&quot;&gt;सीखे गए सबक&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_सही_मॉक_की_जाँच_करें&quot;&gt;1. सही मॉक की जाँच करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_नेस्टेड_मॉक_से_बचें&quot;&gt;2. नेस्टेड मॉक से बचें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_मूल्यांकन_कॉलबैक_को_मॉक_करें&quot;&gt;3. मूल्यांकन कॉलबैक को मॉक करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_पथों_के_समाधान_का_परीक्षण_करें&quot;&gt;4. पथों के समाधान का परीक्षण करें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अंतिम_परीक्षण_आर्किटेक्चर&quot;&gt;अंतिम परीक्षण आर्किटेक्चर&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संसाधन&quot;&gt;संसाधन&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle प्लगइन के विकास के दौरान&lt;strong&gt;बेकरी&lt;/strong&gt;मेरे JBake ब्लॉग के लिए, मुझे एक स्पष्ट रूप से सरल समस्या का सामना करना पड़ा: एक इकाई परीक्षण जो त्रुटि के साथ विफल हो रहा था`Wanted but not invoked`. क्या दिख रहा था कि एक तुच्छ बग था, वह साबित हुआ Mockito और Kotlin के साथ मॉकिंग की सूक्ष्मताओं को समझने के लिए एक आदर्श केस स्टडी।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस लेख में, मैं आपको एक विधिपूर्वक डिबगिंग की यात्रा पर ले जाता हूँ, जहाँ प्रत्येक समाधान एक नई समस्या को उजागर करता है, अंतिम समाधान तक।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ_प्लगइन_ग्रेडल_बेकरी&quot;&gt;संदर्भ: प्लगइन ग्रेडल बेकरी&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bakery प्लगिन JBake के चारों ओर एक रैपर है जो स्थिर साइटों के प्रकाशन को आसान बनाता है। इसकी सरलीकृत संरचना यहाँ है :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class BakeryPlugin : Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        val extension = project.extensions.create(
            &quot;bakery&quot;,
            BakeryExtension::class.java
        )

        project.afterEvaluate {
            if (!project.layout.projectDirectory.asFile
                    .resolve(extension.configPath.get()).exists()) {
                println(&quot;config file does not exists&quot;)
            } else {
                // C&#39;EST ICI QUE ÇA SE PASSE
                project.plugins.apply(JBakePlugin::class.java)

                val site = FileSystemManager.from(project, extension.configPath.get())
                // Configuration de JBake...
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;असफल होने वाला परीक्षण सरल था :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin applies jbake gradle plugin`() {
    val project = createMockProject()
    val plugin = BakeryPlugin()

    plugin.apply(project)

    verify(project.plugins).apply(JBakePlugin::class.java)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;त्रुटि :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;Wanted but not invoked:
pluginContainer.apply(class org.jbake.gradle.JBakePlugin);
Actually, there were zero interactions with this mock.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_1_खराब_मॉक_की_जाँच_करें&quot;&gt;समस्या #1: खराब मॉक की जाँच करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निदान&quot;&gt;निदान&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Test
participant &quot;project.plugins&quot; as PP
participant &quot;मॉकप्लगइनकंटेनर&quot; as MPC
participant &quot;BakeryPlugin&quot; as BP

Test -&amp;gt; Test: createMockProject()
activate Test
Test -&amp;gt; MPC: create mock
Test -&amp;gt; PP: doReturn mockPluginContainer
Test --&amp;gt; Test: return project
deactivate Test

Test -&amp;gt; BP: apply(project)
activate BP
BP -&amp;gt; PP: project.plugins
PP --&amp;gt; BP: returns mockPluginContainer
BP -&amp;gt; MPC: apply(JBakePlugin::class.java)
deactivate BP

Test -&amp;gt; PP: verify(project.plugins).apply(...)
note right
  ❌ ÉCHEC !
  Mockito vérifie &quot;project.plugins&quot;
  mais l&#39;interaction a eu lieu sur
  &quot;मॉकप्लगइनकंटेनर&quot;
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्या: Mockito इंटरैक्शन को ट्रेस नहीं कर सकता`project.plugins`क्योंकि यह केवल एक गेटर है जो वास्तविक मॉक लौटाता है`mockPluginContainer`सत्यापन मॉक के इंस्टेंस पर सीधे किया जाना चाहिए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान&quot;&gt;समाधान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;संपादित`createMockProject()`दो ऑब्जेक्ट्स लौटाने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;private fun createMockProject(): Pair&amp;lt;Project, PluginContainer&amp;gt; {
    val mockPluginContainer = mock&amp;lt;PluginContainer&amp;gt;()
    val mockProject = mock&amp;lt;Project&amp;gt; {
        on { plugins } doReturn mockPluginContainer
    }
    return Pair(mockProject, mockPluginContainer)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और परीक्षा को अनुकूलित करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin applies jbake gradle plugin`() {
    val (project, mockPluginContainer) = createMockProject()
    val plugin = BakeryPlugin()

    plugin.apply(project)

    // ✅ Vérification directe sur le bon mock
    verify(mockPluginContainer).apply(JBakePlugin::class.java)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_2_सिलसिलेवार_unfinishedstubbingexception&quot;&gt;समस्या #2 : सिलसिलेवार UnfinishedStubbingException&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निदान_2&quot;&gt;निदान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पहला सुधार लागू होने के बाद, एक नई त्रुटि सामने आई :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;UnfinishedStubbingException:
Unfinished stubbing detected here
Hints:
 3. you are stubbing the behaviour of another mock inside
    before &#39;thenReturn&#39; instruction is completed&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;समस्याग्रस्त कोड Mockito-Kotlin की DSL सिंटैक्स का उपयोग कर रहा था :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val mockProject = mock&amp;lt;Project&amp;gt; {
    on { extensions } doReturn mockExtensionContainer
    on { plugins } doReturn mockPluginContainer
    on { logger } doReturn mock()  // ❌ PROBLÈME ICI !
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;Mockito&quot; as M
participant &quot;मॉक बिल्डर&quot; as MB
participant &quot;python
इनलाइन मॉक&quot; as IM

M -&amp;gt; MB: mock&amp;lt;Project&amp;gt; { ... }
activate MB
MB -&amp;gt; MB: on { logger } doReturn
MB -&amp;gt; IM: mock()
activate IM
note right
  ❌ Création d&#39;un nouveau mock
  PENDANT le stubbing en cours !

  Mockito perd le contexte
  du stubbing parent
end note
IM --&amp;gt; MB: nouveau mock
deactivate IM
MB -x M: UnfinishedStubbingException
deactivate MB
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_2&quot;&gt;समाधान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;बनाना&lt;strong&gt;सभी&lt;/strong&gt;किसी भी स्टबिंग ब्लॉक के बाहर के मॉक, फिर उन्हेंconfigure करने के साथ`whenever()`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;private fun createMockProject(): Pair&amp;lt;Project, PluginContainer&amp;gt; {
    // 1️⃣ Créer TOUS les mocks d&#39;abord
    val mockPluginContainer = mock&amp;lt;PluginContainer&amp;gt;()
    val mockExtensionContainer = mock&amp;lt;ExtensionContainer&amp;gt;()
    val mockLogger = mock&amp;lt;org.gradle.api.logging.Logger&amp;gt;()
    val mockProject = mock&amp;lt;Project&amp;gt;()

    // 2️⃣ Configurer les mocks séparément avec whenever()
    whenever(mockProject.plugins).thenReturn(mockPluginContainer)
    whenever(mockProject.extensions).thenReturn(mockExtensionContainer)
    whenever(mockProject.logger).thenReturn(mockLogger)

    return Pair(mockProject, mockPluginContainer)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock tip&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-tip&quot; title=&quot;Tip&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;स्वर्ण नियम&lt;/strong&gt;कभी कॉल न करें`mock()`मॉक कॉन्फ़िगरेशन ब्लॉक के अंदर. हमेशा पहले मॉक बनाएं, फिर उन्हें कॉन्फ़िगर करें।&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_3_कॉन्फ़िगरेशन_फ़ाइल_मौजूद_नहीं_है&quot;&gt;समस्या #3: कॉन्फ़िगरेशन फ़ाइल मौजूद नहीं है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निदान_3&quot;&gt;निदान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हालांकि सही मॉक के साथ, परीक्षण हमेशा विफल रहता था क्योंकि प्लगिन को कॉन्फ़िगरेशन फ़ाइल नहीं मिल रही थी :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// Dans BakeryPlugin.kt
if (!project.layout.projectDirectory.asFile
        .resolve(extension.configPath.get()).exists()) {
    println(&quot;config file does not exists&quot;)
    return@afterEvaluate  // ❌ Sort avant d&#39;appliquer JBake !
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;BakeryPlugin&quot; as BP
participant &quot;प्रोजेक्ट लेयआउट&quot; as PL
participant &quot;विस्तार&quot; as EXT
participant &quot;फ़ाइलसिस्टम&quot; as FS

BP -&amp;gt; PL: layout.projectDirectory.asFile
PL --&amp;gt; BP: /some/mock/path
BP -&amp;gt; EXT: extension.configPath.get()
EXT --&amp;gt; BP: &quot;../../site.yml&quot;
BP -&amp;gt; BP: resolve(&quot;../../site.yml&quot;)
BP -&amp;gt; FS: exists() ?
FS --&amp;gt; BP: false ❌
BP -&amp;gt; BP: return (skip JBake)
note right
  Le plugin ne trouve pas
  le fichier et sort
  avant d&#39;appliquer JBake
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_3&quot;&gt;समाधान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पाथ रिज़ॉल्यूशन काम करने के लिए मॉक को कॉन्फ़िगर करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;private fun createMockProject(): Pair&amp;lt;Project, PluginContainer&amp;gt; {
    // ... autres mocks ...

    val configFile = File(&quot;../../site.yml&quot;).canonicalFile
    val projectDir = configFile.parentFile

    // Configuration cohérente des chemins
    whenever(mockConfigPathProperty.get()).thenReturn(&quot;site.yml&quot;)
    whenever(mockProjectDirectory.asFile).thenReturn(projectDir)

    // Maintenant : projectDir.resolve(&quot;site.yml&quot;) existe ! ✅
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!define SUCCESS #90EE90
!define PROBLEM #FFB6C1

rectangle &quot;मॉक कॉन्फ़िगरेशन&quot; {
    card &quot;projectDirectory.asFile&quot; SUCCESS
    card &quot;returns: /real/path/to/project&quot; SUCCESS

    card &quot;configPath.get()&quot; SUCCESS
    card &quot;वापसी: site.yml&quot; SUCCESS

    card &quot;resolve()&quot; SUCCESS
    card &quot;/real/path/to/project/site.yml&quot; SUCCESS

    card &quot;exists()&quot; SUCCESS
    card &quot;true ✅&quot; SUCCESS
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समस्या_4_afterevaluate_और_nullpointerexception&quot;&gt;समस्या #4 : afterEvaluate और NullPointerException&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_निदान_4&quot;&gt;निदान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्लगिन JBake को एक ब्लॉक में लागू करता है`afterEvaluate`, और पहुँचता है`buildDirectory.dir()`(No output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.afterEvaluate {
    // ...
    project.tasks.withType(JBakeTask::class.java)
        .getByName(&quot;bake&quot;).apply {
            output = project.layout.buildDirectory
                .dir(site.bake.destDirPath)  // ❌ NPE ici !
                .get()
                .asFile
        }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मॉक का`buildDirectory.dir()&lt;code&gt;वह वापस आ रहा था`null&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_समाधान_4&quot;&gt;समाधान&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मॉकर`afterEvaluate`ताकि वह तुरंत चल सके, और पूरी तरह से कॉन्फ़िगर करें`buildDirectory`(no output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;private fun createMockProject(): Pair&amp;lt;Project, PluginContainer&amp;gt; {
    // ... autres mocks ...

    val mockBuildDirectory = mock&amp;lt;DirectoryProperty&amp;gt;()
    val buildDir = File(projectDir, &quot;build&quot;)

    // Mocker dir() pour retourner un Provider valide
    whenever(mockBuildDirectory.dir(any&amp;lt;String&amp;gt;())).doAnswer { invocation -&amp;gt;
        val path = invocation.arguments[0] as String
        val mockDirProvider = mock&amp;lt;Provider&amp;lt;Directory&amp;gt;&amp;gt;()
        val mockDir = mock&amp;lt;Directory&amp;gt;()

        whenever(mockDir.asFile).thenReturn(File(buildDir, path))
        whenever(mockDirProvider.get()).thenReturn(mockDir)

        mockDirProvider
    }

    // Mocker afterEvaluate pour exécution immédiate
    whenever(mockProject.afterEvaluate(any&amp;lt;Action&amp;lt;Project&amp;gt;&amp;gt;())).doAnswer { invocation -&amp;gt;
        val action = invocation.arguments[0] as Action&amp;lt;Project&amp;gt;
        action.execute(mockProject)  // ✅ Exécution synchrone
        null
    }

    return Pair(mockProject, mockPluginContainer)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;परीक्षण&quot; as T
participant &quot;BakeryPlugin&quot; as BP
participant &quot;mockProject&quot; as MP
participant &quot;मूल्यांकन के बाद कार्य&quot; as AE

T -&amp;gt; BP: apply(project)
activate BP
BP -&amp;gt; MP: afterEvaluate { ... }
activate MP
note right
  Mock configuré pour
  exécuter immédiatement
end note
MP -&amp;gt; AE: execute(project)
activate AE
AE -&amp;gt; MP: layout.buildDirectory.dir(&quot;bake&quot;)
MP --&amp;gt; AE: Provider&amp;lt;Directory&amp;gt; ✅
AE -&amp;gt; MP: plugins.apply(JBakePlugin)
deactivate AE
MP --&amp;gt; BP:
deactivate MP
BP --&amp;gt; T:
deactivate BP

T -&amp;gt; T: verify(mockPluginContainer).apply(...)
note right: ✅ SUCCÈS !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पूर्ण_समाधान&quot;&gt;पूर्ण समाधान&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ फ़ंक्शन है`createMockProject()`अंतिम, जो सभी समस्याओं को हल करता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;private fun createMockProject(): Pair&amp;lt;Project, PluginContainer&amp;gt; {
    // 1️⃣ CRÉER tous les mocks (pas de nested mocks !)
    val mockPluginContainer = mock&amp;lt;PluginContainer&amp;gt;()
    val mockExtensionContainer = mock&amp;lt;ExtensionContainer&amp;gt;()
    val mockLogger = mock&amp;lt;org.gradle.api.logging.Logger&amp;gt;()
    val mockTaskContainer = mock&amp;lt;TaskContainer&amp;gt;()
    val mockConfigPathProperty = mock&amp;lt;Property&amp;lt;String&amp;gt;&amp;gt;()
    val mockBakeryExtension = mock&amp;lt;BakeryExtension&amp;gt;()
    val mockProjectDirectory = mock&amp;lt;Directory&amp;gt;()
    val mockBuildDirectory = mock&amp;lt;DirectoryProperty&amp;gt;()
    val mockProjectLayout = mock&amp;lt;ProjectLayout&amp;gt;()
    val mockProject = mock&amp;lt;Project&amp;gt;()

    // 2️⃣ CONFIGURER la résolution des chemins
    val configFile = File(&quot;../../site.yml&quot;).canonicalFile
    val projectDir = configFile.parentFile
    val buildDir = File(projectDir, &quot;build&quot;)

    whenever(mockConfigPathProperty.get()).thenReturn(&quot;site.yml&quot;)
    whenever(mockConfigPathProperty.isPresent).thenReturn(true)
    whenever(mockBakeryExtension.configPath).thenReturn(mockConfigPathProperty)
    whenever(mockProjectDirectory.asFile).thenReturn(projectDir)

    // 3️⃣ CONFIGURER buildDirectory avec dir()
    whenever(mockBuildDirectory.dir(any&amp;lt;String&amp;gt;())).doAnswer { invocation -&amp;gt;
        val path = invocation.arguments[0] as String
        val mockDirProvider = mock&amp;lt;Provider&amp;lt;Directory&amp;gt;&amp;gt;()
        val mockDir = mock&amp;lt;Directory&amp;gt;()
        whenever(mockDir.asFile).thenReturn(File(buildDir, path))
        whenever(mockDirProvider.get()).thenReturn(mockDir)
        mockDirProvider
    }

    // 4️⃣ ASSEMBLER le projet
    whenever(mockProjectLayout.projectDirectory).thenReturn(mockProjectDirectory)
    whenever(mockProjectLayout.buildDirectory).thenReturn(mockBuildDirectory)

    whenever(mockExtensionContainer.create(&quot;bakery&quot;, BakeryExtension::class.java))
        .thenReturn(mockBakeryExtension)
    whenever(mockExtensionContainer.getByType(BakeryExtension::class.java))
        .thenReturn(mockBakeryExtension)

    whenever(mockProject.extensions).thenReturn(mockExtensionContainer)
    whenever(mockProject.plugins).thenReturn(mockPluginContainer)
    whenever(mockProject.tasks).thenReturn(mockTaskContainer)
    whenever(mockProject.layout).thenReturn(mockProjectLayout)
    whenever(mockProject.logger).thenReturn(mockLogger)
    whenever(mockProject.projectDir).thenReturn(projectDir)

    // 5️⃣ CONFIGURER afterEvaluate pour exécution immédiate
    whenever(mockProject.afterEvaluate(any&amp;lt;Action&amp;lt;Project&amp;gt;&amp;gt;())).doAnswer { invocation -&amp;gt;
        val action = invocation.arguments[0] as Action&amp;lt;Project&amp;gt;
        action.execute(mockProject)
        null
    }

    return Pair(mockProject, mockPluginContainer)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;और अंतिम परीक्षा जो पास होती है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin applies jbake gradle plugin`() {
    val (project, mockPluginContainer) = createMockProject()
    val plugin = BakeryPlugin()

    plugin.apply(project)

    verify(mockPluginContainer).apply(JBakePlugin::class.java) // ✅ SUCCÈS !
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सीखे_गए_सबक&quot;&gt;सीखे गए सबक&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
* Mocking avec Mockito
** ✅ Bonnes pratiques
*** Créer tous les mocks d&#39;abord
*** Configurer avec whenever() séparément
*** Vérifier le mock exact, pas un proxy
*** Tester la résolution des chemins
** ❌ Pièges à éviter
*** mock() dans un bloc de configuration
*** Vérifier project.x au lieu de mockX
*** Ignorer les blocs afterEvaluate
*** Retourner null pour les Providers
@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_सही_मॉक_की_जाँच_करें&quot;&gt;1. सही मॉक की जाँच करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// ❌ FAUX
verify(project.plugins).apply(JBakePlugin::class.java)

// ✅ CORRECT
val (project, mockPluginContainer) = createMockProject()
verify(mockPluginContainer).apply(JBakePlugin::class.java)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_नेस्टेड_मॉक_से_बचें&quot;&gt;2. नेस्टेड मॉक से बचें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// ❌ FAUX - UnfinishedStubbingException
val mockProject = mock&amp;lt;Project&amp;gt; {
    on { logger } doReturn mock()  // Nested mock creation !
}

// ✅ CORRECT - Créer séparément
val mockLogger = mock&amp;lt;org.gradle.api.logging.Logger&amp;gt;()
val mockProject = mock&amp;lt;Project&amp;gt;()
whenever(mockProject.logger).thenReturn(mockLogger)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_मूल्यांकन_कॉलबैक_को_मॉक_करें&quot;&gt;3. मूल्यांकन कॉलबैक को मॉक करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// ✅ afterEvaluate doit s&#39;exécuter pour les tests
whenever(mockProject.afterEvaluate(any())).doAnswer { invocation -&amp;gt;
    val action = invocation.arguments[0] as Action&amp;lt;Project&amp;gt;
    action.execute(mockProject)
    null
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_पथों_के_समाधान_का_परीक्षण_करें&quot;&gt;4. पथों के समाधान का परीक्षण करें&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// Toujours vérifier que les chemins se résolvent correctement
val extension = project.extensions.getByType(BakeryExtension::class.java)
val configPath = extension.configPath.get()
val projectDir = project.layout.projectDirectory.asFile
val resolvedConfig = projectDir.resolve(configPath)

println(&quot;Resolved config: ${resolvedConfig.absolutePath}&quot;)
println(&quot;Exists: ${resolvedConfig.exists()}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अंतिम_परीक्षण_आर्किटेक्चर&quot;&gt;अंतिम परीक्षण आर्किटेक्चर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;परीक्षण परत&quot; {
    [Test Class] --&amp;gt; [createMockProject()]
}

package &quot;मॉक सृजन&quot; {
    [createMockProject()] --&amp;gt; [Create All Mocks]
    [Create All Mocks] --&amp;gt; [Configure Paths]
    [Configure Paths] --&amp;gt; [Configure Callbacks]
    [Configure Callbacks] --&amp;gt; [Assemble Project]
}

package &quot;मॉक ऑब्जेक्ट्स&quot; {
    [Assemble Project] --&amp;gt; [Project Mock]
    [Assemble Project] --&amp;gt; [PluginContainer Mock]
    [Assemble Project] --&amp;gt; [Extension Mocks]
    [Assemble Project] --&amp;gt; [Layout Mocks]
}

package &quot;### ग्रेडल एकीकरण
JBake को JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड में एकीकृत किया जा सकता है:

```kotlin
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}&quot; {
    [Test Class] --&amp;gt; [BakeryPlugin]
    [BakeryPlugin] --&amp;gt; [Project Mock]
    [BakeryPlugin] --&amp;gt; [PluginContainer Mock]
}

package &quot;सत्यापन&quot; {
    [Test Class] --&amp;gt; [verify(mockPluginContainer)]
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जो एक साधारण परीक्षण समस्या लग रहा था, वह एक उत्कृष्ट केस स्टडी का उदाहरण साबित हुआ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin के साथ Mockito की सूक्ष्मताएँ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;सही वस्तुओं का मॉक करने का महत्व&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;परीक्षण में असिंक्रोनस कॉलबैक का प्रबंधन&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Gradle प्लगिन में पथ समाधान&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;प्रणालीगत डिबगिंग, समस्या की प्रत्येक परत को समझते हुए, ने एक मजबूत और संधारणीय समाधान तक पहुँचने में सक्षम बना दिया।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock tip&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-tip&quot; title=&quot;Tip&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;सलाह आपके टेस्ट के लिए&lt;/strong&gt;यदि आप Mockito के साथ &quot;Wanted but not invoked&quot; का सामना करते हैं, तो हमेशा खुद से पूछें:
1. क्या मैं सही mock की जाँच कर रहा हूँ?
2. क्या मेरे सभी मॉक कॉन्फ़िगरेशन ब्लॉक के बाहर बनाए जाते हैं ?
3. क्या मेरे कॉलबैक वास्तव में निष्पादित होते हैं ?
4. क्या मेरे रास्ते सही तरीके से हल हो रहे हैं?&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संसाधन&quot;&gt;संसाधन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/mockito/mockito-kotlin&quot;&gt;Mockito-Kotlin दस्तावेज़&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/custom_plugins.html&quot;&gt;Gradle Plugin Development Guide&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://jbake.org/&quot;&gt;JBake स्टेटिक साइट जनरेटर&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;क्या आपने अपने परीक्षणों में समान समस्याओं का सामना किया है? कृपया टिप्पणियों में अपने अनुभव को साझा करें!&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_इथर_मोनैड_क्या_है&quot;&gt;इथर मोनैड क्या है ?&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_either_का_उपयोग_क्यों_करें&quot;&gt;Either का उपयोग क्यों करें?&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_संदर्भ&quot;&gt;संदर्भ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_विभिन्न_दृष्टिकोण&quot;&gt;विभिन्न दृष्टिकोण&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_पारंपरिक_पद्धति_के_साथ_when&quot;&gt;पारंपरिक पद्धति के साथ `when&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fold_का_उपयोग_एक_अधिक_संक्षिप्त_दृष्टिकोण_के_लिए&quot;&gt;fold` का उपयोग एक अधिक संक्षिप्त दृष्टिकोण के लिए&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_परिवर्तन_map_और_mapleft_के_साथ&quot;&gt;परिवर्तन &lt;code&gt;map&lt;/code&gt; और &lt;code&gt;mapLeft&lt;/code&gt; के साथ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_त्रुटि_प्रबंधन_के_साथ_getorelse&quot;&gt;त्रुटि प्रबंधन के साथ `getOrElse&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_साइड_कार्रवाई_onleft_और_onright_के_साथ&quot;&gt;साइड कार्रवाई &lt;code&gt;onLeft&lt;/code&gt; और &lt;code&gt;onRight&lt;/code&gt; के साथ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ऑपरेशन_चेनिंग_flatmap_के_साथ&quot;&gt;ऑपरेशन चेनिंग &lt;code&gt;flatMap&lt;/code&gt; के साथ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_द्विदिशात्मक_परिवर्तन_के_साथ_bimap&quot;&gt;द्विदिशात्मक परिवर्तन के साथ `bimap&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_swap_के_साथ_किनारों_को_उलटना&quot;&gt;swap के साथ किनारों को उलटना&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tap_और_tapleft_का_उपयोग&quot;&gt;tap` और &lt;code&gt;tapLeft&lt;/code&gt; का उपयोग:&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_उपयोग_recover&quot;&gt;उपयोग &lt;code&gt;recover&lt;/code&gt; :&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_प्रायोगिक_उपयोग_के_मामले&quot;&gt;प्रायोगिक उपयोग के मामले&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_और_आगे_जाने_के_लिए&quot;&gt;और आगे जाने के लिए&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;लक्षित दर्शक :&lt;/em&gt; मध्यम से उन्नत स्तर के कोटलिन डेवलपर्स&lt;/div&gt;
&lt;p&gt;Kotlin में कार्यात्मक प्रोग्रामिंग की दुनिया में, Arrow लाइब्रेरी शक्तिशाली उपकरण प्रदान करती है जो त्रुटियों और वैकल्पिक मामलों को संभालने के लिए हैं। इन उपकरणों में, मोनैड`Either`यह अपनी दो संभावित स्थितियों को दर्शाने की क्षमता के कारण विशेष है: सफलता (Right) या विफलता (Left)। लेकिन हम इन दो स्थितियों के बीच प्रभावी रूप से नेविगेट कैसे करें? ये हम इस लेख में खोजने वाले हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_इथर_मोनैड_क्या_है&quot;&gt;इथर मोनैड क्या है ?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एकक`Either`यह दो आपस में अनन्य संभावनाओं का प्रतिनिधित्व करने वाला एक डेटा संरचना है। Kotlin में Arrow के साथ, यह अक्सर किसी ऑपरेशन की सफलता और विफलता के मामलों को प्रबंधित करने के लिए उपयोग की जाती है, पारंपरिक अपवादों का एक शानदार विकल्प प्रदान करती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_either_का_उपयोग_क्यों_करें&quot;&gt;Either का उपयोग क्यों करें?&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;स्पष्ट त्रुटि प्रबंधन : डेवलपर को असफलता के मामलों पर विचार करने के लिए बाध्य करता है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;कार्यात्मक संयोजन: असफल हो सकने वाले ऑपरेशनों की श्रृंखलाकरण को सुविधा प्रदान करता है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;प्रकार‑सुरक्षा: त्रुटियाँ प्रकारबद्ध होती हैं, जिससे उनका अधिक सटीक प्रबंधन करना संभव होता है।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pas d&amp;#8217;exceptions : Évite les effets de bord et les interruptions inattendues du flux d&amp;#8217;exécution.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_संदर्भ&quot;&gt;संदर्भ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मान लीजिए कि आप एक REST API विकसित कर रहे हैंhttps://spring.io/projects/spring-boot/[Spring Boot,विंडोज़=पढ़ें बाद में] et &lt;a href=&quot;https://kotlinlang.org/&quot;&gt;Kotlin&lt;/a&gt;, पुस्तकालय का उपयोग करकेhttps://arrow-kt.io/[तीर,विंडोज़=पढ़ें-बाद में]. आपके पास एक फ़ंक्शन है`findOneUserByEmail`जो एक लौटाता है`Either&amp;lt;Throwable, User&amp;gt;`आप इस परिणाम को शालीन और कार्यात्मक ढंग से कैसे संभाल सकते हैं?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हमारे पास एक User क्लास है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@file:Suppress(
    &quot;RemoveRedundantQualifierName&quot;,
    &quot;MemberVisibilityCanBePrivate&quot;,
    &quot;SqlNoDataSourceInspection&quot;
)

package webapp.users

import arrow.core.Either
import arrow.core.left
import arrow.core.right
import com.fasterxml.jackson.annotation.JsonIgnore
import com.fasterxml.jackson.databind.ObjectMapper
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Pattern
import jakarta.validation.constraints.Size
import org.springframework.beans.factory.getBean
import org.springframework.context.ApplicationContext
import org.springframework.data.r2dbc.core.R2dbcEntityTemplate
import org.springframework.r2dbc.core.DatabaseClient
import org.springframework.r2dbc.core.awaitOne
import org.springframework.r2dbc.core.awaitRowsUpdated
import webapp.core.property.ANONYMOUS_USER
import webapp.core.property.EMPTY_STRING
import webapp.core.utils.AppUtils.cleanField
import webapp.users.EntityModel.Companion.ID_MEMBER
import webapp.users.User.UserDao.Attributes.EMAIL_ATTR
import webapp.users.User.UserDao.Attributes.ID_ATTR
import webapp.users.User.UserDao.Attributes.LANG_KEY_ATTR
import webapp.users.User.UserDao.Attributes.LOGIN_ATTR
import webapp.users.User.UserDao.Attributes.PASSWORD_ATTR
import webapp.users.User.UserDao.Attributes.VERSION_ATTR
import webapp.users.User.UserDao.Constraints.LOGIN_REGEX
import webapp.users.User.UserDao.Fields.EMAIL_FIELD
import webapp.users.User.UserDao.Fields.ID_FIELD
import webapp.users.User.UserDao.Fields.LANG_KEY_FIELD
import webapp.users.User.UserDao.Fields.LOGIN_FIELD
import webapp.users.User.UserDao.Fields.PASSWORD_FIELD
import webapp.users.User.UserDao.Fields.VERSION_FIELD
import webapp.users.User.UserDao.Relations.INSERT
import webapp.users.security.Role
import webapp.users.security.Role.RoleDao
import webapp.users.security.UserRole.UserRoleDao
import java.util.*
import jakarta.validation.constraints.Email as EmailConstraint

data class User(
    override val id: UUID? = null,

    @field:NotNull
    @field:Pattern(regexp = LOGIN_REGEX)
    @field:Size(min = 1, max = 50)
    val login: String,

    @JsonIgnore
    @field:NotNull
    @field:Size(min = 60, max = 60)
    val password: String = EMPTY_STRING,

    @field:EmailConstraint
    @field:Size(min = 5, max = 254)
    val email: String = EMPTY_STRING,

    @JsonIgnore
    val roles: MutableSet&amp;lt;Role&amp;gt; = mutableSetOf(Role(ANONYMOUS_USER)),

    @field:Size(min = 2, max = 10)
    val langKey: String = EMPTY_STRING,

    @JsonIgnore
    val version: Long = -1,
) : EntityModel&amp;lt;UUID&amp;gt;() {

    companion object {
        @JvmStatic
        fun main(args: Array&amp;lt;String&amp;gt;) = println(UserDao.Relations.sqlScript)
    }

    object UserDao {
        object Constraints {
            // Regex for acceptable logins
            const val LOGIN_REGEX =
                &quot;^(?&amp;gt;[a-zA-Z0-9!$&amp;amp;*+=?^_`{|}~.-]+@[a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*)|(?&amp;gt;[_.@A-Za-z0-9-]+)$&quot;
            const val PASSWORD_MIN: Int = 4
            const val PASSWORD_MAX: Int = 16
            const val IMAGE_URL_DEFAULT = &quot;https://placehold.it/50x50&quot;
            const val PHONE_REGEX = &quot;^(\\+|00)?[1-9]\\d{0,49}\$&quot;
        }

        object Members {
            const val PASSWORD_MEMBER = &quot;password&quot;
            const val ROLES_MEMBER = &quot;roles&quot;
        }

        object Fields {
            const val ID_FIELD = &quot;`id`&quot;
            const val LOGIN_FIELD = &quot;`login`&quot;
            const val PASSWORD_FIELD = &quot;`password`&quot;
            const val EMAIL_FIELD = &quot;`email`&quot;
            const val LANG_KEY_FIELD = &quot;`lang_key`&quot;
            const val VERSION_FIELD = &quot;`version`&quot;
        }

        object Attributes {
            val ID_ATTR = ID_FIELD.cleanField()
            val LOGIN_ATTR = LOGIN_FIELD.cleanField()
            val PASSWORD_ATTR = PASSWORD_FIELD.cleanField()
            val EMAIL_ATTR = EMAIL_FIELD.cleanField()
            const val LANG_KEY_ATTR = &quot;langKey&quot;
            val VERSION_ATTR = VERSION_FIELD.cleanField()
        }

        object Relations {
            const val TABLE_NAME = &quot;`user`&quot;
            const val SQL_SCRIPT = &quot;&quot;&quot;
            CREATE TABLE IF NOT EXISTS $TABLE_NAME (
                $ID_FIELD                     UUID default random_uuid() PRIMARY KEY,
                $LOGIN_FIELD                  VARCHAR,
                $PASSWORD_FIELD               VARCHAR,
                $EMAIL_FIELD                  VARCHAR,
                $LANG_KEY_FIELD               VARCHAR,
                $VERSION_FIELD                bigint
            );
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_login`
            ON $TABLE_NAME ($LOGIN_FIELD);
            CREATE UNIQUE INDEX IF NOT EXISTS `uniq_idx_user_email`
            ON $TABLE_NAME ($EMAIL_FIELD);
&quot;&quot;&quot;

            @Suppress(&quot;SqlDialectInspection&quot;)
            const val INSERT = &quot;&quot;&quot;
            insert into $TABLE_NAME (
                $LOGIN_FIELD, $EMAIL_FIELD,
                $PASSWORD_FIELD, $LANG_KEY_FIELD,
                $VERSION_FIELD
            ) values ( :login, :email, :password, :langKey, :version)&quot;&quot;&quot;

            @JvmStatic
            val sqlScript: String
                get() = setOf(
                    UserDao.Relations.SQL_SCRIPT,
                    RoleDao.Relations.SQL_SCRIPT,
                    UserRoleDao.Relations.SQL_SCRIPT
                ).joinToString(&quot;&quot;)
                    .trimMargin()
        }

        object Dao {
            val Pair&amp;lt;User, ApplicationContext&amp;gt;.toJson: String
                get() = second.getBean&amp;lt;ObjectMapper&amp;gt;().writeValueAsString(first)

            suspend fun Pair&amp;lt;User, ApplicationContext&amp;gt;.save(): Either&amp;lt;Throwable, Long&amp;gt; = try {
                second.getBean&amp;lt;R2dbcEntityTemplate&amp;gt;()
                    .databaseClient
                    .sql(INSERT)
                    .bind(LOGIN_ATTR, first.login)
                    .bind(EMAIL_ATTR, first.email)
                    .bind(PASSWORD_ATTR, first.password)
                    .bind(LANG_KEY_ATTR, first.langKey)
                    .bind(VERSION_ATTR, first.version)
                    .fetch()
                    .awaitRowsUpdated()
                    .right()
            } catch (e: Throwable) {
                e.left()
            }


            suspend fun ApplicationContext.findOneUserByEmail(
                email: String
            ): Either&amp;lt;Throwable, User&amp;gt; = try {
                getBean&amp;lt;DatabaseClient&amp;gt;()
                    .sql(&quot;SELECT * FROM `user` WHERE LOWER(email) = LOWER(:email)&quot;)
                    .bind(&quot;email&quot;, email)
                    .fetch()
                    .awaitOne()
                    .let { row -&amp;gt;
                        User(
                            id = row[ID_ATTR] as UUID?,
                            login = row[LOGIN_ATTR] as String,
                            password = row[PASSWORD_ATTR] as String,
                            email = row[EMAIL_ATTR] as String,
                            langKey = row[LANG_KEY_ATTR] as String,
                            version = row[VERSION_ATTR] as Long
                        )
                    }.right()
            } catch (e: Throwable) {
                e.left()
            }
        }
    }

    /** Account REST API URIs */
    object UserRestApis {
        const val API_AUTHORITY = &quot;/api/authorities&quot;
        const val API_USERS = &quot;/api/users&quot;
        const val API_SIGNUP = &quot;/signup&quot;
        const val API_SIGNUP_PATH = &quot;$API_USERS$API_SIGNUP&quot;
        const val API_ACTIVATE = &quot;/activate&quot;
        const val API_ACTIVATE_PATH = &quot;$API_USERS$API_ACTIVATE?key=&quot;
        const val API_ACTIVATE_PARAM = &quot;{activationKey}&quot;
        const val API_ACTIVATE_KEY = &quot;key&quot;
        const val API_RESET_INIT = &quot;/reset-password/init&quot;
        const val API_RESET_FINISH = &quot;/reset-password/finish&quot;
        const val API_CHANGE = &quot;/change-password&quot;
        const val API_CHANGE_PATH = &quot;$API_USERS$API_CHANGE&quot;
    }
}

// Abstract entity model with Generic ID, which can be of any type
abstract class EntityModel&amp;lt;T&amp;gt;(
    open val id: T? = null
) {
    companion object {
        const val ID_MEMBER = &quot;id&quot;
    }
}

// Generic extension function that allows the ID to be applied to any EntityModel type
inline fun &amp;lt;reified T : EntityModel&amp;lt;ID&amp;gt;, ID&amp;gt; T.withId(id: ID): T {
    // Use reflection to create a copy with the passed ID
    return this::class.constructors.first { it.parameters.any { param -&amp;gt; param.name == ID_MEMBER } }
        .call(id, *this::class.constructors.first().parameters.drop(1).map { param -&amp;gt;
            this::class.members.first { member -&amp;gt; member.name == param.name }.call(this)
        }.toTypedArray())
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_विभिन्न_दृष्टिकोण&quot;&gt;विभिन्न दृष्टिकोण&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_पारंपरिक_पद्धति_के_साथ_when&quot;&gt;पारंपरिक पद्धति के साथ `when&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val user: User by lazy { userFactory(USER) }

val result: Either&amp;lt;Throwable, User&amp;gt; = context.findOneUserByEmail(user.email)

when (result) {
    is Either.Left -&amp;gt; {
        val error = result.value
        println(&quot;Erreur : ${error.message}&quot;)
    }
    is Either.Right -&amp;gt; {
        val user = result.value
        println(&quot;Utilisateur trouvé : ${user.login}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;हालांकि यह विधि सरल और पठनीय है, यह तीर की कार्यात्मक क्षमताओं का पूरी तरह से उपयोग नहीं करती।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fold_का_उपयोग_एक_अधिक_संक्षिप्त_दृष्टिकोण_के_लिए&quot;&gt;fold` का उपयोग एक अधिक संक्षिप्त दृष्टिकोण के लिए&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;result.fold(
{ error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) },
{ user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`fold`यह Left और Right दोनों मामलों के लिए कार्यों को परिभाषित करने की अनुमति देता है, संक्षिप्त और शालीन तरीके से।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_परिवर्तन_map_और_mapleft_के_साथ&quot;&gt;परिवर्तन &lt;code&gt;map&lt;/code&gt; और &lt;code&gt;mapLeft&lt;/code&gt; के साथ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val processedResult = result
    .map { user -&amp;gt; &quot;Utilisateur trouvé : ${user.login}&quot; }
    .mapLeft { error -&amp;gt; &quot;Erreur : ${error.message}&quot; }

println(processedResult.merge())&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह दृष्टिकोण Either में निहित मान को बदलने की अनुमति देता है जबकि उसकी संरचना को संरक्षित रखता है, जो अधिक जटिल प्रक्रिया श्रृंखलाओं के लिए आदर्श है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_त्रुटि_प्रबंधन_के_साथ_getorelse&quot;&gt;त्रुटि प्रबंधन के साथ `getOrElse&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val user = result.getOrElse { error -&amp;gt;
    println(&quot;Erreur : ${error.message}&quot;)
    User(login = &quot;default&quot;, email = &quot;default@example.com&quot;) // utilisateur par défaut
}
println(&quot;Login : ${user.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`getOrElse`यह एक शानदार त्रुटि प्रबंधन प्रदान करता है क्योंकि यह एक डिफ़ॉल्ट मान प्रदान करने की अनुमति देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_साइड_कार्रवाई_onleft_और_onright_के_साथ&quot;&gt;साइड कार्रवाई &lt;code&gt;onLeft&lt;/code&gt; और &lt;code&gt;onRight&lt;/code&gt; के साथ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;result.onLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }
.onRight { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ये तरीके किसी भी तरफ कार्रवाई करने की अनुमति देते हैं, Either को संशोधित किए बिना, लॉगिंग या हल्के दुष्प्रभाव के लिए उपयुक्त।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ऑपरेशन_चेनिंग_flatmap_के_साथ&quot;&gt;ऑपरेशन चेनिंग &lt;code&gt;flatMap&lt;/code&gt; के साथ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;fun findUser(email: String): Either&amp;lt;Throwable, User&amp;gt; = // ... implémentation

fun getUserPermissions(user: User): Either&amp;lt;Throwable, List&amp;lt;String&amp;gt;&amp;gt; = // ... implémentation

val userPermissions = findUser(&quot;user@example.com&quot;)
    .flatMap { user -&amp;gt; getUserPermissions(user) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;flatMap`यह ऐसे कार्यों को क्रम में जोड़ने के लिए उपयोगी है जो स्वयं लौटाते हैं`Either&lt;/code&gt;, इस प्रकार बचते हुए`Either`संलग्न.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_द्विदिशात्मक_परिवर्तन_के_साथ_bimap&quot;&gt;द्विदिशात्मक परिवर्तन के साथ `bimap&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val processedResult = result.bimap(
    { error -&amp;gt; &quot;Erreur: ${error.message}&quot; },
    { user -&amp;gt; &quot;Utilisateur: ${user.login}&quot; }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`bimap`बायें और दायें दोनों पक्षों को एक ही ऑपरेशन में बदलने की अनुमति देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_swap_के_साथ_किनारों_को_उलटना&quot;&gt;swap के साथ किनारों को उलटना&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result: Either&amp;lt;Throwable, User&amp;gt; = // ... obtention du résultat
val swapped = result.swap()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;swap`यह उपयोगी है जब आप एक पक्ष को उलटना चाहते हैं`Either&lt;/code&gt;, उदाहरण के लिए एक फ़ंक्शन के इंटरफ़ेस को दूसरे इंटरफ़ेस के अनुसार अनुकूलित करने के लिए.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tap_और_tapleft_का_उपयोग&quot;&gt;tap` और &lt;code&gt;tapLeft&lt;/code&gt; का उपयोग:&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;result.tap { user -&amp;gt; println(&quot;Utilisateur trouvé : ${user.login}&quot;) }
.tapLeft { error -&amp;gt; println(&quot;Erreur : ${error.message}&quot;) }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;जैसे`onLeft` et &lt;code&gt;onRight&lt;/code&gt;, लेकिन इन विधियों में मूल Either लौटाया जाता है, जो संचालन की श्रृंखला के लिए उपयोगी है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_उपयोग_recover&quot;&gt;उपयोग &lt;code&gt;recover&lt;/code&gt; :&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val recoveredUser = result.recover { error -&amp;gt;
    println(&quot;Erreur récupérée : ${error.message}&quot;)
    User(login = &quot;recovered&quot;, email = &quot;recovered@example.com&quot;)
}
println(&quot;Login : ${recoveredUser.login}&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह विधि एक प्रतिस्थापन मान प्रदान करके Either.Left को Either.Right में बदलने की अनुमति देती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्रायोगिक_उपयोग_के_मामले&quot;&gt;प्रायोगिक उपयोग के मामले&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;उपयोग करें`fold`सरल संचालन के लिए जो प्रत्येक मामले के लिए प्रसंस्करण की आवश्यकता होती है। - आप प्राथमिकता दें`map` et &lt;code&gt;mapLeft`डेटा परिवर्तनों के लिए बिना संरचना बदले de l&#39;`Either&lt;/code&gt;. चुनें`flatMap`चेनिंग के दौरान विफल हो सकने वाले संचालन के दौरान उपयोग करें`recover`त्रुटि के मामले में एक डिफ़ॉल्ट मान प्रदान करने के लिए - चुनें`onLeft` et &lt;code&gt;onRight&lt;/code&gt; (ou &lt;code&gt;tap&lt;/code&gt; et &lt;code&gt;tapLeft&lt;/code&gt;) साइड इफ़ेक्ट्स जैसे लॉगिंग के लिए. - उपयोग करें`bimap`दोनों पक्षों को एक ही ऑपरेशन में बदलने के लिए - लागू करें`swap`जब आपको किसी फ़ंक्शन के इंटरफ़ेस को दूसरे से अनुकूलित करने की आवश्यकता होती है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इनमें से प्रत्येक दृष्टिकोण के अपने फायदे होते हैं उपयोग के संदर्भ के अनुसार। तरीके जैसे`fold`, &lt;code&gt;map&lt;/code&gt;(No output)&lt;code&gt;mapLeft&lt;/code&gt;, et `recover`वे विशेष रूप से उपयोगी होते हैं जब आप कई ऑपरेशन को क्रम में रखना चाहते हैं या डेटा को कार्यात्मक रूप से बदलना चाहते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मोनैड`Either`d&amp;#8217;Arrow कोट्लिन एप्लिकेशनों में सफलता और त्रुटि के मामलों को संभालने के लिए उल्लेखनीय लचीलापन प्रदान करता है। इन विभिन्न दृष्टिकोनों को समझने पर, आप अधिक मजबूत, पढ़ने में आसान और अधिक कार्यात्मक कोड लिख पाएँगे।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अपने अगले प्रोजेक्ट में, इन तकनीकों का अन्वेषण करने में संकोच न करें ताकि आप कोटलिन और एरो के साथ कार्यात्मक प्रोग्रामिंग से अधिकतम लाभ उठा सकें !&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_और_आगे_जाने_के_लिए&quot;&gt;और आगे जाने के लिए&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;एरो की आधिकारिक दस्तावेज़:https://arrow-kt.io/docs/apidocs/arrow-core/arrow.core/-either/[तीर या] &lt;mark&gt;#&lt;/mark&gt; Gradle एकीकरण JBake को JBake Gradle प्लगिन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड में एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
}https://arrow-kt.io/docs/fx/[तीर Fx कोरूटीन]

अपने अनुभव और पसंदीदा तकनीकें साझा करना न भूलें साथ में काम करने के लिए`Either`नीचे दिए गए टिप्पणियों में !
----&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_परिचय&quot;&gt;परिचय&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कमांड_का_उपयोग_find&quot;&gt;कमांड का उपयोग `find&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_अतिरिक्त_विकल्प_के_लिए_find&quot;&gt;अतिरिक्त विकल्प के लिए `find&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कमांड_locate_का_उपयोग&quot;&gt;कमांड &lt;code&gt;locate&lt;/code&gt; का उपयोग&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_फ़ाइलों_में_टेक्स्ट_खोजने_के_लिए_grep_कमांड_का_उपयोग&quot;&gt;फ़ाइलों में टेक्स्ट खोजने के लिए &lt;code&gt;grep&lt;/code&gt; कमांड का उपयोग&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;समस्या : एक लिनक्स ऑपरेटिंग सिस्टम में टर्मिनल के माध्यम से फ़ाइलों की खोज करें।&lt;/div&gt;
&lt;p&gt;इस लेख में, हम बताएँगे कि Ubuntu में Zsh टर्मिनल का उपयोग करके फ़ाइल कैसे खोजी जाए। Zsh (Z शेल) एक शक्तिशाली और व्यापक रूप से प्रयोग किए जाने वाले कमांड इंटरप्रेटर है, जो अपनी लचीलापन और उन्नत विशेषताओं के लिए प्रसिद्ध है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu, एक लोकप्रिय लिनक्स वितरण, कमांड लाइन में कई उपकरण प्रदान करता है जिनका उपयोग फ़ाइलों को खोजने के लिए किया जाता है। हम देखेंगे कि कैसे ऐसे कमांड का उपयोग किया जाता है, जैसे कि`find`, &lt;code&gt;locate&lt;/code&gt; et `grep`टर्मिनल में फ़ाइलों को तेज़ी से और प्रभावी ढंग से खोजने के लिए&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कमांड_का_उपयोग_find&quot;&gt;कमांड का उपयोग `find&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आदेश`find`यह किसी विशिष्ट निर्देशिका और उसके उप-निर्देशिकाओं में फ़ाइलों की खोज करने की अनुमति देता है। इसका मूल वाक्य विन्यास निम्नलिखित है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find [chemin] -name [nom_du_fichier]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ एक व्यावहारिक उदाहरण है जहाँ हम एक नामित फ़ाइल की तलाश कर रहे हैं`example.txt`निर्देशिका में`/home`[Translation: The fragment to translate is empty, so the output is empty.]&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find /home -name &quot;example.txt&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह कमांड सभी उप-निर्देशिकाओं का अन्वेषण करेगी`/home`और यदि फ़ाइल मिलती है तो उसका पूर्ण पथ दिखाएँ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;कमांड का ऑनलाइन मैनुअल&lt;/strong&gt;&lt;code&gt;find&lt;/code&gt;:https://man.archlinux.org/man/find.1.fr/[man find,windows=read-later]*&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_अतिरिक्त_विकल्प_के_लिए_find&quot;&gt;अतिरिक्त विकल्प के लिए `find&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आदेश`find`यह बहुत शक्तिशाली है और कई विकल्प प्रदान करता है। यहाँ कुछ उपयोगी उदाहरण हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;फ़ाइल प्रकार द्वारा खोजें&lt;/strong&gt;: केवल फ़ाइलों की खोज करने के लिए, उपयोग करें`-type f`, और निर्देशिकाएँ, खोजने के लिए उपयोग करें`-type d`. - &lt;strong&gt;आकार द्वारा खोजें&lt;/strong&gt;आप आकार के आधार पर फ़ाइलों को फ़िल्टर भी कर सकते हैं विकल्प का उपयोग करके`-size`. Par exemple, pour rechercher des fichiers de plus de 100 Mo, utilisez :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find /home -size +100M&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कमांड_locate_का_उपयोग&quot;&gt;कमांड &lt;code&gt;locate&lt;/code&gt; का उपयोग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आदेश`locate`ज्यादा तेज़ है`find`car यह प्रणाली पर मौजूद फ़ाइलों की पूर्व-इंडेक्स की गई डेटाबेस का उपयोग करती है। आपको इस डेटाबेस को अपडेट करने के लिए पहले निम्नलिखित कमांड का उपयोग करना होगा :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo updatedb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फिर, आप इस तरह एक फ़ाइल खोज सकते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;locate example.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;मैं उपयोग कर रहा हूँhttps://fr.wikipedia.org/wiki/Z_Shell[zsh]साथhttps://github.com/ohmyzsh/ohmyzsh/wiki[oh-my-zsh], यह पता चलता है कि आदेश`locate`इसे एक्सेस नहीं किया जा सकता`zsh`लेकिन निश्चित रूप से संभव से`bash`, इस बात से निपटने के लिए, तर्क`-c`आदेश का`bash`एक कमांड चलाने की अनुमति देता है`bash`दूसरे प्रकार के टर्मिनल से।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यहाँ मैं उन फाइलों की तलाश कर रहा हूँ जो इस पैटर्न से समाप्त होती हैं`001.pdf`उपयोगकर्ता निर्देशिका में&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;bash -c &quot;locate ~/*001.pdf&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;कमांड का ऑनलाइन मैनुअल`locate`:https://man.archlinux.org/man/locate.1.fr/[आदमी स्थान निर्धारित,windows=read-later]&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_फ़ाइलों_में_टेक्स्ट_खोजने_के_लिए_grep_कमांड_का_उपयोग&quot;&gt;फ़ाइलों में टेक्स्ट खोजने के लिए &lt;code&gt;grep&lt;/code&gt; कमांड का उपयोग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यदि आप फ़ाइल के भीतर किसी विशिष्ट पाठ को खोजना चाहते हैं, तो आप उपयोग कर सकते हैं`grep`. उदाहरण के लिए, &quot;Ubuntu&quot; शब्द की घटना खोजने के लिए सभी फ़ाइलों में`.txt`वर्तमान निर्देशिका में, उपयोग करें:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;grep &quot;Ubuntu&quot; *.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ubuntu के तहत Zsh टर्मिनल के माध्यम से फ़ाइलों की खोज कई शक्तिशाली टूल्स के उपयोग से की जा सकती है।`find`लचीला है और बहुत सारे विकल्प प्रदान करता है, जबकि`locate`यह त्वरित खोज की अनुमति देता है पहले से निर्मित डेटाबेस का उपयोग करके। अंत में,`grep`फ़ाइलों के भीतर पाठ के उदाहरण खोजने की अनुमति देता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इन कमांडों से आपको फ़ाइलों की खोज को अधिक प्रभावी और आपकी आवश्यकताओं के अनुरूप बनाने के लिए टूल की पूरी श्रृंखला मिलती है, और इनमें से प्रत्येक कमांड के साथ एक मैनुअल दिखाई देता है।&lt;code&gt;man&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_कीबोर्ड&quot;&gt;कीबोर्ड :&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ctrl_कुंजी&quot;&gt;&lt;em&gt;&amp;lt;Ctrl&amp;gt; कुंजी&lt;/em&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_अनुमतिप्राधिकरण&quot;&gt;अनुमति(प्राधिकरण)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_फाइल_खोज&quot;&gt;फाइल खोज&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कीबोर्ड&quot;&gt;कीबोर्ड :&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ctrl_कुंजी&quot;&gt;&lt;em&gt;&amp;lt;Ctrl&amp;gt; कुंजी&lt;/em&gt;&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://korben.info/les-raccourcis-clavier-pour-bash-terminal-linux-et-macos.html&quot;&gt;लिंक&lt;/a&gt;&lt;br&gt;
&lt;a href=&quot;https://blogmotion.fr/systeme/astuces-bash-linux-16175&quot;&gt;अन्य लिंक&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_अनुमतिप्राधिकरण&quot;&gt;अनुमति(प्राधिकरण)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CHMOD का उपयोग फ़ाइल की अनुमतियाँ बदलने के लिए किया जाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अनुमति      आदेश&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U   G   W rwx rwx rwx     chmod 777 फ़ाइल नाम rwx rwx r-x     chmod 775 filename rwx r-x r-x     chmod 755 फ़ाइल का नाम rw- rw- r--     chmod 664 filename rw- r-- r--     chmod 644 फ़ाइल नाम&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;U = उपयोगकर्ता G = समूह W = दुनिया&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;r = पढ़ने योग्य w = लेखन योग्य x = निष्पादन योग्य - = अनुमति नहीं&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अनुमतियों को देखने का एक और तरीका:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;400     मालिक द्वारा पढ़ा गया 040     समूह द्वारा पढ़ा गया 004     कोई भी द्वारा पढ़ा गया (अन्य) 200 मालिक द्वारा लिखा गया 020     समूह द्वारा लिखें 002     write by anybody 100     मालिक द्वारा निष्पादित 010     समूह द्वारा निष्पादित किसी भी द्वारा निष्पादित&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक संयोजन प्राप्त करने के लिए, बस उन्हें जोड़ दें।&lt;br&gt;
उदाहरण के लिए, इसे पढ़ा, लिखा, निष्पादित करने के लिए स्वामी द्वारा,&lt;br&gt;
पढ़ा, निष्पादित, समूह द्वारा और कोई भी द्वारा निष्पादित,&lt;br&gt;
आप 400+200+100+040+010+001 जोड़ेंगे जिससे 751 प्राप्त होगा।&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_फाइल_खोज&quot;&gt;&lt;a href=&quot;/blog/2024/0074_seach_file_linux_post.html&quot;&gt;फाइल खोज&lt;/a&gt;&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;पढ़ने का समय : 10 सेकंड&lt;/em&gt;&lt;/div&gt;
&lt;p&gt;समस्या : Ubuntu सबसिस्टम का होस्ट Windows होने पर पोर्ट 8820 को कैसे उजागर करें? Ubuntu को कमांड से बूट किया जाता है`wsl --install`.&lt;/p&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;पढ़ने का समय : 3 मिनट&lt;/em&gt; Pandoc एक सार्वभौमिक दस्तावेज़ कंवर्टर&lt;/div&gt;
&lt;p&gt;Pandoc एक ओपन सोर्स टेक्स्ट प्रोसेसिंग सॉफ़्टवेयर है जो विभिन्न प्रारूपों के बीच दस्तावेज़ों को बदलने के लिए प्रयोग किया जा सकता है। पैंडोक को स्थापित करने के कई तरीके हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_डाउनलोड_पेज_से_इंस्टॉलेशन&quot;&gt;डाउनलोड पेज से इंस्टॉलेशन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pandoc को डाउनलोड पेज से इंस्टॉल करने के लिए, निम्नलिखित चरणों का पालन करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;पंडॉक डाउनलोड पेज पर जाएँ:https://pandoc.org/installing.html/[&lt;a href=&quot;https://pandoc.org/installing.html&quot; class=&quot;bare&quot;&gt;https://pandoc.org/installing.html&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;अपने ऑपरेटिंग सिस्टम के लिए पैकेज इंस्टॉलर डाउनलोड करें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pandoc स्थापित करने के लिए इंस्टॉलर चलाएँ।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ज़िप फ़ाइल से इंस्टॉलेशन&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक zip फ़ाइल से Pandoc स्थापित करने के लिए, निम्नलिखित चरणों का पालन करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;पांडॉक बाइनरीज़ और दस्तावेज़ रखने वाली ज़िप फ़ाइल डाउनलोड करें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ज़िप फ़ाइल को निकालें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;बाइनरी को अपनी पसंद की निर्देशिका में ले जाएँ।&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Chocolatey की मदद से स्थापना&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पंडॉक को Chocolatey के माध्यम से स्थापित करने के लिए, निम्नलिखित चरणों का पालन करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;कमांड प्रॉम्प्ट खोलें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;आगामी कमांड को निष्पादित करें :&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-powershell hljs&quot; data-lang=&quot;powershell&quot;&gt;choco install pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;winget का उपयोग करके स्थापना&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;winget का उपयोग करके Pandoc स्थापित करने के लिए, इन चरणों का पालन करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;एक कमांड प्रॉम्प्ट खोलें।&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;निम्नलिखित कमांड को निष्पादित करें :&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-powershell hljs&quot; data-lang=&quot;powershell&quot;&gt;winget install --source winget --exact --id JohnMacFarlane.Pandoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;सिफ़ारिशें&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;डिफ़ॉल्ट रूप से, Pandoc LaTeX का उपयोग करके PDF फ़ाइलें बनाता है। LaTeX को MiKTeX के माध्यम से स्थापित करने की सिफारिश की जाती है। विकल्प के साथ`--pdf-engine`हालांकि आप इस कार्य के लिए अन्य कार्यक्रम भी निर्दिष्ट कर सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;चेतावनी&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कई इंस्टॉलेशन विधियों का उपयोग करने से Pandoc की दो अलग-अलग इंस्टॉलेशन हो सकती हैं। अनुशंसा की जाती है कि वैकल्पिक इंस्टॉलेशन विधि में बदलने से पहले Pandoc को सही तरीके से अनइंस्टॉल कर दिया जाए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;WSL के माध्यम से Linux पर स्थापना&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पैकेज प्रबंधक में pandoc के संस्करण की जाँच करें कि क्या यह पुराना नहीं है। Pandoc Debian, Ubuntu, Slackware, Arch, Fedora, NixOS, openSUSE, gentoo और Void के रिपॉजिटरी में उपलब्ध है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;नवीनतम संस्करण प्राप्त करने के लिए, हम amd64 आर्किटेक्चर के लिए बाइनरी पैकेज डाउनलोड पृष्ठ पर प्रदान करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;निष्पादन योग्य फ़ाइल स्थैतिक रूप से लिंक की गई है और इसमें कोई गतिशील निर्भरता नहीं है, साथ ही कोई बाहरी डेटा फ़ाइलों पर निर्भरता भी नहीं है। नोट: स्थैतिक लिंकिंग के कारण, इस पैकेज का pandoc बाइनरी ऐसे lua फ़िल्टर का उपयोग नहीं कर सकता है जिनमें C में लिखे गए बाहरी lua मॉड्यूल की आवश्यकता होती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;एक tarball और एक deb इंस्टॉलर प्रदान किया जाता है। deb को स्थापित करने के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i $DEB&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लेखन के समय उदाहरण :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://github.com/jgm/pandoc/releases/download/3.1.11.1/pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo dpkg -i pandoc-3.1.11.1-1-amd64.deb&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$DEB`यह डाउनलोड किए गए deb तक जाने का पथ है। यह एक्सीक्यूटेबल इंस्टॉल करेगा`pandoc`और मैनुअल पृष्ठ&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यदि आप RPM-आधारित वितरण का उपयोग कर रहे हैं, तो आप संभवतः हमारे डाउनलोड पृष्ठ से .deb को एलीन का उपयोग करके स्थापित कर सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कोई भी वितरण पर, आप tarball से इंस्टॉल कर सकते हैं`$DEST`(उदाहरण के लिए,&lt;code&gt;/usr/local/&lt;/code&gt; ou &lt;code&gt;$HOME/.local&lt;/code&gt;) करते हुए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar xvzf $TGZ --strip-components 1 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;où `$TGZ`यह डाउनलोड किए गए ज़िप्ड टारबॉल का पथ है। पांडोक के 2.0 से पहले के संस्करणों के लिए, जो टारबॉल प्रदान नहीं करते हैं, इसके बजाय प्रयास करें :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;ar p $DEB data.tar.gz | tar xvz --strip-components 2 -C $DEST&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;आप स्रोत से भी इंस्टॉल कर सकते हैं, नीचे दिए गए निर्देशों का उपयोग करके`Compilation à partir de la source`. ध्यान दें कि अधिकांश वितरणों में उनके पैकेज रिपॉज़िटरी में हास्केल प्लेटफ़ॉर्म उपलब्ध है। उदाहरण के लिए, Debian/Ubuntu पर, आप इसे स्थापित कर सकते हैं&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;apt-get install haskell-platform&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;डिफ़ॉल्ट रूप से, Pandoc LaTeX का उपयोग करके PDFs बनाता है। हम आपको अपने पैकेज मैनेजर के माध्यम से TeX Live स्थापित करने की सिफारिश करते हैं। (डेबियन/उबंटू पर,&lt;code&gt;apt-get install texlive&lt;/code&gt;). विकल्प के साथ`--pdf-engine`, आप हालांकि इस कार्य के लिए अन्य प्रोग्राम निर्दिष्ट कर सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;पढ़ने का समय: 2 मिनट&lt;/em&gt; JavaScript, TypeScript और Python में kotlin.Triple क्लास का पूर्ण कार्यान्वयन कार्यात्मक प्रोग्रामिंग का उपयोग करके बनाएं।&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;नोट :&lt;/strong&gt;प्रकार`Maybe`, &lt;code&gt;Either&lt;/code&gt;, `Result`वे जावास्क्रिप्ट या टाइपस्क्रिप्ट के मूल भाषा के हिस्सा नहीं हैं, इसलिए हमें उन्हें खुद लागू करना होगा।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_जावास्क्रिप्ट&quot;&gt;जावास्क्रिप्ट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;//javascript
// Maybe type
const Maybe = (value) =&amp;gt; ({
  map: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? Maybe(fn(value)) : Maybe(null)),
  flatMap: (fn) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? fn(value) : Maybe(null)),
  getOrElse: (defaultValue) =&amp;gt; (value !== null &amp;amp;&amp;amp; value !== undefined ? value : defaultValue),
});

// Either type
const Either = {
  Left: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Left(value),
    flatMap: (fn) =&amp;gt; Either.Left(value),
    getOrElse: (defaultValue) =&amp;gt; defaultValue,
    isLeft: true,
    isRight: false,
  }),
  Right: (value) =&amp;gt; ({
    map: (fn) =&amp;gt; Either.Right(fn(value)),
    flatMap: (fn) =&amp;gt; fn(value),
    getOrElse: (defaultValue) =&amp;gt; value,
    isLeft: false,
    isRight: true,
  }),
};

// Triple class
class Triple {
  constructor(a, b, c) {
    this.a = a;
    this.b = b;
    this.c = c;
  }

  map(fn) {
    return new Triple(fn(this.a), fn(this.b), fn(this.c));
  }

  static of(a, b, c) {
    return new Triple(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other) {
    return Maybe(this.b)
      .flatMap((numerator) =&amp;gt;
        Maybe(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0
              ? Either.Right(numerator / denominator)
              : Either.Left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(Either.Left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_typescript&quot;&gt;TypeScript&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-typescript hljs&quot; data-lang=&quot;typescript&quot;&gt;//Typescript
// Maybe type
// noinspection JSAnnotator

type Maybe&amp;lt;T&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Maybe&amp;lt;U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;): Maybe&amp;lt;U&amp;gt;;
  getOrElse(defaultValue: T): T;
};

const just = &amp;lt;T&amp;gt;(value: T): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U) =&amp;gt; just(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: T) =&amp;gt; value,
});

const nothing = &amp;lt;T&amp;gt;(): Maybe&amp;lt;T&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; U) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  flatMap: &amp;lt;U&amp;gt;(_: (value: T) =&amp;gt; Maybe&amp;lt;U&amp;gt;) =&amp;gt; nothing&amp;lt;U&amp;gt;(),
  getOrElse: (defaultValue: T) =&amp;gt; defaultValue,
});

// Either type
type Either&amp;lt;L, R&amp;gt; = {
  map&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U): Either&amp;lt;L, U&amp;gt;;
  flatMap&amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;): Either&amp;lt;L, U&amp;gt;;
  getOrElse(defaultValue: R): R;
  isLeft: boolean;
  isRight: boolean;
};

const left = &amp;lt;L, R&amp;gt;(value: L): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; U) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  flatMap: &amp;lt;U&amp;gt;(_: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; left&amp;lt;L, U&amp;gt;(value),
  getOrElse: (defaultValue: R) =&amp;gt; defaultValue,
  isLeft: true,
  isRight: false,
});

const right = &amp;lt;L, R&amp;gt;(value: R): Either&amp;lt;L, R&amp;gt; =&amp;gt; ({
  map: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; U) =&amp;gt; right&amp;lt;L, U&amp;gt;(fn(value)),
  flatMap: &amp;lt;U&amp;gt;(fn: (value: R) =&amp;gt; Either&amp;lt;L, U&amp;gt;) =&amp;gt; fn(value),
  getOrElse: (_: R) =&amp;gt; value,
  isLeft: false,
  isRight: true,
});

// Triple class
class Triple&amp;lt;T&amp;gt; {
  constructor(public a: T, public b: T, public c: T) {}

  map&amp;lt;U&amp;gt;(fn: (value: T) =&amp;gt; U): Triple&amp;lt;U&amp;gt; {
    return new Triple&amp;lt;U&amp;gt;(fn(this.a), fn(this.b), fn(this.c));
  }

  static of&amp;lt;T&amp;gt;(a: T, b: T, c: T): Triple&amp;lt;T&amp;gt; {
    return new Triple&amp;lt;T&amp;gt;(a, b, c);
  }

  // Example method using Maybe and Either
  divideBy(other: T): Either&amp;lt;string, number&amp;gt; {
    return just(this.b)
      .flatMap((numerator) =&amp;gt;
        just(other)
          .flatMap((denominator) =&amp;gt;
            denominator !== 0 ? right(numerator / denominator) : left(&#39;Division by zero&#39;)
          )
      )
      .getOrElse(left(&#39;Invalid input&#39;));
  }
}

// Example usage
const triple = Triple.of(1, 2, 3);
const result = triple.map((x) =&amp;gt; x * 2);
console.log(result); // Triple { a: 2, b: 4, c: 6 }

const divisionResult = triple.divideBy(2);
console.log(divisionResult); // Either.Right { value: 1 }

const invalidDivisionResult = triple.divideBy(0);
console.log(invalidDivisionResult); // Either.Left { value: &#39;Division by zero&#39; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_python_pydantic_pymonad&quot;&gt;Python, pydantic, pymonad&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Python में एक कार्यान्वयन बनाने के लिए उपयोग करके`pydantic`प्रकारों की पुष्टि के लिए और`pymonad`मोनाड्स के लिए :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;निर्भरताएँ स्थापित करें :&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;pip install pydantic pymonad&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-python hljs&quot; data-lang=&quot;python&quot;&gt;from pymonad.either import Either, Left, Right
from pydantic import BaseModel, ValidationError, validator

# Définition de la classe Triple avec Pydantic
class Triple(BaseModel):
    a: int
    b: int
    c: int

    @validator(&#39;b&#39;)
    def validate_b(cls, b, values):
        if b == 0:
            raise ValueError(&#39;Division by zero is not allowed&#39;)
        return b

    # Méthode utilisant Either pour la gestion des erreurs
    def divide_by(self, other):
        def division(numerator, denominator):
            return Right(numerator / denominator)

        def handle_error(error):
            return Left(str(error))

        return Either(lambda: division(self.b, other)).or_else(handle_error)

# Exemple d&#39;utilisation
try:
    triple = Triple(a=1, b=2, c=3)
    result = triple.divide_by(2)

    if result.is_right:
        print(f&#39;Division result: {result.value}&#39;)
    else:
        print(f&#39;Error: {result.value}&#39;)

except ValidationError as e:
    print(f&#39;Validation Error: {e}&#39;)
except Exception as e:
    print(f&#39;An unexpected error occurred: {e}&#39;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;इस उदाहरण में :&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;pydantic`क्लास को परिभाषित करने के लिए`Triple`टाइप्ड फ़ील्ड के साथ. विधि`divide_by`मोनाड का उपयोग करता है`Either&lt;/code&gt; de `pymonad`शून्य से विभाजन के परिणामस्वरूप होने वाली संभावित त्रुटियों को संभालने के लिए - व्यक्तिगत सत्यापन यह सुनिश्चित करने के लिए कि मान का`b`यह शून्य के बराबर नहीं है। यदि यह शून्य के बराबर है, तो एक अपवाद उठाया जाता है, और`pymonad`इसे परिणाम लौटाने के लिए इस अपवाद को पकड़ें`Left`त्रुटि दर्शाते हुए.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_विषय_सूची&quot;&gt;विषय-सूची&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;पढ़ने का समय : 30 मिनट&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#परिचय&quot;&gt;[परिचय]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Google Apps Script में बुनियादी संरचना&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#गूगल एप्स स्क्रिप्ट में प्रकार और चर&quot;&gt;[गूगल एप्स स्क्रिप्ट में प्रकार और चर]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#स्थिरांक&quot;&gt;चर, और Google Apps Script में अक्षर&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Google Apps Script में संचालन और ऑपरेटर&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Var, Let और Const Google Apps Script में&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Google Apps Script में नियंत्रण संरचनाएँ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_google_apps_script_में_लूप&quot;&gt;Google Apps Script में लूप&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#गूगल ऐप्स स्क्रिप्ट में वस्तुएँ&quot;&gt;[गूगल ऐप्स स्क्रिप्ट में वस्तुएँ]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#फ़ंक्शन Google Apps Script में&quot;&gt;[फ़ंक्शन Google Apps Script में]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#पैरामीटर और स्कोप में Google Apps Script&quot;&gt;[पैरामीटर और स्कोप में Google Apps Script]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script में रेस्ट और स्प्रेड ऑपरेटर&quot;&gt;[Google Apps Script में रेस्ट और स्प्रेड ऑपरेटर]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script में विघटन द्वारा आवंटन&quot;&gt;[Google Apps Script में विघटन द्वारा आवंटन]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#कलेक्शन और घोषणात्मक प्रोग्रामिंग Google Apps Script में&quot;&gt;[कलेक्शन और घोषणात्मक प्रोग्रामिंग Google Apps Script में]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परिचय&quot;&gt;परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script (GAS) Google सेवाओं जैसे Google Sheets, Google Docs और Google Forms से जुड़ी एक स्क्रिप्ट विकास प्लेटफ़ॉर्म है। यह कार्यों को स्वचालित करने, कस्टम फ़ंक्शन जोड़ने और Google सेवाओं को एकीकृत करने की अनुमति देती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस ज्ञापन में, हम ठोस उदाहरणों के आधार पर Google Apps Script के मुख्य अवधारणाओं का पता लगाएंगे। हम चर, लूप, फ़ंक्शन जैसी अवधारणाओं के साथ-साथ अन्य कई चीज़ों को GAS के विशिष्ट संदर्भ में अनुकूलित करके देखेंगे।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_मूल_संरचना&quot;&gt;Google Apps Script में मूल संरचना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;शुरू करने से पहले, आइए Google Apps स्क्रिप्ट की मूल संरचना की जाँच करें।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Structure de base en Google Apps Script
 */
function exempleStructureGAS() {
    // Votre code ici
    Logger.log(&quot;Hello, Google Apps Script!&quot;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्रकार_और_चर_google_apps_script_में&quot;&gt;प्रकार और चर Google Apps Script में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script को प्रोग्रामिंग भाषा के रूप में JavaScript का उपयोग करता है। डेटा प्रकार और चर मानक JavaScript की तरह काम करते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Types et Variables en Google Apps Script
 */
function exempleTypesVariablesGAS() {
    // Votre code ici
    var nombre = 42;
    var texte = &quot;Bonjour, Google Apps Script!&quot;;
    Logger.log(nombre);
    Logger.log(texte);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_गूगल_ऐप्स_स्क्रिप्ट_में_संचालन_और_संचालक&quot;&gt;गूगल ऐप्स स्क्रिप्ट में संचालन और संचालक&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script में ऑपरेशन और ऑपरेटर JavaScript के समान होते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérations et Opérateurs en Google Apps Script
 */
function exempleOperationsGAS() {
    // Votre code ici
    var x = 10;
    var y = 5;
    var resultat = x + y;
    Logger.log(resultat);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_var_let_और_const_google_apps_script_में&quot;&gt;Var, Let और Const Google Apps Script में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GAS में, अवधारणाओं का`var`, &lt;code&gt;let&lt;/code&gt;, et `const`इन्हें चर को घोषित करने के लिए उपयोग किया जाता है। हालाँकि, उनके अंतर और उनके निहितार्थ को समझना आवश्यक है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Var, Let et Const en Google Apps Script
 */
function exempleVarLetConstGAS() {
    // Votre code ici
    // Utilisation de var
    var x = 10;
    if (true) {
        var x = 20; // La variable x est modifiée globalement
    }
    Logger.log(x);

    // Utilisation de let
    let y = 30;
    if (true) {
        let y = 40; // La variable y est limitée au bloc if
    }
    Logger.log(y);

    // Utilisation de const
    const z = 50;
    // z = 60; // Impossible de réassigner une constante
    Logger.log(z);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_नियंत्रण_संरचनाएँ_google_apps_script_में&quot;&gt;नियंत्रण संरचनाएँ Google Apps Script में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;नियंत्रण संरचनाएँ जैसे`if`, &lt;code&gt;else&lt;/code&gt;, &lt;code&gt;while&lt;/code&gt; et `for`इन्हें Google Apps Script में निष्पादन प्रवाह को प्रबंधित करने के लिए प्रयोग किया जाता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Structures de Contrôle en Google Apps Script
 */
function exempleStructuresControleGAS() {
    // Votre code ici
    var condition = true;

    if (condition) {
        Logger.log(&quot;La condition est vraie.&quot;);
    } else {
        Logger.log(&quot;La condition est fausse.&quot;);
    }

    var compteur = 0;
    while (compteur &amp;lt; 5) {
        Logger.log(compteur);
        compteur++;
    }

    for (var i = 0; i &amp;lt; 3; i++) {
        Logger.log(i);
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पैरामीटर_और_स्कोप्स_google_apps_script_में&quot;&gt;पैरामीटर और स्कोप्स Google Apps Script में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;पैरामीटर और स्कोप GAS में स्क्रिप्ट विकास में एक महत्वपूर्ण भूमिका निभाते हैं। समझें कि वे कैसे काम करते हैं ताकि अप्रत्याशित व्यवहार से बचा जा सके।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Paramètres et Scopes en Google Apps Script
 */
function exempleParametresScopesGAS(parametre) {
    // Votre code ici
    var variableGlobale = &quot;Je suis global&quot;;

    function afficherParametre() {
        Logger.log(parametre);
    }

    afficherParametre();
    Logger.log(variableGlobale);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_स्थिरांक_चर_और_अक्षर&quot;&gt;Google Apps Script में स्थिरांक, चर, और अक्षर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अंतर को समझना`const`, &lt;code&gt;var&lt;/code&gt;, et `let`यह Google Apps Script में चर के प्रभावी उपयोग के लिए आवश्यक है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Constantes, Variables, et Lettres en Google Apps Script
 */
function exempleConstantesVariablesLettresGAS() {
    // Votre code ici
    const constante = &quot;Je ne change pas&quot;;
    Logger.log(constante);

    var variable = &quot;Je peux changer&quot;;
    Logger.log(variable);

    let lettre = &quot;Je peux aussi changer, mais seulement dans mon bloc&quot;;
    Logger.log(lettre);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_लूप&quot;&gt;Google Apps Script में लूप&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;लूप, जैसे`for` et &lt;code&gt;while&lt;/code&gt;, तत्वों पर इटरेट करने और दोहराव वाले संचालन करने के लिए आवश्यक हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Boucles en Google Apps Script
 */
function exempleBouclesGAS() {
    // Votre code ici
    for (var i = 0; i &amp;lt; 3; i++) {
        Logger.log(i);
    }

    var condition = true;
    var compteur = 0;

    while (condition) {
        Logger.log(&quot;Tour de boucle&quot;);
        compteur++;
        if (compteur === 3) {
            condition = false;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_गूगल_एप्स_स्क्रिप्ट_में_वस्तुएँ&quot;&gt;गूगल एप्स स्क्रिप्ट में वस्तुएँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;वस्तुओं का उपयोग डेटा को संरचित करने के लिए किया जाता है। GAS में, कई अंतर्निहित वस्तुएं Google सेवाओं के साथ इंटरैक्शन को सुगम बनाती हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Objets en Google Apps Script
 */
function exempleObjetsGAS() {
    // Votre code ici
    var feuille = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
    var cellule = feuille.getRange(&quot;A1&quot;);
    cellule.setValue(&quot;Nouvelle valeur&quot;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_स्थिरांक_चर_और_अक्षर_2&quot;&gt;Google Apps Script में स्थिरांक, चर और अक्षर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अंतर को समझना`const`, &lt;code&gt;var&lt;/code&gt;, et `let`यह आवश्यक है Google Apps Script में चरों के प्रभावी उपयोग के लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Constantes, Variables, et Lettres en Google Apps Script
 */
function exempleConstantesVariablesLettresGAS() {
    // Votre code ici
    const constante = &quot;Je ne change pas&quot;;
    Logger.log(constante);

    var variable = &quot;Je peux changer&quot;;
    Logger.log(variable);

    let lettre = &quot;Je peux aussi changer, mais seulement dans mon bloc&quot;;
    Logger.log(lettre);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_फ़ंक्शन&quot;&gt;Google Apps Script में फ़ंक्शन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;फ़ंक्शन प्रोग्रामिंग में मूलभूत तत्व होते हैं। GAS में, उन्हें विभिन्न तरीकों से घोषित और कॉल किया जा सकता है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Fonctions en Google Apps Script
 */
function exempleFonctionsGAS() {
    // Votre code ici
    function additionner(a, b) {
        return a + b;
    }

    var resultat = additionner(2, 3);
    Logger.log(resultat);

    // Fonction anonyme
    var multiplier = function (x, y) {
        return x * y;
    };

    Logger.log(multiplier(4, 5));
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_गूगल_एप्स_स्क्रिप्ट_में_आराम_और_प्रसार_ऑपरेटर&quot;&gt;गूगल एप्स स्क्रिप्ट में आराम और प्रसार ऑपरेटर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;विराम संचालक (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) और प्रसार की (&lt;code&gt;&amp;#8230;&amp;#8203;&lt;/code&gt;) ये एरे (या सरणी) और ऑब्जेक्ट को संक्षिप्त रूप से नियंत्रित करने में उपयोगी हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérateurs de Repos et de Propagation en Google Apps Script
 */
function exempleOperateursReposPropagationGAS() {
    // Votre code ici
    // Opérateur de repos (...) pour les tableaux
    var nombres = [1, 2, 3, 4, 5];
    var [...copieNombres] = nombres;
    Logger.log(copieNombres);

    // Opérateur de propagation (...) pour les objets
    var objOriginal = { x: 1, y: 2 };
    var objClone = { ...objOriginal, z: 3 };
    Logger.log(objClone);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_google_apps_script_में_विघटन_द्वारा_असाइनमेंट&quot;&gt;Google Apps Script में विघटन द्वारा असाइनमेंट&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;विनियोजन द्वारा विघटन एक शक्तिशाली विशेषता है जो वस्तुओं और ऐरे से मान को संक्षिप्त रूप में निकालने की अनुमति देती है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Affectation par Décomposition en Google Apps Script
 */
function exempleAffectationDecompositionGAS() {
    // Votre code ici
    var coordonnees = [3, 4];
    var [x, y] = coordonnees;
    Logger.log(x);
    Logger.log(y);

    var utilisateur = { nom: &quot;John&quot;, age: 30 };
    var { nom, age } = utilisateur;
    Logger.log(nom);
    Logger.log(age);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_collections_et_programmation_déclarative_en_google_apps_script&quot;&gt;Collections et Programmation Déclarative en Google Apps Script&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Google Apps Script डेटा संरचनाओं जैसे कि एरे का समर्थन करता है, और कार्यात्मक प्रोग्रामिंग तथा घोषित इटरेशन की अवधारणाओं (&amp;gt;&amp;lt;आदेशात्मक) जैसे कि`map`, &lt;code&gt;reduce&lt;/code&gt; et &lt;code&gt;forEach&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Collections et Programmation Déclarative en Google Apps Script
 */
function exempleCollectionsFonctionnelleGAS() {
    // Votre code ici
    // Exemple de tableau (collection)
    var nombres = [1, 2, 3, 4, 5];

    // Utilisation de forEach
    nombres.forEach(function (nombre) {
        Logger.log(nombre);
    });

    // Utilisation de map
    var carresNombres = nombres.map(function (nombre) {
        return nombre * nombre;
    });
    Logger.log(carresNombres);

    // Utilisation de reduce
    var somme = nombres.reduce(function (acc, nombre) {
        return acc + nombre;
    }, 0);
    Logger.log(somme);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_निष्कर्ष&quot;&gt;निष्कर्ष&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस मेमो ने Google Apps Script के मूलभूत अवधारणाओं को ठोस कोड उदाहरणों के माध्यम से समझाते हुए कवर किया। आप इस ज्ञान का उपयोग करके अपने दैनिक कार्यों को स्वचालित कर सकते हैं, अपने दस्तावेज़ों को वैयक्तिकृत कर सकते हैं और Google Apps Script की सभी सुविधाओं का पूर्ण उपयोग कर सकते हैं।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अवधि: 30 मिनट&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_उद्देश्य&quot;&gt;उद्देश्य&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Forms में Google Apps Script के मूल सिद्धांत समझें - स्क्रिप्ट एडिटर तक पहुँचना सीखें और ट्रिगर पर एक निर्देश निष्पादित करें&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_समय_खींचना&quot;&gt;समय खींचना&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;गूगल फ़ॉर्म स्क्रिप्ट का परिचय&lt;/strong&gt;(5 मिनट)&lt;/p&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Google Form Script का त्वरित अवलोकन - मुख्य विशेषताओं की प्रस्तुति&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;एक Google फ़ॉर्म और एक संबंधित स्क्रिप्ट का निर्माण&lt;/strong&gt;(5 मिनट)&lt;/p&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;गूगल फ़ॉर्म्स के साथ एक सरल फ़ॉर्म बनाना - संलग्न स्क्रिप्ट संपादक का परिचय&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;निर्देश निष्पादित करें&lt;/strong&gt;(10 मिनट)&lt;/p&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ऑन स्टार्ट ट्रिगर की कॉन्फ़िगरेशन &quot;on start - ट्रिगर की कॉन्फ़िगरेशन \&quot;on submit\ एक निर्देश चलाने के लिए एक स्क्रिप्ट लिखना - त्वरित परीक्षण जर्नल में सही काम करने की जाँच करने के लिए&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;परिणामों का विश्लेषण और सर्वोत्तम प्रथाएँ&lt;/strong&gt;(10 मिनट)&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;निर्देश के निष्पादन के परिणामों की पुष्टि - स्क्रिप्ट के एक उदाहरण पर चर्चा और कैसे स्वचालन समय बचा सकता है&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पूर्वशर्त&quot;&gt;पूर्वशर्त&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;एक Google खाता और Google Forms और Google Sheets तक पहुँच होना&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सामग्री&quot;&gt;सामग्री&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;कंप्यूटर के साथ एक वेब ब्राउज़र और एक इंटरनेट कनेक्शन&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_टिप्पणी&quot;&gt;टिप्पणी&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह एक्सप्रेस प्रशिक्षण Google Form Script के साथ स्वचालन का त्वरित परिचय देता है। एक गहरी समझ के लिए, लंबी अवधि के प्रशिक्षण की सिफ़ारिश की जाती है।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_google_form_स्क्रिप्ट_का_परिचय&quot;&gt;1 - Google Form स्क्रिप्ट का परिचय&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_slide_1_google_form_script_का_त्वरित_अवलोकन&quot;&gt;Slide 1: Google Form Script का त्वरित अवलोकन&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Google Form Script एक Google Forms में एम्बेडेड स्क्रिप्टिंग प्लेटफ़ॉर्म है। - यह कस्टम फ़ीचर जोड़ने और कार्यों को स्वचालित करने की अनुमति देता है।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_स्लाइड_2_मुख्य_सुविधाओं_का_परिचय&quot;&gt;स्लाइड 2: मुख्य सुविधाओं का परिचय&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Script Editor : इंटीग्रेटेड स्क्रिप्ट एडिटर Google Apps Script स्क्रिप्ट लिखने के लिए - ट्रिगर : &#39;on submit&#39; जैसी घटनाएँ जो स्क्रिप्ट के निष्पादन को सक्रिय करती हैं।&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_slide_3_google_फ़ॉर्म_स्क्रिप्ट_के_उपयोग_के_लाभ&quot;&gt;Slide 3: Google फ़ॉर्म स्क्रिप्ट के उपयोग के लाभ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;कस्टमाइज़ेशन: अद्वितीय सुविधाओं के साथ कस्टम फ़ॉर्म बनाएँ। - ऑटोमेशन: फ़ॉर्म प्रतिक्रियाओं के जवाब में कार्यों को स्वचालित करें. - इंटीग्रेशन : अन्य Google सेवाओं के साथ स्क्रिप्ट को एकीकृत करें एक समृद्ध अनुभव के लिए।&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_प्रस्तुतकर्ता_के_लिए_नोट&quot;&gt;प्रस्तुतकर्ता के लिए नोट:&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ये सुविधाएँ फ़ॉर्म को अनुकूलित और स्वचालित करने के लिए बहुत अधिक क्षमता प्रदान करती हैं। इस प्रशिक्षण के अगले भाग में स्क्रिप्ट और विशिष्ट ऑटोमेशन के निर्माण का विस्तृत अन्वेषण किया जाएगा।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://developers.google.com/apps-script/add-ons/editors/forms?hl=fr&quot; class=&quot;bare&quot;&gt;https://developers.google.com/apps-script/add-ons/editors/forms?hl=fr&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://developers.google.com/apps-script/reference/forms?hl=fr&quot; class=&quot;bare&quot;&gt;https://developers.google.com/apps-script/reference/forms?hl=fr&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://developers.google.com/apps-script/reference/forms/form-app?hl=fr&quot; class=&quot;bare&quot;&gt;https://developers.google.com/apps-script/reference/forms/form-app?hl=fr&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_गूगल_फ़ॉर्म_और_संबंधित_स्क्रिप्ट_बनाना_5_मिनट&quot;&gt;गूगल फ़ॉर्म और संबंधित स्क्रिप्ट बनाना (5 मिनट)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;

&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_विंडोज़_पर_पायथन_इंस्टॉल_करें&quot;&gt;विंडोज़ पर पायथन इंस्टॉल करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://ninite.com/pythonx3/&quot;&gt;विंडोज़ पर पायथन&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://python-docs.readthedocs.io/en/latest/starting/install3/win.html&quot; class=&quot;bare&quot;&gt;https://python-docs.readthedocs.io/en/latest/starting/install3/win.html&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://python-docs.readthedocs.io/en/latest/dev/virtualenvs.html#virtualenvironments-ref&quot; class=&quot;bare&quot;&gt;https://python-docs.readthedocs.io/en/latest/dev/virtualenvs.html#virtualenvironments-ref&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_पायथन_चल_रहा_है&quot;&gt;पायथन चल रहा है&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;संदर्भ :&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd mon_projet

python -m venv mon_venv

source mon_venv/bin/activate

# Sur windows
mon_venv\Scripts\activate

deactivate&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_इंस्टॉल_आवश्यकता&quot;&gt;इंस्टॉल आवश्यकता&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;pip install -r requirements.txt&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_प्रारंभ&quot;&gt;प्रारंभ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://python.doctor/page-apprendre-programmation-orientee-objet-poo-classes-python-cours-debutants&quot;&gt;python वस्तु-उन्मुख प्रोग्रामिंग&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gof_के_डिज़ाइन_पैटर्न_python_में&quot;&gt;GoF के डिज़ाइन पैटर्न Python में&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/whikwon/python-patterns/&quot;&gt;कार्यान्वयन 1&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/Sean-Bradley/Design-Patterns-In-Python&quot;&gt;कार्यान्वयन 2&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://sbcode.net/python/&quot;&gt;पूरी किताब&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GoF के डिज़ाइन पैटर्न 23 डिज़ाइन पैटर्न का एक सेट हैं जिन्हें पुस्तक &quot;Design Patterns: Elements of Reusable Object-Oriented Software&quot; में वर्णित किया गया है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;।यहाँ GoF डिज़ाइन पैटर्न की सूची है&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
&lt;col style=&quot;width: 2.0833%;&quot;&gt;
