&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_सहायता_दिखाएँ&quot;&gt;सहायता दिखाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jvm_का_सिस्टम_प्रॉपर्टी_सेट_करें_d_system_prop&quot;&gt;JVM का सिस्टम प्रॉपर्टी सेट करें : `-D, --system-prop&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_परियोजना_की_संपत्ति_को_बिल्ड_स्क्रिप्ट_के_लिए_परिभाषित_करें_pmypropmyvalue&quot;&gt;परियोजना की संपत्ति को बिल्ड स्क्रिप्ट के लिए परिभाषित करें : `-Pmyprop=myvalue&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gradle_की_स्टार्टअप_निर्देशिका_निर्दिष्ट_करता_है_डिफ़ॉल्ट_मान_वर्तमान_निर्देशिका_है&quot;&gt;Gradle की स्टार्टअप निर्देशिका निर्दिष्ट करता है। डिफ़ॉल्ट मान वर्तमान निर्देशिका है।&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_कमांड_लाइन_से_param_component_property_को_ओवरराइट_करें&quot;&gt;कमांड लाइन से &#39;param_component&#39; property को ओवरराइट करें :&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kotlin_dsl_के_साथ_एक_सामान्य_प्रोज़क्ट_में_सोर्स_सेट_में_एक_फ़ोल्डर_जोड़ें&quot;&gt;Kotlin DSL के साथ एक सामान्य प्रोज़क्ट में सोर्स-सेट में एक फ़ोल्डर जोड़ें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एंड्रॉइड_प्रोजेक्ट_में_स्रोत_सेट_में_ग्रोवी_dsl_के_माध्यम_से_फ़ोल्डर_जोड़ें&quot;&gt;एंड्रॉइड प्रोजेक्ट में स्रोत सेट में ग्रोवी DSL के माध्यम से फ़ोल्डर जोड़ें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_सब_मॉड्यूल_का_निर्माण_और_परीक्षण_करने_से_बचें&quot;&gt;एक सब मॉड्यूल का निर्माण और परीक्षण करने से बचें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tar_एक_फ़ोल्डर&quot;&gt;Tar एक फ़ोल्डर&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_एक_बिल्ड_की_निर्भरताएँ_दिखाएँ&quot;&gt;एक बिल्ड की निर्भरताएँ दिखाएँ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_reduce_का_उपयोग_करने_का_उदाहरण_सूची_को_स्ट्रिंग_में_संयोजन&quot;&gt;reduce का उपयोग करने का उदाहरण: सूची को स्ट्रिंग में संयोजन&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_किसी_विशेष_कार्य_का_विवरण_प्राप्त_करें&quot;&gt;किसी विशेष कार्य का विवरण प्राप्त करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_workingdir_root_से_एक_कार्य_लॉन्च_करने_के_लिए_फिर_कार्य_को_से_प्रीफ़िक्स&quot;&gt;workingDir root से एक कार्य लॉन्च करने के लिए, फिर कार्य को &lt;code&gt;:&lt;/code&gt; से प्रीफ़िक्स&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_असफल_कार्यों_को_पुनः_चलाने_के_लिए_विकल्प_rerun_tasks_का_उपयोग_करें&quot;&gt;असफल कार्यों को पुनः चलाने के लिए, विकल्प &lt;code&gt;--rerun-tasks&lt;/code&gt; का उपयोग करें&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_दूसरे_निर्देशिका_से_एक_विशिष्ट_प्रोजेक्ट_में_एक_टास्क_शुरू_करें&quot;&gt;दूसरे निर्देशिका से एक विशिष्ट प्रोजेक्ट में एक टास्क शुरू करें&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_सहायता_दिखाएँ&quot;&gt;सहायता दिखाएँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew --help&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_jvm_का_सिस्टम_प्रॉपर्टी_सेट_करें_d_system_prop&quot;&gt;JVM का सिस्टम प्रॉपर्टी सेट करें : `-D, --system-prop&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Dmyprop=myvalue
#ou
./gradlew --system-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_परियोजना_की_संपत्ति_को_बिल्ड_स्क्रिप्ट_के_लिए_परिभाषित_करें_pmypropmyvalue&quot;&gt;परियोजना की संपत्ति को बिल्ड स्क्रिप्ट के लिए परिभाषित करें : `-Pmyprop=myvalue&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pmyprop=myvalue
#ou
./gradlew --project-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gradle_की_स्टार्टअप_निर्देशिका_निर्दिष्ट_करता_है_डिफ़ॉल्ट_मान_वर्तमान_निर्देशिका_है&quot;&gt;Gradle की स्टार्टअप निर्देशिका निर्दिष्ट करता है। डिफ़ॉल्ट मान वर्तमान निर्देशिका है।&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/src/next_startup
#ou
./gradlew --project-dir ~/src/next_startup&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_कमांड_लाइन_से_param_component_property_को_ओवरराइट_करें&quot;&gt;कमांड लाइन से &#39;param_component&#39; property को ओवरराइट करें :&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pparam_component=CUSTOM_VALUE&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kotlin_dsl_के_साथ_एक_सामान्य_प्रोज़क्ट_में_सोर्स_सेट_में_एक_फ़ोल्डर_जोड़ें&quot;&gt;Kotlin DSL के साथ एक सामान्य प्रोज़क्ट में सोर्स-सेट में एक फ़ोल्डर जोड़ें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;sourceSets {
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/groovy&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/kscript&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/test/javascript&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एंड्रॉइड_प्रोजेक्ट_में_स्रोत_सेट_में_ग्रोवी_dsl_के_माध्यम_से_फ़ोल्डर_जोड़ें&quot;&gt;एंड्रॉइड प्रोजेक्ट में स्रोत सेट में ग्रोवी DSL के माध्यम से फ़ोल्डर जोड़ें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;android {
    sourceSets {
        main.java.srcDirs += &quot;src/main/../../../../ceelo/domain/src/main/java/&quot;
        test.java.srcDirs += &quot;src/test/../../../../ceelo/domain/src/test/java/&quot;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक_सब_मॉड्यूल_का_निर्माण_और_परीक्षण_करने_से_बचें&quot;&gt;एक सब मॉड्यूल का निर्माण और परीक्षण करने से बचें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;gradle build -x :excluded-module:check -x :excluded-module:assemble -x :excluded-module:build&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;फ़ाइलें ले जाना&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;moveWebappNode&quot;) {
    doLast {
        ant.withGroovyBuilder {
            &quot;move&quot;(
                &quot;webapp/node_modules&quot; to &quot;$rootDir/webapp-src/node_modules&quot;,
            )
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tar_एक_फ़ोल्डर&quot;&gt;Tar एक फ़ोल्डर&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register&amp;lt;Tar&amp;gt;(&quot;tarWebapp&quot;) {
    dependsOn(&quot;moveWebappNpm&quot;)
    group = WEBAPP
    description = &quot;tar webapp&quot;
    doLast {
        setOf(
            &quot;build&quot;,
            &quot;target&quot;,
            &quot;node_modules&quot;
        ).forEach { dir -&amp;gt; exclude { it.name .dir } }
        archiveFileName.set(&quot;webapp.tar&quot;)
        destinationDirectory.set(File(&quot;${rootDir.absolutePath}$sep$WEBAPP_SRC&quot;))
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_एक_बिल्ड_की_निर्भरताएँ_दिखाएँ&quot;&gt;एक बिल्ड की निर्भरताएँ दिखाएँ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printDependencies&quot;) {
    description = &quot;print project dependencies&quot;
    group = WEBAPP
    doLast {
        println(&quot;${project.name} dependencies&quot;)
        mutableMapOf&amp;lt;String, Map&amp;lt;String, String&amp;gt;&amp;gt;(
            &quot;buildDependencies&quot; to buildDependencies,
            &quot;domainDeps&quot; to domainDeps,
            &quot;domainTestDeps&quot; to domainTestDeps,
        ).apply { putAll(appModules) }
            .forEach { module -&amp;gt;
                if (module.value.isNotEmpty()) {
                    println(&quot;${module.key}:&quot;)
                    module.value.forEach { println(dependency(it)) }
                    println()
                }
            }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_reduce_का_उपयोग_करने_का_उदाहरण_सूची_को_स्ट्रिंग_में_संयोजन&quot;&gt;reduce का उपयोग करने का उदाहरण: सूची को स्ट्रिंग में संयोजन&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printWebappSrc&quot;) {
    description = &quot;print webapp sources&quot;
    group = WEBAPP
    doLast {
        webAppSrc
            .reduce { acc, s -&amp;gt; &quot;$acc\n\t$s&quot; }
            .run { println(&quot;$WEBAPP_SRC: $this\n&quot;) }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_किसी_विशेष_कार्य_का_विवरण_प्राप्त_करें&quot;&gt;किसी विशेष कार्य का विवरण प्राप्त करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -q help --task foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_workingdir_root_से_एक_कार्य_लॉन्च_करने_के_लिए_फिर_कार्य_को_से_प्रीफ़िक्स&quot;&gt;workingDir root से एक कार्य लॉन्च करने के लिए, फिर कार्य को &lt;code&gt;:&lt;/code&gt; से प्रीफ़िक्स&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew :foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_असफल_कार्यों_को_पुनः_चलाने_के_लिए_विकल्प_rerun_tasks_का_उपयोग_करें&quot;&gt;असफल कार्यों को पुनः चलाने के लिए, विकल्प &lt;code&gt;--rerun-tasks&lt;/code&gt; का उपयोग करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew check --rerun-tasks&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_दूसरे_निर्देशिका_से_एक_विशिष्ट_प्रोजेक्ट_में_एक_टास्क_शुरू_करें&quot;&gt;दूसरे निर्देशिका से एक विशिष्ट प्रोजेक्ट में एक टास्क शुरू करें&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;विकल्प`-p` (ou &lt;code&gt;--project-dir&lt;/code&gt;) एक Gradle प्रोजेक्ट तक पहुँचने का पथ निर्दिष्ट करने और उसे एक कार्य निष्पादित करने की अनुमति देता है, भले ही वर्तमान निर्देशिका अलग हो।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;उदाहरण के लिए, कार्य शुरू करने के लिए`build`परियोजना स्थित में`~/projets/mon-autre-projet`होते हुए एक अन्य निर्देशिका में :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/projets/mon-autre-projet build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;यह कई परियोजनाओं में कार्यों को स्क्रिप्ट करने के लिए केंद्रीय स्थान से विशेष रूप से उपयोगी है।&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;भी देखें :&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_warnings&quot;&gt;ref&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_options&quot;&gt;ref&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://stackoverflow.com/a/36178581/837404&quot;&gt;चर्चा&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सील्ड क्लासेस, enum नहीं हैं (कीवर्ड: enum).&lt;br&gt;
जावा से आने पर, आप अपनी सुविधा प्रदान करने वाली सूची को ओवरलोड करने के लिए ललचा सकते हैं: // Java code&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-java hljs&quot; data-lang=&quot;java&quot;&gt;enum PizzaOrderStatus {
    ORDER_RECEIVED,
    PIZZA_BEING_MADE,
    OUT_FOR_DELIVERY,
    COMPLETED;
    public PizzaOrderStatus nextStatus() {
        switch (this) {
        case ORDER_RECEIVED: return PIZZA_BEING_MADE;
        case PIZZA_BEING_MADE: return OUT_FOR_DELIVERY;
        case OUT_FOR_DELIVERY: return COMPLETED;
        case COMPLETED:return COMPLETED;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इसके बजाय, आप sealed क्लास का उपयोग कर सकते हैं :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;sealed class PizzaOrderStatus(protected val orderId: Int) {
    abstract fun nextStatus() : PizzaOrderStatus
    class OrderReceived(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return PizzaBeingMade(orderId)
        }
    }
    class PizzaBeingMade(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return OutForDelivery(orderId)
        }
    }
    class OutForDelivery(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return Completed(orderId)
        }
    }
    class Completed(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return this
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;इस दृष्टिकोण का लाभ यह है कि हम अब डेटा को साथ में संचारित कर सकते हैं स्थिति:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;var status: PizzaOrderStatus = OrderReceived(123)
while (status !is Completed) {
    status = when (status) {
        is OrderReceived -&amp;gt; status.nextStatus()
        is PizzaBeingMade -&amp;gt; status.nextStatus()
        is OutForDelivery -&amp;gt; status.nextStatus()
        is Completed -&amp;gt; status
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;सामान्य रूप से, sealed classes अच्छी होती हैं यदि आप संबद्ध डेटा रखना चाहते हैं एक राज्य&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mind_map&quot;&gt;Mind map&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;span class=&quot;image&quot;&gt;&lt;img src=&quot;../../diagram/training_kotlin.png&quot; alt=&quot;training_kotlin&quot;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_फलनात्मक_प्रोग्रामिंग&quot;&gt;फलनात्मक प्रोग्रामिंग&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;अभ्यास पुस्तक से लिए गए हैं:&lt;br&gt;
&lt;mark&gt;#&lt;/mark&gt; ग्रेडल एकीकरण JBake को JBake Gradle प्लगइन का उपयोग करके या JBake CLI को सीधे बुलाकर Gradle बिल्ड में एकीकृत किया जा सकता है:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;----
tasks.register&amp;lt;JavaExec&amp;gt;(&quot;bake&quot;) {
    mainClass.set(&quot;org.jbake.launcher.Main&quot;)
    classpath = configurations[&quot;jbake&quot;]
    args = listOf(projectDir.absolutePath, &quot;$buildDir/jbake&quot;)
} +
